/**
 * The side panel's look: the website's stone-and-gold palette, its Cinzel heading font, and the small painted
 * parts (cards, buttons, bars, board squares) with their gentle animations. Everything here is Swing-only and
 * runs on the EDT. Animations are short and stop by themselves; {@link #animations} turns them all off.
 */
final class PanelUi
{
    private PanelUi()
    {
    }

    // ---- palette (warm stone and soft gold, like the website's panels; easy on the eyes next to the game)
    // These twelve change with the theme (PanelTheme.palette, same order); read them when painting, never keep a
    // copy in a static final. Classic values shown.
    static Color BG = ColorScheme.DARK_GRAY_COLOR;
    static Color CARD_TOP = new Color(0x363029);
    static Color CARD_BOTTOM = new Color(0x2b2722);
    static Color CARD_EDGE = new Color(0x4d4437);
    static Color INSET = new Color(0x1f1c18);
    static Color INSET_EDGE = new Color(0x3d362c);
    static Color GOLD = new Color(0xffbf1f);
    static Color GOLD_SOFT = new Color(0xe9b84e);
    static Color GOLD_DARK = new Color(0xa07222);
    static Color ORANGE = new Color(0xff981f);
    static Color TEXT = new Color(0xe6dfd3);
    static Color MUTED = new Color(0xa69d8f);

    /** how much of the theme moves; Off also drops the still decorations (drips, crystals, lava cracks) */
    static volatile ForgeBingoConfig.PanelEffects effects = ForgeBingoConfig.PanelEffects.FULL;

    static boolean decorations()
    {
        return effects != ForgeBingoConfig.PanelEffects.OFF;
    }

    /** the look in use; change it with {@link #applyTheme} */
    static volatile PanelTheme theme = PanelTheme.CLASSIC;

    private static Color[] themed()
    {
        return new Color[] {BG, CARD_TOP, CARD_BOTTOM, CARD_EDGE, INSET, INSET_EDGE, GOLD, GOLD_SOFT, GOLD_DARK, ORANGE, TEXT, MUTED};
    }

    /**
     * Switches the palette. Returns old colour -> new colour, for components that were given a colour when they
     * were built (labels' text, card stripes); everything that paints itself just reads the new values.
     */
    static java.util.Map<Color, Color> applyTheme(PanelTheme t)
    {
        PanelTheme to = t == null ? PanelTheme.CLASSIC : t;
        Color[] was = themed();
        int[] p = to.palette;
        BG = new Color(p[0]);
        CARD_TOP = new Color(p[1]);
        CARD_BOTTOM = new Color(p[2]);
        CARD_EDGE = new Color(p[3]);
        INSET = new Color(p[4]);
        INSET_EDGE = new Color(p[5]);
        GOLD = new Color(p[6]);
        GOLD_SOFT = new Color(p[7]);
        GOLD_DARK = new Color(p[8]);
        ORANGE = new Color(p[9]);
        TEXT = new Color(p[10]);
        MUTED = new Color(p[11]);
        theme = to;
        BoardOverlay.retheme();
        Color[] now = themed();
        java.util.Map<Color, Color> map = new java.util.HashMap<>();
        for (int i = 0; i < was.length; i++) if (!was[i].equals(now[i])) map.put(was[i], now[i]);
        return map;
    }

    /** A colour a little lighter (or darker, for a negative amount) on every channel. */
    static Color lift(Color c, int d)
    {
        return new Color(Math.max(0, Math.min(255, c.getRed() + d)), Math.max(0, Math.min(255, c.getGreen() + d)),
            Math.max(0, Math.min(255, c.getBlue() + d)));
    }

    static final Color GREEN = new Color(0x66d966);
    static final Color GREEN_DARK = new Color(0x2f6a33);
    static final Color AMBER = new Color(0xf2bb45);
    static final Color RED = new Color(0xff7b70);

    /** false = no motion at all: values jump, nothing pulses (the "Side panel animations" setting) */
    static volatile boolean animations = true;

    // ---- fonts
    private static final Font CINZEL = loadCinzel();
    private static final String SANS = pickSans();
    static final Font CLEAN_SMALL = new Font(SANS, Font.PLAIN, 11);
    static final Font CLEAN_BODY = new Font(SANS, Font.PLAIN, 12);
    static final Font CLEAN_BOLD = new Font(SANS, Font.BOLD, 13);
    /** headings: Cinzel, the website's display font (falls back to the bold body font if it cannot load) */
    static final Font CLEAN_HEAD = CINZEL == null ? CLEAN_BOLD : CINZEL.deriveFont(13f);
    static final Font CLEAN_TITLE = CINZEL == null ? CLEAN_BOLD.deriveFont(15f) : CINZEL.deriveFont(16f);
    static final Font CLEAN_CAPS = (CINZEL == null ? CLEAN_SMALL.deriveFont(Font.BOLD) : CINZEL.deriveFont(10.5f))
        .deriveFont(Collections.singletonMap(TextAttribute.TRACKING, 0.08f));

    private static Font loadCinzel()
    {
        try (InputStream in = PanelUi.class.getResourceAsStream("fonts/Cinzel-Bold.ttf"))
        {
            if (in == null) return null;
            Font f = Font.createFont(Font.TRUETYPE_FONT, in);
            // labels that wrap their text (HTML) look fonts up by family name, so the font has to be registered
            java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().registerFont(f);
            return f;
        }
        catch (Exception | LinkageError e)
        {
            return null;
        }
    }

    /** A smooth system sans-serif where there is one; Java's own otherwise. */
    private static String pickSans()
    {
        try
        {
            java.util.Set<String> have = new java.util.HashSet<>(java.util.Arrays.asList(
                java.awt.GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames()));
            for (String f : new String[] {"Segoe UI", "Inter", "SF Pro Text", "Helvetica Neue", "Noto Sans", "DejaVu Sans"})
            {
                if (have.contains(f)) return f;
            }
        }
        catch (RuntimeException | LinkageError e)
        {
            // fall through
        }
        return Font.SANS_SERIF;
    }

    /** The heading font when it has every character of the text (it is Latin only); the fallback otherwise. */
    static Font headingFor(String text, Font heading, Font fallback)
    {
        return text == null || heading.canDisplayUpTo(text) < 0 ? heading : fallback;
    }

    static Graphics2D smooth(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
        textHints(g2);
        return g2;
    }

    private static volatile java.util.Map<?, ?> desktopHints;
    private static volatile boolean desktopHintsRead;

    /**
     * Text drawn the way this computer draws its own text (owner, 2026-11-14): the system's font smoothing, which
     * on most Windows screens is the sharper sub-pixel kind (ClearType), instead of plain grey smoothing. Falls
     * back to grey smoothing when the system gives no answer. Letters sit on whole pixels so small text stays sharp.
     */
    static void textHints(Graphics2D g2)
    {
        if (!desktopHintsRead)
        {
            try
            {
                Object h = java.awt.Toolkit.getDefaultToolkit().getDesktopProperty("awt.font.desktophints");
                if (h instanceof java.util.Map) desktopHints = (java.util.Map<?, ?>) h;
            }
            catch (RuntimeException | LinkageError e)
            {
                desktopHints = null;
            }
            desktopHintsRead = true;
        }
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        java.util.Map<?, ?> h = desktopHints;
        if (h != null)
        {
            Object aa = h.get(RenderingHints.KEY_TEXT_ANTIALIASING);
            // "off" or "default" would bring back jagged letters: keep ours unless the system asks for a smooth kind
            if (aa != null && aa != RenderingHints.VALUE_TEXT_ANTIALIAS_OFF && aa != RenderingHints.VALUE_TEXT_ANTIALIAS_DEFAULT)
            {
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
                Object contrast = h.get(RenderingHints.KEY_TEXT_LCD_CONTRAST);
                if (contrast != null) g2.setRenderingHint(RenderingHints.KEY_TEXT_LCD_CONTRAST, contrast);
            }
        }
        g2.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
    }

    /**
     * The panel's ordinary text: a label drawn with the smoothing above and a soft one-pixel shadow under the
     * letters, like the game's own text, so it stays readable on every theme's cards. The shadow is drawn once and
     * kept until the text, size or font changes.
     */
    static class CrispLabel extends JLabel
    {
        private java.awt.image.BufferedImage shadow;
        private String shadowKey;

        CrispLabel()
        {
            super();
        }

        CrispLabel(String text)
        {
            super(text);
        }

        CrispLabel(javax.swing.Icon icon)
        {
            super(icon);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            try
            {
                textHints(g2);
                String text = getText();
                int w = getWidth();
                int h = getHeight();
                if (getIcon() == null && text != null && !text.trim().isEmpty() && w > 0 && h > 0 && w * h < 400_000)
                {
                    // drawn at the screen's own scale (a 150% or 200% display), or the shadow would not line up
                    double sc = Math.max(1.0, Math.min(4.0, g2.getTransform().getScaleX()));
                    String key = text + '|' + w + '|' + h + '|' + getFont() + '|' + isEnabled() + '|' + sc;
                    if (shadow == null || !key.equals(shadowKey))
                    {
                        // the label's own letters, turned black
                        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage((int) Math.ceil(w * sc), (int) Math.ceil(h * sc),
                            java.awt.image.BufferedImage.TYPE_INT_ARGB);
                        Graphics2D s = img.createGraphics();
                        try
                        {
                            s.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                            s.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
                            s.scale(sc, sc);
                            s.setClip(0, 0, w, h); // wrapped (HTML) text will not paint without a clip
                            super.paintComponent(s);
                            s.setComposite(AlphaComposite.SrcIn);
                            s.setColor(Color.BLACK);
                            s.fillRect(0, 0, w + 1, h + 1);
                        }
                        finally
                        {
                            s.dispose();
                        }
                        shadow = img;
                        shadowKey = key;
                    }
                    java.awt.Composite old = g2.getComposite();
                    g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.62f));
                    g2.drawImage(shadow, 1, 1, w, h, null);
                    g2.setComposite(old);
                }
                else
                {
                    shadow = null;
                    shadowKey = null;
                }
                super.paintComponent(g2);
            }
            finally
            {
                g2.dispose();
            }
        }
    }

    static Color mix(Color a, Color b, float t)
    {
        float k = Math.max(0f, Math.min(1f, t));
        return new Color(
            Math.round(a.getRed() + (b.getRed() - a.getRed()) * k),
            Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * k),
            Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * k),
            Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * k));
    }

    static Color alpha(Color c, int a)
    {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, a)));
    }

    /** A slow breath between 0 and 1 (about 2.6 s), shared so everything that glows glows together. */
    static float pulse()
    {
        if (!animations) return 1f;
        return 0.5f + 0.5f * (float) Math.sin(System.currentTimeMillis() / 2600.0 * Math.PI * 2);
    }

    /** Runs f with an eased 0..1 over ms milliseconds (or just once with 1 when animations are off). */
    static void tween(int ms, DoubleConsumer f)
    {
        if (!animations)
        {
            f.accept(1);
            return;
        }
        long start = System.nanoTime();
        Timer t = new Timer(16, null);
        t.addActionListener(e -> {
            double k = Math.min(1.0, (System.nanoTime() - start) / 1e6 / ms);
            f.accept(1 - Math.pow(1 - k, 3));
            if (k >= 1) t.stop();
        });
        f.accept(0);
        t.start();
    }

    /** A value that glides between 0 and 1 (hover highlights). */
    static final class Fader
    {
        private final JComponent owner;
        private final int ms;
        private final Timer timer = new Timer(16, e -> step());
        private float value;
        private float target;
        private long last;

        Fader(JComponent owner, int ms)
        {
            this.owner = owner;
            this.ms = ms;
        }

        void set(boolean on)
        {
            target = on ? 1f : 0f;
            if (!animations)
            {
                value = target;
                owner.repaint();
                return;
            }
            if (!timer.isRunning())
            {
                last = System.nanoTime();
                timer.start();
            }
        }

        float get()
        {
            return value;
        }

        private void step()
        {
            long now = System.nanoTime();
            float d = (now - last) / 1e6f / ms;
            last = now;
            value = target > value ? Math.min(target, value + d) : Math.max(target, value - d);
            if (value == target || !owner.isDisplayable()) timer.stop();
            owner.repaint();
        }
    }

    // ------------------------------------------------------------------ card

    /** A rounded stone card: soft gradient, thin edge, optional coloured stripe down the left. */
    static class Card extends JPanel
    {
        private static final int ARC = 8;
        private Color accent;
        /** null = the theme's usual edge */
        private Color edge;
        private boolean inset;
        private Fader hover;
        private float alpha = 1f;
        private float lift;

        Card(Color accent)
        {
            this.accent = accent;
            setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
            setOpaque(false);
            setAlignmentX(LEFT_ALIGNMENT);
            pad(8, 8, 8, 8);
            putClientProperty(PanelImps.PLATFORM, Boolean.TRUE);
        }

        /** Padding inside the card; the stripe's width is added on the left. */
        final Card pad(int top, int left, int bottom, int right)
        {
            setBorder(BorderFactory.createEmptyBorder(top, left + (accent == null ? 0 : 3), bottom, right));
            return this;
        }

        /** The darker, sunken look (a task inside a tile card). */
        Card inset(Color edgeColour)
        {
            inset = true;
            edge = edgeColour;
            return this;
        }

        /** The theme changed: a stripe or edge given in the old palette moves to the new one. */
        void remap(java.util.Map<Color, Color> map)
        {
            if (accent != null && map.containsKey(accent)) accent = map.get(accent);
            if (edge != null && map.containsKey(edge)) edge = map.get(edge);
        }

        /** Blood running down from the top edge (the Theatre of Blood look). The same card always drips the same. */
        private void paintDrips(Graphics2D g2, int w, int h)
        {
            java.util.Random r = new java.util.Random(w * 31L + getY() * 17L + getX());
            Color blood = new Color(0xb3121c);
            Color dark = new Color(0x6d0a12);
            g2.setColor(alpha(blood, 210));
            g2.fillRect(ARC / 2, 1, w - ARC, 2);
            int n = Math.max(2, w / 34);
            for (int i = 0; i < n; i++)
            {
                int x = ARC + r.nextInt(Math.max(1, w - 2 * ARC - 4));
                int len = 3 + r.nextInt(Math.max(1, Math.min(11, h / 3)));
                int wd = 2 + r.nextInt(2);
                g2.setColor(alpha(dark, 200));
                g2.fillRoundRect(x, 1, wd + 1, len + 1, wd + 1, wd + 1);
                g2.setColor(blood);
                g2.fillRoundRect(x, 1, wd, len, wd, wd);
                g2.setColor(new Color(255, 150, 150, 150));
                g2.fillRect(x, 2 + len / 2, 1, 1);
            }
        }

        /** Brightens a little under the mouse. */
        Card hoverable()
        {
            hover = new Fader(this, 130);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseEntered(MouseEvent e)
                {
                    hover.set(true);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    hover.set(false);
                }
            });
            return this;
        }

        /** Fades in and settles up a few pixels (a tile being opened, team news arriving). */
        void fadeIn()
        {
            tween(240, k -> {
                alpha = (float) k;
                lift = (float) (1 - k) * 5f;
                repaint();
            });
        }

        @Override
        public void paint(Graphics g)
        {
            if (alpha >= 1f && lift <= 0f)
            {
                super.paint(g);
                return;
            }
            Graphics2D g2 = (Graphics2D) g.create();
            try
            {
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, Math.min(1f, alpha))));
                g2.translate(0, Math.round(lift));
                super.paint(g2);
            }
            finally
            {
                g2.dispose();
            }
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            int w = getWidth();
            int h = getHeight();
            Graphics2D g2 = smooth(g);
            try
            {
                float hv = hover == null ? 0f : hover.get();
                Shape body = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1f, h - 1f, ARC, ARC);
                if (inset)
                {
                    g2.setColor(INSET);
                }
                else
                {
                    Color top = mix(CARD_TOP, lift(CARD_TOP, 18), hv);
                    Color bottom = mix(CARD_BOTTOM, lift(CARD_BOTTOM, 13), hv);
                    g2.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
                }
                g2.fill(body);
                if (accent != null)
                {
                    Shape old = g2.getClip();
                    g2.clip(body);
                    g2.setColor(accent);
                    g2.fillRect(0, 0, 3, h);
                    g2.setClip(old);
                }
                // A crisp two-line frame like the game's own interface boxes (owner, 2026-11-14): a near-black outer
                // line, the theme's edge colour just inside it, a faint light line under the top, and small gold
                // brackets in the corners.
                Color rim = mix(edge != null ? edge : inset ? INSET_EDGE : CARD_EDGE, GOLD_DARK, hv * 0.7f);
                g2.setStroke(new java.awt.BasicStroke(1f));
                if (inset)
                {
                    g2.setColor(rim);
                    g2.draw(body);
                }
                else
                {
                    g2.setColor(new Color(0, 0, 0, 215));
                    g2.draw(body);
                    g2.setColor(rim);
                    g2.draw(new RoundRectangle2D.Float(1.5f, 1.5f, w - 3f, h - 3f, ARC - 2, ARC - 2));
                    g2.setColor(new Color(255, 240, 210, 20));
                    g2.drawLine(ARC / 2 + 2, 2, w - ARC / 2 - 3, 2);
                    if (w > 60 && h > 30)
                    {
                        g2.setColor(alpha(mix(GOLD_DARK, GOLD_SOFT, 0.35f + hv * 0.4f), 200));
                        int in = 4;
                        int len = 6;
                        int r = w - 1 - in;
                        int b = h - 1 - in;
                        g2.drawLine(in, in, in + len, in);
                        g2.drawLine(in, in, in, in + len);
                        g2.drawLine(r, in, r - len, in);
                        g2.drawLine(r, in, r, in + len);
                        g2.drawLine(in, b, in + len, b);
                        g2.drawLine(in, b, in, b - len);
                        g2.drawLine(r, b, r - len, b);
                        g2.drawLine(r, b, r, b - len);
                    }
                }
                if (theme.drips && !inset && h > 20 && decorations()) paintDrips(g2, w, h);
                if (theme == PanelTheme.XERIC && h > 26 && decorations())
                {
                    // crystals growing in the corners (Chambers of Xeric); the same card always grows the same ones
                    long seed = w * 131L + getY() * 17L + getX() + (inset ? 7 : 0);
                    java.util.Random r = new java.util.Random(seed);
                    Shape old = g2.getClip();
                    g2.clip(body);
                    int big = inset ? 10 : 16;
                    ThemeFx.crystals(g2, seed, w - 9 - r.nextInt(8), h - 1, big + r.nextInt(4));
                    if (!inset || r.nextBoolean()) ThemeFx.crystals(g2, seed + 1, 7 + r.nextInt(6), h - 1, big - 4 + r.nextInt(3));
                    if (!inset && w > 150 && r.nextInt(3) > 0) ThemeFx.crystals(g2, seed + 2, w / 3 + r.nextInt(w / 3), h - 1, 8 + r.nextInt(3));
                    g2.setClip(old);
                }
            }
            finally
            {
                g2.dispose();
            }
        }
    }

