package com.forgebingo;

import com.forgebingo.core.SkillProp;
import com.forgebingo.core.SkillProps;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * The extra touches each theme has besides its colours and creatures (owner, 2026-11-14):
 * crystals growing on the cards (Chambers of Xeric), sand that falls, piles up on the cards and gets blown or
 * knocked away (Tombs of Amascut), and tiny volcanoes that erupt and send a lava stream off the side of their card
 * (Inferno). The moving ones live in the same layer as the creatures (PanelImps drives them); the crystals are
 * painted by the cards themselves. Everything is in the column's coordinates, like the creatures.
 */
final class ThemeFx
{
    // ------------------------------------------------------------------ crystals (painted by cards and headers)

    // lit face, shaded face, top facet, outline, glint
    private static final Color[] CRYSTAL = {new Color(0x4fe3c4), new Color(0x1c917d), new Color(0xb6fff0), new Color(0x083a34), new Color(0xffffff)};

    /**
     * A little cluster of crystals growing up from (x, baseY): chunky six-sided prisms with a pointed cap, straight
     * sided so they read as gems and not as blades of grass. The same seed always grows the same cluster.
     * {@code size} is the tallest crystal's height in pixels.
     */
    static void crystals(Graphics2D g, long seed, int x, int baseY, int size)
    {
        Random r = new Random(seed);
        int n = size >= 12 ? 3 : 2;
        // drawn back to front: the short outer ones first, the tall middle one last
        int[] order = n == 3 ? new int[] {0, 2, 1} : new int[] {0, 1};
        float w = Math.max(4f, size * 0.44f);
        for (int i : order)
        {
            boolean main = n == 3 ? i == 1 : i == 0;
            float h = main ? size : size * (0.5f + r.nextFloat() * 0.2f);
            float cw = main ? w : w * 0.8f;
            float off = n == 3 ? (i - 1) * w * 0.78f : (i == 0 ? -w * 0.3f : w * 0.55f);
            // how far the top leans away from the middle
            float lean = (main ? (r.nextFloat() - 0.5f) * 0.12f : (off < 0 ? -0.34f : 0.34f)) * h;
            float bx = x + off;
            float cap = Math.min(h * 0.34f, cw * 0.9f);
            float sy = baseY - (h - cap); // the shoulders, where the cap starts
            float sx = bx + lean * (h - cap) / h;
            float tx = bx + lean;
            float ty = baseY - h;
            Path2D.Float left = new Path2D.Float();
            left.moveTo(bx - cw / 2, baseY);
            left.lineTo(sx - cw / 2, sy);
            left.lineTo(sx, sy + cap * 0.35f);
            left.lineTo(bx, baseY);
            left.closePath();
            Path2D.Float right = new Path2D.Float();
            right.moveTo(bx, baseY);
            right.lineTo(sx, sy + cap * 0.35f);
            right.lineTo(sx + cw / 2, sy);
            right.lineTo(bx + cw / 2, baseY);
            right.closePath();
            Path2D.Float top = new Path2D.Float();
            top.moveTo(sx - cw / 2, sy);
            top.lineTo(tx, ty);
            top.lineTo(sx + cw / 2, sy);
            top.lineTo(sx, sy + cap * 0.35f);
            top.closePath();
            Path2D.Float all = new Path2D.Float();
            all.moveTo(bx - cw / 2, baseY);
            all.lineTo(sx - cw / 2, sy);
            all.lineTo(tx, ty);
            all.lineTo(sx + cw / 2, sy);
            all.lineTo(bx + cw / 2, baseY);
            all.closePath();
            g.setColor(CRYSTAL[0]);
            g.fill(left);
            g.setColor(CRYSTAL[1]);
            g.fill(right);
            g.setColor(CRYSTAL[2]);
            g.fill(top);
            g.setStroke(new BasicStroke(1f));
            g.setColor(CRYSTAL[3]);
            g.draw(all);
            if (main && size >= 10)
            {
                // a glint on the lit face
                int gx = Math.round(sx - cw * 0.22f);
                int gy = Math.round(sy + (baseY - sy) * 0.3f);
                g.setColor(PanelUi.alpha(CRYSTAL[4], 230));
                g.fillRect(gx, gy - 1, 1, 3);
                g.fillRect(gx - 1, gy, 3, 1);
            }
        }
    }

    /**
     * Glowing cracks of lava in the rock behind the cards (Inferno). The same place always cracks the same way;
     * only the glow breathes.
     */
    static void lavaGround(Graphics2D g, int w, int h, Rectangle clip, float glow)
    {
        g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
        int band = 58;
        for (int i = 0; i * band < h + band; i++)
        {
            int cy = i * band + 20;
            if (clip != null && (cy + 30 < clip.y || cy - 30 > clip.y + clip.height)) continue;
            Random r = new Random(i * 7919L + 13);
            Path2D.Float crack = new Path2D.Float();
            float y = cy + r.nextInt(17) - 8;
            crack.moveTo(-2, y);
            for (int x = 10 + r.nextInt(8); x < w + 12; x += 9 + r.nextInt(12))
            {
                y = Math.max(cy - 16, Math.min(cy + 16, y + r.nextInt(15) - 7));
                crack.lineTo(x, y);
                if (r.nextInt(5) == 0)
                {
                    // a short side branch
                    crack.lineTo(x + 4 + r.nextInt(5), y + (r.nextBoolean() ? 9 : -9));
                    crack.moveTo(x, y);
                }
            }
            g.setStroke(new BasicStroke(6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(new Color(150, 30, 6, Math.round(34 + 30 * glow)));
            g.draw(crack);
            g.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(PanelUi.alpha(LAVA_DEEP, Math.round(150 + 60 * glow)));
            g.draw(crack);
            g.setStroke(new BasicStroke(1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g.setColor(PanelUi.alpha(PanelUi.mix(LAVA, LAVA_HOT, glow * 0.6f), Math.round(170 + 80 * glow)));
            g.draw(crack);
        }
    }

    // ------------------------------------------------------------------ the moving effects

    private static final Color SAND = new Color(0xdcb96c);
    private static final Color SAND_DARK = new Color(0xb38d45);
    private static final Color SAND_LIGHT = new Color(0xf4dd9c);
    private static final Color LAVA = new Color(0xff7a1a);
    private static final Color LAVA_HOT = new Color(0xffd24a);
    private static final Color LAVA_DEEP = new Color(0xc2300c);
    private static final Color ROCK = new Color(0x2a1a16);
    private static final Color ROCK_LIT = new Color(0x4d2d22);

    private static final int MAX_PILES = 12;
    private static final float PILE_FULL = 26f;
    private static final int MAX_VOLCANOES = 3;

    /** x, y, vx, vy, life left, kind (0 sand grain, 1 dust, 2 lava spark, 3 lava drip) */
    private final List<float[]> bits = new ArrayList<>();

    private static final class Pile
    {
        float x, amount, age;
        int y, l, r;
    }

    private static final class Volcano
    {
        int x, y, l, r;
        /** which side of its card the lava runs off: -1 left, 1 right */
        int side;
        int drop;
        float next, erupt, dripT;
    }

    /** A skill's little prop standing on a card (Skilling theme): it grows in, stays a while and fades. */
    private static final class Prop
    {
        SkillProp skill;
        int x, y, l, r;
        float age, life;
    }

    private static final int MAX_PROPS = 5;
    private static final float GROW = 0.55f;
    private static final float FADE = 0.9f;
    private final List<Prop> props = new ArrayList<>();
    private float nextProp = 1.5f;
    private SkillProp lastSkill;

    private final List<Pile> piles = new ArrayList<>();
    private final List<Volcano> volcanoes = new ArrayList<>();
    private float spawn;

    static boolean moving(PanelTheme t)
    {
        return t == PanelTheme.AMASCUT || t == PanelTheme.INFERNO || t == PanelTheme.SKILLING;
    }

    void reset()
    {
        bits.clear();
        piles.clear();
        volcanoes.clear();
        props.clear();
    }

    boolean isEmpty()
    {
        return bits.isEmpty() && piles.isEmpty() && volcanoes.isEmpty() && props.isEmpty();
    }

    private static boolean onPlat(List<int[]> plats, int l, int r, int y)
    {
        for (int[] p : plats) if (p[2] == y && p[0] == l && p[1] == r) return true;
        return false;
    }

    void step(PanelTheme theme, float dt, List<int[]> plats, Rectangle view, int vw, Random rnd)
    {
        if (theme == PanelTheme.AMASCUT) stepSand(dt, plats, view, vw, rnd);
        else piles.clear();
        if (theme == PanelTheme.INFERNO) stepLava(dt, plats, view, rnd);
        else volcanoes.clear();
        if (theme == PanelTheme.SKILLING) stepProps(dt, plats, view, rnd);
        else props.clear();
        // everything loose: fall, drift, fade
        for (int i = bits.size() - 1; i >= 0; i--)
        {
            float[] b = bits.get(i);
            int kind = (int) b[5];
            float py = b[1];
            if (kind == 0) b[2] += (rnd.nextFloat() - 0.5f) * 30f * dt;
            else if (kind == 1) { b[3] += 40f * dt; b[2] *= 1 - Math.min(1, dt * 1.2f); }
            else b[3] += 320f * dt;
            b[0] += b[2] * dt;
            b[1] += b[3] * dt;
            b[4] -= dt;
            boolean gone = b[4] <= 0 || b[1] > view.y + view.height + 12 || b[0] < -10 || b[0] > vw + 10;
            if (!gone && kind == 0)
            {
                // a grain that reaches the top of a card joins (or starts) a pile there
                for (int[] p : plats)
                {
                    if (b[0] >= p[0] + 4 && b[0] <= p[1] - 4 && py <= p[2] && b[1] >= p[2] && rnd.nextFloat() < 0.14f)
                    {
                        land(b[0], p, rnd);
                        gone = true;
                        break;
                    }
                }
            }
            if (gone) bits.remove(i);
        }
    }

    // ---- skill props

    private void stepProps(float dt, List<int[]> plats, Rectangle view, Random rnd)
    {
        for (int i = props.size() - 1; i >= 0; i--)
        {
            Prop p = props.get(i);
            p.age += dt;
            if (p.age >= p.life || !onPlat(plats, p.l, p.r, p.y)) props.remove(i);
        }
        nextProp -= dt;
        if (nextProp > 0 || props.size() >= MAX_PROPS) return;
        nextProp = 1.6f + rnd.nextFloat() * 2.6f;
        // a card you can see, with room for it away from the other props
        List<int[]> ok = new ArrayList<>();
        for (int[] p : plats)
        {
            if (p[1] - p[0] < 80 || p[2] < view.y + 26 || p[2] > view.y + view.height - 8) continue;
            if (p.length < 4 || p[3] != 1) continue; // only where it will not sit on a heading or a button
            ok.add(p);
        }
        if (ok.isEmpty()) return;
        int[] plat = ok.get(rnd.nextInt(ok.size()));
        int x = plat[0] + 18 + rnd.nextInt(Math.max(1, plat[1] - plat[0] - 36));
        for (Prop o : props) if (o.y == plat[2] && Math.abs(o.x - x) < 34) return;
        // a skill that is not standing somewhere already, and not the one before
        SkillProp[] all = SkillProp.values();
        SkillProp skill = null;
        for (int tries = 0; tries < 12 && skill == null; tries++)
        {
            SkillProp c = all[rnd.nextInt(all.length)];
            if (c == lastSkill || SkillProps.image(c, 2, 0) == null) continue;
            boolean here = false;
            for (Prop o : props) if (o.skill == c) here = true;
            if (!here) skill = c;
        }
        if (skill == null) return;
        Prop p = new Prop();
        p.skill = skill;
        p.x = x;
        p.y = plat[2];
        p.l = plat[0];
        p.r = plat[1];
        p.life = 9f + rnd.nextFloat() * 7f;
        props.add(p);
        lastSkill = skill;
    }

    private void paintProp(Graphics2D g, Prop p, float clock)
    {
        int stage = p.age < GROW ? 0 : p.age < GROW * 2 ? 1 : 2;
        java.awt.image.BufferedImage img = SkillProps.image(p.skill, stage, ((int) (clock * 3f + p.x)) % 2);
        if (img == null) return;
        float left = p.life - p.age;
        float alpha = left < FADE ? Math.max(0f, left / FADE) : 1f;
        // a small hop as each stage arrives, so it reads as growing
        float inStage = p.age < GROW * 2 ? (p.age % GROW) / GROW : 1f;
        int hop = inStage < 0.35f && p.age < GROW * 3 ? -1 : 0;
        java.awt.Composite old = g.getComposite();
        if (alpha < 1f) g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
        g.drawImage(img, p.x - img.getWidth() / 2, p.y - img.getHeight() + 1 + hop, null);
        g.setComposite(old);
    }

    // ---- sand

    private void stepSand(float dt, List<int[]> plats, Rectangle view, int vw, Random rnd)
    {
        spawn += dt * 9f;
        while (spawn >= 1f && bits.size() < 90)
        {
            spawn -= 1f;
            bits.add(new float[] {6 + rnd.nextFloat() * Math.max(10, vw - 12), view.y - 4 - rnd.nextFloat() * 30, (rnd.nextFloat() - 0.5f) * 10f,
                55f + rnd.nextFloat() * 45f, 30f, 0});
        }
        if (spawn > 4f) spawn = 0;
        for (int i = piles.size() - 1; i >= 0; i--)
        {
            Pile p = piles.get(i);
            p.age += dt;
            if (!onPlat(plats, p.l, p.r, p.y))
            {
                piles.remove(i);
                continue;
            }
            // a full pile sooner or later gets blown away; so does a very old one
            boolean windy = p.amount >= PILE_FULL && rnd.nextFloat() < dt * 0.35f;
            if (windy || p.age > 55f) scatter(p, rnd.nextBoolean() ? 1 : -1, rnd);
        }
    }

    private void land(float x, int[] plat, Random rnd)
    {
        Pile best = null;
        for (Pile p : piles) if (p.y == plat[2] && Math.abs(p.x - x) < 22f) { best = p; break; }
        if (best == null)
        {
            // not every grain starts a pile, so the cards do not fill up edge to edge
            if (rnd.nextFloat() > 0.55f) return;
            if (piles.size() >= MAX_PILES) scatter(piles.get(0), rnd.nextBoolean() ? 1 : -1, rnd);
            best = new Pile();
            best.x = Math.max(plat[0] + 26, Math.min(plat[1] - 26, x));
            best.y = plat[2];
            best.l = plat[0];
            best.r = plat[1];
            piles.add(best);
        }
        best.amount = Math.min(PILE_FULL, best.amount + 2.5f);
    }

    /** The pile breaks up into dust that drifts off to one side. */
    private void scatter(Pile p, int dir, Random rnd)
    {
        int n = 6 + Math.round(p.amount * 0.5f);
        float w = pileWidth(p);
        for (int i = 0; i < n; i++)
        {
            bits.add(new float[] {p.x + (rnd.nextFloat() - 0.5f) * w, p.y - rnd.nextFloat() * pileHeight(p), dir * (40f + rnd.nextFloat() * 90f),
                -(10f + rnd.nextFloat() * 50f), 0.5f + rnd.nextFloat() * 0.7f, 1});
        }
        piles.remove(p);
    }

    private static float pileWidth(Pile p)
    {
        return 14f + p.amount * 1.35f;
    }

    private static float pileHeight(Pile p)
    {
        return 4f + p.amount * 0.46f;
    }

    /** The mouse brushed past: any pile under it is knocked away, off in the direction the mouse was moving. */
    boolean mouseAt(int x, int y, int dx, Random rnd)
    {
        for (int i = piles.size() - 1; i >= 0; i--)
        {
            Pile p = piles.get(i);
            float w = pileWidth(p);
            if (Math.abs(x - p.x) <= w / 2 + 3 && y <= p.y + 3 && y >= p.y - pileHeight(p) - 5)
            {
                scatter(p, dx < 0 ? -1 : 1, rnd);
                return true;
            }
        }
        return false;
    }

    // ---- lava

    private void stepLava(float dt, List<int[]> plats, Rectangle view, Random rnd)
    {
        for (int i = volcanoes.size() - 1; i >= 0; i--)
        {
            Volcano v = volcanoes.get(i);
            if (!onPlat(plats, v.l, v.r, v.y))
            {
                volcanoes.remove(i);
                continue;
            }
            v.next -= dt;
            if (v.next <= 0)
            {
                v.next = 7f + rnd.nextFloat() * 9f;
                v.erupt = 1.3f;
            }
            if (v.erupt > 0)
            {
                v.erupt -= dt;
                if (rnd.nextFloat() < dt * 34f && bits.size() < 140)
                {
                    bits.add(new float[] {v.x + (rnd.nextFloat() - 0.5f) * 3f, v.y - 10, (rnd.nextFloat() - 0.5f) * 90f, -(90f + rnd.nextFloat() * 120f),
                        0.7f + rnd.nextFloat() * 0.6f, 2});
                }
            }
            // now and then a drop lets go of the end of the stream
            v.dripT -= dt;
            if (v.dripT <= 0)
            {
                v.dripT = 1.6f + rnd.nextFloat() * 2.6f;
                int ex = v.side < 0 ? v.l + 1 : v.r - 2;
                bits.add(new float[] {ex, v.y + v.drop, 0, 12f, 1.4f, 3});
            }
        }
        if (volcanoes.size() < MAX_VOLCANOES && rnd.nextFloat() < dt * 0.8f)
        {
            // a new one on a card you can see, away from the others
            List<int[]> ok = new ArrayList<>();
            for (int[] p : plats)
            {
                if (p[1] - p[0] < 110 || p[2] < view.y + 12 || p[2] > view.y + view.height - 30) continue;
                boolean taken = false;
                for (Volcano v : volcanoes) if (v.y == p[2]) taken = true;
                if (!taken) ok.add(p);
            }
            if (!ok.isEmpty())
            {
                int[] p = ok.get(rnd.nextInt(ok.size()));
                Volcano v = new Volcano();
                v.l = p[0];
                v.r = p[1];
                v.y = p[2];
                v.side = rnd.nextBoolean() ? 1 : -1;
                int span = (p[1] - p[0]) / 3;
                v.x = v.side < 0 ? p[0] + 26 + rnd.nextInt(Math.max(1, span)) : p[1] - 26 - rnd.nextInt(Math.max(1, span));
                v.drop = 16 + rnd.nextInt(22);
                v.next = 1.5f + rnd.nextFloat() * 5f;
                v.dripT = 1f + rnd.nextFloat() * 2f;
                volcanoes.add(v);
            }
        }
    }

    // ------------------------------------------------------------------ painting

    void paint(Graphics2D g, float clock)
    {
        for (Prop p : props) paintProp(g, p, clock);
        for (Volcano v : volcanoes) paintVolcano(g, v, clock);
        for (Pile p : piles) paintPile(g, p);
        for (float[] b : bits)
        {
            int kind = (int) b[5];
            int x = Math.round(b[0]);
            int y = Math.round(b[1]);
            if (kind == 0)
            {
                g.setColor(PanelUi.alpha(SAND, 200));
                g.fillRect(x, y, 1, 2);
            }
            else if (kind == 1)
            {
                g.setColor(PanelUi.alpha(SAND_LIGHT, Math.max(0, Math.min(220, Math.round(b[4] * 260)))));
                g.fillRect(x, y, 2, 2);
            }
            else if (kind == 2)
            {
                float k = Math.max(0f, Math.min(1f, b[4]));
                g.setColor(PanelUi.alpha(PanelUi.mix(LAVA_DEEP, LAVA_HOT, k), Math.round(120 + 135 * k)));
                g.fillRect(x, y, 2, 2);
            }
            else
            {
                g.setColor(LAVA);
                g.fillRoundRect(x - 1, y - 1, 3, 5, 3, 3);
                g.setColor(LAVA_HOT);
                g.fillRect(x, y, 1, 2);
            }
        }
    }

    private static void paintPile(Graphics2D g, Pile p)
    {
        float w = pileWidth(p);
        float h = pileHeight(p);
        Path2D.Float mound = new Path2D.Float();
        mound.moveTo(p.x - w / 2, p.y);
        mound.quadTo(p.x - w * 0.22f, p.y - h * 1.25f, p.x + w * 0.06f, p.y - h);
        mound.quadTo(p.x + w * 0.3f, p.y - h * 0.8f, p.x + w / 2, p.y);
        mound.closePath();
        g.setColor(SAND_DARK);
        g.fill(mound);
        Path2D.Float lit = new Path2D.Float();
        lit.moveTo(p.x - w / 2 + 1, p.y);
        lit.quadTo(p.x - w * 0.22f, p.y - h * 1.2f, p.x + w * 0.04f, p.y - h + 0.5f);
        lit.quadTo(p.x - w * 0.05f, p.y - h * 0.3f, p.x + w * 0.12f, p.y);
        lit.closePath();
        g.setColor(SAND);
        g.fill(lit);
        g.setStroke(new BasicStroke(1f));
        g.setColor(new Color(0x6e5424));
        g.draw(mound);
        Random r = new Random((long) p.y * 31 + p.l);
        int grains = Math.round(w / 5);
        for (int i = 0; i < grains; i++)
        {
            float fx = (r.nextFloat() - 0.5f) * w * 0.7f;
            float top = h * (1f - Math.abs(fx) / (w * 0.5f));
            float fy = r.nextFloat() * Math.max(1f, top - 2f) + 1f;
            g.setColor(i % 2 == 0 ? PanelUi.alpha(SAND_LIGHT, 230) : PanelUi.alpha(new Color(0x8f6f2f), 220));
            g.fillRect(Math.round(p.x + fx), Math.round(p.y - fy), 1, 1);
        }
    }

    private static void paintVolcano(Graphics2D g, Volcano v, float clock)
    {
        float glow = 0.6f + 0.4f * (float) Math.sin(clock * 3.1f + v.x);
        boolean erupting = v.erupt > 0;
        // the stream: out of the crater, down the cone, along the top of the card, off its side and down
        int edge = v.side < 0 ? v.l + 1 : v.r - 2;
        int foot = v.x + v.side * 8;
        Path2D.Float river = new Path2D.Float();
        river.moveTo(v.x + v.side, v.y - 9);
        river.lineTo(foot, v.y - 1);
        river.lineTo(edge, v.y - 1);
        river.lineTo(edge, v.y + v.drop);
        g.setStroke(new BasicStroke(3.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(PanelUi.alpha(LAVA_DEEP, 150));
        g.draw(river);
        g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(PanelUi.mix(LAVA_DEEP, LAVA, 0.6f + 0.4f * glow));
        g.draw(river);
        // brighter beads running along it, so it reads as flowing
        float len = Math.abs(edge - foot) + v.drop;
        g.setColor(PanelUi.alpha(LAVA_HOT, 230));
        for (int i = 0; i < 4; i++)
        {
            float d = ((clock * 22f + i * len / 4f) % Math.max(1f, len));
            int bx;
            int by;
            if (d < Math.abs(edge - foot))
            {
                bx = Math.round(foot + v.side * d);
                by = v.y - 1;
            }
            else
            {
                bx = edge;
                by = Math.round(v.y - 1 + (d - Math.abs(edge - foot)));
            }
            g.fillRect(bx, by - 1, 2, 2);
        }
        // the bulb at the end of the stream
        g.setColor(LAVA);
        g.fillOval(edge - 2, v.y + v.drop - 1, 5, 5);
        g.setColor(LAVA_HOT);
        g.fillRect(edge, v.y + v.drop, 1, 2);

        // the cone
        Path2D.Float cone = new Path2D.Float();
        cone.moveTo(v.x - 10, v.y);
        cone.lineTo(v.x - 3, v.y - 10);
        cone.lineTo(v.x + 3, v.y - 10);
        cone.lineTo(v.x + 10, v.y);
        cone.closePath();
        g.setColor(ROCK);
        g.fill(cone);
        Path2D.Float face = new Path2D.Float();
        face.moveTo(v.x - 10, v.y);
        face.lineTo(v.x - 3, v.y - 10);
        face.lineTo(v.x, v.y - 10);
        face.lineTo(v.x - 3, v.y);
        face.closePath();
        g.setColor(ROCK_LIT);
        g.fill(face);
        g.setStroke(new BasicStroke(1f));
        g.setColor(Color.BLACK);
        g.draw(cone);
        // the crater, brighter while it erupts
        g.setColor(PanelUi.mix(LAVA_DEEP, LAVA_HOT, erupting ? 1f : glow * 0.7f));
        g.fillRect(v.x - 3, v.y - 11, 6, 2);
        if (erupting)
        {
            g.setColor(PanelUi.alpha(LAVA_HOT, 90));
            g.fillOval(v.x - 7, v.y - 17, 14, 10);
        }
        // a lick of lava down the cone on the stream's side
        g.setColor(LAVA);
        g.drawLine(v.x + v.side * 2, v.y - 9, v.x + v.side * 7, v.y - 2);
    }
}

package com.forgebingo.core;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Activity uniques that may reach the backpack without a loot event: reward-shop purchases (Barbarian Assault, Mage
 * Training Arena, ...), opened containers (Forgotten lockbox, Pyramid Plunder chests, Vale offerings) and raid or
 * minigame rewards the loot tracker may not name. Item id -> activity name the server knows (npc_sources alias).
 *
 * The rows live in the bundled data file src/main/resources/com/forgebingo/data/activity-items.txt (format in its
 * header); they come from apps/web/src/features/boardgen/data/activities.ts. The table as it was in Java is kept as
 * ActivityItemsReference in src/test/java, and ActivityItemsDataTest proves the two are equal. A missing or broken
 * file leaves this table empty and logs an error (see DataFile for why it does not throw).
 */
public final class ActivityItems
{
    private static final Map<Integer, String> BY_ITEM;

    static
    {
        Map<Integer, String> m;
        try
        {
            m = parse(DataFile.lines("activity-items"));
        }
        catch (RuntimeException e)
        {
            DataFile.failed("activity-items", e);
            m = new HashMap<>();
        }
        BY_ITEM = Collections.unmodifiableMap(m);
    }

    private ActivityItems()
    {
    }

    /**
     * "[Activity name]" starts an activity; every other line is its item ids, separated by spaces.
     *
     * @throws RuntimeException on anything else: ids before the first activity, not a number, or an id listed twice
     */
    static Map<Integer, String> parse(List<String> lines)
    {
        Map<Integer, String> m = new HashMap<>();
        String activity = null;
        for (String line : lines)
        {
            if (line.startsWith("[") && line.endsWith("]"))
            {
                activity = line.substring(1, line.length() - 1).trim();
                if (activity.isEmpty()) throw new IllegalStateException(line);
                continue;
            }
            for (String id : line.split(" +"))
            {
                if (activity == null || m.put(Integer.valueOf(id), activity) != null) throw new IllegalStateException(line);
            }
        }
        return m;
    }

    /** Activity name for an item id, or null when the item is not an activity unique. */
    public static String activityFor(int itemId)
    {
        return BY_ITEM.get(itemId);
    }

    public static int size()
    {
        return BY_ITEM.size();
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.List;

/**
 * The last few things that counted for the player's team, so they can see the plugin working without opening the
 * website (owner, 2026-11-14). Kept small on purpose: the side panel shows only the newest as one line, and the
 * rest in its tooltip. Nothing here is sent anywhere.
 */
public final class ActivityLog
{
    public static final int MAX = 6;

    private static final class Entry
    {
        final String id;
        final String what;
        final long at;
        boolean picture;

        Entry(String id, String what, long at)
        {
            this.id = id;
            this.what = what;
            this.at = at;
        }
    }

    private final List<Entry> entries = new ArrayList<>();

    /** Something counted. {@code id} is the game event's id, so its picture can be ticked off later. */
    public synchronized void counted(String id, String what, long nowMillis)
    {
        if (what == null || what.trim().isEmpty()) return;
        String text = what.trim();
        if (text.length() > 60) text = text.substring(0, 57) + "...";
        entries.add(0, new Entry(id, text, nowMillis));
        while (entries.size() > MAX) entries.remove(entries.size() - 1);
    }

    /** That event's proof picture reached the server. */
    public synchronized void pictureSent(String id)
    {
        if (id == null) return;
        for (Entry e : entries) if (id.equals(e.id)) e.picture = true;
    }

    public synchronized boolean isEmpty()
    {
        return entries.isEmpty();
    }

    public synchronized void clear()
    {
        entries.clear();
    }

    /** "2m ago", "just now", "1h ago". */
    static String ago(long thenMillis, long nowMillis)
    {
        long s = Math.max(0, (nowMillis - thenMillis) / 1000);
        if (s < 45) return "just now";
        if (s < 3600) return Math.max(1, Math.round(s / 60f)) + "m ago";
        if (s < 86_400) return Math.round(s / 3600f) + "h ago";
        return Math.round(s / 86_400f) + "d ago";
    }

    /** The newest entry as one short line, or null when nothing has counted yet. */
    public synchronized String newest(long nowMillis)
    {
        if (entries.isEmpty()) return null;
        Entry e = entries.get(0);
        return "Counted: " + e.what + " (" + ago(e.at, nowMillis) + ")";
    }

    /** Every entry, newest first, one per line: what, when, and whether its picture was sent. */
    public synchronized List<String> lines(long nowMillis)
    {
        List<String> out = new ArrayList<>();
        for (Entry e : entries) out.add(e.what + " - " + ago(e.at, nowMillis) + (e.picture ? ", picture sent" : ""));
        return out;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Activity uniques that reach the backpack without a loot event (reward-shop purchases, opened lockboxes and chests,
 * claimed rewards). Each new activity item in the inventory is held for one tick, so every container event of that
 * tick is seen first, then reported unless it was only moved or already reported:
 * <ul>
 *   <li>the loot tracker / NPC loot already reported it within {@link #LOOT_WINDOW} ticks (reward chests post their loot
 *       when they open; claiming the items minutes later must not count them again);</li>
 *   <li>another item left the backpack in the same tick (an item changing form: a looting bag closing, a tablet being
 *       made, a weapon being uncharged, a cape taken apart) unless it was a currency being spent;</li>
 *   <li>the same item left another container (bank, equipment, storage, looting bag, trade) around that tick;</li>
 *   <li>the worn equipment changed around that tick (taking gear off; a worn item may carry another id);</li>
 *   <li>a ground item of that id vanished next to the player around that tick (a pickup: PvP loot never counts);</li>
 *   <li>a Grand Exchange offer changed around that tick (a collect);</li>
 *   <li>a trade with another player was open, accepted or closed around that tick (traded items never count);</li>
 *   <li>the player died moments ago, or it is an item they had when they died coming back to them;</li>
 *   <li>the player is in the Wilderness or on a PvP world.</li>
 * </ul>
 * Every acquisition counts, duplicates included. Pure Java so it is unit-tested without RuneLite.
 */
public final class ActivityWatcher
{
    public static final int LOOT_WINDOW = 300;
    public static final int MOVE_WINDOW = 2;
    private static final int KEEP = 30;

    /** One activity unique to report. */
    public static final class Drop
    {
        public final int itemId;
        public final int quantity;
        public final String activity;

        Drop(int itemId, int quantity, String activity)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.activity = activity;
        }
    }

    private static final class Pending
    {
        final int itemId;
        final int quantity;
        final int tick;
        final String activity;

        Pending(int itemId, int quantity, int tick, String activity)
        {
            this.itemId = itemId;
            this.quantity = quantity;
            this.tick = tick;
            this.activity = activity;
        }
    }

    private final Map<Integer, Integer> lootSeen = new HashMap<>();
    private final Map<Integer, Integer> leftContainer = new HashMap<>();
    private final Map<Integer, Integer> pickedUp = new HashMap<>();
    private int geTick = Integer.MIN_VALUE / 2;
    /** ticks in which a non-currency item left the backpack: additions in those ticks are transformations, not drops */
    private final java.util.Set<Integer> transformTicks = new java.util.HashSet<>();
    private final List<Pending> pending = new ArrayList<>();

    public void onLoot(int itemId, int tick)
    {
        lootSeen.put(itemId, tick);
    }

    public void onLeftContainer(int itemId, int tick)
    {
        leftContainer.put(itemId, tick);
    }

    public void onGroundItemGone(int itemId, int tick)
    {
        pickedUp.put(itemId, tick);
    }

    public void onGrandExchange(int tick)
    {
        geTick = tick;
    }

    /** ticks in which the worn equipment changed: anything reaching the backpack then came off the player */
    private final java.util.Set<Integer> wornTicks = new java.util.HashSet<>();

    /** The worn equipment changed this tick (equip, unequip, swap). */
    public void onWornChanged(int tick)
    {
        wornTicks.add(tick);
    }

    private boolean nearWornChange(int tick)
    {
        for (int t = tick - MOVE_WINDOW; t <= tick + MOVE_WINDOW; t++) if (wornTicks.contains(t)) return true;
        return false;
    }

    /** how long after a player trade (window open, accepted or closed) a backpack gain is still that trade's items */
    public static final int TRADE_WINDOW = 4;
    private final java.util.Set<Integer> tradeTicks = new java.util.HashSet<>();

    /**
     * A trade with another player is open, was accepted or just closed this tick (owner, 2026-11-17: an item traded
     * over counted as a reward). Items from another player are never a drop.
     */
    public void onTrade(int tick)
    {
        tradeTicks.add(tick);
    }

    /**
     * The player is getting their own items back this tick: a gravestone, a boss's item-retrieval service, Death's
     * office or coffer, or Perdu selling lost untradeables back (owner, 2026-11-23). Works without the death having
     * been seen (it may have happened on another device). Counted like a trade: nothing reaching the backpack while
     * this goes on, or just after, is a reward.
     */
    public void onReclaim(int tick)
    {
        tradeTicks.add(tick);
    }

    private boolean nearTrade(int tick)
    {
        for (int t = tick - TRADE_WINDOW; t <= tick + 1; t++) if (tradeTicks.contains(t)) return true;
        return false;
    }

    /** right after the player dies nothing that reaches the backpack is a reward (kept items being handed back) */
    public static final int DEATH_WINDOW = 25;
    /**
     * how long the items lost at a death are remembered: reclaiming them from a gravestone, Death's office or a boss's
     * item-retrieval service never counts. A day, so a player who restarts or reclaims much later is still covered.
     */
    public static final long DEATH_MEMORY_MILLIS = 24L * 60 * 60 * 1000;
    private int deathTick = Integer.MIN_VALUE / 2;
    private boolean settlePending;
    /** item id to {amount still to come back, forget-at millis} */
    private final Map<Integer, long[]> lostAtDeath = new HashMap<>();
    private boolean deathMemoryChanged;

    /**
     * The player died this tick holding {@code held} (backpack and worn, item id to amount). Getting those items back,
     * whether kept at a safe death or reclaimed later, never counts as a reward (owner, 2026-11-19: a player's own
     * Eclipse atlatl counted as a Moons of Peril drop after they died at the Colosseum). Several deaths add up.
     */
    public void onDeath(int tick, Map<Integer, Integer> held, long nowMillis)
    {
        // the same death seen twice (RuneLite's death event and hitpoints reaching 0): count its items once
        if (tick >= deathTick && tick - deathTick <= DEATH_WINDOW) return;
        deathTick = tick;
        settlePending = true;
        if (held == null) return;
        long forgetAt = nowMillis + DEATH_MEMORY_MILLIS;
        held.forEach((id, qty) -> {
            if (id == null || qty == null || qty <= 0 || ActivityItems.activityFor(id) == null) return;
            long[] e = lostAtDeath.computeIfAbsent(id, k -> new long[]{0, 0});
            e[0] += qty;
            e[1] = Math.max(e[1], forgetAt);
        });
        deathMemoryChanged = true;
    }

    /**
     * true once, when the death moment is over and the plugin should report what the player still holds. Inside a
     * raid or other instance (Chambers of Xeric, Theatre of Blood, Tombs of Amascut, the Colosseum) the player can
     * respawn with their gear much later, so the death moment lasts until they leave it (owner, 2026-11-19).
     */
    public boolean wantsHoldingsAfterDeath(int tick, boolean inInstance)
    {
        return settlePending && !inInstance && tick - deathTick > DEATH_WINDOW;
    }

    /**
     * how long gear the player still had once a death was over stays remembered: long enough that a raid taking it
     * away and handing it back later (The Fractured Archive, Theatre of Blood style deaths) does not count, short
     * enough that a real new drop of it soon after counts again
     */
    public static final long KEPT_MEMORY_MILLIS = 30L * 60 * 1000;

    /**
     * What the player holds (backpack and worn) once the death moment is over. Those were kept (a safe death); they
     * are remembered for {@link #KEPT_MEMORY_MILLIS} instead of a day, in case the game takes them away and hands
     * them back (owner, 2026-11-19: raids, The Fractured Archive). Items not held stay remembered for the full day.
     */
    public void onHoldingsAfterDeath(Map<Integer, Integer> held, long nowMillis)
    {
        settlePending = false;
        if (held == null) return;
        long keptUntil = nowMillis + KEPT_MEMORY_MILLIS;
        held.forEach((id, qty) -> {
            long[] e = id == null ? null : lostAtDeath.get(id);
            if (e == null || qty == null || qty <= 0) return;
            e[1] = Math.min(e[1], keptUntil);
            deathMemoryChanged = true;
        });
    }

    private boolean useUp(int itemId, int qty)
    {
        long[] e = lostAtDeath.get(itemId);
        if (e == null || qty <= 0) return false;
        e[0] -= qty;
        if (e[0] <= 0) lostAtDeath.remove(itemId);
        deathMemoryChanged = true;
        return true;
    }

    /** true when this gain is the player getting back something they had when they died (uses up that amount) */
    private boolean afterDeath(Pending p, long nowMillis)
    {
        int since = p.tick - deathTick;
        // the death moment: until the player has left the raid or instance they died in, nothing counts
        if (since >= 0 && (since <= DEATH_WINDOW || settlePending)) return true;
        long[] e = lostAtDeath.get(p.itemId);
        if (e == null || e[1] < nowMillis) return false;
        return useUp(p.itemId, p.quantity);
    }

    /** The death memory as text to keep between sessions ("id:amount:forgetAt;..."). */
    public String saveDeathMemory()
    {
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, long[]> e : lostAtDeath.entrySet())
        {
            if (sb.length() > 0) sb.append(';');
            sb.append(e.getKey()).append(':').append(e.getValue()[0]).append(':').append(e.getValue()[1]);
        }
        deathMemoryChanged = false;
        return sb.toString();
    }

    /** Puts back a death memory saved earlier (other entries of this session are kept); bad text is ignored. */
    public void restoreDeathMemory(String saved, long nowMillis)
    {
        if (saved == null || saved.isEmpty()) return;
        for (String part : saved.split(";"))
        {
            String[] f = part.split(":");
            if (f.length != 3) continue;
            try
            {
                int id = Integer.parseInt(f[0].trim());
                long qty = Long.parseLong(f[1].trim());
                long forgetAt = Long.parseLong(f[2].trim());
                if (qty <= 0 || forgetAt < nowMillis || ActivityItems.activityFor(id) == null) continue;
                long[] e = lostAtDeath.computeIfAbsent(id, k -> new long[]{0, 0});
                e[0] = Math.max(e[0], Math.min(qty, 1000));
                e[1] = Math.max(e[1], Math.min(forgetAt, nowMillis + DEATH_MEMORY_MILLIS));
            }
            catch (NumberFormatException ignored)
            {
                // a hand-edited or damaged value: skip that entry
            }
        }
    }

    /** Forgets every death (another account logged in: its own memory is restored next). */
    public void clearDeathMemory()
    {
        lostAtDeath.clear();
        settlePending = false;
        deathMemoryChanged = false;
    }

    /** true when the death memory changed since it was last saved */
    public boolean deathMemoryChanged()
    {
        return deathMemoryChanged;
    }

    /** A non-currency item left the backpack this tick (see the class comment). */
    public void onItemsLeftInventory(int tick)
    {
        transformTicks.add(tick);
    }

    public void onInventoryAdded(int itemId, int quantity, int tick)
    {
        String activity = ActivityItems.activityFor(itemId);
        if (activity != null && quantity > 0)
        {
            pending.add(new Pending(itemId, quantity, tick, activity));
        }
    }

    /** Call once per game tick. Returns what to report from earlier ticks. */
    public List<Drop> flush(int tick, boolean pvp)
    {
        return flush(tick, pvp, System.currentTimeMillis());
    }

    public List<Drop> flush(int tick, boolean pvp, long nowMillis)
    {
        lostAtDeath.values().removeIf(e -> e[1] < nowMillis);
        List<Drop> out = new ArrayList<>();
        Iterator<Pending> it = pending.iterator();
        while (it.hasNext())
        {
            Pending p = it.next();
            if (p.tick >= tick)
            {
                continue;
            }
            it.remove();
            boolean cameBack = afterDeath(p, nowMillis);
            if (cameBack || pvp || near(lootSeen, p.itemId, p.tick, LOOT_WINDOW, 1) || near(leftContainer, p.itemId, p.tick, MOVE_WINDOW, MOVE_WINDOW)
                || near(pickedUp, p.itemId, p.tick, MOVE_WINDOW, MOVE_WINDOW) || Math.abs(p.tick - geTick) <= MOVE_WINDOW
                || transformTicks.contains(p.tick) || transformTicks.contains(p.tick - 1) || nearWornChange(p.tick) || nearTrade(p.tick))
            {
                continue;
            }
            out.add(new Drop(p.itemId, p.quantity, p.activity));
        }
        // kept for the whole loot window: a chest's loot may be claimed minutes after the chest reported it
        lootSeen.values().removeIf(t -> t < tick - LOOT_WINDOW);
        prune(leftContainer, tick);
        prune(pickedUp, tick);
        transformTicks.removeIf(t -> t < tick - KEEP);
        wornTicks.removeIf(t -> t < tick - KEEP);
        tradeTicks.removeIf(t -> t < tick - KEEP);
        return out;
    }

    /** true when the item was recorded between {@code before} ticks before and {@code after} ticks after {@code tick}. */
    private static boolean near(Map<Integer, Integer> m, int itemId, int tick, int before, int after)
    {
        Integer t = m.get(itemId);
        return t != null && t >= tick - before && t <= tick + after;
    }

    private static void prune(Map<Integer, Integer> m, int tick)
    {
        m.values().removeIf(t -> t < tick - KEEP);
    }

    int pendingCount()
    {
        return pending.size();
    }
}

package com.forgebingo.core;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.util.List;
import java.util.function.Supplier;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * The only class that knows the HTTP routes. Blocking: call from the plugin's
 * executor, never the client or EDT thread. Every request carries the key in
 * {@code X-API-Key} (plus {@code Accept}, {@code X-Plugin-Version} and {@code X-Plugin-Decimals}; JSON bodies are {@code Content-Type: application/json}) and only ever goes to the configured base URL.
 */
public final class ApiClient
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final long MAX_BODY_BYTES = 2L * 1024 * 1024;
    private static final long MAX_ICON_BYTES = 1024L * 1024;
    public static final int MAX_SCREENSHOT_BYTES = 8 * 1024 * 1024;

    private final OkHttpClient http;
    /** same client with longer timeouts, for screenshot uploads only (a slow upload used to time out) */
    private final OkHttpClient uploadHttp;
    private final Gson gson;
    private final Supplier<String> baseUrl;
    private final Supplier<String> apiKey;
    private final String pluginVersion;

    public ApiClient(OkHttpClient http, Gson gson, Supplier<String> baseUrl, Supplier<String> apiKey, String pluginVersion)
    {
        // no redirects: OkHttp keeps custom headers (X-API-Key) on a redirect to another host, so a redirecting
        // server or proxy could collect the key
        this.http = http.newBuilder().followRedirects(false).followSslRedirects(false).build();
        this.uploadHttp = this.http.newBuilder().writeTimeout(60, java.util.concurrent.TimeUnit.SECONDS)
            .readTimeout(60, java.util.concurrent.TimeUnit.SECONDS).callTimeout(90, java.util.concurrent.TimeUnit.SECONDS).build();
        this.gson = gson;
        this.baseUrl = baseUrl;
        this.apiKey = apiKey;
        this.pluginVersion = pluginVersion;
    }

    /** Validates a user-supplied base URL: https only (http allowed for localhost dev). */
    public static HttpUrl parseBaseUrl(String raw)
    {
        if (raw == null)
        {
            return null;
        }
        HttpUrl url = HttpUrl.parse(raw.trim());
        if (url == null)
        {
            return null;
        }
        boolean local = "localhost".equals(url.host()) || "127.0.0.1".equals(url.host());
        if (!url.isHttps() && !(local && "http".equals(url.scheme())))
        {
            return null;
        }
        return url;
    }

    /** The default base URL is a placeholder; it must be replaced before anything is sent. */
    public static boolean isPlaceholder(String raw)
    {
        return raw == null || raw.contains("YOUR-PROJECT-REF") || raw.contains("<");
    }

    public boolean configured()
    {
        String base = baseUrl.get();
        return !isPlaceholder(base) && parseBaseUrl(base) != null && !apiKey.get().trim().isEmpty();
    }

    // --- routes (single place; keep in sync with docs/API.md section 8) ---

    /** GET /v1/me */
    public ApiResult<ApiModels.Me> me()
    {
        return get(url("v1", "me"), ApiModels.Me.class);
    }

    /**
     * POST /v1/hello: reports the logged-in RSN + account hash. The server binds each membership to that OSRS account
     * and says per event whether the name matches the one the player joined with.
     */
    public ApiResult<ApiModels.HelloResponse> hello(String rsn, String accountHash)
    {
        String name = Sanitizer.normalizeRsn(rsn);
        if (!Sanitizer.validRsn(name) || accountHash == null || !accountHash.matches("^-?[0-9]{1,20}$"))
        {
            return new ApiResult<>(400, null, "not logged in", "invalid_rsn", null, 0);
        }
        RequestBody body = RequestBody.create(JSON, gson.toJson(new ApiModels.HelloRequest(name, accountHash)));
        return execute(builder(url("v1", "hello")).post(body).build(), ApiModels.HelloResponse.class);
    }

    /**
     * POST /v1/wom/update {rsn}: asks the server to refresh this player's Wise Old Man stats for the bingos that track
     * them (sent on logout / world hop). The server rate-limits it; a 404 means this server has no WOM connector yet.
     */
    public ApiResult<ApiModels.WomUpdateResponse> womUpdate(String rsn)
    {
        String name = Sanitizer.normalizeRsn(rsn);
        if (!Sanitizer.validRsn(name)) return new ApiResult<>(400, null, "not logged in", "invalid_rsn", null, 0);
        RequestBody body = RequestBody.create(JSON, gson.toJson(java.util.Collections.singletonMap("rsn", name)));
        return execute(builder(url("v1", "wom", "update")).post(body).build(), ApiModels.WomUpdateResponse.class);
    }

    /** GET /v1/boards: non-draft events the user plays in. Poll no faster than every 5 s. */
    public ApiResult<ApiModels.BoardsResponse> boards()
    {
        return get(url("v1", "boards"), ApiModels.BoardsResponse.class);
    }

    /** GET /v1/boards/{teamBoardId} */
    public ApiResult<ApiModels.BoardResponse> board(String teamBoardId)
    {
        return get(url("v1", "boards", teamBoardId), ApiModels.BoardResponse.class);
    }

    /** POST /v1/boards/{teamBoardId}/working-on: mark or unmark a tile you are going for (your team sees it). */
    public ApiResult<Object> setWorkingOn(String teamBoardId, String tileId, boolean on)
    {
        java.util.Map<String, Object> m = new java.util.LinkedHashMap<>();
        m.put("tileId", tileId);
        m.put("on", on);
        RequestBody body = RequestBody.create(JSON, gson.toJson(m));
        return execute(builder(url("v1", "boards", teamBoardId, "working-on")).post(body).build(), Object.class);
    }

    /** GET /v1/boards/{teamBoardId}/leaderboard */
    public ApiResult<ApiModels.LeaderboardResponse> leaderboard(String teamBoardId)
    {
        return get(url("v1", "boards", teamBoardId, "leaderboard"), ApiModels.LeaderboardResponse.class);
    }

    /** GET /v1/catalogue/items: id/name of the server's item catalogue (to resolve collection log names). */
    public ApiResult<ApiModels.CatalogueResponse> catalogueItems()
    {
        return get(url("v1", "catalogue", "items"), ApiModels.CatalogueResponse.class);
    }

    /**
     * POST /v1/game-events. The server fans the event out to every open event the player is in.
     * The eventId in the body is the idempotency key, so retries are safe.
     */
    public ApiResult<ApiModels.EventResult> sendEvent(GameEvent event)
    {
        event.pluginVersion = pluginVersion;
        Sanitizer.event(event);
        String json = gson.toJson(event);
        if (json.getBytes(java.nio.charset.StandardCharsets.UTF_8).length > Sanitizer.MAX_EVENT_JSON_BYTES)
        {
            return new ApiResult<>(413, null, "event payload too large", "payload_too_large", null, 0);
        }
        RequestBody body = RequestBody.create(JSON, json);
        return execute(builder(url("v1", "game-events")).post(body).build(), ApiModels.EventResult.class);
    }

    /**
     * POST /v1/boards/{teamBoardId}/proofs (multipart). Attaches the screenshot to the given submissions
     * (from {@code matched[].submissionId}); 1-25 targets.
     */
    public ApiResult<ApiModels.ProofResponse> uploadProof(String teamBoardId, byte[] png, List<String> submissionIds)
    {
        return uploadProof(teamBoardId, png, submissionIds, null, null);
    }

    /** As above, also telling the server which keyword was stamped on the shot and when it was taken (ISO instant). */
    public ApiResult<ApiModels.ProofResponse> uploadProof(String teamBoardId, byte[] png, List<String> submissionIds, String stampKeyword, String capturedAt)
    {
        return uploadProof(teamBoardId, png, submissionIds, stampKeyword, capturedAt, null);
    }

    /** As above; label names the stored file after the task it proves ("Big boners" becomes big-boners_....png). */
    public ApiResult<ApiModels.ProofResponse> uploadProof(String teamBoardId, byte[] png, List<String> submissionIds, String stampKeyword, String capturedAt, String label)
    {
        if (png.length > MAX_SCREENSHOT_BYTES)
        {
            return new ApiResult<>(413, null, "screenshot too large", "payload_too_large", null, 0);
        }
        if (submissionIds.isEmpty() || submissionIds.size() > 25)
        {
            return new ApiResult<>(400, null, "1-25 submission ids required", "invalid_targets", null, 0);
        }
        RequestBody body = proofBody("submissionIds", String.join(",", submissionIds), png, stampKeyword, capturedAt, label);
        return execute(uploadHttp, builder(url("v1", "boards", teamBoardId, "proofs")).post(body).build(), ApiModels.ProofResponse.class);
    }

    /**
     * The multipart body of a proof upload: what the picture is for (targetField: "submissionIds" or "taskId"), the
     * file name label, the stamped keyword and capture time (each at most 40 characters), then the picture itself.
     */
    private static RequestBody proofBody(String targetField, String target, byte[] png, String stampKeyword, String capturedAt, String label)
    {
        MultipartBody.Builder mb = new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart(targetField, target);
        addLabel(mb, label);
        if (stampKeyword != null && !stampKeyword.isEmpty()) mb.addFormDataPart("stampKeyword", stampKeyword.length() > 40 ? stampKeyword.substring(0, 40) : stampKeyword);
        if (capturedAt != null && !capturedAt.isEmpty()) mb.addFormDataPart("capturedAt", capturedAt.length() > 40 ? capturedAt.substring(0, 40) : capturedAt);
        return mb.addFormDataPart("file", fileName(png), RequestBody.create(MediaType.parse(mime(png)), png)).build();
    }

    private static String fileName(byte[] b) { return ScreenshotEncode.isJpeg(b) ? "proof.jpg" : "proof.png"; }
    private static String mime(byte[] b) { return ScreenshotEncode.isJpeg(b) ? "image/jpeg" : "image/png"; }

    /** POST /v1/boards/{team}/proofs with a taskId: a new pending submission for that task with this screenshot. */
    public ApiResult<ApiModels.ProofResponse> uploadTaskScreenshot(String teamBoardId, String taskId, byte[] png, String stampKeyword, String capturedAt, String label)
    {
        if (png.length > MAX_SCREENSHOT_BYTES)
        {
            return new ApiResult<>(413, null, "screenshot too large", "payload_too_large", null, 0);
        }
        RequestBody body = proofBody("taskId", taskId, png, stampKeyword, capturedAt, label);
        return execute(uploadHttp, builder(url("v1", "boards", teamBoardId, "proofs")).post(body).build(), ApiModels.ProofResponse.class);
    }

    /** The task name the server uses for the file name (letters, digits and spaces only, at most 60). */
    private static void addLabel(MultipartBody.Builder mb, String label)
    {
        if (label == null) return;
        String clean = label.replaceAll("[^A-Za-z0-9 ]", " ").trim().replaceAll("\\s+", " ");
        if (clean.isEmpty()) return;
        mb.addFormDataPart("label", clean.length() > 60 ? clean.substring(0, 60) : clean);
    }

    /** Fetches an icon from the server's icon proxy. Returns null on any failure. */
    public byte[] icon(String proxyPath)
    {
        if (!IconRef.isProxyPath(proxyPath))
        {
            return null;
        }
        HttpUrl base = parseBaseUrl(baseUrl.get());
        if (base == null)
        {
            return null;
        }
        HttpUrl.Builder b = base.newBuilder();
        for (String seg : proxyPath.substring(1).split("/"))
        {
            b.addPathSegment(seg);
        }
        try (Response r = http.newCall(builder(b.build()).get().build()).execute())
        {
            ResponseBody rb = r.body();
            if (!r.isSuccessful() || rb == null || rb.contentLength() > MAX_ICON_BYTES)
            {
                return null;
            }
            // never buffer more than the limit, whatever Content-Length says (it is absent on chunked replies)
            okio.BufferedSource source = rb.source();
            source.request(MAX_ICON_BYTES + 1);
            if (source.getBuffer().size() > MAX_ICON_BYTES)
            {
                return null;
            }
            return source.readByteArray();
        }
        catch (IOException ex)
        {
            return null;
        }
    }

    // --- plumbing ---

    private HttpUrl url(String... segments)
    {
        HttpUrl base = parseBaseUrl(baseUrl.get());
        if (base == null)
        {
            throw new IllegalStateException("API base URL is not a valid https URL");
        }
        HttpUrl.Builder b = base.newBuilder();
        for (String s : segments)
        {
            if (s == null || s.isEmpty() || ".".equals(s) || "..".equals(s))
            {
                throw new IllegalArgumentException("bad path segment");
            }
            b.addPathSegment(s);
        }
        return b.build();
    }

    private Request.Builder builder(HttpUrl url)
    {
        return new Request.Builder().url(url)
            .header("X-API-Key", apiKey.get().trim())
            .header("Accept", "application/json")
            .header("X-Plugin-Version", pluginVersion)
            // this plugin reads decimal points (0.25); without it the server sends whole numbers, as older plugins need
            .header("X-Plugin-Decimals", "1")
            .header("User-Agent", "ForgeBingo-RuneLite/" + pluginVersion);
    }

    private <T> ApiResult<T> get(HttpUrl url, Class<T> type)
    {
        return execute(builder(url).get().build(), type);
    }

    private <T> ApiResult<T> execute(Request request, Class<T> type)
    {
        return execute(http, request, type);
    }

    private <T> ApiResult<T> execute(OkHttpClient client, Request request, Class<T> type)
    {
        try (Response r = client.newCall(request).execute())
        {
            long retryAfter = Backoff.parseRetryAfterMillis(r.header("Retry-After"));
            String etag = r.header("ETag");
            ResponseBody rb = r.body();
            String text = rb == null ? "" : readLimited(rb);
            if (r.isSuccessful())
            {
                T parsed = null;
                if (type != Void.class && !text.isEmpty())
                {
                    try
                    {
                        parsed = sanitize(gson.fromJson(text, type));
                    }
                    catch (JsonSyntaxException ex)
                    {
                        // 2xx with garbage: treat as transient so we do not lose the event on a bad proxy page.
                        return new ApiResult<>(0, null, "unreadable response", null, null, 0);
                    }
                }
                return new ApiResult<>(r.code(), parsed, null, null, etag, retryAfter);
            }
            String error = null;
            String code = null;
            try
            {
                ApiModels.ErrorBody eb = gson.fromJson(text, ApiModels.ErrorBody.class);
                if (eb != null)
                {
                    code = clip(eb.error);
                    error = clip(eb.message);
                }
            }
            catch (RuntimeException ignored)
            {
                // non-JSON error body
            }
            return new ApiResult<>(r.code(), null, error, code, etag, retryAfter);
        }
        catch (IOException ex)
        {
            return new ApiResult<>(0, null, ex.getClass().getSimpleName(), null, null, 0);
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T sanitize(T v)
    {
        if (v instanceof ApiModels.BoardsResponse) return (T) Sanitizer.boards((ApiModels.BoardsResponse) v);
        if (v instanceof ApiModels.LeaderboardResponse) return (T) Sanitizer.leaderboard((ApiModels.LeaderboardResponse) v);
        if (v instanceof ApiModels.BoardResponse) return (T) Sanitizer.board((ApiModels.BoardResponse) v);
        if (v instanceof ApiModels.EventResult) return (T) Sanitizer.result((ApiModels.EventResult) v);
        if (v instanceof ApiModels.Me) return (T) Sanitizer.me((ApiModels.Me) v);
        if (v instanceof ApiModels.CatalogueResponse) return (T) Sanitizer.catalogue((ApiModels.CatalogueResponse) v);
        if (v instanceof ApiModels.HelloResponse) return (T) Sanitizer.hello((ApiModels.HelloResponse) v);
        return v;
    }

    /** Server error text is shown to the player and kept with queued events: keep it short. */
    private static String clip(String s)
    {
        if (s == null) return null;
        String t = Sanitizer.str(s);
        return t == null || t.length() <= 200 ? t : t.substring(0, 200);
    }

    private static String readLimited(ResponseBody rb) throws IOException
    {
        okio.BufferedSource source = rb.source();
        source.request(MAX_BODY_BYTES + 1);
        if (source.getBuffer().size() > MAX_BODY_BYTES)
        {
            throw new IOException("response too large");
        }
        return source.readUtf8();
    }
}

