package com.forgebingo.core;

/** Outcome of one HTTP call. {@code status == 0} means the request never completed. */
public final class ApiResult<T>
{
    public final int status;
    public final T body;
    /** Human-readable message. */
    public final String error;
    /** Machine code from the server's error body, e.g. invalid_rsn. */
    public final String errorCode;
    public final String etag;
    public final long retryAfterMillis;

    public ApiResult(int status, T body, String error, String errorCode, String etag, long retryAfterMillis)
    {
        this.status = status;
        this.body = body;
        this.error = error;
        this.errorCode = errorCode;
        this.etag = etag;
        this.retryAfterMillis = retryAfterMillis;
    }

    public ErrorClass errorClass()
    {
        return ErrorClass.of(status, errorCode);
    }

    public boolean ok()
    {
        return status >= 200 && status < 300;
    }

    public boolean notModified()
    {
        return status == 304;
    }

    /** True when this should leave a user-visible failure (not 304, not success). */
    public String describe()
    {
        if (status == 0)
        {
            return error == null ? "network error" : error;
        }
        String head = errorCode != null ? errorCode : error;
        return "HTTP " + status + (head == null ? "" : ": " + head) + (errorCode != null && error != null ? " (" + error + ")" : "");
    }
}

package com.forgebingo.core;

import java.util.Random;

/** Exponential backoff with jitter that honours Retry-After. */
public final class Backoff
{
    public static final long BASE_MILLIS = 5_000L;
    public static final long MAX_MILLIS = 15 * 60_000L;

    private Backoff()
    {
    }

    /**
     * @param attempt number of failed attempts so far (1 = first failure)
     * @param retryAfterMillis server hint, or &lt;= 0 for none
     * @param random jitter source (null for no jitter)
     */
    public static long delayMillis(int attempt, long retryAfterMillis, Random random)
    {
        int exponent = Math.min(Math.max(0, attempt - 1), 10);
        long delay = Math.min(MAX_MILLIS, BASE_MILLIS * (1L << exponent));
        if (random != null)
        {
            delay = (long) (delay * (0.8 + 0.4 * random.nextDouble()));
        }
        if (retryAfterMillis > 0)
        {
            delay = Math.max(delay, Math.min(retryAfterMillis, MAX_MILLIS));
        }
        return delay;
    }

    /** Parses a Retry-After header holding delta-seconds; HTTP-dates are ignored. */
    public static long parseRetryAfterMillis(String header)
    {
        if (header == null)
        {
            return 0;
        }
        try
        {
            long seconds = Long.parseLong(header.trim());
            return seconds <= 0 ? 0 : Math.min(seconds * 1000L, MAX_MILLIS);
        }
        catch (NumberFormatException ex)
        {
            return 0;
        }
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * What to celebrate when a freshly fetched board is compared with the tiles already seen finished: teammates' tiles,
 * a new line, a blackout. Decides only; the plugin shows it and remembers what was seen.
 */
public final class BoardCelebrations
{
    private BoardCelebrations()
    {
    }

    /** The outcome of comparing a board with what was seen before. */
    public static final class Change
    {
        /** nothing was known about this board yet: record {@link #done}, replay nothing (a blackout still shows) */
        public boolean firstLook;
        /** every tile on the board is finished */
        public boolean all;
        /** ids of the tiles finished on this board now: add them to what was seen */
        public final Set<String> done = new HashSet<>();
        /** shown titles of tiles finished since the last look (by a teammate: the player's own are marked seen first) */
        public final List<String> finishedTitles = new ArrayList<>();
        /** lines completed since the last look, 0 when the count of finished tiles did not grow */
        public int newLines;

        /** the banner for {@link #newLines}, or null when there is no new line */
        public String lineText()
        {
            return newLines <= 0 ? null : newLines > 1 ? "Double line complete!" : "Line complete!";
        }
    }

    /**
     * @param seen tile ids already seen finished on this board, or null on the first look of the session (not changed)
     */
    public static Change changes(Set<String> seen, ApiModels.BoardResponse board)
    {
        Change c = new Change();
        for (ApiModels.Tile t : board.tiles)
        {
            if (t.completed && t.id != null) c.done.add(t.id);
        }
        c.all = !board.tiles.isEmpty() && c.done.size() >= board.tiles.size();
        if (seen == null)
        {
            c.firstLook = true;
            return c;
        }
        int size = board.size();
        int linesBefore = countLines(seen, board, size);
        Set<String> after = new HashSet<>(seen);
        for (ApiModels.Tile t : board.tiles)
        {
            if (t.completed && t.id != null && after.add(t.id)) c.finishedTitles.add(TileInfo.shownTitle(t));
        }
        int linesAfter = countLines(after, board, size);
        if (linesAfter > linesBefore && c.done.size() > seen.size()) c.newLines = linesAfter - linesBefore;
        return c;
    }

    /** Finished rows, columns and the two diagonals of a size x size board, given the ids of its finished tiles. */
    public static int countLines(Set<String> doneIds, ApiModels.BoardResponse board, int size)
    {
        boolean[][] d = new boolean[size][size];
        for (ApiModels.Tile t : board.tiles)
        {
            if (t.id != null && doneIds.contains(t.id) && t.row < size && t.col < size) d[t.row][t.col] = true;
        }
        int n = 0;
        for (int i = 0; i < size; i++)
        {
            boolean row = true;
            boolean col = true;
            for (int j = 0; j < size; j++)
            {
                row &= d[i][j];
                col &= d[j][i];
            }
            if (row) n++;
            if (col) n++;
        }
        boolean diag = true;
        boolean anti = true;
        for (int i = 0; i < size; i++)
        {
            diag &= d[i][i];
            anti &= d[i][size - 1 - i];
        }
        if (diag) n++;
        if (anti) n++;
        return n;
    }
}

package com.forgebingo.core;

import java.awt.Rectangle;

/**
 * Where the on-screen board overlay goes (owner request, 2026-11-07): a centred board panel at most ~80% of the
 * smaller viewport side, its square grid of cells, the close button, the card a tile opens into, and hit-testing for
 * clicks. Everything but the cells grows with the board (see {@link #scale}), so the header, padding and close button
 * keep their proportions on a big game window instead of staying fixed-client sized. Pure and immutable, so the overlay (client thread) and the mouse listener (AWT thread) can share one.
 * Coordinates are game canvas coordinates: RuneLite's stretched mode translates mouse events into this space before
 * plugin listeners see them, and overlays draw in it too.
 */
public final class BoardLayout
{
    public static final double MAX_FRACTION = 0.8;
    public static final int MIN_CELL = 28;
    /** gap, padding, header height and close button side at scale 1 (the 765x503 fixed client) */
    public static final int GAP = 4;
    public static final int PAD = 12;
    public static final int HEADER = 46;
    public static final int CLOSE = 22;
    /** the board side (px) that scale 1 is designed for: 80% of the fixed client's 503px height */
    public static final double BASE_SIDE = 402;
    public static final double MAX_SCALE = 4;
    /** space kept free around the board when a small viewport forces it bigger than MAX_FRACTION */
    public static final int MARGIN = 4;

    public final int viewW;
    public final int viewH;
    public final int size;
    public final int cell;
    public final int gap;
    /** how much bigger than the fixed-client design everything is drawn: 1 on a 765x503 client, ~2.1 at 1080p */
    public final double scale;
    /** padding around the header and grid, the header's height and the close button's side, already scaled */
    public final int pad;
    public final int header;
    public final int close;
    private final int bx;
    private final int by;
    private final int bw;
    private final int bh;
    private final int gx;
    private final int gy;
    private final int cardX;
    private final int cardY;
    private final int cardW;
    private final int cardH;

    private BoardLayout(int viewW, int viewH, int size, int cell, int gap, double scale, int pad, int header, int close)
    {
        this.scale = scale;
        this.pad = pad;
        this.header = header;
        this.close = close;
        this.viewW = viewW;
        this.viewH = viewH;
        this.size = size;
        this.cell = cell;
        this.gap = gap;
        int grid = cell * size + gap * (size - 1);
        bw = grid + 2 * pad;
        bh = grid + header + 2 * pad;
        bx = (viewW - bw) / 2;
        by = (viewH - bh) / 2;
        gx = bx + pad;
        gy = by + header + pad;

        int maxW = Math.max(1, viewW - 16);
        int maxH = Math.max(1, viewH - 16);
        cardW = Math.min(maxW, Math.max(Math.min(260, maxW), (int) Math.round(bw * 0.6)));
        cardH = Math.min(maxH, Math.max(Math.min(220, maxH), (int) Math.round(bh * 0.7)));
        cardX = clamp(bx + (bw - cardW) / 2, 8, viewW - 8 - cardW);
        cardY = clamp(by + (bh - cardH) / 2, 8, viewH - 8 - cardH);
    }

    /** Lays out an N x N board (N clamped to 1..20) in a viewport of the given size. */
    public static BoardLayout compute(int viewW, int viewH, int boardSize)
    {
        int vw = Math.max(1, viewW);
        int vh = Math.max(1, viewH);
        int n = Math.max(1, Math.min(20, boardSize));
        int avail = (int) (Math.min(vw, vh) * MAX_FRACTION);
        double scale = Math.max(1, Math.min(MAX_SCALE, avail / BASE_SIDE));
        int pad = (int) Math.round(PAD * scale);
        int header = (int) Math.round(HEADER * scale);
        int close = (int) Math.round(CLOSE * scale);
        // the panel is taller than wide (header), so the height decides the grid side
        int gridAvail = avail - header - 2 * pad;
        // gaps grow with the board, but never eat into the cells of a board with many tiles
        int gap = Math.max(GAP, Math.min((int) Math.round(GAP * scale), gridAvail / (n * 14)));
        int cell = (gridAvail - gap * (n - 1)) / n;
        if (cell < MIN_CELL)
        {
            // small viewport or big board: grow towards MIN_CELL while the board still fits on screen
            int fit = Math.min(vw - 2 * MARGIN - 2 * pad, vh - 2 * MARGIN - header - 2 * pad);
            int fitCell = (fit - gap * (n - 1)) / n;
            if (fitCell < 8)
            {
                gap = 1;
                fitCell = (fit - (n - 1)) / n;
            }
            cell = Math.max(cell, Math.min(MIN_CELL, fitCell));
        }
        return new BoardLayout(vw, vh, n, Math.max(2, cell), gap, scale, pad, header, close);
    }

    /** The whole board panel (background, header and grid). */
    public Rectangle board()
    {
        return new Rectangle(bx, by, bw, bh);
    }

    /** The square grid of cells inside the panel. */
    public Rectangle grid()
    {
        int side = cell * size + gap * (size - 1);
        return new Rectangle(gx, gy, side, side);
    }

    public Rectangle cell(int row, int col)
    {
        return new Rectangle(gx + col * (cell + gap), gy + row * (cell + gap), cell, cell);
    }

    /** The close button in the header's top-right corner. */
    public Rectangle closeButton()
    {
        return new Rectangle(bx + bw - pad - close, by + pad, close, close);
    }

    /** The card a clicked tile opens into: centred on the board, ~60% of its width, kept inside the viewport. */
    public Rectangle card()
    {
        return new Rectangle(cardX, cardY, cardW, cardH);
    }

    /** The small "no board yet" message box, centred. */
    public static Rectangle message(int viewW, int viewH)
    {
        int w = Math.min(Math.max(1, viewW - 16), 340);
        int h = Math.min(Math.max(1, viewH - 16), 64);
        return new Rectangle((viewW - w) / 2, (viewH - h) / 2, w, h);
    }

    /** Index (row * size + col) of the cell under the point, or -1 for the gaps and anything off the grid. */
    public int cellAt(int x, int y)
    {
        int dx = x - gx;
        int dy = y - gy;
        if (dx < 0 || dy < 0) return -1;
        int step = cell + gap;
        int col = dx / step;
        int row = dy / step;
        if (col >= size || row >= size) return -1;
        if (dx - col * step >= cell || dy - row * step >= cell) return -1;
        return row * size + col;
    }

    public boolean insideBoard(int x, int y)
    {
        return x >= bx && y >= by && x < bx + bw && y < by + bh;
    }

    public boolean onCloseButton(int x, int y)
    {
        return closeButton().contains(x, y);
    }

    public boolean insideCard(int x, int y)
    {
        return x >= cardX && y >= cardY && x < cardX + cardW && y < cardY + cardH;
    }

    /** Smooth both ways (cubic ease-in-out) over 0..1 (clamped): for things that fade or grow in place. */
    public static double easeInOut(double t)
    {
        double c = Math.max(0, Math.min(1, t));
        return c < 0.5 ? 4 * c * c * c : 1 - Math.pow(-2 * c + 2, 3) / 2;
    }

    /** Cubic ease-out over 0..1 (clamped): fast start, soft landing. */
    public static double easeOut(double t)
    {
        double c = Math.max(0, Math.min(1, t));
        return 1 - Math.pow(1 - c, 3);
    }

    private static int clamp(int v, int lo, int hi)
    {
        if (hi < lo) return Math.max(0, (lo + hi) / 2); // no room for the margins: centre it
        return Math.max(lo, Math.min(hi, v));
    }
}

package com.forgebingo.core;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Which of the player's boards is shown, from the list GET /v1/boards returns: the one they picked, else the first
 * live one, else the first. Also how many are live and whether one has just opened (the shared reveal).
 */
public final class BoardSelection
{
    private BoardSelection()
    {
    }

    /** The team board ids in the list. */
    public static Set<String> ids(List<ApiModels.BoardSummary> boards)
    {
        Set<String> ids = new HashSet<>();
        if (boards != null) for (ApiModels.BoardSummary b : boards) if (b != null) ids.add(b.teamBoardId);
        return ids;
    }

    /** How many of the boards are live right now (a drop can count for one that is not selected). */
    public static int liveCount(List<ApiModels.BoardSummary> boards)
    {
        int live = 0;
        if (boards != null) for (ApiModels.BoardSummary b : boards) if (b != null && b.active) live++;
        return live;
    }

    /**
     * A live board that was not in the list before: its bingo has just started. Null on the first list of a session
     * (knownBefore is null then: nothing can be new yet) and when nothing opened. The first one in list order wins.
     */
    public static ApiModels.BoardSummary newlyOpened(List<ApiModels.BoardSummary> boards, Set<String> knownBefore)
    {
        if (boards == null || knownBefore == null) return null;
        for (ApiModels.BoardSummary b : boards)
        {
            if (b == null || knownBefore.contains(b.teamBoardId) || !b.active) continue;
            return b;
        }
        return null;
    }

    /** The board to show: the wanted one when it is in the list, else the first live one, else the first, else null. */
    public static ApiModels.BoardSummary select(List<ApiModels.BoardSummary> boards, String wanted)
    {
        if (boards == null) return null;
        ApiModels.BoardSummary selected = null;
        for (ApiModels.BoardSummary b : boards)
        {
            if (b != null && b.teamBoardId != null && b.teamBoardId.equals(wanted)) selected = b;
        }
        if (selected == null)
        {
            for (ApiModels.BoardSummary b : boards)
            {
                if (b != null && b.active) { selected = b; break; }
            }
            if (selected == null && !boards.isEmpty()) selected = boards.get(0);
        }
        return selected;
    }
}

package com.forgebingo.core;

import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Pure parsing of game chat messages. No RuneLite dependencies so it is unit-testable. */
public final class ChatParsers
{
    private static final Pattern TAGS = Pattern.compile("<[^>]*>");
    private static final Pattern COLLECTION_LOG = Pattern.compile("^New item added to your collection log: (.+?)\\.?$");
    // Counts above 999 are printed with thousands separators ("1,234").
    private static final Pattern KC = Pattern.compile(
        "^Your (?:completed |subdued )?(.+?) (?:(?:kill|harvest|lap|completion|chest) )?count is: ([0-9][0-9,]{0,12})\\.?$");
    private static final Pattern KC_FOR = Pattern.compile("^Your completion count for (.+?) is: ([0-9][0-9,]{0,12})\\.?$");
    /** "You have completed 12 hard Treasure Trails." (singular for the first one). */
    private static final Pattern CLUE = Pattern.compile(
        "^You have completed ([0-9][0-9,]{0,12}) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?$", Pattern.CASE_INSENSITIVE);
    private static final Pattern PET_NORMAL = Pattern.compile("^You have a funny feeling like you.?re being followed\\.?$");
    private static final Pattern PET_BACKPACK = Pattern.compile("^You feel something weird sneaking into your backpack\\.?$");
    private static final Pattern PET_DUPE = Pattern.compile("^You have a funny feeling like you would have been followed\\.{0,3}$");
    /**
     * Clan broadcast, the only line that names a duplicate pet:
     * "Zezima has a funny feeling like he's being followed: Vorki at 1,234 killcount.",
     * "Zezima feels something weird sneaking into her backpack: Heron at 99 Fishing.",
     * "Zezima has a funny feeling like they would have been followed: Olmlet at 50 killcount."
     */
    private static final Pattern PET_BROADCAST = Pattern.compile(
        "^([A-Za-z0-9 _-]{1,12}) (?:has a funny feeling like \\S+(?: \\S+)?? (?:(would have been)|(?:is |are )?being) followed"
            + "|feels something weird sneaking into \\S+ backpack): (.+?)(?: at [0-9][0-9,]* .*?)?\\.?$");

    private ChatParsers()
    {
    }

    public static String stripTags(String message)
    {
        if (message == null)
        {
            return "";
        }
        return TAGS.matcher(message).replaceAll("").replace(' ', ' ').trim();
    }

    public static final class Kc
    {
        public final String boss;
        public final int count;

        Kc(String boss, int count)
        {
            this.boss = boss;
            this.count = count;
        }
    }

    /** "Congratulations, you've completed a hard combat task: Noxious Foe (3 points)." (owner, 2026-11-11; hidden for now) */
    private static final Pattern COMBAT_TASK = Pattern.compile(
        "^Congratulations, you.?ve completed an? (easy|medium|hard|elite|master|grandmaster) combat task: (.+?)(?: \\(\\d+ points?\\))?\\.?$",
        Pattern.CASE_INSENSITIVE);

    public static final class CombatTask
    {
        public final String tier;
        public final String name;

        CombatTask(String tier, String name)
        {
            this.tier = tier;
            this.name = name;
        }
    }

    public static Optional<CombatTask> combatTask(String message)
    {
        Matcher m = COMBAT_TASK.matcher(stripTags(message));
        return m.matches() ? Optional.of(new CombatTask(m.group(1).toLowerCase(java.util.Locale.ROOT), m.group(2).trim())) : Optional.empty();
    }

    public static Optional<String> collectionLogItem(String message)
    {
        Matcher m = COLLECTION_LOG.matcher(stripTags(message));
        return m.matches() ? Optional.of(m.group(1).trim()) : Optional.empty();
    }

    public static Optional<Kc> killCount(String message)
    {
        String text = stripTags(message);
        Matcher m = KC.matcher(text);
        if (!m.matches())
        {
            m = KC_FOR.matcher(text);
            if (!m.matches())
            {
                return Optional.empty();
            }
        }
        Integer n = count(m.group(2));
        return n == null ? Optional.empty() : Optional.of(new Kc(m.group(1).trim(), n));
    }

    private static Integer count(String digits)
    {
        try
        {
            return Integer.parseInt(digits.replace(",", ""));
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
    }

    public static final class Clue
    {
        /** lower-case tier: beginner .. master */
        public final String tier;
        public final int count;

        Clue(String tier, int count)
        {
            this.tier = tier;
            this.count = count;
        }

        /** sourceName for the {@code kc} event; an alias of the {@code clue_<tier>} catalogue source. */
        public String sourceName()
        {
            return "Clue scroll (" + tier + ")";
        }
    }

    /** Treasure Trail completion: "You have completed N <tier> Treasure Trails." */
    public static Optional<Clue> clueCompletion(String message)
    {
        Matcher m = CLUE.matcher(stripTags(message));
        if (!m.matches())
        {
            return Optional.empty();
        }
        Integer n = count(m.group(1));
        return n == null ? Optional.empty() : Optional.of(new Clue(m.group(2).toLowerCase(java.util.Locale.ROOT), n));
    }

    public enum Pet
    {
        /** New pet, now following the player. */
        FOLLOWING,
        /** New pet, put into the backpack (the player already had a follower). */
        BACKPACK,
        /** Duplicate: the player already owns it; nothing appears. */
        DUPLICATE;

        public boolean isNew()
        {
            return this != DUPLICATE;
        }
    }

    public static Optional<Pet> pet(String message)
    {
        String text = stripTags(message);
        if (PET_NORMAL.matcher(text).matches())
        {
            return Optional.of(Pet.FOLLOWING);
        }
        if (PET_BACKPACK.matcher(text).matches())
        {
            return Optional.of(Pet.BACKPACK);
        }
        if (PET_DUPE.matcher(text).matches())
        {
            return Optional.of(Pet.DUPLICATE);
        }
        return Optional.empty();
    }

    public static final class PetBroadcast
    {
        public final String player;
        public final String petName;
        public final boolean duplicate;

        PetBroadcast(String player, String petName, boolean duplicate)
        {
            this.player = player;
            this.petName = petName;
            this.duplicate = duplicate;
        }
    }

    /** A clan "funny feeling" broadcast; the caller checks {@code player} against the local player. */
    public static Optional<PetBroadcast> petBroadcast(String message)
    {
        Matcher m = PET_BROADCAST.matcher(stripTags(message));
        if (!m.matches())
        {
            return Optional.empty();
        }
        return Optional.of(new PetBroadcast(m.group(1).trim(), m.group(3).trim(), m.group(2) != null));
    }
}

package com.forgebingo.core;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * A raid with more than one reward chest (The Fractured Archive: the standard chest, plus a second one for whoever
 * rolled the unique). RuneLite's loot tracker reports only the first chest opened in a raid, so the plugin reads the
 * chest window itself each time it opens. This remembers what that raid's chests have already shown, so opening the
 * same chest again reports nothing and a second chest reports only what is new, whether the game shows each chest's
 * loot on its own or adds it to the first chest's. Pure Java so it is unit-tested without RuneLite.
 */
public final class ChestOpens
{
    private final Map<Integer, Integer> reported = new HashMap<>();

    /**
     * @param contents item id to quantity, as the chest window shows it now
     * @return what has not been reported yet in this raid (empty when there is nothing new)
     */
    public Map<Integer, Integer> opened(Map<Integer, Integer> contents)
    {
        Map<Integer, Integer> fresh = new LinkedHashMap<>();
        if (contents == null) return fresh;
        for (Map.Entry<Integer, Integer> c : contents.entrySet())
        {
            int had = reported.getOrDefault(c.getKey(), 0);
            if (c.getValue() > had) fresh.put(c.getKey(), c.getValue() - had);
        }
        // a window showing one chest at a time: what it showed before still counts as reported
        for (Map.Entry<Integer, Integer> c : contents.entrySet()) reported.merge(c.getKey(), c.getValue(), Math::max);
        return fresh;
    }

    /** The raid is over (the player left the instance or logged out). */
    public void reset()
    {
        reported.clear();
    }
}

package com.forgebingo.core;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * Chexy (owner's reference, 2026-11-14): a glowing rainbow "atom" that drifts over the side panel as a rare
 * visitor. Four thin tilted rings turn and precess; bright comets ride them with long neon light trails that fade
 * back into the ring, and tiny glints twinkle along the rings and around it. Drawn with Java2D rather than a pixel
 * grid so the glow and the trails stay smooth. A point's colour comes from where it sits around the centre (yellow
 * on the right, green and cyan below, blue and violet on the left, magenta and red on top), so a comet sweeps
 * through the whole wheel on every lap.
 *
 * The comets are steered by the angle they sit at around the centre, spaced evenly round the wheel with only a
 * small sway, so they never bunch up; where that angle falls on each comet's ring is solved exactly.
 *
 * The power-up (owner, 2026-11-14): on a power-up visit (half its visits; the rest are spell visits) Chexy powers up, anime style. A few seconds as itself, then it
 * charges (it trembles, its rings spin up, sparks crackle and the glow pulses), flashes, and comes back in its GOLD
 * FORM, with gold rings and a tall flickering flame aura, lightning and rising specks. Later it charges again and
 * flashes into its BLUE FORM: cyan and electric blue, with a calmer, steadier aura and a blue shimmer. It stays blue
 * until the visit ends and it pops out. Everything is a pure function of the clocks: no state, and nothing big is
 * allocated per frame.
 */
public final class Chexy
{
    private Chexy()
    {
    }

    /** how wide it is at normal size, in pixels (the rings; the glow, and in a form the aura, reach further) */
    public static final float SIZE = 38f;
    /** how fast the comets go round (rad/s): one lap every LAP seconds; the twinkles keep time with it */
    public static final float LAP = 2.52f;
    private static final float W = (float) (Math.PI * 2 / LAP);

    // ------------------------------------------------------------------ the power-up, by seconds into the visit
    /** the forms */
    public static final int BASE = 0, GOLD = 1, BLUE = 2;
    /** seconds as itself before the first charge (on a power-up visit; a spell visit stays itself: ChexySpells) */
    public static final float CHARGE_AT = 6f;
    /** how long a charge-up lasts */
    public static final float CHARGE_TIME = 1.8f;
    /** the flash into the gold form */
    public static final float GOLD_AT = CHARGE_AT + CHARGE_TIME;
    /** the second charge (the gold form holds 26 s) */
    public static final float CHARGE2_AT = GOLD_AT + 26f;
    /** the flash into the blue form, which then holds until the visit ends (a visit lasts 60-90 s) */
    public static final float BLUE_AT = CHARGE2_AT + CHARGE_TIME;

    /**
     * The power-up's clock for a visit: the visit's age on a power-up visit, -1 (the base form throughout) on a spell
     * visit. Each visit is one or the other, never both (owner).
     */
    public static float powerAge(boolean spellVisit, float visitAge)
    {
        return spellVisit ? -1f : visitAge;
    }

    /** which form it is in, this many seconds into its visit (below 0: no visit, always the base form) */
    public static int form(float age)
    {
        return age < GOLD_AT ? BASE : age < BLUE_AT ? GOLD : BLUE;
    }

    /** how far into a charge-up it is, 0 (none) to 1 (about to flash) */
    public static float charge(float age)
    {
        if (age >= CHARGE_AT && age < GOLD_AT) return (age - CHARGE_AT) / CHARGE_TIME;
        if (age >= CHARGE2_AT && age < BLUE_AT) return (age - CHARGE2_AT) / CHARGE_TIME;
        return 0f;
    }

    /** the white flash at a change of form, 0 to 1 */
    static float flash(float age)
    {
        float d = Math.abs(age - GOLD_AT) < Math.abs(age - BLUE_AT) ? age - GOLD_AT : age - BLUE_AT;
        if (d < -0.12f || d > 0.55f) return 0f;
        if (d < 0) return 1f + d / 0.12f;
        float k = 1f - d / 0.55f;
        return k * k;
    }

    /** seconds since the last change of form (for the shock ring and the aura flaring up) */
    private static float sinceChange(float age)
    {
        return age >= BLUE_AT ? age - BLUE_AT : age >= GOLD_AT ? age - GOLD_AT : 99f;
    }

    /**
     * How fast its own clock should run, this far into the visit: the rings spin up while it charges and stay a
     * little quicker in its forms. The caller advances Chexy's clock by dt times this.
     */
    public static float spin(float age)
    {
        float c = charge(age);
        if (c > 0) return (form(age) == GOLD ? 1.45f : 1f) + 1.7f * c * c;
        int f = form(age);
        return f == GOLD ? 1.45f : f == BLUE ? 1.25f : 1f;
    }

    private static final int RINGS = 4;
    private static final int SEGS = 64;
    private static final int HUES = 64;
    private static final int ALPHAS = 32;
    private static final double TAU = Math.PI * 2;

    /** per form: saturated glow colours and pale core colours, by hue bin and alpha step (made once) */
    private static final Color[][][] GLOW = new Color[3][HUES][ALPHAS];
    private static final Color[][][] CORE = new Color[3][HUES][ALPHAS];
    private static final Color[] WHITE = new Color[ALPHAS];
    /** the aura's three layers per form (outer, middle, inner), then the lightning glow, by alpha step */
    private static final Color[][][] AURA = new Color[3][4][ALPHAS];
    private static final Composite[] FADE = new Composite[ALPHAS];

    static
    {
        for (int h = 0; h < HUES; h++)
        {
            double wave = Math.sin(h / (double) HUES * TAU * 2);
            int[] glow = {
                Color.HSBtoRGB(h / (float) HUES, 0.9f, 1f),
                // gold: amber to yellow, rippling round the wheel so the rings still shimmer
                Color.HSBtoRGB((float) (0.118 + 0.028 * wave), 0.86f, 1f),
                // blue: cyan to electric blue
                Color.HSBtoRGB((float) (0.545 + 0.045 * wave), 0.82f, 1f),
            };
            int[] core = {
                Color.HSBtoRGB(h / (float) HUES, 0.45f, 1f),
                Color.HSBtoRGB(0.14f, 0.3f, 1f),
                Color.HSBtoRGB(0.52f, 0.22f, 1f),
            };
            for (int f = 0; f < 3; f++)
            {
                for (int a = 0; a < ALPHAS; a++)
                {
                    int alpha = Math.round(255f * (a + 1) / ALPHAS);
                    GLOW[f][h][a] = new Color((glow[f] & 0xffffff) | alpha << 24, true);
                    CORE[f][h][a] = new Color((core[f] & 0xffffff) | alpha << 24, true);
                }
            }
        }
        int[][] aura = {
            {0xffffff, 0xffffff, 0xffffff, 0xffffff},
            {0xff8a1a, 0xffc93a, 0xfff3b8, 0xffe27a},
            {0x2f6dff, 0x39cfff, 0xd9f7ff, 0x8fe8ff},
        };
        for (int a = 0; a < ALPHAS; a++)
        {
            int alpha = Math.round(255f * (a + 1) / ALPHAS);
            WHITE[a] = new Color(255, 255, 255, alpha);
            FADE[a] = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (a + 1) / (float) ALPHAS);
            for (int f = 0; f < 3; f++)
            {
                for (int l = 0; l < 4; l++) AURA[f][l][a] = new Color(aura[f][l] | alpha << 24, true);
            }
        }
    }

    /** the glow behind it, per form: a faint lumpy blue-violet nebula, a warm gold blaze, a cold blue one */
    private static final BufferedImage[] HAZE = {haze(0), haze(1), haze(2)};
    /** the flash at a change of form: white light, bright in the middle and fading softly out */
    private static final BufferedImage BLOOM = bloom();

    private static BufferedImage bloom()
    {
        int n = 48;
        BufferedImage img = new BufferedImage(n, n, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < n; y++)
        {
            for (int x = 0; x < n; x++)
            {
                double dx = (x + 0.5) / n * 2 - 1;
                double dy = (y + 0.5) / n * 2 - 1;
                double d = Math.min(1, Math.sqrt(dx * dx + dy * dy));
                int a = (int) Math.round(255 * Math.pow(1 - d, 1.8));
                img.setRGB(x, y, a << 24 | 0xfffdf4);
            }
        }
        return img;
    }

    private static BufferedImage haze(int form)
    {
        int n = 48;
        BufferedImage img = new BufferedImage(n, n, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < n; y++)
        {
            for (int x = 0; x < n; x++)
            {
                double dx = (x + 0.5) / n * 2 - 1;
                double dy = (y + 0.5) / n * 2 - 1;
                double d = Math.min(1, Math.sqrt(dx * dx + dy * dy));
                double fall = Math.pow(1 - d, 2.2);
                double lump = 0.5 + 0.25 * Math.sin(dx * 5.1 + dy * 2.3) + 0.25 * Math.sin(dy * 6.3 - dx * 3.7 + 1.3);
                double mix = 0.5 + 0.5 * Math.sin(dx * 3.2 - dy * 2.1 + 0.6);
                int rr, gg, bb, a;
                if (form == BASE)
                {
                    rr = (int) (28 + 70 * mix);
                    gg = (int) (30 + 8 * mix);
                    bb = (int) (150 + 40 * (1 - mix));
                    a = (int) Math.round(72 * fall * (0.4 + 0.6 * lump));
                }
                else if (form == GOLD)
                {
                    rr = 255;
                    gg = (int) (195 + 50 * (1 - d));
                    bb = (int) (80 + 110 * (1 - d) * (1 - d));
                    a = (int) Math.round(72 * fall * (0.75 + 0.25 * lump));
                }
                else
                {
                    rr = (int) (60 + 120 * (1 - d) * (1 - d));
                    gg = (int) (170 + 60 * (1 - d));
                    bb = 255;
                    a = (int) Math.round(70 * fall * (0.75 + 0.25 * lump));
                }
                img.setRGB(x, y, a << 24 | rr << 16 | gg << 8 | bb);
            }
        }
        return img;
    }

    // per ring: starting tilt, how fast the tilt turns (precession), size
    private static final float[] TILT = {0.25f, 1.05f, 1.85f, 2.65f};
    private static final float[] PRECESS = {0.15f, 0.12f, 0.17f, 0.13f};
    private static final float[] REACH = {1f, 0.93f, 0.97f, 0.88f};
    /** which ring each comet rides; the comets sit evenly round the wheel */
    private static final int[] COMET_RING = {0, 1, 2, 3, 1};
    private static final int COMETS = COMET_RING.length;
    private static final float SWAY = 0.3f; // < half the spacing, so neighbours can never meet
    private static final float TRAIL = 0.8f; // how much of a lap the light trail covers

    /** glints along the rings: ring, place on it, twinkle (times the lap speed), phase */
    private static final float[][] GLINTS = {
        {0, 0.9f, 2, 0.3f}, {1, 3.6f, 3, 2.1f}, {2, 5.2f, 2, 4.0f}, {3, 2.2f, 3, 5.2f}, {0, 4.4f, 1, 1.4f}, {2, 1.6f, 1, 3.3f},
    };
    /** ambient star specks: angle, distance (of the radius), twinkle (times the lap speed), phase */
    private static final float[][] SPECKS = {
        {0.3f, 1.2f, 1, 0.0f}, {1.4f, 1.3f, 2, 1.7f}, {2.2f, 1.25f, 1, 3.1f}, {3.0f, 1.35f, 2, 4.4f},
        {3.9f, 1.22f, 1, 2.2f}, {4.7f, 1.32f, 2, 5.3f}, {5.4f, 1.18f, 1, 0.9f}, {6.0f, 1.28f, 2, 3.8f},
    };

    private static final ThreadLocal<Scratch> SCRATCH = ThreadLocal.withInitial(Scratch::new);

    /** reused per thread: ring points and brightness, and the strokes for the last size drawn */
    private static final class Scratch
    {
        final float[][] rx = new float[RINGS][SEGS + 1];
        final float[][] ry = new float[RINGS][SEGS + 1];
        final float[][] ra = new float[RINGS][SEGS];
        final float[][] rd = new float[RINGS][SEGS];
        final float[] ra2 = new float[RINGS];
        final float[] rb2 = new float[RINGS];
        final float[] rc = new float[RINGS];
        final float[] rs = new float[RINGS];
        final double[] headU = new double[COMETS];
        final float[] p = new float[2];
        final Path2D.Float path = new Path2D.Float();
        final Line2D.Float line = new Line2D.Float();
        final Ellipse2D.Float dot = new Ellipse2D.Float();
        float strokeScale = -1;
        Stroke wide, mid, core, hot, thin, bolt;

        void strokes(float s)
        {
            if (s == strokeScale) return;
            strokeScale = s;
            // the glow passes have butt ends so neighbouring translucent runs meet instead of overlapping
            wide = new BasicStroke(3.6f * s, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND);
            mid = new BasicStroke(1.7f * s, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND);
            core = new BasicStroke(Math.max(0.6f, 0.75f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
            hot = new BasicStroke(Math.max(0.5f, 0.55f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
            thin = new BasicStroke(Math.max(0.45f, 0.55f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
            bolt = new BasicStroke(Math.max(1f, 2.2f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        }
    }

    /** hue bin for a point at (x, y) from the centre: yellow on the right, round through green, cyan, blue, violet, red */
    private static int hue(float x, float y, float shift)
    {
        double h = 0.16 + Math.atan2(y, x) / TAU + shift;
        h -= Math.floor(h);
        return Math.min(HUES - 1, (int) (h * HUES));
    }

    /** how round a ring looks right now: it nods as if tipping towards and away from you, never closing to a line */
    private static float squash(float t, int ring)
    {
        return 0.42f + 0.12f * (float) Math.sin(t * 0.47f + ring * 1.7f);
    }

    private static int step(float a)
    {
        return Math.max(0, Math.min(ALPHAS - 1, Math.round(a * ALPHAS) - 1));
    }

    /** a steady pseudo-random number in 0..1 for an integer (sparks and lightning pick their spots with it) */
    private static float hash(int n)
    {
        n = (n << 13) ^ n;
        n = n * (n * n * 15731 + 789221) + 1376312589;
        return (n & 0x7fffffff) / (float) 0x7fffffff;
    }

    /** the near half of a ring is brighter than the far half */
    private static float depth(double u)
    {
        return 0.6f + 0.4f * (0.5f + 0.5f * (float) Math.sin(u));
    }

    /** a point on a ring, by its place u along it: x into px[0], y into px[1] */
    private static void at(Scratch k, int ring, double u, float off, float[] px)
    {
        float ex = k.ra2[ring] * off * (float) Math.cos(u);
        float ey = k.rb2[ring] * off * (float) Math.sin(u);
        px[0] = ex * k.rc[ring] - ey * k.rs[ring];
        px[1] = ex * k.rs[ring] + ey * k.rc[ring];
    }

    /**
     * Draws it centred on (cx, cy), in its base form.
     *
     * @param t    its own clock in seconds (keep it running; the caller slows it for Calm)
     * @param size how wide the rings are, in pixels (SIZE is normal)
     * @param calm fewer sparkles
     */
    public static void paint(Graphics2D g, float cx, float cy, float t, float size, boolean calm)
    {
        paint(g, cx, cy, t, t, size, calm, -1f);
    }

    /**
     * As above, with the slow motions (the rings turning and nodding, the colour wheel creeping round) on a clock of
     * their own, and {@code age} the seconds since its visit began, which picks the power-up's stage (below 0: base
     * form). The panel passes the same clock for t and drift; a looping preview sways drift so it repeats.
     */
    public static void paint(Graphics2D g, float cx, float cy, float t, float drift, float size, boolean calm, float age)
    {
        paint(g, cx, cy, t, drift, size, calm, age, -1f);
    }

    /**
     * As above, for a visit on either path (owner: each visit either powers up or casts spells, never both):
     * {@code age} the seconds into a power-up visit (below 0: none, the base form throughout), {@code spellAge} the
     * seconds into a spell visit (below 0: no spells; ChexySpells). See {@link #powerAge} and ChexySpells.spellAge.
     */
    public static void paint(Graphics2D g, float cx, float cy, float t, float drift, float size, boolean calm, float age,
        float spellAge)
    {
        Scratch k = SCRATCH.get();
        float s = size / SIZE;
        k.strokes(s);
        Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Object sc = g.getRenderingHint(RenderingHints.KEY_STROKE_CONTROL);
        Object interp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        Stroke oldStroke = g.getStroke();
        Color oldColor = g.getColor();
        Composite oldComp = g.getComposite();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

        int form = age < 0 ? BASE : form(age);
        float charge = age < 0 ? 0f : charge(age);
        float flash = age < 0 ? 0f : flash(age);
        float since = age < 0 ? 99f : sinceChange(age);
        Color[][] glow = GLOW[form];
        Color[][] coreCol = CORE[form];

        // it trembles while it charges (harder towards the flash), and hums a little in its gold form
        if (!calm)
        {
            float shake = charge > 0 ? 1.6f * charge * charge + 0.25f : form == GOLD ? 0.3f : 0f;
            if (shake > 0)
            {
                cx += shake * s * (float) (Math.sin(t * 61.3) * 0.6 + Math.sin(t * 97.1 + 1.3) * 0.4);
                cy += shake * s * (float) (Math.sin(t * 73.7 + 0.4) * 0.6 + Math.sin(t * 89.9 + 2.2) * 0.4);
            }
        }

        // it breathes a little (faster as it charges), and the whole colour wheel turns very slowly
        float pulse = charge > 0 ? charge * (0.55f + 0.45f * (float) Math.sin(t * (14f + 16f * charge))) : 0f;
        float r = size * 0.5f * (1f + 0.03f * (float) Math.sin(t * W) + 0.05f * pulse);
        float shift = drift * 0.015f;
        float bright = form == BASE ? 1f : 1.12f;
        bright *= 1f + 0.5f * pulse;
        float[] p = k.p;

        // the glow behind it, brighter while it charges
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        int nr = Math.round(r * (form == BASE ? 1.3f : 1.6f));
        g.drawImage(HAZE[form], Math.round(cx) - nr, Math.round(cy) - nr, nr * 2, nr * 2, null);
        if (pulse > 0.05f)
        {
            // the charge glow takes on the colour it is about to become
            g.setComposite(FADE[step(Math.min(1f, pulse))]);
            int pr = Math.round(r * (1.3f + 0.4f * pulse));
            g.drawImage(HAZE[form == BASE ? GOLD : BLUE], Math.round(cx) - pr, Math.round(cy) - pr, pr * 2, pr * 2, null);
            g.setComposite(oldComp);
        }
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            interp == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : interp);
        // the soft glow while it casts the flower spell
        float flowers = spellAge < 0 ? -1f : ChexySpells.flowerPhase(spellAge);
        if (flowers >= 0) ChexySpells.paintCastGlow(g, cx, cy, r, flowers);

        // the aura: behind the rings. It flares up after a flash, swells in the second charge, and a faint gold
        // flicker already starts to show through in the first charge
        if (form != BASE || charge > 0.45f)
        {
            float amt;
            int af = form;
            if (form == BASE)
            {
                af = GOLD;
                float c = (charge - 0.45f) / 0.55f;
                amt = 0.5f * c * c;
            }
            else
            {
                amt = Math.min(1f, since / 0.35f) * (1f + 0.25f * Math.max(0f, 1f - since / 1.2f));
                if (charge > 0) amt *= 1f + 0.35f * charge;
            }
            aura(g, k, cx, cy, r, t, s, af, amt, calm);
        }

        // the rings: shape, then where each comet is
        for (int ring = 0; ring < RINGS; ring++)
        {
            double tilt = TILT[ring] + drift * PRECESS[ring];
            k.ra2[ring] = r * REACH[ring];
            k.rb2[ring] = k.ra2[ring] * squash(drift, ring);
            k.rc[ring] = (float) Math.cos(tilt);
            k.rs[ring] = (float) Math.sin(tilt);
            for (int i = 0; i <= SEGS; i++)
            {
                at(k, ring, TAU * i / SEGS, 1f, p);
                k.rx[ring][i] = p[0];
                k.ry[ring][i] = p[1];
            }
        }
        for (int c = 0; c < COMETS; c++)
        {
            int ring = COMET_RING[c];
            // the angle round the centre this comet sits at, then the place on its ring at that angle
            double theta = t * W + c * TAU / COMETS + SWAY * Math.sin(t * W + c * 2.1);
            double phi = theta - (TILT[ring] + drift * PRECESS[ring]);
            k.headU[c] = Math.atan2(k.ra2[ring] * Math.sin(phi), k.rb2[ring] * Math.cos(phi));
        }
        for (int ring = 0; ring < RINGS; ring++)
        {
            float[] al = k.ra[ring];
            float[] dp = k.rd[ring];
            for (int i = 0; i < SEGS; i++)
            {
                double u = TAU * (i + 0.5) / SEGS;
                float best = 0f;
                for (int c = 0; c < COMETS; c++)
                {
                    if (COMET_RING[c] != ring) continue;
                    double d = (k.headU[c] - u) / TAU;
                    d -= Math.floor(d);
                    if (d < TRAIL)
                    {
                        float f = 1f - (float) (d / TRAIL);
                        best = Math.max(best, (float) Math.pow(f, 1.7));
                    }
                }
                al[i] = best;
                dp[i] = depth(u);
            }
        }

        // four passes, wide and faint first, so the glow builds up like light does, then a hot white core
        for (int pass = 0; pass < 4; pass++)
        {
            g.setStroke(pass == 0 ? k.wide : pass == 1 ? k.mid : pass == 2 ? k.core : k.hot);
            int run = pass < 2 ? 4 : 2;
            for (int ring = 0; ring < RINGS; ring++)
            {
                float[] xs = k.rx[ring];
                float[] ys = k.ry[ring];
                float[] al = k.ra[ring];
                float[] dp = k.rd[ring];
                for (int i0 = 0; i0 < SEGS; i0 += run)
                {
                    float tr = 0f, dd = 0f;
                    for (int i = i0; i < i0 + run; i++)
                    {
                        tr += al[i];
                        dd += dp[i];
                    }
                    tr /= run;
                    dd /= run;
                    float alpha;
                    Color[][] table = glow;
                    if (pass == 0)
                    {
                        if (tr < 0.06f) continue;
                        alpha = 0.17f * tr * dd;
                    }
                    else if (pass == 1)
                    {
                        if (tr < 0.04f) continue;
                        alpha = 0.32f * tr * dd;
                    }
                    else if (pass == 2)
                    {
                        // the faint full ring is always there; the trail lights it up towards the comet
                        alpha = (0.22f + 0.78f * tr) * dd;
                        if (tr > 0.72f) table = coreCol;
                    }
                    else
                    {
                        if (tr < 0.6f) continue;
                        alpha = Math.min(1f, (tr - 0.6f) * 2.2f) * dd;
                        table = null;
                    }
                    alpha *= bright;
                    if (alpha < 0.03f) continue;
                    int mid = i0 + run / 2;
                    g.setColor(table == null ? WHITE[step(alpha)] : table[hue(xs[mid], ys[mid], shift)][step(alpha)]);
                    k.path.reset();
                    k.path.moveTo(cx + xs[i0], cy + ys[i0]);
                    for (int i = i0 + 1; i <= i0 + run; i++) k.path.lineTo(cx + xs[i], cy + ys[i]);
                    g.draw(k.path);
                }
            }
        }

        // glints that flash along the rings now and then
        g.setStroke(k.thin);
        int glints = calm ? 2 : GLINTS.length;
        for (int i = 0; i < glints; i++)
        {
            float[] gl = GLINTS[i];
            float tw = (float) Math.sin(t * W * gl[2] + gl[3]);
            if (tw <= 0.3f) continue;
            tw = (float) Math.pow(tw, 6);
            at(k, (int) gl[0], gl[1], 1f, p);
            star(g, k, cx + p[0], cy + p[1], tw, s, coreCol[hue(p[0], p[1], shift)]);
        }

        // the comet heads, with a few specks shed behind them
        g.setStroke(k.thin);
        for (int c = 0; c < COMETS; c++)
        {
            int ring = COMET_RING[c];
            double u = k.headU[c];
            float depth = depth(u);
            at(k, ring, u, 1f, p);
            float hx = p[0];
            float hy = p[1];
            int hh = hue(hx, hy, shift);
            g.setColor(glow[hh][step(0.18f * depth * bright)]);
            fillDot(g, k, cx + hx, cy + hy, 3.0f * s);
            g.setColor(glow[hh][step(0.5f * depth * bright)]);
            fillDot(g, k, cx + hx, cy + hy, 1.7f * s);
            g.setColor(WHITE[step(depth)]);
            fillDot(g, k, cx + hx, cy + hy, 0.95f * s);
            // a four-point flare that glints on the near side
            if (depth > 0.72f)
            {
                float tw = 0.5f + 0.5f * (float) Math.sin(t * W * 3 + c * 2.4f);
                float fl = (1.4f + 2.8f * tw * tw) * s * depth;
                g.setColor(WHITE[step(0.5f * depth * (0.4f + 0.6f * tw))]);
                k.line.setLine(cx + hx - fl, cy + hy, cx + hx + fl, cy + hy);
                g.draw(k.line);
                k.line.setLine(cx + hx, cy + hy - fl * 0.8f, cx + hx, cy + hy + fl * 0.8f);
                g.draw(k.line);
            }
            int shed = calm ? 1 : 3;
            for (int j = 1; j <= shed; j++)
            {
                // each speck drifts outward a little as it falls behind
                float off = 1f + (0.04f + 0.03f * j) * (float) Math.sin(j * 2.3 + c * 1.9 + t * W);
                at(k, ring, u - 0.3 * j, off, p);
                float sa = (0.7f - 0.17f * j) * (0.55f + 0.45f * (float) Math.sin(t * W * 4 + j * 1.7f + c));
                g.setColor(coreCol[hue(p[0], p[1], shift)][step(sa)]);
                fillDot(g, k, cx + p[0], cy + p[1], 0.6f * s);
            }
        }

        // tiny stars twinkling around it (in a form, the aura's rising specks take their place)
        if (form == BASE)
        {
            int specks = calm ? 3 : SPECKS.length;
            for (int i = 0; i < specks; i++)
            {
                float[] sp = SPECKS[calm ? i * 2 + 1 : i];
                float tw = (float) Math.sin(t * W * sp[2] + sp[3]);
                if (tw <= 0.2f) continue;
                tw = tw * tw * tw;
                double ang = sp[0] + drift * 0.08f;
                float px = (float) Math.cos(ang) * r * sp[1];
                float py = (float) Math.sin(ang) * r * sp[1] * 0.85f;
                star(g, k, cx + px, cy + py, tw * 0.7f, s * 0.8f, coreCol[hue(px, py, shift)]);
            }
        }

        if (charge > 0) sparks(g, k, cx, cy, r, t, s, charge, form == BASE ? GOLD : BLUE, calm);
        if (flash > 0 || since < 0.6f) burst(g, k, cx, cy, r, s, flash, since, form);
        // the barrier, over everything
        float shield = spellAge < 0 ? -1f : ChexySpells.barrierPhase(spellAge);
        if (shield >= 0) ChexySpells.paintBarrier(g, cx, cy, r * 1.3f, shield, t, form, calm);

        g.setComposite(oldComp);
        g.setStroke(oldStroke);
        g.setColor(oldColor);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
        g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, sc == null ? RenderingHints.VALUE_STROKE_DEFAULT : sc);
    }

    // ------------------------------------------------------------------ the aura

    /** the aura's layers: how big (outer, middle, inner) and how strong, per form */
    private static final float[] LAYER_SCALE = {1f, 0.8f, 0.58f};
    private static final float[] GOLD_LAYER_ALPHA = {0.2f, 0.2f, 0.17f};
    private static final float[] BLUE_LAYER_ALPHA = {0.18f, 0.19f, 0.16f};
    /** the aura's gradient fill: stops, and per form, layer and strength level the colours (made once) */
    private static final float[] GRAD_STOPS = {0f, 0.5f, 1f};
    private static final int GRAD_LEVELS = 9;
    private static final Color[][][][] GRAD = new Color[3][3][GRAD_LEVELS][];

    static
    {
        // per form and layer: body, middle, tip colours (rgb) and their alphas at full strength
        int[][][] rgb = {
            {{0xffffff, 0xffffff, 0xffffff}, {0xffffff, 0xffffff, 0xffffff}, {0xffffff, 0xffffff, 0xffffff}},
            {{0xffbe46, 0xffaa32, 0xff8c1e}, {0xffe16e, 0xffcd50, 0xffb93c}, {0xfff8c8, 0xffeb96, 0xffdc6e}},
            {{0x78c8ff, 0x3278ff, 0x285aff}, {0xa0e6ff, 0x46beff, 0x3296ff}, {0xe6faff, 0x8ce1ff, 0x5ac8ff}},
        };
        float[][] alpha = {{0.1f, 0.42f, 0.16f}, {0.08f, 0.36f, 0.1f}, {0.14f, 0.3f, 0.06f}};
        for (int f = 0; f < 3; f++)
        {
            for (int l = 0; l < 3; l++)
            {
                for (int v = 0; v < GRAD_LEVELS; v++)
                {
                    float k = v / (float) (GRAD_LEVELS - 1);
                    Color[] c = new Color[3];
                    for (int i = 0; i < 3; i++)
                    {
                        int a = Math.round(255 * Math.min(1f, alpha[l][i] * k));
                        c[i] = new Color(rgb[f][l][i] | a << 24, true);
                    }
                    GRAD[f][l][v] = c;
                }
            }
        }
    }

    /**
     * The flame aura: three layers (outer, middle, inner), each one closed silhouette of flame tongues round the
     * body, so a whole layer is a single fill. The tongues are tallest on top and lean upward on the sides, so the
     * fire rises; each one licks up and drops back on its own beat and sways, with a wave running round. The gold
     * form burns wild; the blue form burns steadier, with more, shorter tongues and an electric rim.
     */
    private static void aura(Graphics2D g, Scratch k, float cx, float cy, float r, float t, float s, int form,
        float amt, boolean calm)
    {
        boolean gold = form == GOLD;
        float soft = calm ? 0.65f : 1f;
        float speed = calm ? 0.6f : 1f;
        int tongues = gold ? (calm ? 9 : 13) : (calm ? 10 : 15);
        float wild = gold ? 0.5f : 0.22f;
        float tall = (gold ? 1.05f : 0.82f) * r;
        float[] layerAlpha = gold ? GOLD_LAYER_ALPHA : BLUE_LAYER_ALPHA;
        for (int layer = 0; layer < 3; layer++)
        {
            float ls = LAYER_SCALE[layer];
            Path2D.Float path = k.path;
            path.reset();
            float base = r * (0.86f + 0.06f * layer) * ls + r * 0.1f * (1 - ls);
            float rot = layer * 0.37f + (float) Math.sin(t * 0.7f * speed + layer) * 0.08f;
            float pvx = cx + (float) Math.cos(rot) * base;
            float pvy = cy + (float) Math.sin(rot) * base * 0.95f;
            path.moveTo(pvx, pvy);
            for (int i = 0; i < tongues; i++)
            {
                // the valley this tongue ends at, and its own centre line
                double a1 = rot + TAU * (i + 1) / tongues;
                double ac = rot + TAU * (i + 0.5) / tongues;
                float vx = cx + (float) Math.cos(a1) * base;
                float vy = cy + (float) Math.sin(a1) * base * 0.95f;
                // this tongue: how tall (tallest on top), how it flickers, which way it leans
                float up = (float) -Math.sin(ac);
                float shape = 0.22f + 0.78f * (float) Math.pow(0.5f + 0.5f * up, 1.6);
                int seed = i * 7 + layer * 31;
                float ph = hash(seed) * 6.28f;
                float rate = (gold ? 1.3f : 0.75f) * (0.8f + 0.5f * hash(seed + 1)) * speed;
                float lick = (float) ((t * rate + hash(seed + 2)) % 1.0);
                lick = 1f - lick;
                float flick = (0.5f + 0.3f * (float) Math.sin(t * 9.1f * speed + ph) + 0.2f * (float) Math.sin(t * 15.3f * speed + ph * 1.7f));
                float h = tall * ls * shape * (1f - wild + wild * (0.55f * flick + 0.45f * lick * lick)) * amt;
                float sway = (float) (0.16 * Math.sin(t * 3.3f * speed + ph) + 0.1 * Math.sin(t * 4.6f * speed - ac * 2));
                // the tip leans upward: radial direction bent towards the top
                double dirX = Math.cos(ac + sway);
                double dirY = Math.sin(ac + sway) - 0.9;
                double len = Math.sqrt(dirX * dirX + dirY * dirY);
                float bx = cx + (float) Math.cos(ac) * base;
                float by = cy + (float) Math.sin(ac) * base * 0.95f;
                float tx = bx + (float) (dirX / len) * h;
                float ty = by + (float) (dirY / len) * h;
                // the sides hug the body, then sweep up and pinch to a sharp point: a spiky flame tongue
                path.quadTo(pvx * 0.45f + bx * 0.25f + tx * 0.3f, pvy * 0.45f + by * 0.25f + ty * 0.3f, tx, ty);
                path.quadTo(vx * 0.45f + bx * 0.25f + tx * 0.3f, vy * 0.45f + by * 0.25f + ty * 0.3f, vx, vy);
                pvx = vx;
                pvy = vy;
            }
            path.closePath();
            // a few slender flame wisps break off the top of the outer fire and rise away, shrinking
            int wisps = layer > 0 ? 0 : calm ? 1 : 3;
            for (int j = 0; j < wisps; j++)
            {
                float ph = (float) ((t * (gold ? 1.1f : 0.7f) * speed + j / (float) wisps) % 1.0);
                float wx = cx + r * 0.42f * (float) Math.sin(j * 2.4f + t * 0.8f) + (float) Math.sin(t * 7f + j) * 0.8f * s;
                float wy = cy - r * 0.9f - tall * (0.75f + 0.7f * ph);
                float ws = (1f - ph) * (gold ? 1.5f : 1.2f) * s * amt;
                if (ws < 0.3f) continue;
                path.moveTo(wx, wy - ws * 3.2f);
                path.quadTo(wx + ws * 0.9f, wy - ws * 0.4f, wx, wy + ws);
                path.quadTo(wx - ws * 0.9f, wy - ws * 0.4f, wx, wy - ws * 3.2f);
                path.closePath();
            }
            // filled with light that is hot and bright by the body and fades out towards the tips
            float flare = layer == 2 ? 1f : 0.9f + 0.1f * (float) Math.sin(t * 11f * speed + layer);
            float strength = layerAlpha[layer] * 5f * soft * Math.min(1f, amt) * flare;
            int level = Math.max(0, Math.min(GRAD_LEVELS - 1, Math.round(strength * (GRAD_LEVELS - 1))));
            if (level > 0)
            {
                java.awt.Paint oldPaint = g.getPaint();
                float gr = base + tall * ls * 0.95f;
                g.setPaint(new java.awt.RadialGradientPaint(cx, cy - r * 0.1f, gr, GRAD_STOPS, GRAD[form][layer][level]));
                g.fill(path);
                g.setPaint(oldPaint);
            }
            if (layer < 2)
            {
                // the brighter rims: gold's edges burn and flicker; blue's shimmer electric
                float rim = gold ? (layer == 0 ? 0.75f : 0.4f) * (0.8f + 0.2f * (float) Math.sin(t * 17f * speed + layer * 2))
                    : (layer == 0 ? 0.55f : 0.36f) + 0.22f * (float) Math.sin(t * 13f * speed + layer * 2.5f);
                if (layer == 0)
                {
                    // a soft halo round the outer edge, so the fire glows against the dark panel
                    g.setStroke(k.mid);
                    g.setColor(AURA[form][1][step(0.22f * rim * soft * Math.min(1f, amt))]);
                    g.draw(path);
                }
                g.setStroke(k.thin);
                g.setColor(AURA[form][3][step(rim * soft * Math.min(1f, amt))]);
                g.draw(path);
            }
        }

        // thin streaks of light rushing up through the fire, so it reads as rising
        g.setStroke(k.thin);
        int streaks = calm ? 2 : gold ? 6 : 5;
        for (int j = 0; j < streaks; j++)
        {
            float ph = (float) ((t * (gold ? 1.4f : 0.9f) * speed + hash(j + 60)) % 1.0);
            float sx = cx + r * (hash(j + 70) * 1.5f - 0.75f);
            float sy = cy + r * (0.55f - 1.9f * ph) - tall * 0.5f * ph;
            float len = (2.5f + 3f * hash(j + 80)) * s * (gold ? 1f : 0.8f);
            float a = (float) Math.sin(Math.PI * ph) * 0.55f * soft * Math.min(1f, amt);
            g.setColor(AURA[form][2][step(a)]);
            k.line.setLine(sx, sy, sx, sy + len);
            g.draw(k.line);
        }

        // energy specks rising through it
        int specks = calm ? 3 : 7;
        for (int j = 0; j < specks; j++)
        {
            float ph = (float) ((t * (gold ? 0.7f : 0.5f) * speed + hash(j + 90)) % 1.0);
            float sx = cx + r * (hash(j + 40) * 2f - 1f) * 1.05f + (float) Math.sin(t * 2f + j) * s;
            float sy = cy + r * (0.9f - 2.3f * ph);
            float a = (float) Math.sin(Math.PI * ph) * 0.9f * Math.min(1f, amt);
            g.setColor(AURA[form][2][step(a)]);
            fillDot(g, k, sx, sy, (0.5f + 0.4f * (1f - ph)) * s);
        }

        // lightning: now and then a short jagged crackle flicks out from the body (often in gold, rarely in blue)
        float chance = gold ? (calm ? 0.12f : 0.4f) : (calm ? 0.05f : 0.16f);
        int slot = (int) Math.floor(t * 6f);
        float into = t * 6f - slot;
        if (amt > 0.6f && into < 0.55f && hash(slot * 3 + 7) < chance)
        {
            double ang = hash(slot * 3 + 8) * TAU;
            float r0 = r * 0.7f;
            float r1 = r * (1.35f + 0.3f * hash(slot * 3 + 9));
            Path2D.Float bolt = k.path;
            bolt.reset();
            float nx = (float) -Math.sin(ang);
            float ny = (float) Math.cos(ang);
            for (int i = 0; i <= 5; i++)
            {
                float f = i / 5f;
                float rr = r0 + (r1 - r0) * f;
                float jit = (i == 0 || i == 5) ? 0f : (hash(slot * 17 + i) * 2f - 1f) * 2.6f * s;
                float x = cx + (float) Math.cos(ang) * rr + nx * jit;
                float y = cy + (float) Math.sin(ang) * rr + ny * jit;
                if (i == 0) bolt.moveTo(x, y);
                else bolt.lineTo(x, y);
            }
            float fade = 1f - into / 0.55f;
            g.setStroke(k.bolt);
            g.setColor(AURA[form][1][step(0.4f * fade)]);
            g.draw(bolt);
            g.setStroke(k.thin);
            g.setColor(WHITE[step(0.95f * fade)]);
            g.draw(bolt);
        }
    }

    /** charge-up sparks: short crackles bursting out round it, more of them as the charge builds */
    private static void sparks(Graphics2D g, Scratch k, float cx, float cy, float r, float t, float s, float charge,
        int toward, boolean calm)
    {
        int slot = (int) Math.floor(t * 14f);
        int n = calm ? 1 : 1 + Math.round(4 * charge);
        g.setStroke(k.thin);
        for (int i = 0; i < n; i++)
        {
            int seed = slot * 13 + i * 5;
            double ang = hash(seed) * TAU;
            float r0 = r * (0.8f + 0.45f * hash(seed + 1));
            float len = (2f + 3.5f * hash(seed + 2) * charge) * s;
            float x0 = cx + (float) Math.cos(ang) * r0;
            float y0 = cy + (float) Math.sin(ang) * r0;
            // a little zigzag outward
            float kx = (float) -Math.sin(ang) * 1.2f * s;
            float ky = (float) Math.cos(ang) * 1.2f * s;
            float mx = x0 + (float) Math.cos(ang) * len * 0.5f + kx;
            float my = y0 + (float) Math.sin(ang) * len * 0.5f + ky;
            float x1 = x0 + (float) Math.cos(ang) * len;
            float y1 = y0 + (float) Math.sin(ang) * len;
            g.setColor(AURA[toward][3][step(0.7f)]);
            k.line.setLine(x0, y0, mx, my);
            g.draw(k.line);
            k.line.setLine(mx, my, x1, y1);
            g.draw(k.line);
            g.setColor(WHITE[step(0.9f)]);
            fillDot(g, k, x0, y0, 0.55f * s);
        }
    }

    /** the change of form: a white flash that swallows it, then a ring of light that rushes outward */
    private static void burst(Graphics2D g, Scratch k, float cx, float cy, float r, float s, float flash, float since,
        int form)
    {
        if (flash > 0)
        {
            // a soft bloom of white light, with a hot core
            Composite old = g.getComposite();
            Object interp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.setComposite(FADE[step(flash)]);
            int fr = Math.round(r * (1.1f + 0.6f * flash));
            g.drawImage(BLOOM, Math.round(cx) - fr, Math.round(cy) - fr, fr * 2, fr * 2, null);
            g.setComposite(old);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
                interp == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : interp);
            g.setColor(WHITE[step(0.85f * flash)]);
            fillDot(g, k, cx, cy, r * 0.45f * (0.6f + 0.4f * flash));
        }
        if (since < 0.6f)
        {
            float q = since / 0.6f;
            float rr = r * (1f + 0.65f * q);
            g.setStroke(k.mid);
            g.setColor(AURA[form][3][step(0.8f * (1f - q))]);
            k.dot.setFrame(cx - rr, cy - rr * 0.95f, rr * 2, rr * 1.9f);
            g.draw(k.dot);
        }
    }

    // ------------------------------------------------------------------ its float, and small helpers

    /** its float, a slow figure of eight in time with the comets: x offset in pixels at time t */
    public static float bobX(float t)
    {
        return 2.2f * (float) Math.sin(t * W);
    }

    /** its float: y offset in pixels at time t */
    public static float bobY(float t)
    {
        return 1.8f * (float) Math.sin(t * W * 2 + 0.6f);
    }

    /** a small four-point glint: faint rays and a bright tinted centre (colours by alpha step) */
    private static void star(Graphics2D g, Scratch k, float x, float y, float tw, float s, Color[] tint)
    {
        float len = (0.8f + 2.2f * tw) * s;
        g.setColor(tint[step(0.55f * tw)]);
        k.line.setLine(x - len, y, x + len, y);
        g.draw(k.line);
        k.line.setLine(x, y - len, x, y + len);
        g.draw(k.line);
        g.setColor(tint[step(0.95f * tw)]);
        fillDot(g, k, x, y, 0.6f * s);
    }

    private static void fillDot(Graphics2D g, Scratch k, float x, float y, float rad)
    {
        k.dot.setFrame(x - rad, y - rad, rad * 2, rad * 2);
        g.fill(k.dot);
    }

    private static BufferedImage still;

    /** One still frame on the shared creature grid (ImpSprite.WIDTH x HEIGHT), for anything that wants a picture. */
    public static synchronized BufferedImage still()
    {
        if (still == null)
        {
            BufferedImage img = new BufferedImage(ImpSprite.WIDTH, ImpSprite.HEIGHT, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = img.createGraphics();
            paint(g, ImpSprite.WIDTH / 2f, ImpSprite.HEIGHT / 2f, 1.3f, Math.min(ImpSprite.HEIGHT - 4, SIZE), false);
            g.dispose();
            still = img;
        }
        return still;
    }
}

package com.forgebingo.core;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.AffineTransform;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;

/**
 * Chexy's spells (owner, 2026-11-15), all our own designs, cast at set moments of a spell visit (half its visits; the rest power up instead, never both), all in its base form:
 * <ul>
 * <li>the FLOWER SPELL, in its base form: it glows softly, a gentle wave spreads out from under it and small pixel
 * flowers pop up and bloom one after another on the cards around it and near the bottom of the panel, sway, shed a
 * few petals, and fade;</li>
 * <li>the BARRIER, a pale rainbow dome of hexagon cells grows round it, a shimmer sweeps across it, stray
 * sparks strike it and it ripples and flashes where they hit, then it breaks into fading fragments;</li>
 * <li>the BEAM VOLLEY, once: it stops, a layered magic circle opens in front of it (an outer
 * ring of small rune strokes and an inner geometric ring turning the other way) and two small satellite circles
 * open beside it; particles are drawn in, and four beams fire one after another at different angles, the last one
 * sweeping, each with a hot core, soft glow, wavy energy edges, a brief afterimage and sparks where it ends, and
 * Chexy kicks back a little with every shot.</li>
 * </ul>
 * Everything is a pure function of the clocks. The flowers' and the beams' placing is the caller's (PanelImps).
 */
public final class ChexySpells
{
    private ChexySpells()
    {
    }

    // ------------------------------------------------------------------ when, by seconds into the visit

    /**
     * The spell clock for a visit: the visit's age on a spell visit, -1 (no spells) on a power-up visit. Each visit
     * is one or the other, never both (owner), rolled 50/50 when Chexy arrives. A spell visit stays in the base form.
     */
    public static float spellAge(boolean spellVisit, float visitAge)
    {
        return spellVisit ? visitAge : -1f;
    }

    /** the flower spell starts here (just after it has popped in) */
    public static final float FLOWER_AT = 1.4f;
    /** and a second, gentler bloom late in the visit (fewer flowers), done before the shortest visit ends */
    public static final float FLOWER_AGAIN = 44f;
    /** both blooms */
    public static final float[] FLOWER_TIMES = {FLOWER_AT, FLOWER_AGAIN};
    /** how long Chexy glows for it */
    public static final float FLOWER_CAST = 1.6f;
    /** how far into the cast the wave sets off and the flowers are placed */
    public static final float FLOWER_SPAWN = 0.35f;
    /** how long the flowers last once placed (they fade over the last FLOWER_FADE) */
    public static final float FLOWER_LIFE = 7.6f;
    public static final float FLOWER_FADE = 1.8f;
    /** the barrier, after the first flowers have faded */
    public static final float BARRIER_AT = 14f;
    public static final float BARRIER_TIME = 4.2f;
    /** the beam volley, half way through; then it floats calmly until the second bloom */
    public static final float[] VOLLEYS = {28f};
    public static final float VOLLEY_TIME = 3.8f;

    /** seconds into a flower spell's cast, or -1 */
    public static float flowerPhase(float age)
    {
        for (float at : FLOWER_TIMES)
        {
            float p = age - at;
            if (p >= 0 && p < FLOWER_CAST) return p;
        }
        return -1f;
    }

    /** seconds into the barrier, or -1 */
    public static float barrierPhase(float age)
    {
        float p = age - BARRIER_AT;
        return p >= 0 && p < BARRIER_TIME ? p : -1f;
    }

    /** seconds into a beam volley, or -1 */
    public static float volleyPhase(float age)
    {
        for (float v : VOLLEYS)
        {
            float p = age - v;
            if (p >= 0 && p < VOLLEY_TIME) return p;
        }
        return -1f;
    }

    /** how fast Chexy may fly while it casts: it stands still to fire, slows to cast and to shield */
    public static float flySpeed(float age)
    {
        if (volleyPhase(age) >= 0) return 0f;
        if (flowerPhase(age) >= 0) return 0.2f;
        if (barrierPhase(age) >= 0) return 0.35f;
        return 1f;
    }

    // ------------------------------------------------------------------ colours, strokes, scratch

    private static final int ALPHAS = 32;
    private static final double TAU = Math.PI * 2;
    /** per form (base, gold, blue): the spell colour (the base form: white-cyan beams; its dome and runes are rainbow), a paler one, by alpha step */
    private static final Color[][] TINT = new Color[3][ALPHAS];
    private static final Color[][] PALE = new Color[3][ALPHAS];
    private static final Color[] WHITE = new Color[ALPHAS];
    private static final Composite[] FADE = new Composite[ALPHAS];
    /** round-ended strokes by width in quarter pixels, up to 16 px (made once) */
    private static final Stroke[] STROKES = new Stroke[65];

    static
    {
        int[] tint = {0x8fe6ff, 0xffcf5a, 0x6fe3ff};
        int[] pale = {0xe8fbff, 0xfff4cf, 0xd8f8ff};
        for (int a = 0; a < ALPHAS; a++)
        {
            int alpha = Math.round(255f * (a + 1) / ALPHAS);
            WHITE[a] = new Color(255, 255, 255, alpha);
            FADE[a] = AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (a + 1) / (float) ALPHAS);
            for (int f = 0; f < 3; f++)
            {
                TINT[f][a] = new Color(tint[f] | alpha << 24, true);
                PALE[f][a] = new Color(pale[f] | alpha << 24, true);
            }
        }
        for (int i = 0; i < STROKES.length; i++)
        {
            STROKES[i] = new BasicStroke(Math.max(0.25f, i / 4f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
        }
    }

    private static int step(float a)
    {
        return Math.max(0, Math.min(ALPHAS - 1, Math.round(a * ALPHAS) - 1));
    }

    private static Stroke stroke(float w)
    {
        return STROKES[Math.max(1, Math.min(STROKES.length - 1, Math.round(w * 4)))];
    }

    private static float hash(int n)
    {
        n = (n << 13) ^ n;
        n = n * (n * n * 15731 + 789221) + 1376312589;
        return (n & 0x7fffffff) / (float) 0x7fffffff;
    }

    private static float smooth(float a, float b, float x)
    {
        float k = Math.max(0f, Math.min(1f, (x - a) / (b - a)));
        return k * k * (3 - 2 * k);
    }

    /** eases in with a small overshoot, for things that spring open */
    private static float spring(float k)
    {
        k = Math.max(0f, Math.min(1f, k));
        float c = 1.7f;
        float m = k - 1;
        return 1 + (c + 1) * m * m * m + c * m * m;
    }

    private static int formOf(int form)
    {
        return Math.max(0, Math.min(2, form));
    }

    /** a soft white light, bright in the middle (made once, drawn scaled) */
    private static final BufferedImage GLOW = glow(0xffffff);
    /** a soft pink-white light for the flower spell */
    private static final BufferedImage GLOW_PINK = glow(0xffd8ec);

    private static BufferedImage glow(int rgb)
    {
        int n = 40;
        BufferedImage img = new BufferedImage(n, n, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < n; y++)
        {
            for (int x = 0; x < n; x++)
            {
                double dx = (x + 0.5) / n * 2 - 1;
                double dy = (y + 0.5) / n * 2 - 1;
                double d = Math.min(1, Math.sqrt(dx * dx + dy * dy));
                int a = (int) Math.round(255 * Math.pow(1 - d, 1.9));
                img.setRGB(x, y, a << 24 | rgb);
            }
        }
        return img;
    }

    private static final ThreadLocal<Scratch> SCRATCH = ThreadLocal.withInitial(Scratch::new);

    private static final class Scratch
    {
        final Path2D.Float a = new Path2D.Float();
        final Path2D.Float b = new Path2D.Float();
        final Line2D.Float line = new Line2D.Float();
        final Ellipse2D.Float dot = new Ellipse2D.Float();
        final Rectangle2D.Float rect = new Rectangle2D.Float();
        final float[] p = new float[2];
        final float[] q = new float[2];
        /** the dome's strokes are drawn in its own unit space, so their widths depend on its size (kept per size) */
        float hexR = -1;
        Stroke hexThin, hexBold, hexRim;
        final Path2D.Float c = new Path2D.Float();

        void hexStrokes(float r)
        {
            float key = Math.round(r * 4) / 4f;
            if (key == hexR) return;
            hexR = key;
            hexThin = new BasicStroke(0.9f / Math.max(1f, key));
            hexBold = new BasicStroke(1.3f / Math.max(1f, key));
            hexRim = new BasicStroke(1.8f / Math.max(1f, key));
        }
    }

    private static void fillDot(Graphics2D g, Scratch k, float x, float y, float r)
    {
        k.dot.setFrame(x - r, y - r, r * 2, r * 2);
        g.fill(k.dot);
    }

    private static void light(Graphics2D g, BufferedImage img, float x, float y, float r, float alpha)
    {
        if (alpha <= 0.02f || r < 0.5f) return;
        Composite old = g.getComposite();
        Object interp = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.setComposite(FADE[step(Math.min(1f, alpha))]);
        int ir = Math.round(r);
        g.drawImage(img, Math.round(x) - ir, Math.round(y) - ir, ir * 2, ir * 2, null);
        g.setComposite(old);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            interp == null ? RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR : interp);
    }

    // ------------------------------------------------------------------ the flower spell

    /** Chexy's soft glow while it casts the flower spell (drawn behind its rings). */
    public static void paintCastGlow(Graphics2D g, float cx, float cy, float r, float phase)
    {
        float k = (float) Math.sin(Math.PI * Math.max(0f, Math.min(1f, phase / FLOWER_CAST)));
        light(g, GLOW_PINK, cx, cy, r * (1.5f + 0.25f * k), 0.55f * k);
    }

    /** how far the wave has spread (px) this long after it set off; below 0 once it is gone */
    public static float waveRadius(float since)
    {
        if (since < 0 || since > 1.5f) return -1f;
        float e = since / 1.5f;
        return 6f + 74f * (1f - (1f - e) * (1f - e));
    }

    /** the gentle wave that spreads out from under Chexy as it casts: two soft rings, green and pink, and a few glints */
    public static void paintWave(Graphics2D g, float x, float y, float since, boolean calm)
    {
        float rad = waveRadius(since);
        if (rad < 0) return;
        Scratch k = SCRATCH.get();
        float e = since / 1.5f;
        Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for (int ring = 0; ring < 2; ring++)
        {
            float rr = rad * (ring == 0 ? 1f : 0.72f);
            float a = (1f - e) * (ring == 0 ? 0.55f : 0.4f) * (calm ? 0.7f : 1f);
            g.setStroke(stroke(ring == 0 ? 1.3f : 1f));
            g.setColor(ring == 0 ? PETAL[4][step(a)] : PETAL[1][step(a)]);
            k.dot.setFrame(x - rr, y - rr * 0.3f, rr * 2, rr * 0.6f);
            g.draw(k.dot);
        }
        int glints = calm ? 3 : 7;
        for (int i = 0; i < glints; i++)
        {
            double ang = i * TAU / glints + 0.4;
            float gx = x + (float) Math.cos(ang) * rad;
            float gy = y + (float) Math.sin(ang) * rad * 0.3f;
            g.setColor(WHITE[step((1f - e) * 0.8f)]);
            g.fillRect(Math.round(gx), Math.round(gy), 1, 1);
        }
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
    }

    /** the flowers: 0 white daisy, 1 pink tulip, 2 yellow star, 3 light-blue bell */
    public static final int FLOWER_KINDS = 4;
    private static final String[][] HEADS = {
        {"..P..", ".PPP.", "PPCPP", ".PPP.", "..P.."},
        {"P.P.P", "PPPPP", "PPCPP", ".PDP."},
        {".P.P.", "PPCPP", ".PDP.", "P...P"},
        {".PPP.", "PPPPP", "PDCDP", "P.P.P"},
    };
    /** per kind: petal, centre, shade; then stem, leaf (rgb) */
    private static final int[][] FLOWER_RGB = {
        {0xf4f4ee, 0xffd250, 0xc8cad6},
        {0xff8cc0, 0xffdc78, 0xd8609c},
        {0xffe146, 0xff9628, 0xe0b028},
        {0x8cc8ff, 0xe6f5ff, 0x5a96e0},
    };
    private static final int STEM = 0x5ab45a, LEAF = 0x82d764;
    private static final int FLOWER_ALPHAS = 8;
    /** [kind][0 petal, 1 centre, 2 shade, 3 stem, 4 leaf][alpha level] */
    private static final Color[][][] FLOWER = new Color[FLOWER_KINDS][5][FLOWER_ALPHAS];
    /** petal colours for drifting petals and the wave, by alpha step: the four kinds, then soft green */
    private static final Color[][] PETAL = new Color[5][ALPHAS];

    static
    {
        for (int f = 0; f < FLOWER_KINDS; f++)
        {
            int[] rgb = {FLOWER_RGB[f][0], FLOWER_RGB[f][1], FLOWER_RGB[f][2], STEM, LEAF};
            for (int c = 0; c < 5; c++)
            {
                for (int a = 0; a < FLOWER_ALPHAS; a++)
                {
                    int alpha = Math.round(255f * (a + 1) / FLOWER_ALPHAS);
                    FLOWER[f][c][a] = new Color(rgb[c] | alpha << 24, true);
                }
            }
            for (int a = 0; a < ALPHAS; a++) PETAL[f][a] = new Color(FLOWER_RGB[f][0] | Math.round(255f * (a + 1) / ALPHAS) << 24, true);
        }
        for (int a = 0; a < ALPHAS; a++) PETAL[4][a] = new Color(0x9cf0a0 | Math.round(255f * (a + 1) / ALPHAS) << 24, true);
    }

    private static final float GROW = 0.32f, BUD = 0.5f, OPEN = 0.6f, FULL = 0.7f, SPARKLE = 0.95f;

    private static int stemHeight(int kind, int x)
    {
        return 5 + ((kind + x) & 1) + (kind == 1 ? 1 : 0);
    }

    private static int sway(float clock, int x)
    {
        return (int) Math.round(Math.sin(clock * 2.1 + x * 0.37) * 0.85);
    }

    private static int fadeLevel(float since, float life)
    {
        float a = since > life - FLOWER_FADE ? Math.max(0f, (life - since) / FLOWER_FADE) : 1f;
        return Math.max(-1, Math.round(a * FLOWER_ALPHAS) - 1);
    }

    /**
     * A number that changes whenever this flower would be drawn differently, so the caller repaints it only then
     * (it sways a pixel at a time, so most frames it does not change at all).
     */
    public static int flowerKey(int kind, int x, float since, float life, float clock)
    {
        if (since < 0) return -1;
        int stage = since < GROW ? Math.round(since / GROW * 8) : since < BUD ? 9 : since < OPEN ? 10 : since < SPARKLE
            ? 11 + Math.round((since - OPEN) / (SPARKLE - OPEN) * 4) : 16;
        int hop = since >= OPEN && since < OPEN + 0.12f ? 50000 : 0;
        return hop + stage * 1000 + (sway(clock, x) + 1) * 100 + fadeLevel(since, life) + 1;
    }

    /**
     * One pixel flower standing on groundY, centred on x: it grows its stem, shows a bud, pops open with a glint,
     * then sways a pixel to and fro, and fades at the end of its life.
     *
     * @param since seconds since this flower started (below 0: not yet)
     * @param life  how long it lasts in all
     * @param clock a running clock for the sway
     */
    public static void paintFlower(Graphics2D g, int x, int groundY, int kind, float since, float life, float clock)
    {
        if (since < 0 || since >= life) return;
        int lv = fadeLevel(since, life);
        if (lv < 0) return;
        Color[][] c = FLOWER[Math.floorMod(kind, FLOWER_KINDS)];
        int h = stemHeight(kind, x);
        int grown = since < GROW ? Math.max(1, Math.round(h * since / GROW)) : h;
        int sw = since < OPEN ? 0 : sway(clock, x);
        // the stem, growing up from the ground; its top bends with the sway
        g.setColor(c[3][lv]);
        for (int i = 0; i < grown; i++) g.fillRect(x + (i >= h - 2 ? sw : 0), groundY - 1 - i, 1, 1);
        if (grown >= 3)
        {
            g.setColor(c[4][lv]);
            int side = ((x + kind) & 1) == 0 ? -1 : 1;
            g.fillRect(x + side, groundY - 3, 1, 1);
            g.fillRect(x + side * 2, groundY - 4, 1, 1);
        }
        if (since < GROW) return;
        int top = groundY - 1 - h; // the row just above the stem
        if (since < BUD)
        {
            // a bud, swelling
            g.setColor(c[4][lv]);
            g.fillRect(x - 1, top, 1, 1);
            g.fillRect(x + 1, top, 1, 1);
            g.setColor(c[0][lv]);
            g.fillRect(x, top - (since > (GROW + BUD) / 2 ? 1 : 0), 1, 2);
            return;
        }
        String[] head = HEADS[Math.floorMod(kind, FLOWER_KINDS)];
        int rows = head.length;
        // popping open: first the middle rows, then the whole flower
        int from = since < OPEN ? rows / 2 - 1 : 0;
        int to = since < OPEN ? rows / 2 + 1 : rows;
        // and it hops up a pixel as it opens, then settles
        int hop = since >= OPEN && since < OPEN + 0.12f ? 1 : 0;
        for (int j = Math.max(0, from); j < Math.min(rows, to); j++)
        {
            String row = head[j];
            int py = top - (rows - 1 - j) - hop;
            for (int i = 0; i < 5; i++)
            {
                char ch = row.charAt(i);
                if (ch == '.') continue;
                g.setColor(c[ch == 'P' ? 0 : ch == 'C' ? 1 : 2][lv]);
                g.fillRect(x - 2 + i + sw, py, 1, 1);
            }
        }
        if (since >= OPEN && since < SPARKLE)
        {
            // a little burst as it opens: white glints on the diagonals, petal-coloured bits straight out
            float k = (since - OPEN) / (SPARKLE - OPEN);
            int d = 3 + Math.round(k * 2);
            int cyy = top - rows / 2;
            float fade = (1f - k) * (lv + 1) / FLOWER_ALPHAS;
            g.setColor(WHITE[step(0.9f * fade)]);
            g.fillRect(x + sw - d, cyy - d, 1, 1);
            g.fillRect(x + sw + d, cyy - d, 1, 1);
            g.fillRect(x + sw - d, cyy + d, 1, 1);
            g.fillRect(x + sw + d, cyy + d, 1, 1);
            g.setColor(PETAL[Math.floorMod(kind, FLOWER_KINDS)][step(0.9f * fade)]);
            g.fillRect(x + sw - d - 1, cyy, 1, 1);
            g.fillRect(x + sw + d + 1, cyy, 1, 1);
            g.fillRect(x + sw, cyy - d - 1, 1, 1);
        }
    }

    /** when this flower's drifting petals are in the air (so the caller keeps repainting around it) */
    public static boolean petalsFlying(float since, int index, boolean calm)
    {
        if (calm && index % 3 != 0) return false;
        for (int j = 0; j < (calm ? 1 : 2); j++)
        {
            float start = FULL + 0.6f + j * 1.7f + hash(index * 5 + j) * 0.8f;
            if (since >= start && since < start + PETAL_LIFE) return true;
        }
        return false;
    }

    private static final float PETAL_LIFE = 2.4f;

    /** A few petals that come loose and drift sideways and down, turning, fading. */
    public static void paintPetals(Graphics2D g, int x, int groundY, int kind, float since, int index, boolean calm)
    {
        if (calm && index % 3 != 0) return;
        int top = groundY - 1 - stemHeight(kind, x) - 2;
        for (int j = 0; j < (calm ? 1 : 2); j++)
        {
            float start = FULL + 0.6f + j * 1.7f + hash(index * 5 + j) * 0.8f;
            float tau = since - start;
            if (tau < 0 || tau >= PETAL_LIFE) continue;
            float side = hash(index * 5 + j + 2) < 0.5f ? -1f : 1f;
            float px = x + side * (4f + 5f * hash(index * 7 + j)) * tau + (float) Math.sin(tau * 3.4f + index) * 1.6f;
            float py = top - 2f * tau + 3.2f * tau * tau;
            float a = (1f - tau / PETAL_LIFE) * 0.95f;
            g.setColor(PETAL[Math.floorMod(kind, FLOWER_KINDS)][step(a)]);
            // it turns as it falls: flat, then edge on
            boolean flat = Math.sin(tau * 6f + j) > 0;
            g.fillRect(Math.round(px), Math.round(py), flat ? 2 : 1, 1);
        }
    }

    // ------------------------------------------------------------------ the barrier

    /** the dome's hexagon cells, on a unit sphere seen from the front (made once) */
    private static final Path2D.Float HEX = hexDome();
    /** a soft-filled bubble per form, brighter towards its rim (made once, drawn scaled) */
    private static final BufferedImage[] BUBBLE = {bubble(0), bubble(1), bubble(2)};
    private static final float[] HITS = {1.05f, 1.75f, 2.35f, 2.95f};
    private static final float[] HITS_CALM = {1.4f, 2.6f};

    private static Path2D.Float hexDome()
    {
        Path2D.Float path = new Path2D.Float();
        double h = 0.21;
        double cell = h * 0.86;
        for (int qq = -8; qq <= 8; qq++)
        {
            for (int rr = -8; rr <= 8; rr++)
            {
                double x = h * Math.sqrt(3) * (qq + rr / 2.0);
                double y = h * 1.5 * rr;
                if (Math.sqrt(x * x + y * y) > 1.18) continue;
                for (int v = 0; v <= 6; v++)
                {
                    double a = Math.PI / 6 + v * Math.PI / 3;
                    double px = x + Math.cos(a) * cell;
                    double py = y + Math.sin(a) * cell;
                    // bend the flat grid onto the dome: cells crowd together towards the rim
                    double d = Math.sqrt(px * px + py * py);
                    double m = d < 1e-6 ? 1 : Math.sin(Math.min(d, 1.25) / 1.25 * Math.PI / 2) / d;
                    if (v == 0) path.moveTo(px * m, py * m);
                    else path.lineTo(px * m, py * m);
                }
                path.closePath();
            }
        }
        return path;
    }

    /** the base form's pale rainbow, as paints across the unit dome at a few strengths (made once) */
    private static final int RAINBOW_LEVELS = 10;
    private static final java.awt.LinearGradientPaint[] RAINBOW = new java.awt.LinearGradientPaint[RAINBOW_LEVELS];
    /** pale rainbow colours by hue step and alpha step, for the base form's runes and fragments */
    private static final int RUNE_HUES = 10;
    private static final Color[][] RUNE = new Color[RUNE_HUES][ALPHAS];

    static
    {
        float[] stops = {0f, 0.2f, 0.4f, 0.6f, 0.8f, 1f};
        float[] hues = {0.85f, 0.98f, 0.15f, 0.33f, 0.5f, 0.68f};
        for (int lv = 0; lv < RAINBOW_LEVELS; lv++)
        {
            int a = Math.round(255f * (lv + 1) / RAINBOW_LEVELS);
            Color[] c = new Color[hues.length];
            for (int i = 0; i < hues.length; i++) c[i] = new Color(Color.HSBtoRGB(hues[i], 0.42f, 1f) & 0xffffff | a << 24, true);
            RAINBOW[lv] = new java.awt.LinearGradientPaint(-1f, -1f, 1f, 1f, stops, c);
        }
        for (int h = 0; h < RUNE_HUES; h++)
        {
            int rgb = Color.HSBtoRGB(h / (float) RUNE_HUES, 0.45f, 1f) & 0xffffff;
            for (int a = 0; a < ALPHAS; a++) RUNE[h][a] = new Color(rgb | Math.round(255f * (a + 1) / ALPHAS) << 24, true);
        }
    }

    private static int rainbowLevel(float a)
    {
        return Math.max(0, Math.min(RAINBOW_LEVELS - 1, Math.round(a * RAINBOW_LEVELS) - 1));
    }

    private static BufferedImage bubble(int form)
    {
        int n = 48;
        int[] rgb = {0xe8fbff, 0xffd264, 0x7ee0ff};
        BufferedImage img = new BufferedImage(n, n, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < n; y++)
        {
            for (int x = 0; x < n; x++)
            {
                double dx = (x + 0.5) / n * 2 - 1;
                double dy = (y + 0.5) / n * 2 - 1;
                // the base form's bubble is tinted round the wheel like its rings (yellow right, cyan below, ...)
                if (form == 0) rgb[0] = Color.HSBtoRGB((float) (0.16 + Math.atan2(dy, dx) / TAU), 0.32f, 1f) & 0xffffff;
                double d = Math.sqrt(dx * dx + dy * dy);
                double a = d >= 1 ? 0 : d < 0.93 ? 16 + 104 * Math.pow(d / 0.93, 4) : 120 * (1 - d) / 0.07;
                // a soft highlight up and to the left, as on a bubble
                double hx = dx + 0.38, hy = dy + 0.42;
                double hl = Math.max(0, 1 - Math.sqrt(hx * hx + hy * hy) / 0.3);
                a = Math.min(255, a + 70 * hl * hl);
                img.setRGB(x, y, (int) Math.round(a) << 24 | rgb[form]);
            }
        }
        return img;
    }

    /**
     * The barrier round Chexy (radius R, centred on cx, cy): a dome of hexagon cells that grows out from the middle,
     * a shimmer sweeping across, stray sparks striking it (each makes a ripple, lights the cells round the hit and
     * flashes), then it breaks up into hexagon fragments that drift away and fade.
     */
    public static void paintBarrier(Graphics2D g, float cx, float cy, float R, float p, float t, int form, boolean calm)
    {
        if (p < 0 || p >= BARRIER_TIME) return;
        int f = formOf(form);
        Scratch k = SCRATCH.get();
        AffineTransform old = g.getTransform();
        Shape oldClip = g.getClip();
        Stroke oldStroke = g.getStroke();
        Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        float dissolveAt = BARRIER_TIME - 0.8f;
        float grow = p / 0.6f;
        float alpha = grow < 1 ? smooth(0f, 1f, grow) : 1f;
        float d = p > dissolveAt ? (p - dissolveAt) / 0.8f : 0f;
        if (d > 0) alpha *= (1f - d) * (1f - d);
        float scale = grow < 1 ? spring(grow) : 1f + 0.015f * (float) Math.sin(t * 3f);
        float rr = R * scale;

        if (alpha > 0.02f)
        {
            // the soft body of the dome
            light(g, BUBBLE[f], cx, cy, rr, alpha);
            // the cells, revealed from the middle outward while it forms, turning slowly
            g.translate(cx, cy);
            if (grow < 1)
            {
                float rev = grow * 1.4f * rr;
                k.dot.setFrame(-rev, -rev, rev * 2, rev * 2);
                g.clip(k.dot);
            }
            g.rotate(t * 0.12);
            g.scale(rr, rr);
            k.hexStrokes(rr);
            g.setStroke(k.hexThin);
            if (f == 0)
            {
                // in its base form the cells and rim are a pale rainbow, like its rings
                java.awt.Paint oldPaint = g.getPaint();
                g.setPaint(RAINBOW[rainbowLevel(0.5f * alpha)]);
                g.draw(HEX);
                g.setStroke(k.hexRim);
                k.dot.setFrame(-1f, -1f, 2f, 2f);
                g.draw(k.dot);
                g.setPaint(oldPaint);
            }
            else
            {
                g.setColor(TINT[f][step(0.5f * alpha)]);
                g.draw(HEX);
            }
            g.setTransform(old);
            g.setClip(oldClip);
            // the shimmer: a bright band that sweeps across the cells
            float sweep = (float) (((p - 0.3f) / 1.5f) % 1.0);
            if (p > 0.3f)
            {
                g.translate(cx, cy);
                k.dot.setFrame(-rr, -rr, rr * 2, rr * 2);
                g.clip(k.dot);
                g.rotate(-0.7);
                float pos = (-1.3f + 2.6f * sweep) * rr;
                k.rect.setRect(pos - rr * 0.2f, -rr * 1.3f, rr * 0.4f, rr * 2.6f);
                g.clip(k.rect);
                g.rotate(0.7 + t * 0.12);
                g.scale(rr, rr);
                g.setStroke(k.hexBold);
                g.setColor(WHITE[step(0.7f * alpha)]);
                g.draw(HEX);
                g.setTransform(old);
                g.setClip(oldClip);
            }
            // the rim, which flares up for a moment each time something strikes the dome
            float struck = 0f;
            for (float h : calm ? HITS_CALM : HITS)
            {
                float q = p - h;
                if (q >= 0 && q < 0.3f) struck = Math.max(struck, 1f - q / 0.3f);
            }
            g.setStroke(stroke(1.6f + 1.4f * struck));
            g.setColor(TINT[f][step((0.35f + 0.45f * struck) * alpha)]);
            k.dot.setFrame(cx - rr, cy - rr, rr * 2, rr * 2);
            g.draw(k.dot);
            g.setStroke(stroke(0.7f));
            g.setColor(PALE[f][step(0.85f * alpha)]);
            g.draw(k.dot);
        }

        // stray sparks that strike it
        float[] hits = calm ? HITS_CALM : HITS;
        for (int i = 0; i < hits.length; i++)
        {
            float q = p - hits[i];
            if (q < -0.22f || q > 0.55f || p > dissolveAt) continue;
            double ang = hash(i * 7 + 3) * TAU;
            float ux = (float) Math.cos(ang);
            float uy = (float) Math.sin(ang);
            if (q < 0)
            {
                // incoming: a short streak flying in
                float head = rr * (1f + 1.2f * (-q / 0.22f));
                g.setStroke(stroke(1.1f));
                g.setColor(TINT[f][step(0.95f)]);
                k.line.setLine(cx + ux * head, cy + uy * head, cx + ux * (head + 6f), cy + uy * (head + 6f));
                g.draw(k.line);
                g.setColor(WHITE[step(0.9f)]);
                fillDot(g, k, cx + ux * head, cy + uy * head, 0.9f);
                continue;
            }
            float e = q / 0.55f;
            float hx = cx + ux * rr * 0.97f;
            float hy = cy + uy * rr * 0.97f;
            // the cells round the hit light up, and ripples run out from it across the dome
            g.translate(cx, cy);
            k.dot.setFrame(-rr, -rr, rr * 2, rr * 2);
            g.clip(k.dot);
            g.setTransform(old);
            float lit = rr * (0.35f + 0.4f * e);
            k.dot.setFrame(hx - lit, hy - lit, lit * 2, lit * 2);
            g.clip(k.dot);
            g.translate(cx, cy);
            g.rotate(t * 0.12);
            g.scale(rr, rr);
            k.hexStrokes(rr);
            g.setStroke(k.hexBold);
            g.setColor(PALE[f][step((1f - e) * 0.8f)]);
            g.draw(HEX);
            g.setTransform(old);
            g.setClip(oldClip);
            g.translate(cx, cy);
            k.dot.setFrame(-rr, -rr, rr * 2, rr * 2);
            g.clip(k.dot);
            g.setTransform(old);
            for (int ring = 0; ring < 2; ring++)
            {
                float rad = rr * (ring == 0 ? 0.12f + 0.75f * e : 0.06f + 0.45f * e);
                g.setStroke(stroke(ring == 0 ? 1.2f : 0.8f));
                g.setColor(WHITE[step((1f - e) * (ring == 0 ? 0.8f : 0.55f))]);
                k.dot.setFrame(hx - rad, hy - rad, rad * 2, rad * 2);
                g.draw(k.dot);
            }
            g.setClip(oldClip);
            if (!calm && q < 0.16f) light(g, GLOW, hx, hy, 7f, 1f - q / 0.16f);
            // sparks bouncing off
            g.setStroke(stroke(0.8f));
            for (int j = 0; j < (calm ? 2 : 4); j++)
            {
                double sa = ang + (hash(i * 11 + j) - 0.5) * 2.2;
                float len = (2.5f + 4f * hash(i * 13 + j)) * (1f - e);
                float s0 = 2f + 9f * e;
                float x0 = hx + (float) Math.cos(sa) * s0;
                float y0 = hy + (float) Math.sin(sa) * s0;
                g.setColor(TINT[f][step(1f - e)]);
                k.line.setLine(x0, y0, x0 + (float) Math.cos(sa) * len, y0 + (float) Math.sin(sa) * len);
                g.draw(k.line);
            }
        }

        // breaking up: hexagon fragments drift off, turning, and fade
        if (d > 0)
        {
            int n = calm ? 7 : 14;
            Path2D.Float frag = k.a;
            frag.reset();
            float time = d * 0.8f;
            for (int j = 0; j < n; j++)
            {
                double a0 = hash(j + 50) * TAU;
                float r0 = rr * (0.55f + 0.45f * hash(j + 60));
                float v = 20f + 18f * hash(j + 70);
                float fx = cx + (float) Math.cos(a0) * (r0 + v * time);
                float fy = cy + (float) Math.sin(a0) * (r0 + v * time) - 9f * time;
                float size = 2.6f * (1f - d * 0.55f);
                double rot = t * 3 + j;
                for (int vtx = 0; vtx <= 6; vtx++)
                {
                    double a = rot + vtx * Math.PI / 3;
                    float px = fx + (float) Math.cos(a) * size;
                    float py = fy + (float) Math.sin(a) * size;
                    if (vtx == 0) frag.moveTo(px, py);
                    else frag.lineTo(px, py);
                }
                frag.closePath();
                if (f == 0)
                {
                    // in its base form each fragment keeps the colour of where it broke off, round the wheel
                    int hue = Math.floorMod((int) Math.floor((0.16 + a0 / TAU) * RUNE_HUES), RUNE_HUES);
                    g.setColor(RUNE[hue][step(0.55f * (1f - d))]);
                    g.fill(frag);
                    g.setStroke(stroke(0.6f));
                    g.setColor(WHITE[step(0.8f * (1f - d))]);
                    g.draw(frag);
                    frag.reset();
                }
            }
            if (f != 0)
            {
                g.setColor(TINT[f][step(0.4f * (1f - d))]);
                g.fill(frag);
                g.setStroke(stroke(0.6f));
                g.setColor(PALE[f][step(0.85f * (1f - d))]);
                g.draw(frag);
            }
        }
        g.setStroke(oldStroke);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
    }

    // ------------------------------------------------------------------ the beam volley

    /** each shot: when it fires (s into the volley), how long it holds, its angle, which circle fires it */
    private static final float[] SHOT_FIRE = {1.0f, 1.42f, 1.84f, 2.3f};
    private static final float[] SHOT_HOLD = {0.42f, 0.42f, 0.42f, 0.85f};
    private static final float[] SHOT_ANGLE = {0f, -0.5f, 0.38f, 0f};
    private static final int[] SHOT_FROM = {0, 1, 2, 0};
    private static final float SHOT_FADE = 0.22f, AFTER = 0.3f;
    private static final float SWEEP = 0.34f;

    /** the small original rune strokes on the circles: each a list of segments (x1, y1, x2, y2) in a unit box */
    private static final float[][] GLYPHS = {
        {-1, -1, 0, 1, 0, 1, 1, -1, -0.6f, 0, 0.6f, 0},
        {0, -1, 0, 1, 0, 1, 0.8f, 0.4f},
        {-0.8f, -1, -0.8f, 0.6f, 0, -0.4f, 0, 1, 0.8f, -1, 0.8f, 0.6f},
        {-0.8f, -1, -0.8f, 1, -0.8f, 1, 0.8f, 1, 0.8f, 1, 0.8f, 0},
        {-1, -0.8f, 0, 0.8f, 0, 0.8f, 0.2f, -0.8f, 0.2f, -0.8f, 1, 0.8f},
        {-1, 0, 1, 0, 0, -1, 0, -0.3f, 0, 0.3f, 0, 1},
    };

    private static boolean shotOn(int shot, boolean calm)
    {
        return !calm || shot == 0 || shot == 3;
    }

    /** a shot's angle (screen radians) at this moment, for Chexy facing dir (1 right, -1 left) */
    private static double shotAngle(int shot, float p, int dir, boolean calm)
    {
        double o = SHOT_ANGLE[shot];
        if (shot == 3 && !calm)
        {
            float q = (p - SHOT_FIRE[3]) / SHOT_HOLD[3];
            o = -SWEEP + 2 * SWEEP * smooth(0f, 1f, q);
        }
        return dir > 0 ? o : Math.PI - o;
    }

    /** where the big circle points: at the first shot, then swinging round to start the sweep */
    private static double aim(float p, int dir, boolean calm)
    {
        double a0 = shotAngle(0, p, dir, calm);
        if (p < SHOT_FIRE[3] - 0.3f) return a0;
        double a3 = shotAngle(3, Math.max(p, SHOT_FIRE[3]), dir, calm);
        if (p >= SHOT_FIRE[3]) return a3;
        float k = smooth(SHOT_FIRE[3] - 0.3f, SHOT_FIRE[3], p);
        return a0 + (a3 - a0) * k;
    }

    /** how open each circle is (0 big, 1 upper satellite, 2 lower satellite) */
    private static float open(int which, float p, boolean calm)
    {
        if (which == 0) return smooth(0f, 0.4f, p) * (1f - smooth(VOLLEY_TIME - 0.5f, VOLLEY_TIME, p));
        if (calm) return 0f;
        float in = which == 1 ? 0.3f : 0.4f;
        float out = which == 1 ? 2.45f : 2.55f;
        return smooth(in, in + 0.3f, p) * (1f - smooth(out, out + 0.35f, p));
    }

    private static void emitter(int which, float cx, float cy, float p, int dir, boolean calm, float[] out)
    {
        if (which == 0)
        {
            double a = aim(p, dir, calm);
            out[0] = cx + (float) Math.cos(a) * 19f;
            out[1] = cy + (float) Math.sin(a) * 19f;
        }
        else
        {
            out[0] = cx + dir * 7f;
            out[1] = cy + (which == 1 ? -23f : 18f);
        }
    }

    /**
     * Chexy's kick back from the shots (and a little wobble), to add to where it is drawn: x into out[0], y into
     * out[1]. dir is the way it faces (1 right, -1 left).
     */
    public static void recoil(float p, int dir, boolean calm, float[] out)
    {
        out[0] = 0;
        out[1] = 0;
        if (p < 0) return;
        for (int s = 0; s < 4; s++)
        {
            if (!shotOn(s, calm)) continue;
            float q = p - SHOT_FIRE[s];
            if (q < 0 || q > 0.38f) continue;
            float k = 1f - q / 0.38f;
            float amp = (calm ? 1.2f : 3.2f) * k * k;
            double a = shotAngle(s, SHOT_FIRE[s], dir, calm);
            out[0] -= (float) Math.cos(a) * amp;
            out[1] -= (float) Math.sin(a) * amp;
            if (!calm) out[1] += (float) Math.sin(q * 45f) * 0.9f * k;
        }
    }

    /** how far a ray from (x, y) at angle a runs before it leaves the box (inset by 6 px), at most max */
    private static float reach(float x, float y, double a, Rectangle box, float max)
    {
        double dx = Math.cos(a), dy = Math.sin(a);
        double best = max;
        double l = box.x + 6, r = box.x + box.width - 6, t = box.y + 6, b = box.y + box.height - 6;
        if (dx > 1e-6) best = Math.min(best, (r - x) / dx);
        if (dx < -1e-6) best = Math.min(best, (l - x) / dx);
        if (dy > 1e-6) best = Math.min(best, (b - y) / dy);
        if (dy < -1e-6) best = Math.min(best, (t - y) / dy);
        return (float) Math.max(10, best);
    }

    /**
     * The beam volley, drawn in the panel's coordinates over everything: Chexy is centred on (cx, cy) facing dir,
     * p seconds into the volley, t a running clock, and the beams stop at the edges of box (what you can see).
     */
    public static void paintVolley(Graphics2D g, float cx, float cy, int dir, float p, float t, int form, boolean calm,
        Rectangle box)
    {
        if (p < 0 || p >= VOLLEY_TIME) return;
        int f = formOf(form);
        Scratch k = SCRATCH.get();
        Stroke oldStroke = g.getStroke();
        Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        dir = dir < 0 ? -1 : 1;

        // the circles, with their charge
        for (int which = 0; which < 3; which++)
        {
            float o = open(which, p, calm);
            if (o <= 0.01f) continue;
            emitter(which, cx, cy, p, dir, calm, k.p);
            double facing = which == 0 ? aim(p, dir, calm) : shotAngle(which, p, dir, calm);
            // the charge: brightest just before this circle's next shot
            float charge = 0f;
            for (int s = 0; s < 4; s++)
            {
                if (SHOT_FROM[s] != which || !shotOn(s, calm)) continue;
                charge = Math.max(charge, smooth(SHOT_FIRE[s] - (s == 0 ? 0.6f : 0.4f), SHOT_FIRE[s], p)
                    * (p < SHOT_FIRE[s] + 0.1f ? 1f : 0f));
                if (p >= SHOT_FIRE[s] && p < SHOT_FIRE[s] + SHOT_HOLD[s]) charge = Math.max(charge, 0.7f);
            }
            circle(g, k, k.p[0], k.p[1], which == 0 ? 14f : 7.5f, facing, t * (which == 0 ? 1.6f : -2.2f), o, f,
                which == 0, charge);
            if (charge > 0.05f && charge < 0.99f && p < SHOT_FIRE[3] + 0.05f)
            {
                // particles drawn in to the circle
                int n = calm ? 3 : 7;
                for (int j = 0; j < n; j++)
                {
                    float ph = (float) ((t * 1.9f + j / (float) n) % 1.0);
                    double ang = j * 2.39 + t * 0.6;
                    float rad = (which == 0 ? 30f : 16f) * (1f - ph);
                    g.setColor(PALE[f][step(ph * charge)]);
                    fillDot(g, k, k.p[0] + (float) Math.cos(ang) * rad, k.p[1] + (float) Math.sin(ang) * rad, 0.5f + 0.6f * ph);
                }
            }
        }

        // the beams
        for (int s = 0; s < 4; s++)
        {
            if (!shotOn(s, calm)) continue;
            float q = p - SHOT_FIRE[s];
            float hold = SHOT_HOLD[s];
            if (q < 0 || q > hold + SHOT_FADE + AFTER) continue;
            emitter(SHOT_FROM[s], cx, cy, p, dir, calm, k.p);
            double a = shotAngle(s, p, dir, calm);
            float ex = k.p[0], ey = k.p[1];
            float full = reach(ex, ey, a, box, 180f);
            float len = full * Math.min(1f, q / 0.07f);
            float x1 = ex + (float) Math.cos(a) * len;
            float y1 = ey + (float) Math.sin(a) * len;
            float on = q < hold ? 1f : Math.max(0f, 1f - (q - hold) / SHOT_FADE);
            // a brief afterimage left where it was
            if (q > hold)
            {
                float after = Math.max(0f, 1f - (q - hold) / (SHOT_FADE + AFTER));
                g.setStroke(stroke(7f));
                g.setColor(TINT[f][step(0.13f * after)]);
                k.line.setLine(ex, ey, x1, y1);
                g.draw(k.line);
            }
            if (on <= 0) continue;
            float punch = calm ? 1f : 1f + 0.6f * Math.max(0f, 1f - q / 0.16f);
            float w = (2.6f + 0.35f * (float) Math.sin(t * 45f + s)) * punch * on * (calm ? 0.8f : 1f);
            beam(g, k, ex, ey, x1, y1, len, w, on, f, t, s);
            if (!calm && q < 0.1f)
            {
                // the punch: the whole beam flashes white as it fires, and a bright spear tip leads it out
                float e = q / 0.1f;
                g.setStroke(stroke(w * 2.4f));
                g.setColor(WHITE[step(0.45f * (1f - e))]);
                k.line.setLine(ex, ey, x1, y1);
                g.draw(k.line);
                light(g, GLOW, x1, y1, 9f, 1f - e * 0.6f);
            }
            if (q > 0.06f)
            {
                impact(g, k, x1, y1, a, w, on, f, t, s, calm);
                // the moment it strikes: a ring of light bursts out where it lands
                float e = (q - 0.06f) / 0.3f;
                if (e < 1)
                {
                    float rad = 2f + 12f * (1f - (1f - e) * (1f - e));
                    g.setStroke(stroke(1.2f * (1f - e) + 0.4f));
                    g.setColor(PALE[f][step(0.9f * (1f - e))]);
                    k.dot.setFrame(x1 - rad, y1 - rad, rad * 2, rad * 2);
                    g.draw(k.dot);
                }
            }
            // the muzzle: a hot point where it leaves the circle, a flash and a shock ring as it fires
            g.setColor(WHITE[step(on)]);
            fillDot(g, k, ex, ey, 1.4f + w * 0.45f);
            if (q < 0.25f)
            {
                float e = q / 0.25f;
                float cf = (float) Math.cos(a), sf = (float) Math.sin(a);
                Path2D.Float ring = k.a;
                ring.reset();
                ellipse(ring, ex + cf * 4f * e, ey + sf * 4f * e, (SHOT_FROM[s] == 0 ? 14f : 7.5f) * (1.1f + 0.9f * e), cf, sf, 0.42f);
                g.setStroke(stroke(1.4f * (1f - e) + 0.4f));
                g.setColor(WHITE[step((calm ? 0.4f : 0.85f) * (1f - e))]);
                g.draw(ring);
            }
            if (!calm && q < 0.18f) light(g, GLOW, ex, ey, 16f, 1f - q / 0.18f);
        }
        g.setStroke(oldStroke);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
    }

    /** a magic circle seen at a slant, facing along its shot: outer rune ring and inner geometry turning opposite */
    private static void circle(Graphics2D g, Scratch k, float x, float y, float R, double facing, float spin,
        float open, int f, boolean rich, float charge)
    {
        float rr = R * (open < 1 ? Math.max(0.05f, spring(open)) : 1f);
        float a = Math.min(1f, open * 1.3f);
        float cf = (float) Math.cos(facing), sf = (float) Math.sin(facing);
        float sq = rich ? 0.42f : 0.5f;
        // its faint face, so it reads as a disc of light
        light(g, GLOW, x, y, rr * 1.15f, 0.22f * a + 0.3f * charge * a);
        // rings: outer pair and inner one
        Path2D.Float rings = k.a;
        rings.reset();
        float[] radii = rich ? RICH_RINGS : SMALL_RINGS;
        for (float rad : radii) ellipse(rings, x, y, rr * rad, cf, sf, sq);
        g.setStroke(stroke(2.2f));
        g.setColor(TINT[f][step(0.28f * a)]);
        g.draw(rings);
        g.setStroke(stroke(0.75f));
        g.setColor(PALE[f][step(0.9f * a)]);
        g.draw(rings);
        // the rune ring (or, on a small circle, ticks), turning one way
        Path2D.Float marks = k.b;
        marks.reset();
        int n = rich ? 10 : 6;
        for (int i = 0; i < n; i++)
        {
            double ang = spin + i * TAU / n;
            if (rich)
            {
                float[] gl = GLYPHS[i % GLYPHS.length];
                float tx = (float) -Math.sin(ang), ty = (float) Math.cos(ang);
                float rx = (float) Math.cos(ang), ry = (float) Math.sin(ang);
                float size = 0.085f;
                // in its base form each rune glows its own colour of the wheel; otherwise they are all white
                Path2D.Float into = f == 0 ? k.c : marks;
                if (f == 0) into.reset();
                for (int s = 0; s + 3 < gl.length; s += 4)
                {
                    float u1 = rx * 0.77f + (tx * gl[s] + rx * gl[s + 1]) * size;
                    float v1 = ry * 0.77f + (ty * gl[s] + ry * gl[s + 1]) * size;
                    float u2 = rx * 0.77f + (tx * gl[s + 2] + rx * gl[s + 3]) * size;
                    float v2 = ry * 0.77f + (ty * gl[s + 2] + ry * gl[s + 3]) * size;
                    map(k.p, x, y, rr, cf, sf, sq, u1, v1);
                    into.moveTo(k.p[0], k.p[1]);
                    map(k.p, x, y, rr, cf, sf, sq, u2, v2);
                    into.lineTo(k.p[0], k.p[1]);
                }
                if (f == 0)
                {
                    g.setStroke(stroke(0.7f));
                    g.setColor(RUNE[i % RUNE_HUES][step(0.95f * a)]);
                    g.draw(into);
                }
            }
            else
            {
                float u = (float) Math.cos(ang), v = (float) Math.sin(ang);
                Path2D.Float into = f == 0 ? k.c : marks;
                if (f == 0) into.reset();
                map(k.p, x, y, rr, cf, sf, sq, u * 0.66f, v * 0.66f);
                into.moveTo(k.p[0], k.p[1]);
                map(k.p, x, y, rr, cf, sf, sq, u * 0.92f, v * 0.92f);
                into.lineTo(k.p[0], k.p[1]);
                if (f == 0)
                {
                    g.setStroke(stroke(0.8f));
                    g.setColor(RUNE[(i * 5 / 3) % RUNE_HUES][step(0.95f * a)]);
                    g.draw(into);
                }
            }
        }
        // the inner geometry, turning the other way: two squares crossed into a star of eight points
        if (rich)
        {
            for (int sqr = 0; sqr < 2; sqr++)
            {
                for (int v = 0; v <= 4; v++)
                {
                    double ang = -spin * 1.5 + sqr * Math.PI / 4 + v * Math.PI / 2;
                    map(k.p, x, y, rr, cf, sf, sq, (float) Math.cos(ang) * 0.54f, (float) Math.sin(ang) * 0.54f);
                    if (v == 0) marks.moveTo(k.p[0], k.p[1]);
                    else marks.lineTo(k.p[0], k.p[1]);
                }
            }
            // and fine ticks round the outer pair, turning slowly
            for (int i = 0; i < 24; i++)
            {
                double ang = -spin * 0.4 + i * TAU / 24;
                float u = (float) Math.cos(ang), v = (float) Math.sin(ang);
                map(k.p, x, y, rr, cf, sf, sq, u * 0.92f, v * 0.92f);
                marks.moveTo(k.p[0], k.p[1]);
                map(k.p, x, y, rr, cf, sf, sq, u, v);
                marks.lineTo(k.p[0], k.p[1]);
            }
        }
        g.setStroke(stroke(0.6f));
        g.setColor(WHITE[step(0.85f * a)]);
        g.draw(marks);
        // the core, brightening as it charges
        g.setColor(TINT[f][step((0.35f + 0.5f * charge) * a)]);
        fillDot(g, k, x, y, (1.4f + 2.4f * charge) * (rr / R));
        g.setColor(WHITE[step((0.6f + 0.4f * charge) * a)]);
        fillDot(g, k, x, y, (0.7f + 1.3f * charge) * (rr / R));
    }

    private static final float[] RICH_RINGS = {1f, 0.92f, 0.62f, 0.3f};
    private static final float[] SMALL_RINGS = {1f, 0.6f};

    /** a point of a slanted circle: (u, v) on the unit disc, the disc squashed along its facing direction */
    private static void map(float[] out, float x, float y, float R, float cf, float sf, float sq, float u, float v)
    {
        out[0] = x + (u * sq * cf - v * sf) * R;
        out[1] = y + (u * sq * sf + v * cf) * R;
    }

    private static void ellipse(Path2D.Float path, float x, float y, float R, float cf, float sf, float sq)
    {
        for (int i = 0; i <= 28; i++)
        {
            double a = i * TAU / 28;
            float u = (float) Math.cos(a), v = (float) Math.sin(a);
            float px = x + (u * sq * cf - v * sf) * R;
            float py = y + (u * sq * sf + v * cf) * R;
            if (i == 0) path.moveTo(px, py);
            else path.lineTo(px, py);
        }
    }

    /** one beam: soft glow, coloured body, hot white core, wavy energy edges and bright ripples running out along it */
    private static void beam(Graphics2D g, Scratch k, float x0, float y0, float x1, float y1, float len, float w,
        float on, int f, float t, int seed)
    {
        k.line.setLine(x0, y0, x1, y1);
        g.setStroke(stroke(w * 3.6f));
        g.setColor(TINT[f][step(0.12f * on)]);
        g.draw(k.line);
        g.setStroke(stroke(w * 2.2f));
        g.setColor(TINT[f][step(0.25f * on)]);
        g.draw(k.line);
        g.setStroke(stroke(w * 1.25f));
        g.setColor(PALE[f][step(0.7f * on)]);
        g.draw(k.line);
        g.setStroke(stroke(Math.max(0.6f, w * 0.55f)));
        g.setColor(WHITE[step(on)]);
        g.draw(k.line);
        if (len < 8) return;
        float ux = (x1 - x0) / len, uy = (y1 - y0) / len;
        float nx = -uy, ny = ux;
        // two strands of energy weaving along its edges
        int pts = Math.max(4, Math.min(40, (int) (len / 5)));
        g.setStroke(stroke(0.6f));
        for (int strand = 0; strand < 2; strand++)
        {
            Path2D.Float path = k.a;
            path.reset();
            for (int i = 0; i <= pts; i++)
            {
                float s = len * i / pts;
                float wob = (float) Math.sin(s * 0.33f - t * 30f + strand * Math.PI + seed) * (w * 0.9f + 1f);
                float px = x0 + ux * s + nx * wob;
                float py = y0 + uy * s + ny * wob;
                if (i == 0) path.moveTo(px, py);
                else path.lineTo(px, py);
            }
            g.setColor(TINT[f][step(0.8f * on)]);
            g.draw(path);
        }
        // pulses of energy racing out along it: soft swellings of light
        for (int j = 0; j < 3; j++)
        {
            float s = (float) ((t * 260f + j * len / 3f + seed * 17) % len);
            float px = x0 + ux * s, py = y0 + uy * s;
            g.setColor(TINT[f][step(0.35f * on)]);
            fillDot(g, k, px, py, w * 1.3f + 0.6f);
            g.setColor(WHITE[step(0.75f * on)]);
            fillDot(g, k, px, py, w * 0.6f + 0.3f);
        }
    }

    /** where a beam ends: a flare of light, a glinting star and sparks spraying back off it */
    private static void impact(Graphics2D g, Scratch k, float x, float y, double a, float w, float on, int f, float t,
        int seed, boolean calm)
    {
        float pulse = 0.8f + 0.2f * (float) Math.sin(t * 38f + seed);
        light(g, GLOW, x, y, (5f + w * 1.6f) * pulse, 0.8f * on);
        g.setColor(TINT[f][step(0.5f * on)]);
        fillDot(g, k, x, y, 1.6f + w * 0.5f);
        g.setStroke(stroke(0.7f));
        g.setColor(WHITE[step(0.8f * on)]);
        float fl = (3f + 2f * pulse) * on;
        k.line.setLine(x - fl, y, x + fl, y);
        g.draw(k.line);
        k.line.setLine(x, y - fl, x, y + fl);
        g.draw(k.line);
        int slot = (int) Math.floor(t * 18f);
        int n = calm ? 2 : 5;
        for (int j = 0; j < n; j++)
        {
            int h = slot * 31 + j * 7 + seed * 101;
            double sa = a + Math.PI + (hash(h) - 0.5) * 2.6;
            float s0 = 1.5f + 3f * hash(h + 1);
            float len = 2.5f + 4.5f * hash(h + 2);
            float x0 = x + (float) Math.cos(sa) * s0, y0 = y + (float) Math.sin(sa) * s0;
            g.setColor(j % 2 == 0 ? WHITE[step(0.9f * on)] : TINT[f][step(0.9f * on)]);
            k.line.setLine(x0, y0, x0 + (float) Math.cos(sa) * len, y0 + (float) Math.sin(sa) * len);
            g.draw(k.line);
        }
    }

    /** the part of the panel a volley can touch, around Chexy at (cx, cy), inside box */
    public static Rectangle volleyArea(float cx, float cy, Rectangle box)
    {
        int top = (int) Math.max(box.y, cy - 120);
        int bottom = (int) Math.min(box.y + box.height, cy + 120);
        return new Rectangle(box.x, top, box.width, Math.max(1, bottom - top));
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Turns server answers into the words the sidebar (and chat) shows: connection state, the verified RSN, the
 * event/team, and what to do about a name mismatch or a revoked key. Written for players: say what is wrong,
 * what it means for their drops, and the one thing to do about it. No RuneLite dependencies (unit-tested).
 */
public final class ConnectionStatus
{
    /** Where players get a key (website wording). */
    public static final String WHERE_TO_GET_A_KEY = "the ForgeBingo website (your team board > Connect RuneLite)";

    public enum Level
    {
        OK,
        INFO,
        WARNING,
        ERROR
    }

    /** One message of the sidebar's status block. May contain "\n" line breaks. */
    public static final class Line
    {
        public final Level level;
        public final String text;

        public Line(Level level, String text)
        {
            this.level = level;
            this.text = text;
        }

        @Override
        public String toString()
        {
            return level + ": " + text;
        }
    }

    private ConnectionStatus()
    {
    }

    /** Message for a 401 (queue paused until the key changes). */
    public static String authMessage(String errorCode)
    {
        if ("api_key_revoked".equals(errorCode))
        {
            return "Your plugin key stopped working (it was revoked or replaced by a newer one). Get a new key from "
                + WHERE_TO_GET_A_KEY + " and paste it into the ForgeBingo plugin settings.";
        }
        return "Your plugin key wasn't recognised. Copy it again from " + WHERE_TO_GET_A_KEY
            + " and paste it into the ForgeBingo plugin settings.";
    }

    /** Messages for a hello response: every verified board in one card, then one card per problem. */
    public static List<Line> fromHello(ApiModels.HelloResponse r)
    {
        List<Line> out = new ArrayList<>();
        if (r == null || r.memberships == null || r.memberships.isEmpty())
        {
            out.add(new Line(Level.WARNING, "This key isn't on any bingo team yet. Join a team with your team link on the website, then press Refresh."));
            return out;
        }
        List<ApiModels.Membership> verified = new ArrayList<>();
        List<Line> problems = new ArrayList<>();
        for (ApiModels.Membership m : r.memberships)
        {
            if ("verified".equals(m.status)) verified.add(m);
            else problems.add(line(m));
        }
        if (!verified.isEmpty()) out.add(verifiedLine(verified));
        out.addAll(problems);
        return out;
    }

    /** "Tracking as Gus. Drops count for:" + one bullet per board. */
    static Line verifiedLine(List<ApiModels.Membership> ms)
    {
        StringBuilder s = new StringBuilder("Tracking drops as ").append(ms.get(0).pluginRsn).append(" for:");
        for (ApiModels.Membership m : ms)
        {
            s.append("\n- ").append(where(m));
        }
        return new Line(Level.OK, s.toString());
    }

    static Line line(ApiModels.Membership m)
    {
        String where = where(m);
        String status = m.status == null ? "" : m.status;
        switch (status)
        {
            case "verified":
                return new Line(Level.OK, "Tracking drops as " + m.pluginRsn + " for " + where + ".");
            case "rsn_mismatch":
                return new Line(Level.ERROR, "Name doesn't match on " + where + ": you're playing as " + m.pluginRsn
                    + ", but the team has you down as " + m.joinedRsn + ". Your drops still send, but a reviewer has to approve them. "
                    + "To fix it, change your name to " + m.pluginRsn + " on the team board, or log in as " + m.joinedRsn + ".");
            case "account_mismatch":
                return new Line(Level.ERROR, where + " is linked to a different OSRS account, so drops from this one won't count. "
                    + "Log in on the linked account, or ask your organizer to switch it.");
            case "account_taken":
                return new Line(Level.ERROR, "This OSRS account is already linked to another player in " + where
                    + ", so drops from it won't count for you. Ask your organizer to sort it out.");
            case "not_approved":
                return new Line(Level.WARNING, "Waiting for the organizer to let you into " + where + ". Drops will count once you're approved.");
            default:
                return new Line(Level.WARNING, where + ": " + status);
        }
    }

    /** "Goblin Squad (Plugin Beta Test)": the team first, since that's what players recognise. */
    static String where(ApiModels.Membership m)
    {
        if (m.teamName == null) return m.eventName == null ? "your event" : m.eventName;
        return m.teamName + (m.eventName == null ? "" : " (" + m.eventName + ")");
    }

    /** True when every membership is verified (drops count automatically where the event auto-approves). */
    public static boolean allVerified(ApiModels.HelloResponse r)
    {
        if (r == null || r.memberships == null || r.memberships.isEmpty())
        {
            return false;
        }
        for (ApiModels.Membership m : r.memberships)
        {
            if (!m.verified)
            {
                return false;
            }
        }
        return true;
    }

    /** What the pasted key can do, under the connection state. */
    public static String keyScope(ApiModels.Me me)
    {
        if (me == null)
        {
            return "";
        }
        return "event".equals(me.keyScope) ? "This key works for one event" : "This key works for all your events";
    }
}

package com.forgebingo.core;

/**
 * The little creatures that wander over the side panel, by theme. Each is our own original pixel art in the spirit
 * of the place it is named after. {@code variants} is how many looks it has (a click cycles a crab's colour).
 */
public enum Critter
{
    IMP(1),
    // Theatre of Blood
    NYLO(3), XARPUS(1), VERZIK(1),
    // Chambers of Xeric: the jewelled crab; white, red, green, blue. The bosses turn up very rarely.
    CRAB(4), MUTTADILE(1), TEKTON(1), VESPULA(1), VANGUARD(3),
    // Tombs of Amascut
    AKKHA(1), ZEBAK(1), KEPHRI(1), BABA(1), WARDEN(1),
    // Barrows
    AHRIM(1), DHAROK(1), GUTHAN(1), KARIL(1), TORAG(1), VERAC(1),
    // Inferno
    ZUK(1), JAD(1), MELEER(1), NIBBLER(1),
    // Skilling: any of the game's pets (see Pet); which one is kept beside it, not as a variant
    PET(1),
    // Chexy: a glowing rainbow atom, a rare visitor in every theme (drawn by Chexy, not a pixel grid)
    CHEXY(1);

    public final int variants;

    Critter(int variants)
    {
        this.variants = variants;
    }

    /** These never land: they fly around the panel instead of walking along the cards. */
    public boolean flies()
    {
        return this == XARPUS || this == VESPULA || this == CHEXY;
    }

    /** Small things that fall down the panel between the famous items. */
    public enum Fall
    {
        BLOOD_DROP, CRYSTAL, KEPHRI_BOMB, WATER_DROP, BONE, EMBER
    }
}

package com.forgebingo.core;

import java.awt.image.BufferedImage;

/**
 * One door to every creature's picture. Anything not drawn yet shows as the imp.
 *
 * The pictures are baked: they come from the bundled sheet sprites/critters.png + critters.txt (see SpriteSheet),
 * keyed "CRITTER|variant|frame" and "fall|FALL|variant". The code that draws them is RaidSprites and CryptSprites in
 * src/test/java (reached through CritterArt there, which is this class as it was before baking); after changing any
 * of it, re-bake with CritterSheetBaker, or CritterSpritesBakedTest fails.
 *
 * The variant and frame arithmetic below is exactly what the drawing code did with out-of-range values, so every
 * input gets the picture it always got.
 */
public final class CritterSprite
{
    private static final SpriteSheet SHEET = new SpriteSheet("critters");

    private CritterSprite()
    {
    }

    /** One walk frame (0 or 1) on the PixelArt.WIDTH x PixelArt.HEIGHT grid, facing left, feet on the bottom row. */
    public static BufferedImage image(Critter c, int variant, int frame)
    {
        // Chexy is drawn live by Chexy; this is just a still of it
        if (c == Critter.CHEXY) return Chexy.still();
        // the variant wraps; any frame but 0 is the second. IMP and PET are not on the sheet, so they fall through.
        BufferedImage img = c == null ? null
            : SHEET.get(c.name() + "|" + Math.floorMod(variant, c.variants) + (frame == 0 ? "|0" : "|1"));
        return img != null ? img : ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, frame);
    }

    /** A small falling thing, or null when nobody draws it. */
    public static BufferedImage fall(Critter.Fall f, int variant)
    {
        if (f == null) return null;
        // bones and embers wrap between their two looks; blood drops and crystals are look 0 up to variant 0 and
        // look 1 above it; the Kephri bomb and the water drop have one look
        int v = f == Critter.Fall.BONE || f == Critter.Fall.EMBER ? Math.floorMod(variant, 2)
            : (f == Critter.Fall.BLOOD_DROP || f == Critter.Fall.CRYSTAL) && variant > 0 ? 1 : 0;
        return SHEET.get("fall|" + f.name() + "|" + v);
    }
}

package com.forgebingo.core;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Lookup tables that ship as readable text instead of as Java: /com/forgebingo/data/NAME.txt, bundled in the jar
 * (nothing is ever downloaded). Each table class (ActivityItems, PetTable) parses its own file once, strictly.
 *
 * WHEN A FILE IS MISSING OR BROKEN the table class calls {@link #failed} and carries on with an EMPTY table: an
 * error is logged, loudly, once; nothing is thrown. Reason: the tables load in a static initialiser the first time
 * the game thread asks about an item, and an exception there is an Error that RuneLite's event bus does not catch,
 * so it would break the client for the player, on every later use too. A Plugin Hub plugin must never do that. An
 * empty table is not silent either: the files are part of the jar, and ActivityItemsDataTest / PetTableDataTest
 * compare what was loaded with the old Java tables row for row, so a missing, empty or malformed file cannot get
 * past the build. Parsing is all or nothing: one bad line refuses the whole file, never half a table.
 */
final class DataFile
{
    private static final Logger log = LoggerFactory.getLogger(DataFile.class);

    private DataFile()
    {
    }

    /**
     * The file's lines, trimmed, without blank lines and "#" comments.
     *
     * @throws IllegalStateException when the file is missing, unreadable or has no lines at all
     */
    static List<String> lines(String name)
    {
        List<String> out = new ArrayList<>();
        try (InputStream in = DataFile.class.getResourceAsStream("/com/forgebingo/data/" + name + ".txt"))
        {
            for (String line : new String(in.readAllBytes(), StandardCharsets.UTF_8).split("\n"))
            {
                line = line.trim();
                if (!line.isEmpty() && !line.startsWith("#")) out.add(line);
            }
        }
        catch (Exception e) // a missing file is a null stream
        {
            throw new IllegalStateException(name + ".txt cannot be read", e);
        }
        if (out.isEmpty()) throw new IllegalStateException(name + ".txt is empty");
        return out;
    }

    /** Says, once and loudly, that a table could not be loaded and is empty. */
    static void failed(String name, RuntimeException e)
    {
        log.error("ForgeBingo: data file '{}' is missing or broken; this table is EMPTY and drops that need it will not count", name, e);
    }
}

package com.forgebingo.core;

/** How the queue should react to an HTTP outcome (docs/API.md section 8, "Limits and errors"). */
public enum ErrorClass
{
    /** 2xx. */
    SUCCESS,
    /** Network error, 408, 425, 429 (honour Retry-After), 5xx: retry with backoff. */
    TRANSIENT,
    /** 401 invalid_api_key: keep the events, pause sending, ask the user for a new key. */
    AUTH,
    /** 409 event_id_conflict: regenerate the eventId and retry. */
    CONFLICT,
    /**
     * 400 (invalid_payload, invalid_items, invalid_rsn, invalid_account_hash, unsupported_source_type,
     * occurred_at_out_of_range, invalid_json), 403 not_a_member (refresh the board list), 404, 413, 415 and
     * any other 4xx: the server will never accept this event. Drop it and tell the user.
     */
    PERMANENT;

    /** @param status HTTP status, or 0 for a network failure. */
    public static ErrorClass of(int status)
    {
        return of(status, null);
    }

    public static ErrorClass of(int status, String code)
    {
        if (status >= 200 && status < 300)
        {
            return SUCCESS;
        }
        if (status == 0 || status == 408 || status == 425 || status == 429 || status >= 500)
        {
            return TRANSIENT;
        }
        if (status == 401)
        {
            return AUTH;
        }
        if (status == 409 && "event_id_conflict".equals(code))
        {
            return CONFLICT;
        }
        return PERMANENT;
    }
}

package com.forgebingo.core;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Suppresses the same logical event seen twice in a short window (for example a
 * collection-log message emitted alongside a loot event, or a chat line replayed on login).
 */
public final class EventDeduplicator
{
    private final long windowMillis;
    private final int maxEntries;
    private final Map<String, Long> seen = new LinkedHashMap<>();

    public EventDeduplicator(long windowMillis, int maxEntries)
    {
        this.windowMillis = windowMillis;
        this.maxEntries = maxEntries;
    }

    public synchronized boolean firstSeen(String signature, long now)
    {
        seen.values().removeIf(t -> now - t > windowMillis);
        if (seen.containsKey(signature))
        {
            return false;
        }
        seen.put(signature, now);
        while (seen.size() > maxEntries)
        {
            seen.remove(seen.keySet().iterator().next());
        }
        return true;
    }

    public synchronized void clear()
    {
        seen.clear();
    }

    public static String signature(GameEvent e, int tick)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(e.sourceType).append('|').append(e.sourceName).append('|').append(e.npcId).append('#').append(e.npcIndex)
            .append('|').append(e.skill).append('|').append(e.level).append('|').append(tick);
        if (e.items != null)
        {
            for (GameEvent.Item i : e.items)
            {
                sb.append('|').append(i.itemId).append('x').append(i.quantity);
            }
        }
        return sb.toString();
    }
}

package com.forgebingo.core;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;

/**
 * One thing that happened in game, as sent to {@code POST /v1/game-events} (docs/API.md section 8).
 * The server decides which team boards / tasks it counts for; the client never matches.
 *
 * <p>{@code id} is serialized as {@code eventId}: a UUID generated once and reused on every retry
 * (the server's idempotency key). {@code accountHash} is a decimal string (a 64-bit long would lose
 * precision in JSON).
 */
public final class GameEvent
{
    public static final String NPC = "npc";
    public static final String RAID_CHEST = "raid_chest";
    public static final String CLUE = "clue";
    public static final String COLLECTION_LOG = "collection_log";
    public static final String PET = "pet";
    public static final String KC = "kc";
    public static final String LEVEL = "level";
    /** a finished Combat Achievement task (sourceName = task name); hidden until the server supports it */
    public static final String COMBAT_TASK = "combat_task";

    public static final class Item
    {
        public int itemId;
        public int quantity;

        public Item()
        {
        }

        public Item(int itemId, int quantity)
        {
            this.itemId = itemId;
            this.quantity = quantity;
        }
    }

    @SerializedName("eventId")
    public String id;
    public String sourceType;
    /** ISO-8601; the server accepts now-1d .. now+5m. */
    public String occurredAt;
    /** Required, ^[A-Za-z0-9 _-]{1,12}$ */
    public String rsn;
    /** Required, client.getAccountHash() as a decimal string. */
    public String accountHash;
    /** npc */
    public Integer npcId;
    /** which NPC in the scene dropped it (never sent or saved): keeps two same-tick kills with the same loot apart */
    public transient Integer npcIndex;
    public String npcName;
    /** raid_chest / clue (tier) / kc (boss or raid name). */
    public String sourceName;
    /** Canonical (unnoted) item ids. Max 40. */
    public List<Item> items;
    /** level: lower-case skill name, or "overall". */
    public String skill;
    public Integer level;
    public String pluginVersion;
    public Integer world;

    public GameEvent()
    {
    }

    public GameEvent addItem(int itemId, int quantity)
    {
        if (items == null)
        {
            items = new ArrayList<>();
        }
        items.add(new Item(itemId, quantity));
        return this;
    }

    /** Human label for notices. */
    public String label()
    {
        if (sourceName != null && !sourceName.isEmpty())
        {
            return sourceName;
        }
        if (npcName != null && !npcName.isEmpty())
        {
            return npcName;
        }
        return skill != null ? skill : sourceType;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Keeps ground items that did not come from the monster out of its loot (owner, 2026-11-17). RuneLite's loot tracker
 * takes whatever appears on the monster's tiles as it dies, whoever owns it, so an item put there at that moment
 * would look like a drop:
 * <ul>
 *   <li>an item the player dropped from the backpack themselves in the last few ticks;</li>
 *   <li>an item belonging to another player turning visible on (or right next to) the monster's tiles.</li>
 * </ul>
 * Another player's item elsewhere on screen is ignored, so a busy spot does not hide real drops.
 * Pure Java so it is unit-tested without RuneLite.
 */
public final class GroundGuard
{
    /** how long after the player chose "Drop" on an item it can still be the thing lying under the monster */
    public static final int DROP_WINDOW = 4;
    /** another player's item and the monster's loot must show up in (nearly) the same tick to be mixed up */
    public static final int FOREIGN_WINDOW = 1;
    private static final int KEEP = 30;

    private final Map<Integer, Integer> droppedByMe = new HashMap<>();
    /** item id to where and when another player's copy appeared: {tick, x, y, plane} */
    private final Map<Integer, List<int[]>> foreign = new HashMap<>();

    /** The player chose "Drop" on this backpack item. */
    public void onDropClicked(int itemId, int tick)
    {
        droppedByMe.put(itemId, tick);
    }

    /** A ground item owned by another player became visible at world tile (x, y, plane). */
    public void onForeignItem(int itemId, int tick, int x, int y, int plane)
    {
        foreign.computeIfAbsent(itemId, k -> new ArrayList<>()).add(new int[]{tick, x, y, plane});
    }

    /**
     * true when this item in the loot of a monster that died at {@code tick} may count as that monster's drop.
     * (npcX, npcY, plane) is the monster's south-west tile and {@code size} its width in tiles.
     */
    public boolean fromMonster(int itemId, int tick, int npcX, int npcY, int plane, int size)
    {
        Integer d = droppedByMe.get(itemId);
        if (d != null && tick >= d && tick - d <= DROP_WINDOW) return false;
        List<int[]> seen = foreign.get(itemId);
        if (seen == null) return true;
        int s = Math.max(1, size);
        for (int[] f : seen)
        {
            if (Math.abs(tick - f[0]) > FOREIGN_WINDOW || f[3] != plane) continue;
            // the monster's tiles plus one tile around them
            if (f[1] >= npcX - 1 && f[1] <= npcX + s && f[2] >= npcY - 1 && f[2] <= npcY + s) return false;
        }
        return true;
    }

    /** how long a drop of the player's own stays remembered while it lies there: 20 minutes of game ticks */
    public static final int OWN_LOOT_KEEP = 2000;
    /** the player's own fresh loot lying on the ground: "id:x:y:plane" to the tick it appeared */
    private final Map<String, Integer> ownLoot = new HashMap<>();

    private static String at(int itemId, int x, int y, int plane)
    {
        return itemId + ":" + x + ":" + y + ":" + plane;
    }

    /**
     * A ground item that belongs to the player appeared at world tile (x, y, plane). Unless they just dropped it from
     * the backpack themselves, it is loot of theirs waiting to be picked up (owner, 2026-11-27: a sea creature killed
     * from a distance leaves its loot where it died, and taking it with Telekinetic Grab did not count).
     */
    public void onOwnItem(int itemId, int tick, int x, int y, int plane)
    {
        Integer d = droppedByMe.get(itemId);
        if (d != null && tick >= d && tick - d <= DROP_WINDOW) return;
        ownLoot.put(at(itemId, x, y, plane), tick);
    }

    /**
     * A ground item vanished from world tile (x, y, plane). true when it was the player's own fresh loot (see
     * {@link #onOwnItem}): picking that up is collecting a reward, not picking up someone's item. Answers once.
     */
    public boolean takeOwnLoot(int itemId, int x, int y, int plane)
    {
        return ownLoot.remove(at(itemId, x, y, plane)) != null;
    }

    /** Call once per game tick. */
    public void prune(int tick)
    {
        ownLoot.values().removeIf(t -> t < tick - OWN_LOOT_KEEP);
        droppedByMe.values().removeIf(t -> t < tick - KEEP);
        foreign.values().forEach(l -> l.removeIf(f -> f[0] < tick - KEEP));
        foreign.values().removeIf(List::isEmpty);
    }
}

package com.forgebingo.core;

import java.util.regex.Pattern;

/**
 * Guards icon loading: the plugin only loads item icons via ItemManager or the two server icon endpoints
 * ({@code /v1/icons/items/<id>.png}, {@code /v1/icons/tiles/<uuid>}). Never a URL taken from board data.
 */
public final class IconRef
{
    private static final Pattern PROXY = Pattern.compile(
        "^/v1/icons/(?:items/\\d{1,6}\\.png|tiles/[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})$");

    private IconRef()
    {
    }

    public static boolean isProxyPath(String path)
    {
        return path != null && path.length() < 100 && PROXY.matcher(path).matches();
    }

    public static String item(int itemId)
    {
        return "/v1/icons/items/" + itemId + ".png";
    }
}

package com.forgebingo.core;

import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The website's pixel-art imp (apps/web/src/features/fun/ImpArt.tsx), ported pixel for pixel so the side panel's
 * imps are the same ones that wander over the site. Our own original art: red skin, little horns, bat wings.
 * Drawn on a 42 x 34 grid, facing LEFT, feet on the bottom edge. Two walk frames; optional hat and held item.
 */
public final class ImpSprite
{
    public static final int WIDTH = 42;
    public static final int HEIGHT = 34;
    /** the grid's origin sits at (-6, -2), like the website's viewBox */
    private static final int OX = 6;
    private static final int OY = 2;

    public enum Hat { NONE, CHEF, WIZARD, SANTA, BUNNY }

    public enum Item { NONE, FIRE_STAFF, AYAK, SOULREAPER }

    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private ImpSprite()
    {
    }

    /** One frame (0 or 1) as a transparent image; cached. */
    public static BufferedImage image(Hat hat, Item item, int frame)
    {
        Hat h = hat == null ? Hat.NONE : hat;
        Item it = item == null ? Item.NONE : item;
        int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(h + "|" + it + "|" + f, k -> render(build(h, it, f)));
    }

    private static int colour(char c)
    {
        switch (c)
        {
            case 'k': return 0x2a0b12; // outline / pupils
            case 'r': return 0xe0402e; // skin
            case 'h': return 0xff7a5c; // highlight
            case 'd': return 0xa82222; // shade
            case 'y': return 0xffe94d;
            case 'w': return 0xffffff;
            case 'b': return 0xefe2b0; // horn
            case 'B': return 0xb79a58;
            case 'v': return 0x8a1c3e; // wing
            case 'u': return 0x5a1030;
            case 'W': return 0xf6f6f2;
            case 'G': return 0xc4cad4;
            case 'P': return 0xf7a8c4;
            case 'N': return 0x2f55d8; // wizard
            case 'n': return 0x6a93ff;
            case 'M': return 0x1d338f;
            case 'Y': return 0xf4c430;
            case 'S': return 0xd9262b; // santa
            case 's': return 0xff6a60;
            case 'Z': return 0x8e1118;
            case 'K': return 0x9a6531; // wood
            case 'J': return 0x5c3a18;
            case 'R': return 0xe02a1a; // fire
            case 'F': return 0xff9a1f;
            case 'E': return 0xffe066;
            case 'C': return 0x2d2840; // ayak
            case 'c': return 0x554c75;
            case 'T': return 0x35e0d0;
            case 't': return 0x1b8f8a;
            case 'Q': return 0xa455ff;
            case 'L': return 0xdbe6f5; // blade
            case 'l': return 0x8fa8cf;
            case 'm': return 0x5c7399;
            default: return 0xff00ff;
        }
    }

    /** A sparse pixel grid; anything outside the sprite's box is dropped. */
    private static final class Grid
    {
        final char[][] px = new char[HEIGHT][WIDTH];

        void set(int x, int y, char c)
        {
            int i = x + OX;
            int j = y + OY;
            if (i >= 0 && i < WIDTH && j >= 0 && j < HEIGHT) px[j][i] = c;
        }

        boolean has(int x, int y)
        {
            int i = x + OX;
            int j = y + OY;
            return i >= 0 && i < WIDTH && j >= 0 && j < HEIGHT && px[j][i] != 0;
        }

        void stamp(int x0, int y0, String... rows)
        {
            for (int j = 0; j < rows.length; j++)
            {
                String row = rows[j];
                for (int i = 0; i < row.length(); i++)
                {
                    char c = row.charAt(i);
                    if (c != '.' && c != ' ') set(x0 + i, y0 + j, c);
                }
            }
        }

        void pxs(char c, int dy, int... xy)
        {
            for (int i = 0; i + 1 < xy.length; i += 2) set(xy[i], xy[i + 1] + dy, c);
        }
    }

    private static Grid shape(int x, int y, String... rows)
    {
        Grid m = new Grid();
        m.stamp(x, y, rows);
        return m;
    }

    private static final int[][] SIDES = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Paint a part onto the sprite with an automatic 1px dark outline around it. */
    private static void part(Grid g, Grid fill)
    {
        for (int j = 0; j < HEIGHT; j++)
        {
            for (int i = 0; i < WIDTH; i++)
            {
                if (fill.px[j][i] == 0) continue;
                for (int[] s : SIDES)
                {
                    int x = i - OX + s[0];
                    int y = j - OY + s[1];
                    if (!fill.has(x, y)) g.set(x, y, 'k');
                }
            }
        }
        for (int j = 0; j < HEIGHT; j++)
        {
            for (int i = 0; i < WIDTH; i++)
            {
                if (fill.px[j][i] != 0) g.px[j][i] = fill.px[j][i];
            }
        }
    }

    // ---------------------------------------------------------------- weapons

    /** The staff leans outward at the top, so it is gripped at x=7 on y=21. */
    private static int shaftX(int y)
    {
        return 7 - (int) Math.floor((21 - y) / 7.0 + 0.5);
    }

    private static Grid shaft(int top, char a, char b, int dy)
    {
        Grid m = new Grid();
        for (int y = top; y <= 31; y++) m.set(shaftX(y), y + dy, y % 4 == 0 ? b : a);
        return m;
    }

    private static void drawItem(Grid g, Item item, int dy)
    {
        if (item == Item.FIRE_STAFF)
        {
            part(g, shaft(8, 'K', 'J', dy));
            int cx = shaftX(8);
            Grid orb = shape(cx - 2, 3 + dy, ".RRR.", "RFFFR", "RFEFR", "RFFFR", ".RRR.");
            orb.pxs('F', dy, cx - 1, 2, cx + 1, 2);
            orb.pxs('E', dy, cx, 1);
            orb.pxs('R', dy, cx - 1, 1, cx + 2, 2);
            part(g, orb);
        }
        else if (item == Item.AYAK)
        {
            part(g, shaft(8, 'C', 'c', dy));
            int cx = shaftX(8);
            part(g, shape(cx - 3, 2 + dy, "C.....C", "C.....C", "cC...Cc"));
            part(g, shape(cx - 2, 3 + dy, "CTTTC", "TWWWT", "WQkQW", "TWWWT", "CTTTC"));
            g.pxs('T', dy, cx - 4, 6, cx + 4, 6, cx, 1);
        }
        else
        {
            part(g, shaft(3, 'C', 'c', dy));
            Grid blade = shape(-5, 1 + dy, "....LLLLL..", "..LLLLLLLll", ".LLLLllllll", "LLll......m", "Ll.........", "L..........");
            blade.pxs('m', dy, -1, 3);
            part(g, blade);
            g.pxs('l', dy, -4, 3, -3, 3);
        }
    }

    // ---------------------------------------------------------------- hats (fitted over the head)

    private static void drawHat(Grid g, Hat hat)
    {
        if (hat == Hat.CHEF)
        {
            part(g, shape(8, 3,
                "..WWW.WWW.WWW.",
                ".WWWWWWWWWWWW.",
                "WWWWWWWWWGWWWW",
                "WWWGWWWWWWWWWW",
                "WWWWWWWWWWWWGW",
                ".WWWWWWWWWWWW.",
                "..WWWWWWWWWW..",
                ".WWWWWWWWWWWW.",
                ".GGGGGGGGGGGG."));
            g.pxs('G', 0, 13, 6, 17, 7); // pleats
        }
        else if (hat == Hat.WIZARD)
        {
            part(g, shape(6, 1,
                "...........NMN....",
                "..........NNM.....",
                ".........nNNM.....",
                "........nNNM......",
                ".......nNNM.......",
                "......nNNNM.......",
                ".....nNNNNNM......",
                "....nnNNNNNMM.....",
                "....YYYYYYYYYY....",
                "..NNNNNNNNNNNNNN..",
                ".MMMMMMMMMMMMMMMM."));
            g.pxs('Y', 0, 17, 5); // little star on the cone
        }
        else if (hat == Hat.SANTA)
        {
            part(g, shape(8, 3,
                ".....SSSSSS.....",
                "....sSSSSSSSZ...",
                "...sSSSSSSSSSZZ.",
                "..sSSSSSSSSSSZZZ",
                "..SSSSSSSSSSSZZ.",
                "..SSSSSSSSSSZZ..",
                ".WWWWWWWWWWWWW..",
                "WWGWWWWWGWWWWW.."));
            part(g, shape(23, 7, "WW", "WW")); // bobble at the dangling tip
            g.pxs('W', 0, 23, 7, 24, 7, 23, 8, 24, 8);
            g.pxs('G', 0, 24, 8);
        }
        else if (hat == Hat.BUNNY)
        {
            part(g, shape(9, 1, "WPW", "WPW", "WPW", ".WPW", ".WPW", ".WPW", ".WPW", ".WPW", ".WPW", ".WPW"));
            part(g, shape(18, 1, "WPW", "WPW", "WPW", "WPW.", "WPW.", "WPW.", "WPW.", "WPW.", "WPW.", "WPW."));
            g.pxs('W', 0, 11, 11, 18, 11);
        }
    }

    // ---------------------------------------------------------------- the imp

    private static Grid leg(int x, char c, int lift)
    {
        Grid m = new Grid();
        char inner = c == 'd' ? 'd' : 'r';
        for (int y = 25; y <= 29 - lift; y++)
        {
            m.set(x, y, c);
            m.set(x + 1, y, inner);
        }
        int fy = 30 - lift;
        m.set(x - 1, fy, c);
        m.set(x, fy, c);
        m.set(x + 1, fy, inner);
        return m;
    }

    private static Grid build(Hat hat, Item item, int f)
    {
        Grid g = new Grid();

        // bat wings (behind everything), flap a little
        int wy = f == 1 ? -1 : 0;
        part(g, shape(17, 12 + wy,
            ".....v.....",
            "....vv...v.",
            "....vvv.vv.",
            "...vvvvvvv.",
            "...vvuvvuv.",
            "..vvvvvvvv.",
            "..vvvuvv.v.",
            "..vvv..v...",
            "..vv......."));
        // tail with a little spade tip
        Grid tail = new Grid();
        tail.pxs('r', 0, 18, 24, 19, 25, 20, 25, 21, 24, 22, 23, 22, 22);
        tail.pxs('d', 0, 21, 21, 22, 21, 23, 21, 22, 20, 22, 22);
        part(g, tail);

        // legs: back leg first (shaded), then front leg
        part(g, leg(f == 1 ? 16 : 17, 'd', 0));
        part(g, leg(f == 1 ? 13 : 11, 'r', f == 1 ? 1 : 0));

        // torso
        part(g, shape(12, 20, "rrrrrd", "rhrrrd", "rrrrrd", "rrrrdd", "drrrdd"));

        // the tail's root: the leg and torso outlines above cut it off, which left the tail floating beside the
        // feet like stray marks. Painted again here so the tail always joins the hip.
        g.pxs('r', 0, 18, 23, 18, 24, 19, 24, 19, 25);
        g.pxs('d', 0, 20, 24);

        // ears and horns go behind the head so its outline overlaps their roots
        part(g, shape(6, 11, "r...", "rr..", "rdr.", ".rrr"));
        part(g, shape(20, 11, "...r", "..rr", ".rdr", "rrr."));
        Grid hornL = new Grid();
        hornL.pxs('b', 0, 12, 10, 11, 9, 11, 10, 10, 8);
        hornL.pxs('B', 0, 12, 10);
        Grid hornR = new Grid();
        hornR.pxs('b', 0, 17, 10, 18, 9, 18, 10, 19, 8);
        hornR.pxs('B', 0, 17, 10);
        part(g, hornL);
        part(g, hornR);

        // head: big, cheeky, yellow eyes looking left
        part(g, shape(10, 12,
            ".rhhrrrrr.",
            "rhrrrrrrrd",
            "rrrrrrrrrd",
            "ryyrryyrrd",
            "rkyrrkyrrd",
            "rrrrrrrrdd",
            ".kwkwkwkd."));
        g.pxs('h', 0, 10, 16); // snout highlight

        // front arm: holds the weapon when there is one, otherwise swings
        if (item != Item.NONE)
        {
            int dy = f == 1 ? -1 : 0;
            drawItem(g, item, dy);
            part(g, shape(9, 21 + dy, "rrr"));
            part(g, shape(6, 21 + dy, "rrd", "rdd"));
        }
        else
        {
            Grid a = new Grid();
            if (f == 1) a.pxs('r', 0, 11, 21, 10, 22, 9, 23, 9, 24);
            else a.pxs('r', 0, 11, 21, 11, 22, 10, 23, 10, 24);
            part(g, a);
        }

        if (hat != Hat.NONE) drawHat(g, hat);
        return g;
    }

    private static BufferedImage render(Grid g)
    {
        BufferedImage img = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
        for (int j = 0; j < HEIGHT; j++)
        {
            for (int i = 0; i < WIDTH; i++)
            {
                char c = g.px[j][i];
                if (c != 0) img.setRGB(i, j, 0xff000000 | colour(c));
            }
        }
        return img;
    }
}

package com.forgebingo.core;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

/** Item-count snapshots of a container and what was added between two of them (pets put into the backpack). */
public final class InventoryDiff
{
    private InventoryDiff()
    {
    }

    /** item id -> total quantity; empty slots (id < 0 or quantity < 1) are ignored. */
    public static Map<Integer, Integer> counts(int[] ids, int[] quantities)
    {
        Map<Integer, Integer> m = new HashMap<>();
        if (ids == null)
        {
            return m;
        }
        for (int i = 0; i < ids.length; i++)
        {
            int q = quantities == null || i >= quantities.length ? 1 : quantities[i];
            if (ids[i] < 0 || q < 1)
            {
                continue;
            }
            m.merge(ids[i], q, Integer::sum);
        }
        return m;
    }

    /** Items whose count went up from {@code before} to {@code after}, with the increase (insertion order of {@code after}). */
    public static Map<Integer, Integer> added(Map<Integer, Integer> before, Map<Integer, Integer> after)
    {
        Map<Integer, Integer> out = new LinkedHashMap<>();
        if (after == null)
        {
            return out;
        }
        for (Map.Entry<Integer, Integer> e : after.entrySet())
        {
            int was = before == null ? 0 : before.getOrDefault(e.getKey(), 0);
            if (e.getValue() > was)
            {
                out.put(e.getKey(), e.getValue() - was);
            }
        }
        return out;
    }
}

package com.forgebingo.core;

import java.util.Collection;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

/**
 * Item name -> canonical item id, for chat lines that only carry a name (the collection log). Built from the
 * server's item catalogue ({@code GET /v1/catalogue/items}), the item ids the current board's tasks ask for and
 * the static {@link PetTable}. Never relies on {@code ItemManager.search}, which only knows tradeable items.
 * Thread-safe: the index is replaced as a whole.
 */
public final class ItemNames
{
    private volatile Map<String, Integer> catalogue = new HashMap<>();
    private volatile Map<String, Integer> board = new HashMap<>();

    /** Lower-case, typographic apostrophes and non-breaking spaces folded, inner whitespace collapsed. */
    public static String normalize(String name)
    {
        if (name == null)
        {
            return "";
        }
        return name.replace('’', '\'').replace('‘', '\'').replace(' ', ' ')
            .trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** Replace the catalogue part (id/name pairs from the server). For duplicate names the lowest id wins. */
    public void setCatalogue(Collection<ApiModels.CatalogueItem> items)
    {
        catalogue = index(items);
        catalogueNames = names(items);
    }

    /** Replace the board part: names of the item ids the board's tasks ask for (from the item definitions). */
    public void setBoard(Collection<ApiModels.CatalogueItem> items)
    {
        board = index(items);
        boardNames = names(items);
    }

    private volatile Map<Integer, String> catalogueNames = new HashMap<>();
    private volatile Map<Integer, String> boardNames = new HashMap<>();

    /** The item's name (board items first, then the catalogue), or "Item &lt;id&gt;" when unknown. */
    public String name(int itemId)
    {
        String n = boardNames.get(itemId);
        if (n == null) n = catalogueNames.get(itemId);
        return n == null ? "Item " + itemId : n;
    }

    private static Map<Integer, String> names(Collection<ApiModels.CatalogueItem> items)
    {
        Map<Integer, String> m = new HashMap<>();
        if (items == null) return m;
        for (ApiModels.CatalogueItem i : items)
        {
            if (i != null && i.name != null && i.id >= 0) m.putIfAbsent(i.id, i.name);
        }
        return m;
    }

    public int size()
    {
        return catalogue.size() + board.size();
    }

    private static Map<String, Integer> index(Collection<ApiModels.CatalogueItem> items)
    {
        Map<String, Integer> m = new HashMap<>();
        if (items == null)
        {
            return m;
        }
        for (ApiModels.CatalogueItem i : items)
        {
            if (i == null || i.name == null || i.id < 0)
            {
                continue;
            }
            String key = normalize(i.name);
            if (key.isEmpty())
            {
                continue;
            }
            m.merge(key, i.id, Math::min);
        }
        return m;
    }

    /** Pets first (static, always right), then the board's own items, then the server catalogue. */
    public Optional<Integer> resolve(String name)
    {
        String key = normalize(name);
        if (key.isEmpty())
        {
            return Optional.empty();
        }
        PetTable.Pet pet = PetTable.byName(key);
        if (pet != null)
        {
            return Optional.of(pet.primaryItemId());
        }
        Integer id = board.get(key);
        if (id == null)
        {
            id = catalogue.get(key);
        }
        return Optional.ofNullable(id);
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * The sub-tasks of a "one of each" item task, the same way the website (lib/itemSlots.ts) and the server
 * (public.item_slot) split it: each item is its own sub-task, except items in a group, where any one of the group
 * counts. Keys match the server's itemProgress: "i&lt;itemId&gt;" or "g&lt;groupIndex&gt;". No RuneLite dependencies.
 */
public final class ItemSlots
{
    public static final class Slot
    {
        public final String key;
        public final List<Integer> itemIds;
        /** how many of this sub-task the task needs: its own amount when set, else the total shared out evenly */
        public final int need;
        public final int approved;
        public final int pending;

        Slot(String key, List<Integer> itemIds, int need, int approved, int pending)
        {
            this.key = key;
            this.itemIds = itemIds;
            this.need = need;
            this.approved = approved;
            this.pending = pending;
        }

        public boolean done()
        {
            return approved >= need;
        }
    }

    private ItemSlots()
    {
    }

    /** The sub-tasks of a "one of each" task with two or more of them; empty for every other task. */
    public static List<Slot> of(ApiModels.Task k)
    {
        if (k == null || !Boolean.TRUE.equals(k.eachItem) || k.itemIds == null || k.itemIds.size() < 2) return Collections.emptyList();
        List<List<Integer>> groups = k.itemGroups == null ? Collections.<List<Integer>>emptyList() : k.itemGroups;
        List<String> keys = new ArrayList<>();
        List<List<Integer>> members = new ArrayList<>();
        Set<Integer> placed = new HashSet<>();
        for (Integer id : k.itemIds)
        {
            if (id == null || placed.contains(id)) continue;
            int gi = -1;
            for (int g = 0; g < groups.size() && gi < 0; g++)
            {
                if (groups.get(g) != null && groups.get(g).contains(id)) gi = g;
            }
            List<Integer> slot = new ArrayList<>();
            if (gi >= 0)
            {
                for (Integer x : groups.get(gi)) if (x != null && k.itemIds.contains(x) && placed.add(x)) slot.add(x);
                keys.add("g" + gi);
            }
            else
            {
                placed.add(id);
                slot.add(id);
                keys.add("i" + id);
            }
            members.add(slot);
        }
        if (members.size() < 2) return Collections.emptyList();
        int shared = Math.max(1, k.requiredQty / members.size());
        List<Slot> out = new ArrayList<>();
        for (int i = 0; i < members.size(); i++)
        {
            int need = shared;
            if (k.itemQtys != null && !k.itemQtys.isEmpty())
            {
                need = 1;
                for (Integer x : members.get(i))
                {
                    Integer q = k.itemQtys.get(String.valueOf(x));
                    if (q != null && q > need) need = q;
                }
            }
            ApiModels.SlotProgress p = k.itemProgress == null ? null : k.itemProgress.get(keys.get(i));
            int approved = p == null ? 0 : Math.min(need, p.approved);
            int pending = p == null ? 0 : Math.max(0, Math.min(need - approved, p.pending));
            // a finished task ticks every sub-task even when older proof had no item list
            if (k.completed) approved = need;
            out.add(new Slot(keys.get(i), members.get(i), need, approved, pending));
        }
        return out;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What to tell the player when the server says an event counted: "Counted", "Task complete", "Tile complete" or
 * "Extra drop" per match, the one-line summary for the side panel, and which tiles to celebrate. Decides the words
 * only; the plugin shows them.
 */
public final class MatchNotices
{
    private MatchNotices()
    {
    }

    /** One line for the player. */
    public static final class Notice
    {
        public final String text;
        /** set when a task was just finished: the words for the on-screen task banner, else null */
        public final String taskEffect;

        Notice(String text, String taskEffect)
        {
            this.text = text;
            this.taskEffect = taskEffect;
        }
    }

    /** A tile this event finished (it was not finished before): banner and fireworks. */
    public static final class Celebration
    {
        /** the team board the tile is on, when the server said; null = the board on screen */
        public final String teamBoardId;
        public final String tileId;
        /** the tile's shown title, or null when the board on screen does not have it */
        public final String title;

        Celebration(String teamBoardId, String tileId, String title)
        {
            this.teamBoardId = teamBoardId;
            this.tileId = tileId;
            this.title = title;
        }
    }

    public static final class Plan
    {
        /** what counted, for the side panel's one activity line ("a, b +2"); null when nothing has a name */
        public String counted;
        public final List<Notice> notices = new ArrayList<>();
        public final List<Celebration> celebrations = new ArrayList<>();
    }

    /** "a", "a, b" or "a, b +N": at most two names, then how many more. Null for no names. */
    public static String joinNames(Collection<String> names)
    {
        if (names == null || names.isEmpty()) return null;
        List<String> n = names instanceof List ? (List<String>) names : new ArrayList<>(names);
        return n.size() <= 2 ? String.join(", ", n) : n.get(0) + ", " + n.get(1) + " +" + (n.size() - 2);
    }

    /** task id -> its description, for every task on the board (empty for no board). */
    public static Map<String, String> taskNames(ApiModels.BoardResponse board)
    {
        Map<String, String> names = new HashMap<>();
        if (board == null || board.tiles == null) return names;
        for (ApiModels.Tile t : board.tiles)
        {
            if (t == null || t.tasks == null) continue;
            for (ApiModels.Task k : t.tasks) if (k != null && k.id != null) names.put(k.id, k.description);
        }
        return names;
    }

    /** What a match is called: its task's description, else its tile's title, else null. */
    static String matchName(ApiModels.Match m, Map<String, String> taskNames, Map<String, String> tileTitles)
    {
        String n = m.taskId == null ? null : taskNames.get(m.taskId);
        if (n == null || n.isEmpty()) n = m.tileId == null ? null : tileTitles.get(m.tileId);
        return n == null || n.isEmpty() ? null : n;
    }

    /**
     * @param result a matched, non-duplicate answer to an event
     * @param before the board on screen as it was before this event (null when none is loaded)
     * @param tileTitles tile id -> shown title of the board on screen
     * @param hiddenTiles ids of hidden secret tiles on that board: their amounts never show
     */
    public static Plan plan(ApiModels.EventResult result, ApiModels.BoardResponse before, Map<String, String> tileTitles, Set<String> hiddenTiles)
    {
        Plan plan = new Plan();
        if (result == null || result.matched == null) return plan;
        // what was already finished before this drop (no second celebration), and task names for the messages
        Set<String> wasDone = new HashSet<>();
        Set<String> taskWasDone = new HashSet<>();
        Map<String, String> taskNames = taskNames(before);
        if (before != null && before.tiles != null)
        {
            for (ApiModels.Tile t : before.tiles)
            {
                if (t == null) continue;
                if (t.completed && t.id != null) wasDone.add(t.id);
                if (t.tasks != null) for (ApiModels.Task k : t.tasks) if (k != null && k.id != null && k.completed) taskWasDone.add(k.id);
            }
        }
        // one quiet line in the side panel: what just counted
        Set<String> counted = new LinkedHashSet<>();
        for (ApiModels.Match m : result.matched)
        {
            if (m == null) continue;
            String n = matchName(m, taskNames, tileTitles);
            if (n != null) counted.add(n);
        }
        plan.counted = joinNames(counted);
        // a match's "completed" is its TASK; the tile is finished when matchedTiles says so
        Map<String, String> tileNowDone = new LinkedHashMap<>();
        if (result.matchedTiles != null)
        {
            for (ApiModels.MatchedTile mt : result.matchedTiles)
            {
                if (mt == null || !mt.completed || mt.tileId == null) continue;
                String team = tileNowDone.get(mt.tileId);
                if (team == null || team.isEmpty()) tileNowDone.put(mt.tileId, mt.teamBoardId == null ? "" : mt.teamBoardId);
            }
        }
        Set<String> announced = new HashSet<>();
        for (ApiModels.Match m : result.matched)
        {
            if (m == null) continue;
            String title = m.tileId == null ? null : tileTitles.get(m.tileId);
            // the server leaves out which hidden secret tile it was (review, 2026-11-22)
            String tileName = title != null ? title : m.tileId == null ? "a secret tile" : "a tile";
            String state = "approved".equals(m.status) ? ""
                : Boolean.FALSE.equals(m.verified) ? " - waiting for review (your name isn't verified yet)" : " - waiting for review";
            if (m.tileId != null && wasDone.contains(m.tileId))
            {
                plan.notices.add(new Notice("Extra drop logged for " + tileName + " (already done)" + state, null));
                continue;
            }
            // a hidden secret tile's amount would hint at its task: only its name shows. A match without a tile id is
            // one the server stripped for that reason (it leaves the amounts out too; this does not rely on it).
            boolean hiddenTile = m.tileId == null || (hiddenTiles != null && hiddenTiles.contains(m.tileId));
            String progress = !hiddenTile && m.requiredQuantity > 0 ? " (" + Math.min(m.currentQuantity, m.requiredQuantity) + "/" + m.requiredQuantity + ")" : "";
            if (m.tileId != null && tileNowDone.containsKey(m.tileId))
            {
                if (announced.add("tile:" + m.tileId)) plan.notices.add(new Notice("Tile complete: " + tileName + state, null));
            }
            else if (m.completed && m.taskId != null && !taskWasDone.contains(m.taskId))
            {
                String task = taskNames.get(m.taskId);
                boolean unnamed = task == null || task.isEmpty();
                String what = unnamed ? tileName : task + " (" + tileName + ")";
                if (announced.add("task:" + m.taskId)) plan.notices.add(new Notice("Task complete: " + what + state, unnamed ? tileName : task));
            }
            else
            {
                plan.notices.add(new Notice("Counted: " + tileName + progress + state, null));
            }
        }
        for (Map.Entry<String, String> done : tileNowDone.entrySet())
        {
            String tileId = done.getKey();
            if (wasDone.contains(tileId)) continue;
            // the team board: from matchedTiles, else from a match for that tile, else unknown (the board on screen)
            String team = done.getValue();
            if (team.isEmpty())
            {
                for (ApiModels.Match m : result.matched)
                {
                    if (m != null && tileId.equals(m.tileId) && m.teamId != null && !m.teamId.isEmpty()) { team = m.teamId; break; }
                }
            }
            plan.celebrations.add(new Celebration(team.isEmpty() ? null : team, tileId, tileTitles.get(tileId)));
        }
        return plan;
    }
}

package com.forgebingo.core;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Durable FIFO of events not yet accepted by the server. Persisted as JSON in the plugin's own data folder through
 * RuneLite's Filepath API (atomic write via temp file + move) so a crash or client close loses nothing.
 * Bounded by count and age. With deferred saves (the plugin's mode) an event is on disk once {@link #flush()} has
 * run after it was added; until then it is only in memory.
 */
public final class OfflineQueue
{
    private static final Logger log = LoggerFactory.getLogger(OfflineQueue.class);
    private static final Type LIST_TYPE = new TypeToken<List<QueuedEvent>>()
    {
    }.getType();

    public static final int MAX_ENTRIES = 500;
    /** The server rejects events older than one day, so there is no point keeping them longer. */
    public static final long MAX_AGE_MILLIS = 23 * 3_600_000L;

    private final Filepath file;
    private final Gson gson;
    private final Map<String, QueuedEvent> entries = new LinkedHashMap<>();
    /** changes are kept in memory and written by {@link #flush()} (from a worker thread), not by the caller */
    private final boolean deferSaves;
    /** deferred mode: the file is behind what is in memory */
    private boolean dirty;
    /** one writer of the file at a time; always taken before this queue's own lock */
    private final Object saveLock = new Object();

    /** A queue that writes its file on every change, on the calling thread. */
    public OfflineQueue(Filepath file, Gson gson)
    {
        this(file, gson, false);
    }

    /**
     * @param deferSaves true: a change only marks the queue as changed, and {@link #flush()} writes the file. The
     *                   plugin adds events on the game thread, which must not write files; its worker flushes.
     */
    public OfflineQueue(Filepath file, Gson gson, boolean deferSaves)
    {
        this.file = file;
        this.gson = gson;
        this.deferSaves = deferSaves;
    }

    public synchronized void load()
    {
        entries.clear();
        if (!file.isFile())
        {
            return;
        }
        try (Reader reader = file.openBufferedReader())
        {
            List<QueuedEvent> loaded = gson.fromJson(reader, LIST_TYPE);
            if (loaded != null)
            {
                for (QueuedEvent q : loaded)
                {
                    if (q != null && q.event != null && q.event.id != null)
                    {
                        entries.put(q.event.id, q);
                    }
                }
            }
        }
        catch (IOException | RuntimeException ex)
        {
            // Corrupt file: keep a copy for inspection and start fresh.
            log.debug("Could not read queue file {}: {}", file, ex.toString());
            try
            {
                file.moveTo(file.getParent().joinSegment(file.getFileName() + ".corrupt"), StandardCopyOption.REPLACE_EXISTING);
            }
            catch (IOException | RuntimeException ignored)
            {
                // nothing more we can do
            }
        }
    }

    /** @return ids evicted because the queue was full (oldest first). */
    public synchronized List<QueuedEvent> add(QueuedEvent q)
    {
        entries.put(q.event.id, q);
        List<QueuedEvent> evicted = new ArrayList<>();
        Iterator<QueuedEvent> it = entries.values().iterator();
        while (entries.size() > MAX_ENTRIES && it.hasNext())
        {
            evicted.add(it.next());
            it.remove();
        }
        changed();
        return evicted;
    }

    /** Removes and returns entries older than {@link #MAX_AGE_MILLIS}. */
    public synchronized List<QueuedEvent> expire(long now)
    {
        List<QueuedEvent> expired = new ArrayList<>();
        Iterator<QueuedEvent> it = entries.values().iterator();
        while (it.hasNext())
        {
            QueuedEvent q = it.next();
            if (now - q.createdAtMillis > MAX_AGE_MILLIS)
            {
                expired.add(q);
                it.remove();
            }
        }
        if (!expired.isEmpty())
        {
            changed();
        }
        return expired;
    }

    public synchronized List<QueuedEvent> due(long now)
    {
        List<QueuedEvent> due = new ArrayList<>();
        for (QueuedEvent q : entries.values())
        {
            if (q.nextAttemptAtMillis <= now)
            {
                due.add(q);
            }
        }
        return due;
    }

    public synchronized void remove(String eventId)
    {
        if (entries.remove(eventId) != null)
        {
            changed();
        }
    }

    public synchronized void scheduleRetry(String eventId, int attempts, long nextAttemptAt, String error)
    {
        QueuedEvent q = entries.get(eventId);
        if (q != null)
        {
            q.attempts = attempts;
            q.nextAttemptAtMillis = nextAttemptAt;
            q.lastError = error;
            changed();
        }
    }

    /** The ids currently queued (a snapshot). Right after {@link #load()} these are the entries that survived a restart. */
    public synchronized java.util.Set<String> ids()
    {
        return new java.util.LinkedHashSet<>(entries.keySet());
    }

    /** Makes everything due now (used after the user fixes their key). */
    public synchronized void retryAllNow(long now)
    {
        for (QueuedEvent q : entries.values())
        {
            q.nextAttemptAtMillis = now;
        }
        changed();
    }

    public synchronized int size()
    {
        return entries.size();
    }

    public synchronized void clear()
    {
        entries.clear();
        changed();
    }

    /** Called with this queue's lock held, after a change. */
    private void changed()
    {
        if (deferSaves)
        {
            dirty = true;
        }
        else
        {
            write(gson.toJson(new ArrayList<>(entries.values()), LIST_TYPE));
        }
    }

    /**
     * Deferred mode: writes the file when something changed since the last write (does nothing otherwise, and
     * nothing in the write-on-every-change mode). Call from a worker thread. A failed write is tried again by the
     * next flush.
     *
     * @return true when the file was written
     */
    public boolean flush()
    {
        if (!deferSaves) return false;
        synchronized (saveLock)
        {
            String json;
            synchronized (this)
            {
                if (!dirty) return false;
                json = gson.toJson(new ArrayList<>(entries.values()), LIST_TYPE);
                dirty = false;
            }
            // the file is written outside the queue's lock: the game thread adding an event never waits for the disk
            if (write(json)) return true;
            synchronized (this)
            {
                dirty = true;
            }
            return false;
        }
    }

    /** Deferred mode: something changed that {@link #flush()} has not written yet. */
    public synchronized boolean unsaved()
    {
        return dirty;
    }

    private boolean write(String json)
    {
        try
        {
            Filepath parent = file.getParent();
            parent.createDirectories();
            Filepath tmp = parent.joinSegment(file.getFileName() + ".tmp");
            try (Writer writer = tmp.openBufferedWriter())
            {
                writer.write(json);
            }
            try
            {
                tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            }
            catch (AtomicMoveNotSupportedException ex)
            {
                tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
            }
            return true;
        }
        catch (IOException | RuntimeException ex)
        {
            log.debug("Could not persist queue to {}: {}", file, ex.toString());
            return false;
        }
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Random;

/**
 * The board's opening animations (owner, 2026-11-15): 100 of them, each 3 seconds, rolled by rarity every time the
 * board opens. Common 45 (60%), Uncommon 30 (25%), Epic 17 (12%), Legendary 8 (3%).
 *
 * <p>Each one is a hand-picked mix of an order (which tiles arrive first), an entrance (the path a tile takes), a pace
 * (how the arrivals are spread over time and how long each flight is) and an effect. Common ones are clean and plain;
 * Uncommon adds a flourish as each tile lands (sparkles, ripples, a glint, a puff of dust); Epic adds motion trails, a
 * glow and a strong effect (lightning, light pillars, embers, shockwaves, prism colours, frost); Legendary is a full
 * show: its own scene behind the board (vortex, starfall, runes, aurora, eclipse, inferno, tempest, prism) and a burst
 * at the end. No two share an order and entrance pair, and every name is unique. Pure logic (no RuneLite), so it is
 * unit-tested; BoardOverlay draws it.
 */
public final class OpeningAnim
{
    /** the whole opening, first tile moving to the last effect fading */
    public static final long DEAL_MS = 3000;
    /** the last tile lands by here, leaving room for the landing effects inside DEAL_MS */
    public static final long LAND_MS = 2550;
    /** sparkles / glow / effect after a tile lands (Uncommon and up) */
    public static final long LANDING_FX_MS = 420;

    public enum Rarity
    {
        COMMON("Common", new Color(0xb4b4b4), 0.60),
        UNCOMMON("Uncommon", new Color(0x3ec46d), 0.25),
        EPIC("Epic", new Color(0xb36bff), 0.12),
        LEGENDARY("Legendary", new Color(0xffa62b), 0.03);

        public final String label;
        public final Color colour;
        public final double chance;

        Rarity(String label, Color colour, double chance)
        {
            this.label = label;
            this.colour = colour;
            this.chance = chance;
        }
    }

    /** How a tile arrives (its path, turn, scale and fade). */
    public enum Entrance
    {
        // plain
        DEAL, DROP, RISE, TIDE, GALE, MIST, BLOOM, FLIP, UNROLL, ZOOM,
        // with some character
        BOUNCE, WHIRL, LEAF, JELLY, SWING, QUAKE, BOOMERANG, RAIN, CONVERGE, SLINGSHOT,
        // big moves
        VORTEX, NOVA, CORKSCREW, COMET, WARP, BLINK, SWARM, ORBIT, STAMP, ASCEND
    }

    /** Which tiles arrive first. Tiles with the same key arrive together. */
    public enum Order
    {
        ROW, COLUMN, SERPENT, DIAGONAL, CROSSING, SPIRAL, UNWINDING, HEART, SIEGE, CHEQUER, SCATTER, PINCER,
        RISING, WEAVE, RIPPLE, CORNERS, PLUS, SWEEP, COMB, CURTAIN
    }

    /** How the arrivals are spread over the opening, and how long one tile's flight takes. */
    public enum Pace
    {
        /** evenly spaced */
        EVEN(460),
        /** quick, snappy flights */
        BRISK(300),
        /** long, overlapping flights */
        DRIFT(760),
        /** a slow start that speeds up */
        SURGE(460),
        /** a rush that settles */
        EASE(460),
        /** five bursts of tiles together */
        PULSE(420);

        public final long flightMs;

        Pace(long flightMs)
        {
            this.flightMs = flightMs;
        }
    }

    /** The extra effect: none for Common, a landing flourish for Uncommon, a strong effect for Epic, a whole scene for Legendary. */
    public enum Fx
    {
        NONE(Rarity.COMMON, -1),
        SPARKLE(Rarity.UNCOMMON, -1), RIPPLE(Rarity.UNCOMMON, -1), GLINT(Rarity.UNCOMMON, -1), DUST(Rarity.UNCOMMON, -1),
        BOLT(Rarity.EPIC, 0x8fc8ff), BEAM(Rarity.EPIC, 0xfff0b0), EMBER(Rarity.EPIC, 0xff7a2a), SHOCK(Rarity.EPIC, -1),
        PRISM(Rarity.EPIC, -2), FROST(Rarity.EPIC, 0x9fe6ff),
        VORTEX(Rarity.LEGENDARY, 0xffc65a), STARFALL(Rarity.LEGENDARY, 0xbfe0ff), RUNES(Rarity.LEGENDARY, 0x5ff0e0),
        AURORA(Rarity.LEGENDARY, 0x6dffb0), ECLIPSE(Rarity.LEGENDARY, 0xffe6a0), INFERNO(Rarity.LEGENDARY, 0xff6a2a),
        TEMPEST(Rarity.LEGENDARY, 0x8fb8ff), PRISMATIC(Rarity.LEGENDARY, -2);

        public final Rarity tier;
        /** the effect's colour as 0xRRGGBB; -1 = the rarity's colour, -2 = a rainbow (a hue per tile) */
        public final int accent;

        Fx(Rarity tier, int accent)
        {
            this.tier = tier;
            this.accent = accent;
        }
    }

    public static final class Spec
    {
        public final String name;
        public final Rarity rarity;
        public final Order order;
        public final Entrance entrance;
        public final Pace pace;
        public final Fx fx;
        /** the effect colour (rainbow effects use {@link #accent(int)}) */
        public final Color colour;

        Spec(String name, Rarity rarity, Order order, Entrance entrance, Pace pace, Fx fx)
        {
            this.name = name;
            this.rarity = rarity;
            this.order = order;
            this.entrance = entrance;
            this.pace = pace;
            this.fx = fx;
            this.colour = fx.accent >= 0 ? new Color(fx.accent) : rarity.colour;
        }

        /** The effect colour for one tile: the same for every tile, or a hue of the rainbow for prism effects. */
        public Color accent(int idx)
        {
            return fx.accent == -2 ? RAINBOW[Math.floorMod(idx * 5, RAINBOW.length)] : colour;
        }

        @Override
        public String toString()
        {
            return name + " (" + rarity.label + ")";
        }
    }

    /** twelve bright hues, for prism effects (made once, so drawing allocates nothing) */
    public static final Color[] RAINBOW = new Color[12];

    static
    {
        for (int i = 0; i < RAINBOW.length; i++) RAINBOW[i] = Color.getHSBColor(i / 12f, 0.62f, 1f);
    }

    public static final int COUNT = 100;
    public static final List<Spec> ALL = build();

    private OpeningAnim()
    {
    }

    private static List<Spec> build()
    {
        Rarity c = Rarity.COMMON, u = Rarity.UNCOMMON, e = Rarity.EPIC, l = Rarity.LEGENDARY;
        List<Spec> out = new ArrayList<>();
        // ---- Common (45): clean arrivals, no extra effect ----
        out.add(new Spec("Dealer's Rows", c, Order.ROW, Entrance.DEAL, Pace.EVEN, Fx.NONE));
        out.add(new Spec("Diagonal Deal", c, Order.DIAGONAL, Entrance.DEAL, Pace.EVEN, Fx.NONE));
        out.add(new Spec("Spiral Deal", c, Order.SPIRAL, Entrance.DEAL, Pace.BRISK, Fx.NONE));
        out.add(new Spec("Shuffled Deal", c, Order.SCATTER, Entrance.DEAL, Pace.SURGE, Fx.NONE));
