        out.add(new Spec("Two-Ended Deal", c, Order.PINCER, Entrance.DEAL, Pace.EASE, Fx.NONE));
        out.add(new Spec("Round the Table", c, Order.SWEEP, Entrance.DEAL, Pace.EVEN, Fx.NONE));
