package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Static table of every pet: in-game item name, item ids (base form first, then metamorph variants) and the follower
 * NPC ids that walk behind the player. Pets are untradeable, so {@code ItemManager.search} (tradeables only) can
 * never resolve them; this table is the plugin's only source for pet ids.
 *
 * <p>Ids come from the RuneLite gameval tables ({@code ItemID} / {@code NpcID}, follower NPCs only: the house
 * menagerie copies are left out). {@code sources} are lower-case boss / activity names as the plugin sees them in
 * loot, kill count and clue events; they are only used to attribute a duplicate pet, which names no pet at all.
 *
 * <p>The rows live in the bundled data file src/main/resources/com/forgebingo/data/pets.txt (format in its header).
 * The table as it was in Java is kept as PetTableReference in src/test/java, and PetTableDataTest proves the two are
 * equal. A missing or broken file (a name, id or source used by two pets included) leaves this table empty and logs
 * an error (see DataFile for why it does not throw).
 */
public final class PetTable
{
    public static final class Pet
    {
        public final String name;
        /** Base item first. Every id is sent, so a task listing any variant matches. */
        public final int[] itemIds;
        public final int[] followerNpcIds;
        public final List<String> sources;

        Pet(String name, int[] itemIds, int[] followerNpcIds, List<String> sources)
        {
            this.name = name;
            this.itemIds = itemIds;
            this.followerNpcIds = followerNpcIds;
            this.sources = sources;
        }

        public int primaryItemId()
        {
            return itemIds[0];
        }

        @Override
        public String toString()
        {
            return name;
        }
    }

    private static final List<Pet> PETS;
    private static final Map<String, Pet> BY_NAME = new HashMap<>();
    private static final Map<Integer, Pet> BY_ITEM = new HashMap<>();
    private static final Map<Integer, Pet> BY_NPC = new HashMap<>();
    private static final Map<String, List<Pet>> BY_SOURCE = new HashMap<>();

    static
    {
        List<Pet> pets;
        try
        {
            pets = parse(DataFile.lines("pets"));
            for (Pet p : pets)
            {
                put(BY_NAME, ItemNames.normalize(p.name), p);
                for (int id : p.itemIds) put(BY_ITEM, id, p);
                for (int id : p.followerNpcIds) put(BY_NPC, id, p);
                for (String s : p.sources) BY_SOURCE.computeIfAbsent(ItemNames.normalize(s), k -> new ArrayList<>()).add(p);
            }
        }
        catch (RuntimeException e)
        {
            DataFile.failed("pets", e);
            pets = new ArrayList<>();
            BY_NAME.clear();
            BY_ITEM.clear();
            BY_NPC.clear();
            BY_SOURCE.clear();
        }
        PETS = Collections.unmodifiableList(pets);
    }

    private PetTable()
    {
    }

    private static <K> void put(Map<K, Pet> map, K key, Pet p)
    {
        Pet old = map.put(key, p);
        if (old != null && old != p)
        {
            throw new IllegalStateException("pet table: " + key + " used by " + old + " and " + p);
        }
    }

    public static List<Pet> all()
    {
        return PETS;
    }

    /** By in-game item name (case, apostrophe and whitespace insensitive). */
    public static Pet byName(String name)
    {
        return name == null ? null : BY_NAME.get(ItemNames.normalize(name));
    }

    public static Pet byItemId(int itemId)
    {
        return BY_ITEM.get(itemId);
    }

    public static Pet byFollowerNpcId(int npcId)
    {
        return BY_NPC.get(npcId);
    }

    /** Pets dropped by a boss / activity name (loot, kill count or clue source); empty when unknown. */
    public static List<Pet> bySource(String source)
    {
        if (source == null)
        {
            return Collections.emptyList();
        }
        List<Pet> pets = BY_SOURCE.get(ItemNames.normalize(source));
        return pets == null ? Collections.emptyList() : pets;
    }

    /**
     * One pet per line: "Name | item ids | follower npc ids | sources" (ids separated by spaces, at least one of
     * each; sources separated by commas, possibly none).
     *
     * @throws RuntimeException on anything else: not four fields, no name, a missing or non-numeric id, an empty source
     */
    static List<Pet> parse(List<String> lines)
    {
        List<Pet> l = new ArrayList<>();
        for (String line : lines)
        {
            String[] f = line.split("\\|", -1);
            List<String> sources = new ArrayList<>();
            if (f.length != 4 || f[0].trim().isEmpty()) throw new IllegalStateException(line);
            if (!f[3].trim().isEmpty())
            {
                for (String s : f[3].split(",", -1))
                {
                    if (s.trim().isEmpty()) throw new IllegalStateException(line);
                    sources.add(s.trim());
                }
            }
            l.add(new Pet(f[0].trim(), ids(f[1]), ids(f[2]), Collections.unmodifiableList(sources)));
        }
        return l;
    }

    private static int[] ids(String field)
    {
        String[] parts = field.trim().split(" +");
        int[] ids = new int[parts.length];
        for (int i = 0; i < ids.length; i++) ids[i] = Integer.parseInt(parts[i]);
        return ids;
    }
}

package com.forgebingo.core;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Points can be decimals (0.04, 0.25, 1.5). They are kept to 2 decimal places, sums are done in whole hundredths so
 * they never drift (0.1 + 0.2 is 0.3), and they print without trailing zeros (0.25, 1.5, 3).
 */
public final class Points
{
    private Points()
    {
    }

    /** A points value in hundredths (0.25 is 25). Unreadable or negative values count as 0. */
    public static long cents(double v)
    {
        if (Double.isNaN(v) || v <= 0) return 0;
        return Math.round(Math.min(v, 1_000_000_000d) * 100d);
    }

    public static double fromCents(long cents)
    {
        return cents / 100d;
    }

    /** Rounded to 2 decimal places, never negative. */
    public static double round(double v)
    {
        return fromCents(cents(v));
    }

    /** "0.25", "1.5", "3": at most 2 decimals, no trailing zeros. */
    public static String text(double v)
    {
        return BigDecimal.valueOf(cents(v), 2).setScale(2, RoundingMode.UNNECESSARY).stripTrailingZeros().toPlainString();
    }

    /** "1 pt", "0.25 pts", "3 pts". */
    public static String label(double v)
    {
        return text(v) + (cents(v) == 100 ? " pt" : " pts");
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Where a drop's proof picture goes: one upload per team the drop counted for (a player can be on teams in several
 * bingos at once), attached to that team's entries, named after the first task and stamped with the tile names.
 */
public final class ProofPlan
{
    /** the server takes 1-25 entries per picture */
    public static final int MAX_TARGETS = 25;

    private ProofPlan()
    {
    }

    /** how often one proof picture is sent before giving up (the first send included) */
    public static final int UPLOAD_TRIES = 3;
    /** the longest wait before another try, whatever the server asks for */
    public static final long RETRY_MAX_MILLIS = 2 * 60_000L;

    /**
     * After a failed upload: how long to wait before sending the same picture again, or -1 to give up. Only a busy
     * (429), unreachable or failing (5xx) server is worth another try; an answer that will not change (the board is
     * gone, the bingo is not open, the entry was already reviewed, a bad key...) is not.
     *
     * @param status the failed upload's HTTP status (0 = it never completed)
     * @param retryAfterMillis the server's Retry-After, or 0
     * @param attempt which send just failed (1 = the first)
     * @param ageMillis how long ago the drop's screenshot was started
     * @param ttlMillis how long a screenshot is kept at most
     */
    public static long retryDelay(int status, String errorCode, long retryAfterMillis, int attempt, long ageMillis, long ttlMillis)
    {
        if (ErrorClass.of(status, errorCode) != ErrorClass.TRANSIENT || attempt >= UPLOAD_TRIES) return -1;
        long delay = Math.min(RETRY_MAX_MILLIS, Backoff.delayMillis(attempt, retryAfterMillis, null));
        return ageMillis + delay < ttlMillis ? delay : -1;
    }

    /** One team's upload. */
    public static final class Team
    {
        public final String teamId;
        /** the entries (matched[].submissionId) the picture is attached to, in order, no repeats, at most 25 */
        public final List<String> submissionIds = new ArrayList<>();
        /** the file is named after the (first) task this drop counted for; null when it has no name */
        public String label;
        /** tiles this drop counted for on this team (repeats possible), for the stamp */
        public final List<String> tileIds = new ArrayList<>();

        Team(String teamId)
        {
            this.teamId = teamId;
        }
    }

    /**
     * A raid's reward chest is also the proof of the raid itself: its pictures go to the chest's own matches and to
     * the tiles the raid's completion (the kill count, a moment earlier) counted for.
     *
     * @param chest the server's answer to the chest's loot
     * @param raidKill the answer to that raid's kill count, or null when there is none (or it is too old)
     * @return chest itself when there is nothing to add, else a new result holding both lists of matches
     */
    public static ApiModels.EventResult withRaidKill(ApiModels.EventResult chest, ApiModels.EventResult raidKill)
    {
        if (chest == null || raidKill == null || raidKill.matched == null) return chest;
        ApiModels.EventResult both = new ApiModels.EventResult();
        both.eventId = chest.eventId;
        both.matched = new ArrayList<>();
        if (chest.matched != null) both.matched.addAll(chest.matched);
        both.matched.addAll(raidKill.matched);
        return both;
    }

    /**
     * @param matched the server's matches for the event (and, for a raid chest, the raid's own kill-count matches)
     * @param taskNames task id -> description of the board on screen
     * @param tileTitles tile id -> shown title of the board on screen
     * @return the teams to upload to, in the order the server named them; teams with no entry to attach to are left out
     */
    public static List<Team> teams(List<ApiModels.Match> matched, Map<String, String> taskNames, Map<String, String> tileTitles)
    {
        Map<String, Team> byTeam = new LinkedHashMap<>();
        if (matched == null) return new ArrayList<>();
        for (ApiModels.Match m : matched)
        {
            if (m == null || m.teamId == null || m.submissionId == null) continue;
            Team t = byTeam.computeIfAbsent(m.teamId, Team::new);
            if (!t.submissionIds.contains(m.submissionId) && t.submissionIds.size() < MAX_TARGETS) t.submissionIds.add(m.submissionId);
            String name = MatchNotices.matchName(m, taskNames, tileTitles);
            if (name != null && t.label == null) t.label = name;
        }
        for (ApiModels.Match m : matched)
        {
            if (m == null || m.teamId == null || m.tileId == null) continue;
            Team t = byTeam.get(m.teamId);
            if (t != null) t.tileIds.add(m.tileId);
        }
        return new ArrayList<>(byTeam.values());
    }

    /**
     * The tile names stamped on a team's picture: from that team's own board, else from the board on screen;
     * "a, b +N" beyond two. Null when no tile has a name.
     */
    public static String tiles(List<String> tileIds, ApiModels.BoardResponse teamBoard, Map<String, String> tileTitles)
    {
        List<String> names = new ArrayList<>();
        for (String tileId : tileIds)
        {
            String title = null;
            if (teamBoard != null && teamBoard.tiles != null)
            {
                for (ApiModels.Tile x : teamBoard.tiles) if (x != null && tileId.equals(x.id)) { title = TileInfo.shownTitle(x); break; }
            }
            if (title == null) title = tileTitles.get(tileId);
            if (title != null && !title.isEmpty() && !names.contains(title)) names.add(title);
        }
        return MatchNotices.joinNames(names);
    }

    /** The tile line of one frame's stamp: the tile names, plus "1 of 2" when a drop has several frames. */
    public static String stampText(String tiles, int frame, int frames)
    {
        String part = frames > 1 ? frame + " of " + frames : null;
        return part == null ? tiles : tiles == null ? part : tiles + " (" + part + ")";
    }
}

package com.forgebingo.core;

import java.util.Locale;

/**
 * When an event gets an automatic proof screenshot and how many: only events that could count for the board, one
 * picture for drops, kills and clues, two for a reward chest's loot window. The server still decides what counted.
 */
public final class ProofPolicy
{
    /** one picture of a drop or kill: a tick on, so the loot is drawn on the ground before it can be picked up */
    public static final long[] SINGLE_SHOT_DELAYS_MS = {600};
    /** one picture of the clue reward window, once it has drawn */
    public static final long[] CLUE_SHOT_DELAYS_MS = {600};
    /** A reward chest's loot window: once as it opens and again a little later (sent as "1 of 2" and "2 of 2"). */
    public static final long[] CHEST_SHOT_DELAYS_MS = {300, 1800};

    private ProofPolicy()
    {
    }

    /**
     * Could this event count for an open task on the board on screen? Only those get a screenshot, so ordinary
     * drops do not fill the few screenshot slots before the drop that matters.
     *
     * @param board the board on screen, or null before the first fetch
     * @param liveBoards how many of the player's boards are live right now
     */
    public static boolean couldCount(GameEvent ev, ApiModels.BoardResponse board, int liveBoards)
    {
        ApiModels.BoardResponse b = board;
        if (b == null || b.tiles == null) return true;
        // On more than one board (several bingos on one key): only the selected board is known here, and the drop may
        // count for another one, so every event gets its picture; it is only sent when the server says it counted.
        // Finished bingos do not count: only boards that are live right now.
        if (liveBoards > 1) return true;
        // finished tiles count too: drops keep counting (with proof) until the bingo is over (owner, 2026-11-11)
        for (ApiModels.Tile t : b.tiles)
        {
            if (t == null || t.tasks == null) continue;
            for (ApiModels.Task k : t.tasks)
            {
                if (k == null) continue;
                if (k.itemIds != null && !k.itemIds.isEmpty())
                {
                    if (ev.items == null) continue;
                    for (GameEvent.Item it : ev.items) if (k.itemIds.contains(it.itemId)) return true;
                }
                else if (k.sourceType != null && k.sourceType.equals(ev.sourceType))
                {
                    return true;
                }
            }
        }
        // secret tiles hide their tasks: their items come as hiddenItemIds
        if (b.hiddenItemIds != null && ev.items != null)
        {
            for (GameEvent.Item it : ev.items) if (b.hiddenItemIds.contains(it.itemId)) return true;
        }
        // a secret tile may ask for a kill count, any pet or any clue (no item ids to go on): with one on the board,
        // those events always get their picture; it is only sent when the server says the event counted (2026-11-22)
        if (GameEvent.KC.equals(ev.sourceType) || GameEvent.PET.equals(ev.sourceType) || GameEvent.CLUE.equals(ev.sourceType))
        {
            for (ApiModels.Tile t : b.tiles) if (t != null && TileInfo.isSecret(t)) return true;
        }
        return false;
    }

    /**
     * Milliseconds between spotting a drop or kill and taking its screenshot(s). The loot notice and the "kill count"
     * chat line arrive in the same game tick as the loot (measured on live Zulrah, Giant Mole, Vorkath and clue
     * events: 5-34 ms apart), so a picture a moment later shows the loot on the ground and the chat line. A reward
     * chest's two pictures go up stacked as one image, see ScreenshotStack.
     */
    public static long[] shotDelays(String sourceType, String sourceName, boolean chestWindow)
    {
        // Two pictures only for reward chests (raids, Barrows, Moons); clues, boss drops and kill counts get one
        // (owner, 2026-11-14).
        if (isClue(sourceType, sourceName)) return CLUE_SHOT_DELAYS_MS;
        return chestWindow ? CHEST_SHOT_DELAYS_MS : SINGLE_SHOT_DELAYS_MS;
    }

    /** a clue casket's loot, or the "You have completed N ... Treasure Trails" count that comes with it */
    public static boolean isClue(String sourceType, String sourceName)
    {
        return GameEvent.CLUE.equals(sourceType)
            || (GameEvent.KC.equals(sourceType) && sourceName != null && sourceName.toLowerCase(Locale.ROOT).startsWith("clue scroll"));
    }

    /** Raids whose completion message comes before their reward chest is opened. */
    public static boolean raidWithChest(String name)
    {
        if (name == null) return false;
        String n = name.toLowerCase(Locale.ROOT);
        return n.contains("chambers of xeric") || n.contains("theatre of blood") || n.contains("tombs of amascut") || n.contains("fractured archive");
    }
}

package com.forgebingo.core;

import java.util.List;
import java.util.Random;
import java.util.function.LongSupplier;
import java.util.function.Function;

/**
 * Drains the {@link OfflineQueue}. Not thread-safe by itself: call {@link #drain()}
 * from one executor thread at a time (the plugin synchronizes on the instance).
 */
public final class QueueProcessor
{
    /** Receives everything the user should know about. */
    public interface Listener
    {
        /** Server accepted the event (also fires for duplicates). */
        void onAccepted(GameEvent event, ApiModels.EventResult result);

        /** Event permanently dropped; show a notice. */
        void onDropped(GameEvent event, String reason);

        /** Key rejected; sending is paused until the key changes or user retries. */
        void onAuthProblem(String message);

        /** Queue state changed (size). */
        void onQueueChanged(int size, String lastError);
    }

    private final OfflineQueue queue;
    private final Function<GameEvent, ApiResult<ApiModels.EventResult>> sender;
    private final Listener listener;
    private final LongSupplier clock;
    private final Random random;
    private volatile boolean authPaused;
    /** the server said slow down (or could not be reached): nothing is sent before this time */
    private volatile long holdUntilMillis;

    public QueueProcessor(OfflineQueue queue, Function<GameEvent, ApiResult<ApiModels.EventResult>> sender,
        Listener listener, LongSupplier clock, Random random)
    {
        this.queue = queue;
        this.sender = sender;
        this.listener = listener;
        this.clock = clock;
        this.random = random;
    }

    public void resumeAfterAuthChange()
    {
        authPaused = false;
        holdUntilMillis = 0;
        queue.retryAllNow(clock.getAsLong());
    }

    public boolean isAuthPaused()
    {
        return authPaused;
    }

    /** @return millis until the next entry becomes due, or -1 when the queue is empty. */
    public synchronized long drain()
    {
        long now = clock.getAsLong();
        for (QueuedEvent expired : queue.expire(now))
        {
            listener.onDropped(expired.event, "too old to be accepted (over 23 hours offline)");
        }
        if (authPaused)
        {
            return queue.size() == 0 ? -1 : 60_000L;
        }
        if (now < holdUntilMillis)
        {
            return queue.size() == 0 ? -1 : holdUntilMillis - now;
        }
        String lastError = null;
        for (QueuedEvent q : queue.due(now))
        {
            ApiResult<ApiModels.EventResult> r = sender.apply(q.event);
            ErrorClass c = r.errorClass();
            if (c == ErrorClass.SUCCESS)
            {
                queue.remove(q.event.id);
                listener.onAccepted(q.event, r.body);
            }
            else if (c == ErrorClass.PERMANENT)
            {
                queue.remove(q.event.id);
                listener.onDropped(q.event, r.describe());
            }
            else if (c == ErrorClass.CONFLICT)
            {
                // event_id_conflict: the id belongs to someone else (never happens with UUIDv4). New id, retry soon.
                queue.remove(q.event.id);
                q.event.id = java.util.UUID.randomUUID().toString();
                q.nextAttemptAtMillis = clock.getAsLong();
                queue.add(q);
            }
            else if (c == ErrorClass.AUTH)
            {
                authPaused = true;
                lastError = r.describe();
                listener.onAuthProblem(ConnectionStatus.authMessage(r.errorCode));
                break;
            }
            else
            {
                int attempts = q.attempts + 1;
                long delay = Backoff.delayMillis(attempts, r.retryAfterMillis, random);
                queue.scheduleRetry(q.event.id, attempts, clock.getAsLong() + delay, r.describe());
                lastError = r.describe();
                if (r.status == 429 || r.status == 0)
                {
                    holdUntilMillis = clock.getAsLong() + delay;
                    break; // do not hammer: the rest would likely fail the same way
                }
            }
        }
        listener.onQueueChanged(queue.size(), lastError);
        return nextDelay();
    }

    private long nextDelay()
    {
        long now = clock.getAsLong();
        long min = Long.MAX_VALUE;
        List<QueuedEvent> all = queue.due(Long.MAX_VALUE);
        for (QueuedEvent q : all)
        {
            min = Math.min(min, q.nextAttemptAtMillis);
        }
        return all.isEmpty() ? -1 : Math.max(1_000L, Math.max(min, holdUntilMillis) - now);
    }
}

package com.forgebingo.core;

/** A {@link GameEvent} waiting to be delivered, plus its retry state. */
public final class QueuedEvent
{
    public GameEvent event;
    public int attempts;
    public long createdAtMillis;
    public long nextAttemptAtMillis;
    public String lastError;

    public QueuedEvent()
    {
    }

    public QueuedEvent(GameEvent event, long now)
    {
        this.event = event;
        this.createdAtMillis = now;
        this.nextAttemptAtMillis = now;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * "Proof sent back" lines for the top of the side panel (owner, 2026-11-21): one per tile whose newest proof a
 * reviewer rejected, whoever on the team sent it, e.g. "Rejected: Bandos hilt - Drop message not visible".
 *
 * The board only says that a tile's newest proof was rejected and why; it carries no time and no id for the
 * rejection. So this class remembers when it first saw each one (tile + reason) and whether the player dismissed it:
 * <ul>
 * <li>a line shows for {@link #WINDOW_MS} after it was first seen, newest first, unless dismissed;</li>
 * <li>once the tile stops being "rejected" (new proof sent, approved, tile done) it is forgotten, so a later
 * rejection of the same tile shows again, even with the same reason; a different reason is a new line at once.</li>
 * </ul>
 * A hidden secret tile only ever gives its shown name ({@link TileInfo#shownTitle}), never the reason.
 */
public final class RejectedNotices
{
    /** how long a rejection counts as recent, from when this plugin first saw it */
    public static final long WINDOW_MS = 48L * 60 * 60 * 1000;
    /** lines shown at once; the rest are summed up as "+N more" */
    public static final int MAX_SHOWN = 5;
    static final int MAX_REASON = 140;
    static final int MAX_REMEMBERED = 60;

    private RejectedNotices()
    {
    }

    public static final class Notice
    {
        /** tile + reason: stays the same from poll to poll, changes when the reviewer gives another reason */
        public final String key;
        public final String tileId;
        public final String title;
        /** the reviewer's reason; null for a hidden secret tile */
        public final String reason;
        long seenAt;

        Notice(String key, String tileId, String title, String reason)
        {
            this.key = key;
            this.tileId = tileId;
            this.title = title;
            this.reason = reason;
        }

        /** when this plugin first saw the rejection */
        public long seenAt()
        {
            return seenAt;
        }

        public String text()
        {
            return "Rejected: " + title + (reason == null || reason.isEmpty() ? "" : " - " + reason);
        }
    }

    /** Every tile on the board whose newest proof was sent back, in board order. */
    public static List<Notice> find(List<ApiModels.Tile> tiles)
    {
        List<Notice> out = new ArrayList<>();
        if (tiles == null) return out;
        Set<String> seen = new HashSet<>();
        for (ApiModels.Tile t : tiles)
        {
            if (t == null || t.id == null || t.id.isEmpty()) continue;
            String reason = TileInfo.needsChangesReason(t);
            if (reason == null) continue;
            String key = key(t.id, reason);
            if (key == null || !seen.add(key)) continue;
            // a hidden secret tile: its shown name and nothing else
            boolean hidden = TileInfo.isSecret(t) && !t.completed;
            String title = TileInfo.shownTitle(t);
            out.add(new Notice(key, t.id, title.isEmpty() ? "A tile" : title, hidden ? null : shorten(reason.trim())));
        }
        return out;
    }

    static String key(String tileId, String reason)
    {
        String k = tileId + ":" + Integer.toHexString(reason.trim().hashCode());
        return validKey(k) ? k : null;
    }

    private static String shorten(String s)
    {
        return s.length() <= MAX_REASON ? s : s.substring(0, MAX_REASON - 3).trim() + "...";
    }

    private static boolean validKey(String k)
    {
        if (k == null || k.isEmpty() || k.length() > 80) return false;
        for (int i = 0; i < k.length(); i++)
        {
            char c = k.charAt(i);
            boolean ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == ':';
            if (!ok) return false;
        }
        return true;
    }

    /** "+2 more", or "" when everything fits. */
    public static String moreText(int total)
    {
        return total > MAX_SHOWN ? "+" + (total - MAX_SHOWN) + " more" : "";
    }

    /** What one board's rejections looked like so far: first seen and dismissed, kept in the player's settings. */
    public static final class Log
    {
        /** key -> {first seen (ms), dismissed (1/0)} */
        private final Map<String, long[]> seen = new LinkedHashMap<>();
        private List<Notice> current = new ArrayList<>();

        /**
         * Takes the board's current rejections: new ones are stamped with now, ones the board no longer reports are
         * forgotten. Returns true when anything to remember changed.
         */
        public boolean update(List<Notice> now, long nowMs)
        {
            boolean changed = false;
            Set<String> keys = new HashSet<>();
            List<Notice> list = now == null ? new ArrayList<>() : now;
            for (Notice n : list)
            {
                keys.add(n.key);
                long[] e = seen.get(n.key);
                if (e == null)
                {
                    if (seen.size() >= MAX_REMEMBERED) continue;
                    e = new long[] {nowMs, 0};
                    seen.put(n.key, e);
                    changed = true;
                }
                else if (e[0] > nowMs)
                {
                    // the computer's clock went back: never keep a line alive past its window because of it
                    e[0] = nowMs;
                    changed = true;
                }
                n.seenAt = e[0];
            }
            for (Iterator<String> it = seen.keySet().iterator(); it.hasNext(); )
            {
                if (!keys.contains(it.next()))
                {
                    it.remove();
                    changed = true;
                }
            }
            current = list;
            return changed;
        }

        /** Every line to show right now, newest first (board order between lines seen together); not capped. */
        public List<Notice> visible(long nowMs)
        {
            List<Notice> out = new ArrayList<>();
            for (Notice n : current)
            {
                long[] e = seen.get(n.key);
                if (e == null || e[1] != 0 || nowMs - e[0] >= WINDOW_MS) continue;
                out.add(n);
            }
            out.sort(Comparator.comparingLong((Notice n) -> -n.seenAt));
            return out;
        }

        /** The player closed a line: it stays away until the tile is rejected anew. */
        public boolean dismiss(String key)
        {
            long[] e = seen.get(key);
            if (e == null || e[1] != 0) return false;
            e[1] = 1;
            return true;
        }

        /** "key~firstSeen~0|1;..." for the settings file. */
        public String save()
        {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, long[]> e : seen.entrySet())
            {
                if (sb.length() > 0) sb.append(';');
                sb.append(e.getKey()).append('~').append(e.getValue()[0]).append('~').append(e.getValue()[1] != 0 ? 1 : 0);
            }
            return sb.toString();
        }

        /** Replaces what is remembered with a saved value; anything malformed is skipped. */
        public void load(String raw)
        {
            seen.clear();
            current = new ArrayList<>();
            if (raw == null || raw.isEmpty() || raw.length() > 8000) return;
            for (String part : raw.split(";"))
            {
                String[] f = part.split("~");
                if (f.length != 3 || !validKey(f[0]) || seen.size() >= MAX_REMEMBERED) continue;
                try
                {
                    long at = Long.parseLong(f[1]);
                    if (at < 0) continue;
                    seen.put(f[0], new long[] {at, "1".equals(f[2]) ? 1 : 0});
                }
                catch (NumberFormatException ignored)
                {
                    // skip
                }
            }
        }
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.List;

/** Size caps and defensive cleanup for outgoing events and incoming server data. */
public final class Sanitizer
{
    public static final int MAX_STRING = 200;
    public static final int MAX_ITEMS_PER_EVENT = 40;
    public static final int MAX_EVENT_JSON_BYTES = 16 * 1024;
    public static final int MAX_EVENTS = 100;
    public static final int MAX_TILES = 400;
    public static final int MAX_TASKS = 50;

    private Sanitizer()
    {
    }

    public static String str(String s)
    {
        if (s == null)
        {
            return null;
        }
        StringBuilder sb = new StringBuilder(Math.min(s.length(), MAX_STRING));
        for (int i = 0; i < s.length() && sb.length() < MAX_STRING; i++)
        {
            char c = s.charAt(i);
            sb.append(Character.isISOControl(c) ? ' ' : c);
        }
        return sb.toString();
    }

    private static final java.util.regex.Pattern RSN = java.util.regex.Pattern.compile("^[A-Za-z0-9 _-]{1,12}$");

    /** RuneScape names use non-breaking spaces in some client APIs; the server wants plain spaces. */
    public static String normalizeRsn(String rsn)
    {
        return rsn == null ? null : str(rsn.replace('\u00a0', ' ')).trim();
    }

    /** Same pattern as the server (^[A-Za-z0-9 _-]{1,12}$): events that fail it are never sent. */
    public static boolean validRsn(String rsn)
    {
        return rsn != null && RSN.matcher(rsn).matches();
    }

    /** Trims strings and item lists of an outgoing event in place. */
    public static void event(GameEvent e)
    {
        e.sourceName = str(e.sourceName);
        e.npcName = str(e.npcName);
        e.skill = str(e.skill);
        e.rsn = normalizeRsn(e.rsn);
        if (e.items != null)
        {
            if (e.items.size() > MAX_ITEMS_PER_EVENT)
            {
                e.items = new ArrayList<>(e.items.subList(0, MAX_ITEMS_PER_EVENT));
            }
            for (GameEvent.Item i : e.items)
            {
                if (i.quantity < 1)
                {
                    i.quantity = 1;
                }
            }
        }
    }

    private static <T> List<T> cap(List<T> in, int max)
    {
        if (in == null)
        {
            return new ArrayList<>();
        }
        return in.size() <= max ? in : new ArrayList<>(in.subList(0, max));
    }

    /** Item ids: at most max, positive, below 1,000,000; null in, empty out. */
    private static List<Integer> cleanIds(List<Integer> in, int max)
    {
        List<Integer> out = new ArrayList<>();
        if (in == null) return out;
        for (Integer i : in)
        {
            if (i != null && i > 0 && i < 1_000_000 && out.size() < max) out.add(i);
        }
        return out;
    }

    private static int clamp(int v)
    {
        return Math.max(0, Math.min(v, 1_000_000_000));
    }

    /** A tile's or task's points: 0 to 1000, 2 decimal places (0.25, 1.5, 3); anything unreadable is 0. */
    private static double points(double v)
    {
        return Points.round(Math.min(v, 1000d));
    }

    public static ApiModels.BoardsResponse boards(ApiModels.BoardsResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.boards = cap(r.boards, MAX_EVENTS);
        r.boards.removeIf(b -> b == null || b.teamBoardId == null || b.teamBoardId.length() > 64);
        for (ApiModels.BoardSummary b : r.boards)
        {
            b.eventName = str(b.eventName);
            b.boardTitle = str(b.boardTitle);
            b.teamName = str(b.teamName);
            b.role = str(b.role);
            b.status = str(b.status);
            b.boardSize = Math.max(1, Math.min(b.boardSize, 20));
            b.completedCount = clamp(b.completedCount);
            b.totalTiles = clamp(b.totalTiles);
        }
        return r;
    }

    public static ApiModels.BoardResponse board(ApiModels.BoardResponse b)
    {
        if (b == null)
        {
            return null;
        }
        if (b.board == null)
        {
            b.board = new ApiModels.BoardInfo();
            b.board.size = 1;
        }
        b.board.size = Math.max(1, Math.min(b.board.size, 20));
        b.board.title = str(b.board.title);
        b.teamName = str(b.teamName);
        if (b.event != null)
        {
            String kw = str(b.event.keyword);
            b.event.keyword = kw == null ? null : kw.trim().substring(0, Math.min(kw.trim().length(), 40));
        }
        b.tiles = cap(b.tiles, MAX_TILES);
        b.tiles.removeIf(t -> t == null);
        b.hiddenItemIds = cap(b.hiddenItemIds, 500);
        b.hiddenItemIds.removeIf(i -> i == null || i < 0);
        for (ApiModels.Tile t : b.tiles)
        {
            t.title = str(t.title);
            t.description = str(t.description);
            t.points = points(t.points);
            t.row = Math.max(0, Math.min(t.row, 19));
            t.col = Math.max(0, Math.min(t.col, 19));
            if (t.iconUrl != null && !IconRef.isProxyPath(t.iconUrl))
            {
                t.iconUrl = null;
            }
            // only ever compared against TileIcons' table, never drawn as text or used in a URL
            if (t.iconEmoji != null && (t.iconEmoji.isEmpty() || t.iconEmoji.length() > 16)) t.iconEmoji = null;
            t.tasks = cap(t.tasks, MAX_TASKS);
            t.tasks.removeIf(x -> x == null);
            for (ApiModels.Task k : t.tasks)
            {
                k.description = str(k.description);
                k.rejectedReason = k.rejectedReason == null ? null : str(k.rejectedReason);
                if (k.points != null) k.points = points(k.points);
                if (k.group != null && (k.group < 1 || k.group > 20)) k.group = null;
                k.requiredQty = clamp(k.requiredQty);
                k.approvedQty = clamp(k.approvedQty);
                k.pendingQty = clamp(k.pendingQty);
                // item ids drive the per-item list, the icon fallback and the screenshot pre-check; npc ids are not needed
                k.itemIds = cleanIds(k.itemIds, 200);
                k.npcIds = null;
                if (k.itemGroups != null)
                {
                    k.itemGroups = cap(k.itemGroups, 20);
                    k.itemGroups.replaceAll(g -> cleanIds(g, 50));
                }
                if (k.itemProgress != null)
                {
                    if (k.itemProgress.size() > 220) k.itemProgress = null;
                    else
                    {
                        k.itemProgress.entrySet().removeIf(e -> e.getKey() == null || !e.getKey().matches("[ig]\\d{1,6}") || e.getValue() == null);
                        for (ApiModels.SlotProgress p : k.itemProgress.values())
                        {
                            p.approved = clamp(p.approved);
                            p.pending = clamp(p.pending);
                        }
                    }
                }
            }
            if (t.workingOn != null)
            {
                t.workingOn = cap(t.workingOn, 30);
                t.workingOn.removeIf(w -> w == null || w.name == null);
                for (ApiModels.WorkingOn w : t.workingOn) w.name = str(w.name).length() > 32 ? str(w.name).substring(0, 32) : str(w.name);
            }
            if (t.contributors != null)
            {
                t.contributors = cap(t.contributors, 12);
                t.contributors.removeIf(c -> c == null || c.name == null || c.qty <= 0);
                for (ApiModels.Contributor c : t.contributors) c.name = str(c.name).length() > 32 ? str(c.name).substring(0, 32) : str(c.name);
            }
        }
        if (b.event != null)
        {
            b.event.name = str(b.event.name);
        }
        return b;
    }

    public static ApiModels.LeaderboardResponse leaderboard(ApiModels.LeaderboardResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.teams = cap(r.teams, 200);
        r.teams.removeIf(t -> t == null);
        for (ApiModels.LeaderboardTeam t : r.teams)
        {
            t.teamName = str(t.teamName);
            t.score = Points.round(t.score);
        }
        return r;
    }

    public static ApiModels.EventResult result(ApiModels.EventResult r)
    {
        if (r == null)
        {
            return null;
        }
        r.matched = cap(r.matched, 100);
        r.matched.removeIf(m -> m == null);
        r.matchedTiles = cap(r.matchedTiles, 100);
        r.skipped = cap(r.skipped, 100);
        r.skipped.removeIf(x -> x == null);
        for (ApiModels.Skipped x : r.skipped)
        {
            x.reason = str(x.reason);
        }
        return r;
    }

    public static ApiModels.Me me(ApiModels.Me m)
    {
        if (m != null)
        {
            m.displayName = str(m.displayName);
            m.keyScope = str(m.keyScope);
        }
        return m;
    }

    public static ApiModels.HelloResponse hello(ApiModels.HelloResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.displayName = str(r.displayName);
        r.rsn = str(r.rsn);
        r.keyScope = str(r.keyScope);
        r.memberships = cap(r.memberships, 20);
        r.memberships.removeIf(x -> x == null);
        for (ApiModels.Membership m : r.memberships)
        {
            m.eventName = str(m.eventName);
            m.teamName = str(m.teamName);
            m.joinedRsn = str(m.joinedRsn);
            m.pluginRsn = str(m.pluginRsn);
            m.status = str(m.status);
            m.eventStatus = str(m.eventStatus);
        }
        return r;
    }

    public static final int MAX_CATALOGUE_ITEMS = 20_000;

    public static ApiModels.CatalogueResponse catalogue(ApiModels.CatalogueResponse r)
    {
        if (r == null)
        {
            return null;
        }
        r.items = cap(r.items, MAX_CATALOGUE_ITEMS);
        r.items.removeIf(i -> i == null || i.id < 0 || i.name == null || i.name.isEmpty());
        for (ApiModels.CatalogueItem i : r.items)
        {
            i.name = str(i.name);
        }
        return r;
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Iterator;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;

/**
 * Screenshots go up as JPEG: a full game window as PNG is several MB and timed out on ordinary home upload speeds
 * (owner report 2026-11-12, "SocketTimeoutException"). JPEG at 85% is roughly a tenth of that and still reads fine
 * for proof. Falls back to lower quality if a shot is still over the limit.
 */
public final class ScreenshotEncode
{
    private ScreenshotEncode()
    {
    }

    /** JPEG bytes no bigger than maxBytes (tries 85%, 70%, 55%), or null if the image cannot be encoded. */
    public static byte[] jpeg(BufferedImage img, int maxBytes) throws IOException
    {
        BufferedImage rgb = new BufferedImage(img.getWidth(), img.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D g = rgb.createGraphics();
        try
        {
            g.setColor(Color.BLACK); // JPEG has no transparency
            g.fillRect(0, 0, rgb.getWidth(), rgb.getHeight());
            g.drawImage(img, 0, 0, null);
        }
        finally
        {
            g.dispose();
        }
        byte[] out = null;
        for (float q : new float[] {0.85f, 0.7f, 0.55f})
        {
            out = encode(rgb, q);
            if (out == null || out.length <= maxBytes) return out;
        }
        return out;
    }

    private static byte[] encode(BufferedImage rgb, float quality) throws IOException
    {
        Iterator<ImageWriter> it = ImageIO.getImageWritersByFormatName("jpeg");
        if (!it.hasNext()) return null;
        ImageWriter w = it.next();
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ImageOutputStream ios = ImageIO.createImageOutputStream(bytes))
        {
            w.setOutput(ios);
            ImageWriteParam p = w.getDefaultWriteParam();
            p.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
            p.setCompressionQuality(quality);
            w.write(null, new IIOImage(rgb, null, null), p);
        }
        finally
        {
            w.dispose();
        }
        return bytes.toByteArray();
    }

    /** True when the bytes are a JPEG (FF D8 FF), else they are treated as PNG. */
    public static boolean isJpeg(byte[] b)
    {
        return b != null && b.length > 3 && (b[0] & 0xff) == 0xff && (b[1] & 0xff) == 0xd8 && (b[2] & 0xff) == 0xff;
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

/**
 * Several pictures of one drop or kill go up as a single image, one above the other in the order they were taken
 * (owner, 2026-11-14), so a reviewer sees them together instead of opening each.
 */
public final class ScreenshotStack
{
    /** dark line between two pictures, so it is clear where one ends */
    public static final int GAP = 6;

    private ScreenshotStack()
    {
    }

    /** The pictures one above the other, first on top. One picture comes back as it is; none gives null. */
    public static BufferedImage vertical(List<BufferedImage> frames)
    {
        if (frames == null || frames.isEmpty()) return null;
        if (frames.size() == 1) return frames.get(0);
        int w = 0;
        int h = GAP * (frames.size() - 1);
        for (BufferedImage f : frames)
        {
            w = Math.max(w, f.getWidth());
            h += f.getHeight();
        }
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.setColor(Color.BLACK);
            g.fillRect(0, 0, w, h);
            int y = 0;
            for (BufferedImage f : frames)
            {
                // a picture taken after the window was resized is centred
                g.drawImage(f, (w - f.getWidth()) / 2, y, null);
                y += f.getHeight() + GAP;
            }
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}

package com.forgebingo.core;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;

/** Stamps the event keyword and the local date/time in the top-left corner of a proof screenshot copy. */
public final class ScreenshotStamp
{
    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
    private static final DateTimeFormatter OFFSET = DateTimeFormatter.ofPattern("xxx");
    /** the stamp box's darkness, 0-255: about 40%, so the game shows through */
    static final int BOX_ALPHA = 100;

    private ScreenshotStamp()
    {
    }

    /** "yyyy-MM-dd HH:mm +02:00" */
    public static String timeText(ZonedDateTime t)
    {
        return TIME.format(t) + " UTC" + OFFSET.format(t);
    }

    /** Returns a new image (same size) with the stamp drawn; the source is not modified. */
    public static BufferedImage stamp(BufferedImage src, String keyword, ZonedDateTime when)
    {
        return stamp(src, keyword, when, null, null);
    }

    /**
     * Proof stamp (owner, 2026-11-12): the tile it is for, the player, "Code: keyword" and the date/time, top-left.
     * Any of tile / player / keyword may be null or blank and is then left out.
     */
    public static BufferedImage stamp(BufferedImage src, String keyword, ZonedDateTime when, String player, String tile)
    {
        java.util.List<String> lines = new java.util.ArrayList<>();
        if (tile != null && !tile.trim().isEmpty()) lines.add(clip(tile.trim(), 64));
        if (player != null && !player.trim().isEmpty()) lines.add(clip(player.trim(), 24));
        if (keyword != null && !keyword.trim().isEmpty()) lines.add("Code: " + clip(keyword.trim(), 40));
        lines.add(timeText(when));
        return draw(src, lines.toArray(new String[0]));
    }

    private static String clip(String s, int max)
    {
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }

    private static BufferedImage draw(BufferedImage src, String[] lines)
    {
        BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.drawImage(src, 0, 0, null);
            int size = Math.max(14, Math.min(24, src.getHeight() / 40));
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, size));
            FontMetrics fm = g.getFontMetrics();
            int pad = Math.max(4, size / 3);
            int w = 0;
            for (String l : lines) w = Math.max(w, fm.stringWidth(l));
            int lineH = fm.getHeight();
            int boxW = Math.min(src.getWidth(), w + pad * 2);
            int boxH = Math.min(src.getHeight(), lineH * lines.length + pad * 2);
            // light enough to see the game behind it (owner, 2026-11-22: the old 75% black box hid what was under it);
            // the text keeps a dark outline so it still reads on bright scenery
            g.setColor(new Color(0, 0, 0, BOX_ALPHA));
            g.fillRect(0, 0, boxW, boxH);
            int y = pad + fm.getAscent();
            Color outline = new Color(0, 0, 0, 220);
            for (String l : lines)
            {
                g.setColor(outline);
                for (int dx = -1; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) if (dx != 0 || dy != 0) g.drawString(l, pad + dx, y + dy);
                g.setColor(Color.WHITE);
                g.drawString(l, pad, y);
                y += lineH;
            }
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}

