package com.forgebingo.core;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Maps a LootReceived source name onto one of the server's source types and normalises clue names. */
public final class SourceClassifier
{
    private static final Pattern TIER = Pattern.compile("\\b(beginner|easy|medium|hard|elite|master)\\b");

    private SourceClassifier()
    {
    }

    /**
     * Loot that never counts (owner, 2026-11-11): Wilderness loot keys. Their chest just hands back items taken from
     * other players, so it is neither a drop nor a task. RuneLite's loot tracker names it "Loot Chest".
     */
    public static boolean ignored(String name)
    {
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT).trim();
        return n.equals("loot chest") || n.contains("loot key");
    }

    public static String forEventLoot(String name)
    {
        String n = name == null ? "" : name.toLowerCase(Locale.ROOT);
        if (n.startsWith("reward casket") || n.contains("clue scroll") || n.contains("clue casket"))
        {
            return GameEvent.CLUE;
        }
        // Raids, Barrows and every other chest / minigame reward share one bucket;
        // the server matches sourceName against its catalogue (unknown names match nothing).
        return GameEvent.RAID_CHEST;
    }

    /** "Reward casket (elite)" -> "elite"; null when no tier is present. */
    public static String clueTier(String name)
    {
        if (name == null)
        {
            return null;
        }
        Matcher m = TIER.matcher(name.toLowerCase(Locale.ROOT));
        return m.find() ? m.group(1) : null;
    }
}

package com.forgebingo.core;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Fixed pixel art that ships as a picture instead of as drawing code.
 *
 * A sheet is two files bundled in the jar under /com/forgebingo/sprites/ (nothing is ever downloaded):
 *   NAME.png  every picture packed into one lossless 32-bit ARGB image
 *   NAME.txt  one line per picture: "KEY x y w h" (where it sits in the png); lines that are not five words
 *             (blank lines, the "# ..." header) are skipped. Keys have no spaces and do not depend on enum order.
 *
 * Both files are WRITTEN BY A BAKER in src/test/java (SheetBaker and e.g. PetSheetBaker) from the original drawing
 * code, which lives in src/test/java too and stays the source of truth for the art. A test (e.g. PetSpritesBakedTest)
 * compares every baked picture with the drawing code pixel for pixel, so the two cannot drift apart unnoticed.
 *
 * The sheet is read once, on first use; every picture is copied into its own TYPE_INT_ARGB image (the same type,
 * size and pixels the drawing code produced) and the same instance is handed out on every call. If the files are
 * missing or unreadable this logs once and every get() returns null ("no art"); it never throws into a paint loop.
 * Safe to call from any thread.
 */
public final class SpriteSheet
{
    private static final Logger log = LoggerFactory.getLogger(SpriteSheet.class);

    private final String name;
    private Map<String, BufferedImage> cells;

    public SpriteSheet(String name)
    {
        this.name = name;
    }

    /** The picture baked under this key, or null when there is none. */
    public synchronized BufferedImage get(String key)
    {
        if (cells == null) cells = load();
        return cells.get(key);
    }

    private Map<String, BufferedImage> load()
    {
        Map<String, BufferedImage> out = new HashMap<>();
        String base = "/com/forgebingo/sprites/" + name;
        try (InputStream png = SpriteSheet.class.getResourceAsStream(base + ".png");
             InputStream txt = SpriteSheet.class.getResourceAsStream(base + ".txt"))
        {
            BufferedImage sheet;
            synchronized (ImageIO.class) // ImageIO is not thread-safe; RuneLite's own loader takes the same lock
            {
                sheet = ImageIO.read(png);
            }
            for (String line : new String(txt.readAllBytes(), StandardCharsets.UTF_8).split("\n"))
            {
                String[] p = line.trim().split(" ");
                if (p.length != 5) continue;
                int w = Integer.parseInt(p[3]);
                int h = Integer.parseInt(p[4]);
                BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
                img.setRGB(0, 0, w, h, sheet.getRGB(Integer.parseInt(p[1]), Integer.parseInt(p[2]), w, h, null, 0, w), 0, w);
                out.put(p[0], img);
            }
        }
        catch (Exception e) // a missing file shows up here as a null stream (IllegalArgument / NullPointer)
        {
            log.warn("ForgeBingo: sprite sheet '{}' could not be loaded; its art is hidden", name, e);
            out.clear();
        }
        return out;
    }
}

package com.forgebingo.core;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Picks an in-game item to show for a tile that has no item icon of its own: website emoji icons (iconEmoji, from
 * servers that send it), then words in the title ("Hard clue", "ToB run"), then the first item a task asks for.
 * Every id here is checked against the items catalogue. No RuneLite dependencies (unit-tested).
 */
public final class TileIcons
{
    /** Title words, most specific first (first match wins). */
    private static final Map<String, Integer> TITLE = new LinkedHashMap<>();
    /** Website emoji icons. */
    private static final Map<String, Integer> EMOJI = new LinkedHashMap<>();

    static
    {
        TITLE.put("free space", 6199);          // Mystery box
        TITLE.put("easy clue", 2677);
        TITLE.put("medium clue", 2801);
        TITLE.put("hard clue", 2722);
        TITLE.put("elite clue", 12073);
        TITLE.put("master clue", 19835);
        TITLE.put("clue", 2722);
        TITLE.put("cox", 20851);                // Olmlet
        TITLE.put("chambers", 20851);
        TITLE.put("tob", 22473);                // Lil' Zik
        TITLE.put("theatre", 22473);
        TITLE.put("toa", 27352);                // Tumeken's guardian
        TITLE.put("tombs", 27352);
        TITLE.put("raid", 21018);               // Ancestral hat
        TITLE.put("raider", 21018);
        TITLE.put("kbd", 12653);                // Prince Black Dragon
        TITLE.put("king black", 12653);
        TITLE.put("barrows", 4716);             // Dharok's helm
        TITLE.put("wildy", 964);                // Skull
        TITLE.put("wilderness", 964);
        TITLE.put("pet", 3695);                 // Pet rock
        TITLE.put("agility", 11850);            // Graceful hood
        TITLE.put("gatherer", 1275);            // Rune pickaxe
        TITLE.put("combat", 1333);              // Rune scimitar
        TITLE.put("level", 13280);              // Max cape
        TITLE.put("solo", 11640);               // Book of Knowledge
        TITLE.put("xp", 2528);                  // Lamp
        TITLE.put("goblin", 288);               // Goblin mail
        TITLE.put("fire cape", 6570);

        EMOJI.put("🎁", 6199);        // gift
        EMOJI.put("💀", 964);         // skull
        EMOJI.put("🐉", 20851);       // dragon
        EMOJI.put("🩸", 22473);       // drop of blood
        EMOJI.put("🏺", 27352);       // amphora
        EMOJI.put("🏆", 9813);        // trophy
        EMOJI.put("🐲", 12653);       // dragon face
        EMOJI.put("📜", 2722);        // scroll
        EMOJI.put("🗺", 19835);       // map
        EMOJI.put("⬆", 13280);             // up arrow
        EMOJI.put("⛏", 1275);              // pick
        EMOJI.put("⚔", 1333);              // crossed swords
        EMOJI.put("📈", 2528);        // chart
        EMOJI.put("🧍", 11640);       // standing person
        EMOJI.put("🏃", 11850);       // runner
        EMOJI.put("🐾", 3695);        // paw prints
        EMOJI.put("🙇", 288);         // bowing
        EMOJI.put("⚰", 4716);              // coffin
        EMOJI.put("🎲", 6199);        // die
        EMOJI.put("👑", 21018);       // crown
        EMOJI.put("🔥", 6570);        // fire
        EMOJI.put("💰", 995);         // money bag
        EMOJI.put("🪙", 995);         // coin
    }

    private TileIcons()
    {
    }

    /** An item to draw for this tile when it has no item icon of its own, or null (show its initials). */
    public static Integer fallbackItem(ApiModels.Tile t)
    {
        if (t == null) return null;
        String title = t.title == null ? "" : " " + t.title.toLowerCase(Locale.ROOT) + " ";
        for (Map.Entry<String, Integer> e : TITLE.entrySet())
        {
            if (containsWord(title, e.getKey())) return e.getValue();
        }
        if (t.iconEmoji != null)
        {
            for (Map.Entry<String, Integer> e : EMOJI.entrySet())
            {
                if (t.iconEmoji.startsWith(e.getKey())) return e.getValue();
            }
        }
        if (t.tasks != null)
        {
            for (ApiModels.Task k : t.tasks)
            {
                if (k != null && k.itemIds != null && !k.itemIds.isEmpty() && k.itemIds.get(0) != null && k.itemIds.get(0) > 0)
                {
                    return k.itemIds.get(0);
                }
            }
        }
        return null;
    }

    /** Skill name (as the plugin reports it) -> that skill's cape, for level-up tasks. */
    private static final Map<String, Integer> SKILL = new LinkedHashMap<>();

    static
    {
        String[] names = {"attack", "strength", "defence", "ranged", "prayer", "magic", "runecraft", "hitpoints", "agility", "herblore",
            "thieving", "crafting", "fletching", "slayer", "construction", "mining", "smithing", "fishing", "cooking", "firemaking",
            "woodcutting", "farming"};
        int[] capes = {9747, 9750, 9753, 9756, 9759, 9762, 9765, 9768, 9771, 9774, 9777, 9780, 9783, 9786, 9789, 9792, 9795, 9798,
            9801, 9804, 9807, 9810};
        for (int i = 0; i < names.length; i++) SKILL.put(names[i], capes[i]);
        SKILL.put("hunter", 9948);
        SKILL.put("sailing", 13280);
        SKILL.put("overall", 13280);            // Max cape
    }

    /**
     * The picture for one task: its own item, else its skill's cape (level-ups), else a boss/activity named in its
     * text, else the tile's picture. Null only when nothing at all fits (the panel then draws a tick box).
     */
    public static Integer taskItem(ApiModels.Task k, ApiModels.Tile t)
    {
        if (k != null)
        {
            if (k.itemIds != null) for (Integer id : k.itemIds) if (id != null && id > 0) return id;
            if (k.skill != null)
            {
                Integer cape = SKILL.get(k.skill.toLowerCase(Locale.ROOT));
                if (cape != null) return cape;
            }
            String text = " " + ((k.description == null ? "" : k.description) + " " + (k.sourceKey == null ? "" : k.sourceKey.replace('_', ' ')))
                .toLowerCase(Locale.ROOT) + " ";
            for (Map.Entry<String, Integer> e : SKILL.entrySet()) if (containsWord(text, e.getKey())) return e.getValue();
            for (Map.Entry<String, Integer> e : TITLE.entrySet()) if (containsWord(text, e.getKey())) return e.getValue();
        }
        if (t == null) return null;
        // XP tasks say "Team gains 100,000 XP"; the skill is only in the tile's name ("100K Fishing XP")
        String title = " " + (t.title == null ? "" : t.title.toLowerCase(Locale.ROOT)) + " ";
        for (Map.Entry<String, Integer> e : SKILL.entrySet()) if (containsWord(title, e.getKey())) return e.getValue();
        return t.iconItemId != null ? t.iconItemId : null;
    }

    /** Last resort for a task with nothing of its own: the tile's own item, else an item picked from its title/emoji. */
    public static Integer taskFallback(ApiModels.Tile t)
    {
        return t == null ? null : t.iconItemId != null ? t.iconItemId : fallbackItem(t);
    }

    /** "cox" matches "CoX run" but not "coxswain"; multi-word keys match as a phrase. */
    private static boolean containsWord(String padded, String key)
    {
        int i = padded.indexOf(key);
        while (i >= 0)
        {
            boolean before = i == 0 || !Character.isLetterOrDigit(padded.charAt(i - 1));
            int end = i + key.length();
            boolean after = end >= padded.length() || !Character.isLetterOrDigit(padded.charAt(end));
            if (before && after) return true;
            i = padded.indexOf(key, i + 1);
        }
        return false;
    }
}

package com.forgebingo.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tile rules shared by the sidebar panel and the board overlay (owner request, 2026-11-07), matching the website:
 * hidden secret tiles, points per task, "needs changes" after a reviewer sends proof back, and "what's next".
 * Works with older servers too: fields they do not send fall back to what the board already had.
 */
public final class TileInfo
{
    public enum State { EMPTY, SECRET, DONE, NEEDS_CHANGES, WAITING, IN_PROGRESS, NOT_STARTED }

    private TileInfo()
    {
    }

    /** A free space: done for every team, with nothing to prove. */
    public static boolean isFree(ApiModels.Tile t)
    {
        return t != null && Boolean.TRUE.equals(t.free);
    }

    /**
     * What one teammate's share of a finished tile is called on its card: "14 kills" when every task counts kills,
     * "3 drops" when every task counts drops or chest loot, otherwise just the number ("x2": screenshots, mixed tiles).
     */
    public static String contributed(ApiModels.Tile t, int qty)
    {
        boolean kills = t != null && t.tasks != null && !t.tasks.isEmpty();
        boolean drops = kills;
        if (t != null && t.tasks != null)
        {
            for (ApiModels.Task k : t.tasks)
            {
                String st = k == null ? null : k.sourceType;
                if (!"kc".equals(st)) kills = false;
                if (!("npc".equals(st) || "raid_chest".equals(st) || "clue".equals(st))) drops = false;
            }
        }
        if (kills) return qty + (qty == 1 ? " kill" : " kills");
        if (drops) return qty + (qty == 1 ? " drop" : " drops");
        return "x" + qty;
    }

    /**
     * "Finished 2 days ago" for a tile's completedAt (an ISO instant), or null when there is none or it cannot be
     * read. Under a minute is "just now"; a time in the future (clocks disagree) is "just now" too.
     */
    public static String finishedAgo(String completedAt, long nowMillis)
    {
        if (completedAt == null || completedAt.isEmpty()) return null;
        long then;
        try
        {
            then = java.time.OffsetDateTime.parse(completedAt).toInstant().toEpochMilli();
        }
        catch (java.time.DateTimeException ex)
        {
            return null;
        }
        long mins = Math.max(0, (nowMillis - then) / 60_000L);
        if (mins < 1) return "Finished just now";
        if (mins < 60) return "Finished " + mins + (mins == 1 ? " minute ago" : " minutes ago");
        long hours = mins / 60;
        if (hours < 24) return "Finished " + hours + (hours == 1 ? " hour ago" : " hours ago");
        long days = hours / 24;
        return "Finished " + days + (days == 1 ? " day ago" : " days ago");
    }

    /** What a tile is called on screen: a hidden secret tile shows the name its organizer gave it, else "Secret tile". */
    public static String shownTitle(ApiModels.Tile t)
    {
        if (t == null) return "";
        if (isSecret(t) && !t.completed && (t.title == null || t.title.isEmpty() || "?".equals(t.title))) return "Secret tile";
        return t.title == null ? "" : t.title;
    }

    /** A hidden secret tile: the server sends "?" and no tasks (and, newer servers, secret=true). */
    public static boolean isSecret(ApiModels.Tile t)
    {
        if (t == null) return false;
        if (t.secret != null) return t.secret;
        return "?".equals(t.title) && (t.tasks == null || t.tasks.isEmpty());
    }

    /**
     * The tile's tasks as the website counts them: tasks of an "all" tile that share a group number are the "OR"
     * options of one task; every other task stands alone. Order follows the server's.
     */
    public static List<List<ApiModels.Task>> taskGroups(ApiModels.Tile t)
    {
        List<List<ApiModels.Task>> out = new ArrayList<>();
        if (t == null || t.tasks == null) return out;
        Map<Integer, List<ApiModels.Task>> byGroup = new HashMap<>();
        boolean all = !"any".equals(t.completionMode);
        for (ApiModels.Task k : t.tasks)
        {
            if (all && k.group != null)
            {
                List<ApiModels.Task> g = byGroup.get(k.group);
                if (g != null)
                {
                    g.add(k);
                    continue;
                }
                g = new ArrayList<>();
                g.add(k);
                byGroup.put(k.group, g);
                out.add(g);
            }
            else
            {
                List<ApiModels.Task> g = new ArrayList<>();
                g.add(k);
                out.add(g);
            }
        }
        return out;
    }

    /** a task's points in hundredths, so decimal points (0.1 + 0.2) add up exactly */
    private static long pts(ApiModels.Task k)
    {
        return k.points == null ? 0 : Points.cents(k.points);
    }

    private static boolean hasTaskPoints(ApiModels.Tile t)
    {
        if (t == null || t.tasks == null) return false;
        for (ApiModels.Task k : t.tasks) if (k.points != null) return true;
        return false;
    }

    /**
     * The most the tile can score, matching the server: every task adds its points, a task with "OR" options adds
     * its best option once, an older "any one" tile its best task (servers before task points: the tile's own points).
     */
    public static double worth(ApiModels.Tile t)
    {
        if (t == null) return 0;
        if (!hasTaskPoints(t)) return Points.round(t.points);
        long sum = 0;
        long best = 0;
        for (List<ApiModels.Task> g : taskGroups(t))
        {
            long top = 0;
            for (ApiModels.Task k : g) top = Math.max(top, pts(k));
            sum += top;
            best = Math.max(best, top);
        }
        return Points.fromCents("any".equals(t.completionMode) ? best : sum);
    }

    /**
     * Points the team has scored on the tile so far, matching the server: each finished task scores as soon as it is
     * done (the tile need not be complete); a task with "OR" options scores only its finished option (the best one if
     * more than one is done).
     */
    public static double earned(ApiModels.Tile t)
    {
        if (t == null) return 0;
        if (!hasTaskPoints(t)) return t.completed ? Points.round(t.points) : 0;
        long sum = 0;
        for (List<ApiModels.Task> g : taskGroups(t))
        {
            long top = 0;
            for (ApiModels.Task k : g) if (k.completed) top = Math.max(top, pts(k));
            sum += top;
        }
        return Points.fromCents(sum);
    }

    /** The newest proof on one of its unfinished tasks was sent back. Returns the reason, or null. */
    public static String needsChangesReason(ApiModels.Tile t)
    {
        if (t == null || t.completed || t.tasks == null) return null;
        for (ApiModels.Task k : t.tasks)
        {
            if (!k.completed && k.pendingQty == 0 && k.rejectedReason != null && !k.rejectedReason.isEmpty()) return k.rejectedReason;
        }
        return null;
    }

    public static boolean waiting(ApiModels.Tile t)
    {
        if (t == null || t.tasks == null) return false;
        for (ApiModels.Task k : t.tasks) if (k.pendingQty > 0) return true;
        return false;
    }

    /** How far along the tile is, 0..1 (approved quantities; "any" tiles take their best task). */
    public static double progress(ApiModels.Tile t)
    {
        if (t == null) return 0;
        if (t.completed) return 1;
        if (t.tasks == null || t.tasks.isEmpty()) return 0;
        // a task with "OR" options is as far along as its best option
        double total = 0;
        double best = 0;
        List<List<ApiModels.Task>> groups = taskGroups(t);
        for (List<ApiModels.Task> g : groups)
        {
            double p = 0;
            for (ApiModels.Task k : g) p = Math.max(p, k.completed ? 1 : k.requiredQty <= 0 ? 0 : Math.min(1, (double) k.approvedQty / k.requiredQty));
            total += p;
            best = Math.max(best, p);
        }
        return "any".equals(t.completionMode) ? best : total / groups.size();
    }

    public static State state(ApiModels.Tile t)
    {
        if (t == null) return State.EMPTY;
        if (isSecret(t)) return t.completed ? State.DONE : State.SECRET;
        if (t.completed) return State.DONE;
        if (needsChangesReason(t) != null) return State.NEEDS_CHANGES;
        if (waiting(t)) return State.WAITING;
        return progress(t) > 0 ? State.IN_PROGRESS : State.NOT_STARTED;
    }

    /** The open tiles closest to done (secret and empty tiles left out), most progress first, then most points. */
    public static List<ApiModels.Tile> nextUp(List<ApiModels.Tile> tiles, int n)
    {
        List<ApiModels.Tile> open = new ArrayList<>();
        if (tiles == null) return open;
        for (ApiModels.Tile t : tiles)
        {
            if (t == null || t.completed || isSecret(t) || t.tasks == null || t.tasks.isEmpty()) continue;
            open.add(t);
        }
        open.sort(Comparator.comparingDouble((ApiModels.Tile t) -> -progress(t)).thenComparingDouble(t -> -worth(t)));
        return open.subList(0, Math.min(n, open.size()));
    }

    /** "3/5" style progress for the tile's least-finished task, or "" when there is nothing to count. */
    public static String countText(ApiModels.Tile t)
    {
        if (t == null || t.tasks == null) return "";
        for (ApiModels.Task k : t.tasks)
        {
            if (!k.completed && k.requiredQty > 1) return Math.min(k.approvedQty, k.requiredQty) + "/" + k.requiredQty;
        }
        // tasks, not options: a task with "OR" options counts once, done when any option is
        List<List<ApiModels.Task>> groups = taskGroups(t);
        int done = 0;
        for (List<ApiModels.Task> g : groups)
        {
            for (ApiModels.Task k : g)
            {
                if (k.completed)
                {
                    done++;
                    break;
                }
            }
        }
        return groups.size() > 1 ? done + "/" + groups.size() + " tasks" : "";
    }
}

package com.forgebingo.core;

/** Comparing plugin version numbers like "2.1.0". */
public final class Versions
{
    private Versions()
    {
    }

    /** The numbers of a version, ignoring anything after them ("2.1.0-test" is 2, 1, 0). Empty when unreadable. */
    static int[] parts(String v)
    {
        if (v == null) return new int[0];
        String[] bits = v.trim().split("[.]");
        int[] out = new int[bits.length];
        for (int i = 0; i < bits.length; i++)
        {
            String digits = bits[i].replaceAll("^(\\d+).*$", "$1");
            if (!digits.matches("\\d{1,6}")) return new int[0];
            out[i] = Integer.parseInt(digits);
        }
        return out;
    }

    /** True when {@code latest} is a higher version than {@code mine}. Unreadable versions are never "newer". */
    public static boolean newer(String latest, String mine)
    {
        int[] a = parts(latest);
        int[] b = parts(mine);
        if (a.length == 0 || b.length == 0) return false;
        for (int i = 0; i < Math.max(a.length, b.length); i++)
        {
            int x = i < a.length ? a[i] : 0;
            int y = i < b.length ? b[i] : 0;
            if (x != y) return x > y;
        }
        return false;
    }
}

package com.forgebingo.core;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Whole-window proof screenshots (opt-in "Include sidebar in screenshots", owner request 2026-11-07).
 * Swing can paint the RuneLite window (sidebar, plugin panel, title bar), but the game area is drawn by the GPU and
 * comes out blank, so the game frame from the draw manager is laid over it at the canvas position.
 */
public final class WindowShot
{
    /** Larger windows fall back to the game screen only (keeps uploads under the size cap). */
    public static final int MAX_SIDE = 4096;

    private WindowShot()
    {
    }

    /**
     * Lays {@code game} over {@code window} at the canvas rectangle. Returns {@code game} unchanged when the window
     * capture is missing, too big or the canvas does not fit inside it.
     */
    public static BufferedImage compose(BufferedImage window, BufferedImage game, int canvasX, int canvasY, int canvasW, int canvasH)
    {
        if (window == null || game == null)
        {
            return game;
        }
        int w = window.getWidth();
        int h = window.getHeight();
        if (w <= 0 || h <= 0 || w > MAX_SIDE || h > MAX_SIDE || canvasW <= 0 || canvasH <= 0
            || canvasX < 0 || canvasY < 0 || canvasX + canvasW > w || canvasY + canvasH > h)
        {
            return game;
        }
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = out.createGraphics();
        try
        {
            g.drawImage(window, 0, 0, null);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(game, canvasX, canvasY, canvasW, canvasH, null);
        }
        finally
        {
            g.dispose();
        }
        return out;
    }
}

