    private static Client client(int w, int h)
    {
        return (Client) Proxy.newProxyInstance(BoardOverlayPreview.class.getClassLoader(), new Class<?>[] {Client.class}, (proxy, m, a) -> {
            switch (m.getName())
            {
                case "getCanvasWidth": return w;
                case "getCanvasHeight": return h;
                case "hashCode": return 1;
                case "equals": return proxy == a[0];
                case "toString": return "preview client";
                default:
                    Class<?> r = m.getReturnType();
                    if (r == boolean.class) return false;
                    if (r == int.class) return 0;
                    if (r == long.class) return 0L;
                    if (r == float.class) return 0f;
                    if (r == double.class) return 0d;
                    if (r == short.class) return (short) 0;
                    if (r == byte.class) return (byte) 0;
                    if (r == char.class) return (char) 0;
                    return null;
            }
        });
    }

    private static BoardOverlay overlay(int w, int h)
    {
        Fake fake = new Fake();
        BoardOverlay o = new BoardOverlay(client(w, h), null, new ForgeBingoConfig() { }, fake);
        PLUGINS.clear();
        PLUGINS.put(o, fake);
        o.clock = () -> now;
        return o;
    }

    /** Something game-like behind the overlay: grass, a path, water, and the fixed-mode interface on the right and below. */
    private static void paintGame(Graphics2D g, int w, int h)
    {
        g.setPaint(new GradientPaint(0, 0, new Color(0x4c6b2d), 0, h, new Color(0x2f4a20)));
        g.fillRect(0, 0, w, h);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(0x7a6a48));
        g.fillPolygon(new int[] {(int) (w * 0.1), (int) (w * 0.22), (int) (w * 0.7), (int) (w * 0.55)}, new int[] {h, h, 0, 0}, 4);
        g.setColor(new Color(0x2c5f86));
        g.fillOval((int) (w * 0.05), (int) (h * 0.08), (int) (w * 0.3), (int) (h * 0.3));
        java.util.Random rng = new java.util.Random(4);
        for (int i = 0; i < 40; i++)
        {
            int x = rng.nextInt(w), y = rng.nextInt(h), s = (int) (h * (0.03 + rng.nextDouble() * 0.05));
            g.setColor(new Color(0x1f3d1a));
            g.fillOval(x, y, s, s);
            g.setColor(new Color(0x3d7a2c));
            g.fillOval(x + s / 6, y + s / 8, s * 2 / 3, s * 2 / 3);
        }
        int side = (int) (h * 0.48), chatH = (int) (h * 0.28);
        g.setColor(new Color(0x3e3529));
        g.fillRect(w - side, 0, side, h);
        g.setColor(new Color(0x5b4f3c));
        g.fillOval(w - side + side / 8, side / 20, side * 3 / 4, side * 3 / 5);
        g.setColor(new Color(0x2a2319));
        g.fillRect(w - side + side / 10, (int) (h * 0.42), side * 4 / 5, (int) (h * 0.5));
        g.setColor(new Color(0xc8b592));
        g.fillRect(0, h - chatH, (int) (w * 0.68) - side / 4, chatH);
        g.setColor(new Color(0x6b5d45));
        g.drawRect(0, h - chatH, (int) (w * 0.68) - side / 4 - 1, chatH - 1);
    }

    private static BufferedImage frame(BoardOverlay o, int w, int h)
    {
        BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        paintGame(g, w, h);
        g.dispose();
        g = img.createGraphics();
        o.render(g);
        g.dispose();
        return img;
    }

    public static void main(String[] args) throws Exception
    {
        File out = new File(args.length > 0 ? args[0] : "build/preview");
        String mode = args.length > 1 ? args[1] : "after";
        // a theme's name as the mode ("blood", "xeric", ...) draws the board in that theme
        for (PanelTheme t : PanelTheme.values()) if (t.name().equalsIgnoreCase(mode)) ForgeBingoPanel.useTheme(t);
        out.mkdirs();
        int[][] sizes = {{765, 503}, {1280, 720}, {1920, 1080}};
        for (int[] s : sizes)
        {
            BoardOverlay o = overlay(s[0], s[1]);
            o.open();
            now += 10_000;
            long t0 = System.nanoTime();
            BufferedImage img = frame(o, s[0], s[1]);
            long first = System.nanoTime() - t0;
            ImageIO.write(img, "png", new File(out, "board-" + mode + "-" + s[0] + "x" + s[1] + ".png"));
            // how long a settled frame takes once everything is cached
            int runs = 200;
            t0 = System.nanoTime();
            for (int i = 0; i < runs; i++)
            {
                now += 16;
                frame(o, s[0], s[1]);
            }
            long game = System.nanoTime();
            for (int i = 0; i < runs; i++)
            {
                BufferedImage b = new BufferedImage(s[0], s[1], BufferedImage.TYPE_INT_RGB);
                Graphics2D g = b.createGraphics();
                paintGame(g, s[0], s[1]);
                g.dispose();
            }
            long bg = System.nanoTime() - game;
            System.out.printf("%dx%d: first frame %.1f ms, settled overlay frame %.2f ms%n", s[0], s[1], first / 1e6,
                ((game - t0) - bg) / 1e6 / runs);
        }
        if (!"before".equals(mode))
        {
            int w = 1280, h = 720;
            BoardOverlay o = overlay(w, h);
            o.open();
            now += 10_000;
            frame(o, w, h);
            BoardLayout l = o.layout();
            Rectangle c = l.cell(3, 1);
            o.hover((int) c.getCenterX(), (int) c.getCenterY());
            now += 1000;
            ImageIO.write(frame(o, w, h), "png", new File(out, "board-" + mode + "-hover-1280x720.png"));

            o = overlay(w, h);
            o.open();
            now += 10_000;
            frame(o, w, h);
            c = l.cell(0, 2);
            o.click((int) c.getCenterX(), (int) c.getCenterY());
            now += 1000;
            ImageIO.write(frame(o, w, h), "png", new File(out, "board-" + mode + "-card-1280x720.png"));

            animation(out, w, h, OpeningAnim.byName("Diagonal Deal"), "board-opening.gif", true);
            animation(out, w, h, OpeningAnim.byName("The Vortex"), "board-opening-legendary.gif", false);
        }
        if ("check".equals(mode)) check(out);
        System.out.println("Wrote board previews to " + out.getAbsolutePath());
        System.exit(0);
    }

    /**
     * Odd cases, to see that nothing breaks or looks wrong away from the usual 5x5: tiny and huge boards, no board
     * at all, the overlay half faded, and one frame each of an Epic and a Legendary opening.
     */
    private static void check(File out) throws Exception
    {
        int[][] cases = {{765, 503, 1}, {765, 503, 3}, {765, 503, 10}, {765, 503, 20}, {1920, 1080, 10}, {1920, 1080, 20}, {2560, 1440, 7}, {320, 240, 5}};
        for (int[] c : cases)
        {
            BoardOverlay o = overlay(c[0], c[1]);
            ((Fake) plugin(o)).board = grid(c[2]);
            o.open();
            now += 10_000;
            frame(o, c[0], c[1]);
            BoardLayout l = o.layout();
            Rectangle cell = l.cell(c[2] / 2, c[2] / 2);
            o.hover((int) cell.getCenterX(), (int) cell.getCenterY());
            now += 1000;
            ImageIO.write(frame(o, c[0], c[1]), "png", new File(out, "board-check-" + c[0] + "x" + c[1] + "-" + c[2] + ".png"));
            o.click((int) cell.getCenterX(), (int) cell.getCenterY());
            now += 100;
            frame(o, c[0], c[1]);
            now += 1000;
            if (c[2] == 3 || c[2] == 7) ImageIO.write(frame(o, c[0], c[1]), "png", new File(out, "board-check-card-" + c[0] + "x" + c[1] + "-" + c[2] + ".png"));
            o.close();
            now += 80;
            frame(o, c[0], c[1]);
        }
        BoardOverlay none = overlay(765, 503);
        ((Fake) plugin(none)).board = null;
        none.open();
        now += 5000;
        ImageIO.write(frame(none, 765, 503), "png", new File(out, "board-check-noboard.png"));
        int k = 0;
        for (OpeningAnim.Spec spec : new OpeningAnim.Spec[] {OpeningAnim.byName("The Vortex"), OpeningAnim.byName("Whirling Heart"),
            OpeningAnim.byName("Card Flip Rows"), OpeningAnim.byName("Raindrops")})
        {
            Rectangle all = new Rectangle(0, 0, 1280, 720);
            ImageIO.write(render(1280, 720, spec, now + 100_000, 1500, all), "png", new File(out, "board-check-anim-" + (++k) + "-" + spec.rarity.label + ".png"));
            ImageIO.write(render(1280, 720, spec, now + 100_000, 2800, all), "png", new File(out, "board-check-anim-" + k + "-end.png"));
        }
        // every animation, start to finish, must draw without complaint
        for (OpeningAnim.Spec spec : OpeningAnim.ALL)
        {
            for (int t = 0; t <= 3100; t += 155) render(640, 480, spec, now + 200_000, t, new Rectangle(0, 0, 640, 480));
        }
        // the card popping open, part way
        BoardOverlay o = overlay(1280, 720);
        o.open();
        now += 10_000;
        frame(o, 1280, 720);
        Rectangle cell = o.layout().cell(0, 2);
        o.click((int) cell.getCenterX(), (int) cell.getCenterY());
        now += 70;
        ImageIO.write(frame(o, 1280, 720), "png", new File(out, "board-check-card-pop.png"));
    }

    private static final java.util.Map<BoardOverlay, ForgeBingoPlugin> PLUGINS = new java.util.IdentityHashMap<>();

    private static ForgeBingoPlugin plugin(BoardOverlay o)
    {
        return PLUGINS.get(o);
    }

    /** An n x n board with every kind of tile scattered over it. */
    private static ApiModels.BoardResponse grid(int n)
    {
        StringBuilder sb = new StringBuilder("{'teamBoardId':'b1','teamName':'The Extremely Long Named Team Of Goblin Slayers And Friends',"
            + "'event':{'id':'e1','name':'A bingo with a very long name indeed, the longest name in Gielinor','status':'live','active':true},"
            + "'board':{'id':'bd','title':'Board','size':" + n + "},'tiles':[");
        for (int r = 0; r < n; r++)
        {
            for (int c = 0; c < n; c++)
            {
                int k = (r * 7 + c * 3) % 9;
                String rest = k == 0 ? "'completed':true,'tasks':[" + doneTask("d", "Done") + "]"
                    : k == 1 ? "'tasks':[" + task("a", "Kill 10 things for the team, a long task text that will need wrapping over lines", 10, "kc", 4, 0) + "]"
                    : k == 2 ? "'tasks':[" + task("a", "Waiting", 1, "manual", 0, 1) + "]"
                    : k == 3 ? "'workingOn':[{'name':'Zezima','me':false}],'tasks':[" + task("a", "One", 1, "npc", 0, 0) + "," + task("b", "Two", 3, "npc", 1, 0) + ","
                        + task("c", "Three", 1, "manual", 0, 0) + "," + task("e", "Four", 1, "manual", 0, 0) + "," + task("f", "Five", 5, "npc", 5, 0) + "]"
                    : "'tasks':[" + task("a", "Not started", 1, "npc", 0, 0) + "]";
                if (k == 4) sb.append("{'id':'t").append(r).append('_').append(c).append("','row':").append(r).append(",'col':").append(c)
                    .append(",'title':'?','secret':true,'points':1,'completionMode':'all','tasks':[]},");
                else sb.append(tile(r, c, k == 5 ? "No icon here" : "Tile " + r + " " + c + " with quite a long name", k == 5 ? null : 1000 + r * 31 + c, 2, rest)
                    .replace("'id':'t" + r + c + "'", "'id':'t" + r + "_" + c + "'"));
            }
        }
        sb.append("{}]}");
        ApiModels.BoardResponse b = new Gson().fromJson(sb.toString(), ApiModels.BoardResponse.class);
        b.tiles.remove(b.tiles.size() - 1);
        return b;
    }

    /**
     * One overlay playing this opening on a boardSize x boardSize board in a w x h client, drawn at each of the given
     * times (ms since it opened). Each frame goes to sink (which may be null: the opening tests only need it to draw).
     */
    static void play(int w, int h, int boardSize, OpeningAnim.Spec spec, java.util.function.BiConsumer<Integer, BufferedImage> sink, int... times)
    {
        BoardOverlay o = overlay(w, h);
        if (boardSize != 5) ((Fake) plugin(o)).board = grid(boardSize);
        long start = now + 100_000;
        now = start;
        o.open();
        o.opening = spec;
        for (int t : times)
        {
            now = start + t;
            BufferedImage img = frame(o, w, h);
            if (sink != null) sink.accept(t, img);
        }
    }

    /** The board's rectangle in a w x h client with an n x n board. */
    static Rectangle boardRect(int w, int h, int n)
    {
        return BoardLayout.compute(w, h, n).board();
    }

    // ---------- the opening animation as a GIF ----------

    /** ~30 fps: GIF delays are whole hundredths of a second, so the frames take turns at 3, 3 and 4 */
    private static final int[] DELAYS = {3, 3, 4};

    private static void animation(File out, int w, int h, OpeningAnim.Spec spec, String name, boolean stills) throws Exception
    {
        animation(out, w, h, java.util.Collections.singletonList(spec), name, stills);
    }

    /** One GIF playing these openings one after another, each held for a moment once finished. */
    static void animation(File out, int w, int h, List<OpeningAnim.Spec> specs, String name, boolean stills) throws Exception
    {
        BoardLayout l = BoardLayout.compute(w, h, 5);
        Rectangle b = l.board();
        int margin = 28;
        Rectangle crop = new Rectangle(b.x - margin, b.y - margin, b.width + 2 * margin, b.height + 2 * margin).intersection(new Rectangle(0, 0, w, h));
        // frame times (ms since the board opened): 3.2 s of animation per opening
        List<Integer> times = new ArrayList<>();
        List<Integer> delays = new ArrayList<>();
        List<OpeningAnim.Spec> whose = new ArrayList<>();
        for (OpeningAnim.Spec sp : specs)
        {
            int t = 0;
            for (int i = 0; t <= 3200; i++)
            {
                times.add(t);
                delays.add(DELAYS[i % 3]);
                whose.add(sp);
                t += DELAYS[i % 3] * 10;
            }
            delays.set(delays.size() - 1, 160); // hold the finished board before the next one (or the loop)
        }
        long start = now + 60_000;
        // pass 1: the colours in use (every third frame is plenty)
        int[] hist = new int[32768];
        for (int i = 0; i < times.size(); i += 3) count(hist, render(w, h, whose.get(i), start, times.get(i), crop));
        count(hist, render(w, h, whose.get(times.size() - 1), start, times.get(times.size() - 1), crop));
        int[] palette = medianCut(hist, 255);
        byte[] lut = new byte[32768];
        boolean[] known = new boolean[32768];
        byte[] r = new byte[256], g = new byte[256], bl = new byte[256];
        for (int i = 0; i < palette.length; i++)
        {
            r[i] = (byte) (palette[i] >> 16);
            g[i] = (byte) (palette[i] >> 8);
            bl[i] = (byte) palette[i];
        }
        IndexColorModel icm = new IndexColorModel(8, 256, r, g, bl, 255);

        File file = new File(out, name);
        file.delete();
        ImageWriter writer = ImageIO.getImageWritersBySuffix("gif").next();
        try (ImageOutputStream ios = ImageIO.createImageOutputStream(file))
        {
            writer.setOutput(ios);
            // one colour table for the whole file (without this the writer falls back to its stock web palette)
            IIOMetadata stream = writer.getDefaultStreamMetadata(null);
            String sfmt = stream.getNativeMetadataFormatName();
            IIOMetadataNode sroot = (IIOMetadataNode) stream.getAsTree(sfmt);
            IIOMetadataNode screen = child(sroot, "LogicalScreenDescriptor");
            screen.setAttribute("logicalScreenWidth", Integer.toString(crop.width));
            screen.setAttribute("logicalScreenHeight", Integer.toString(crop.height));
            screen.setAttribute("colorResolution", "8");
            screen.setAttribute("pixelAspectRatio", "0");
            IIOMetadataNode old = child(sroot, "GlobalColorTable");
            sroot.removeChild(old);
            IIOMetadataNode table = new IIOMetadataNode("GlobalColorTable");
            table.setAttribute("sizeOfGlobalColorTable", "256");
            table.setAttribute("backgroundColorIndex", "0");
            table.setAttribute("sortFlag", "FALSE");
            for (int i = 0; i < 256; i++)
            {
                IIOMetadataNode e = new IIOMetadataNode("ColorTableEntry");
                e.setAttribute("index", Integer.toString(i));
                e.setAttribute("red", Integer.toString(r[i] & 255));
                e.setAttribute("green", Integer.toString(g[i] & 255));
                e.setAttribute("blue", Integer.toString(bl[i] & 255));
                table.appendChild(e);
            }
            sroot.appendChild(table);
            stream.setFromTree(sfmt, sroot);
            writer.prepareWriteSequence(stream);
            byte[] prev = null;
            int still = 0;
            for (int i = 0; i < times.size(); i++)
            {
                BufferedImage rgb = render(w, h, whose.get(i), start, times.get(i), crop);
                if (stills && (times.get(i) == 200 || times.get(i) == 600 || times.get(i) == 1200 || times.get(i) == 2000 || times.get(i) == 2600))
                {
                    ImageIO.write(rgb, "png", new File(out, "board-anim-frame-" + (++still) + ".png"));
                }
                int cw = crop.width, ch = crop.height;
                byte[] idx = new byte[cw * ch];
                int[] px = rgb.getRGB(0, 0, cw, ch, null, 0, cw);
                for (int k = 0; k < px.length; k++)
                {
                    int c15 = ((px[k] >> 9) & 0x7c00) | ((px[k] >> 6) & 0x3e0) | ((px[k] >> 3) & 0x1f);
                    if (!known[c15])
                    {
                        lut[c15] = (byte) nearest(palette, c15);
                        known[c15] = true;
                    }
                    idx[k] = lut[c15];
                }
                // only the part that changed since the last frame is stored; unchanged pixels inside it are see-through
                int x0 = 0, y0 = 0, x1 = cw - 1, y1 = ch - 1;
                boolean transparent = false;
                byte[] data = idx;
                if (prev != null)
                {
                    x0 = cw; y0 = ch; x1 = -1; y1 = -1;
                    for (int y = 0; y < ch; y++)
                    {
                        for (int x = 0; x < cw; x++)
                        {
                            if (idx[y * cw + x] != prev[y * cw + x])
                            {
                                if (x < x0) x0 = x;
                                if (x > x1) x1 = x;
                                if (y < y0) y0 = y;
                                if (y > y1) y1 = y;
                            }
                        }
                    }
                    if (x1 < 0) { x0 = 0; y0 = 0; x1 = 0; y1 = 0; }
                    int sw = x1 - x0 + 1, sh = y1 - y0 + 1;
                    data = new byte[sw * sh];
                    for (int y = 0; y < sh; y++)
                    {
                        for (int x = 0; x < sw; x++)
                        {
                            int at = (y + y0) * cw + x + x0;
                            data[y * sw + x] = idx[at] == prev[at] ? (byte) 255 : idx[at];
                        }
                    }
                    transparent = true;
                }
                int sw = x1 - x0 + 1, sh = y1 - y0 + 1;
                BufferedImage part = new BufferedImage(sw, sh, BufferedImage.TYPE_BYTE_INDEXED, icm);
                part.getRaster().setDataElements(0, 0, sw, sh, data);
                IIOMetadata md = writer.getDefaultImageMetadata(new ImageTypeSpecifier(part), null);
                String fmt = md.getNativeMetadataFormatName();
                IIOMetadataNode root = (IIOMetadataNode) md.getAsTree(fmt);
                IIOMetadataNode gce = child(root, "GraphicControlExtension");
                gce.setAttribute("disposalMethod", "doNotDispose");
                gce.setAttribute("userInputFlag", "FALSE");
                gce.setAttribute("transparentColorFlag", transparent ? "TRUE" : "FALSE");
                gce.setAttribute("delayTime", Integer.toString(delays.get(i)));
                gce.setAttribute("transparentColorIndex", transparent ? "255" : "0");
                IIOMetadataNode desc = child(root, "ImageDescriptor");
                desc.setAttribute("imageLeftPosition", Integer.toString(x0));
                desc.setAttribute("imageTopPosition", Integer.toString(y0));
                desc.setAttribute("imageWidth", Integer.toString(sw));
                desc.setAttribute("imageHeight", Integer.toString(sh));
                desc.setAttribute("interlaceFlag", "FALSE");
                if (i == 0)
                {
                    IIOMetadataNode apps = child(root, "ApplicationExtensions");
                    IIOMetadataNode app = new IIOMetadataNode("ApplicationExtension");
                    app.setAttribute("applicationID", "NETSCAPE");
                    app.setAttribute("authenticationCode", "2.0");
                    app.setUserObject(new byte[] {1, 0, 0}); // loop forever
                    apps.appendChild(app);
                }
                md.setFromTree(fmt, root);
                writer.writeToSequence(new IIOImage(part, null, md), null);
                prev = idx;
            }
            writer.endWriteSequence();
        }
        writer.dispose();
        System.out.println(name + ": " + specs + ", " + times.size() + " frames, " + crop.width + "x" + crop.height
            + ", " + file.length() / 1024 + " KB");
    }

    /** One frame of the opening animation, sinceOpen ms after the board opened, cropped to the board. */
    private static BufferedImage render(int w, int h, OpeningAnim.Spec spec, long start, int sinceOpen, Rectangle crop)
    {
        now = start;
        BoardOverlay o = overlay(w, h);
        o.open();
        o.opening = spec;
        now = start + sinceOpen;
        BufferedImage full = frame(o, w, h);
        BufferedImage part = new BufferedImage(crop.width, crop.height, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = part.createGraphics();
        g.drawImage(full, -crop.x, -crop.y, null);
        g.dispose();
        return part;
    }

    private static IIOMetadataNode child(IIOMetadataNode root, String name)
    {
        for (Node n = root.getFirstChild(); n != null; n = n.getNextSibling())
        {
            if (name.equals(n.getNodeName())) return (IIOMetadataNode) n;
        }
        IIOMetadataNode made = new IIOMetadataNode(name);
        root.appendChild(made);
        return made;
    }

    private static void count(int[] hist, BufferedImage img)
    {
        int[] px = img.getRGB(0, 0, img.getWidth(), img.getHeight(), null, 0, img.getWidth());
        for (int p : px) hist[((p >> 9) & 0x7c00) | ((p >> 6) & 0x3e0) | ((p >> 3) & 0x1f)]++;
    }

    /** Median cut over a 15-bit colour histogram: the n colours that cover the animation best, as 0xRRGGBB. */
    private static int[] medianCut(int[] hist, int n)
    {
        List<int[]> boxes = new ArrayList<>();
        int used = 0;
        for (int c : hist) if (c > 0) used++;
        int[] all = new int[used];
        int k = 0;
        for (int i = 0; i < hist.length; i++) if (hist[i] > 0) all[k++] = i;
        boxes.add(all);
        while (boxes.size() < n)
        {
            int best = -1, bestAxis = 0;
            double bestScore = 0;
            for (int i = 0; i < boxes.size(); i++)
            {
                int[] box = boxes.get(i);
                if (box.length < 2) continue;
                int[] lo = {31, 31, 31}, hi = {0, 0, 0};
                long pop = 0;
                for (int c : box)
                {
                    pop += hist[c];
                    for (int a = 0; a < 3; a++)
                    {
                        int v = (c >> (10 - 5 * a)) & 31;
                        lo[a] = Math.min(lo[a], v);
                        hi[a] = Math.max(hi[a], v);
                    }
                }
                int axis = 0;
                for (int a = 1; a < 3; a++) if (hi[a] - lo[a] > hi[axis] - lo[axis]) axis = a;
                double score = (hi[axis] - lo[axis] + 1) * Math.sqrt(pop);
                if (score > bestScore)
                {
                    bestScore = score;
                    best = i;
                    bestAxis = axis;
                }
            }
            if (best < 0) break;
            int[] box = boxes.remove(best);
            int shift = 10 - 5 * bestAxis;
            long[] keyed = new long[box.length];
            long pop = 0;
            for (int i = 0; i < box.length; i++)
            {
                keyed[i] = ((long) ((box[i] >> shift) & 31) << 32) | box[i];
                pop += hist[box[i]];
            }
            Arrays.sort(keyed);
            long acc = 0;
            int cut = 1;
            for (int i = 0; i < keyed.length - 1; i++)
            {
                acc += hist[(int) keyed[i]];
                cut = i + 1;
                if (acc * 2 >= pop) break;
            }
            int[] a = new int[cut], b = new int[keyed.length - cut];
            for (int i = 0; i < keyed.length; i++)
            {
                if (i < cut) a[i] = (int) keyed[i]; else b[i - cut] = (int) keyed[i];
            }
            boxes.add(a);
            boxes.add(b);
        }
        int[] out = new int[boxes.size()];
        for (int i = 0; i < out.length; i++)
        {
            long r = 0, g = 0, b = 0, pop = 0;
            for (int c : boxes.get(i))
            {
                int p = hist[c];
                r += (long) (((c >> 10) & 31) * 8 + 4) * p;
                g += (long) (((c >> 5) & 31) * 8 + 4) * p;
                b += (long) ((c & 31) * 8 + 4) * p;
                pop += p;
            }
            pop = Math.max(1, pop);
            out[i] = (int) (r / pop) << 16 | (int) (g / pop) << 8 | (int) (b / pop);
        }
        return out;
    }

    private static int nearest(int[] palette, int c15)
    {
        int r = ((c15 >> 10) & 31) * 8 + 4, g = ((c15 >> 5) & 31) * 8 + 4, b = (c15 & 31) * 8 + 4;
        int best = 0, bestD = Integer.MAX_VALUE;
        for (int i = 0; i < palette.length; i++)
        {
            int dr = r - ((palette[i] >> 16) & 255), dg = g - ((palette[i] >> 8) & 255), db = b - (palette[i] & 255);
            int d = dr * dr * 2 + dg * dg * 4 + db * db;
            if (d < bestD)
            {
                bestD = d;
                best = i;
            }
        }
        return best;
    }
}

package com.forgebingo;

import com.forgebingo.core.Chexy;
import com.forgebingo.core.ChexySpells;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/**
 * Writes Chexy's preview: art/chexy-frames.png (eight frames; top row the real pixels blown up, bottom row
 * drawn big) and art/chexy-big.png (one frame, real pixels on the left, drawn big on the right), and prints what
 * one frame costs to draw. Not a test.
 */
public final class ChexyPreview
{
    private ChexyPreview()
    {
    }

    private static final int CELL = 56;
    private static final int FRAMES = 8;
    private static final float STEP = 0.18f;
    private static final int[] BACKS = {
        PanelTheme.CLASSIC.palette[1], PanelTheme.BLOOD.palette[0], PanelTheme.XERIC.palette[1], PanelTheme.AMASCUT.palette[0],
        PanelTheme.CLASSIC.palette[0], PanelTheme.INFERNO.palette[1], PanelTheme.SKILLING.palette[0], PanelTheme.BARROWS.palette[1],
    };

    public static void main(String[] args) throws Exception
    {
        File dir = new File(args.length > 0 ? args[0] : "art");
        dir.mkdirs();
        boolean calm = args.length > 1 && "calm".equals(args[1]);
        int up = 3;
        BufferedImage strip = new BufferedImage(CELL * up * FRAMES, CELL * up * 2, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = strip.createGraphics();
        for (int f = 0; f < FRAMES; f++)
        {
            float t = 3f + f * STEP;
            Color back = new Color(BACKS[f % BACKS.length]);
            BufferedImage small = frame(t, back, 1, calm);
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            g.drawImage(small, f * CELL * up, 0, CELL * up, CELL * up, null);
            g.drawImage(frame(t, back, up, calm), f * CELL * up, CELL * up, null);
        }
        g.dispose();
        ImageIO.write(strip, "png", new File(dir, calm ? "chexy-frames-calm.png" : "chexy-frames.png"));

        int big = 8;
        BufferedImage one = new BufferedImage(CELL * big * 2, CELL * big, BufferedImage.TYPE_INT_RGB);
        g = one.createGraphics();
        Color back = new Color(PanelTheme.CLASSIC.palette[1]);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(frame(3.5f, back, 1, calm), 0, 0, CELL * big, CELL * big, null);
        g.drawImage(frame(3.5f, back, big, calm), CELL * big, 0, null);
        g.dispose();
        ImageIO.write(one, "png", new File(dir, calm ? "chexy-big-calm.png" : "chexy-big.png"));

        if (!calm) gif(new File(dir, "chexy.gif"));
        forms(new File(dir, calm ? "chexy-forms-calm.png" : "chexy-forms.png"), calm);
        if (!calm) powerup(new File(dir, "chexy-powerup.gif"));
        spellsSheet(new File(dir, calm ? "chexy-spells-calm.png" : "chexy-spells.png"), calm);
        if (!calm) spellsGif(new File(dir, "chexy-spells.gif"));

        // what one frame costs, drawn straight onto a panel-sized picture the way the panel's layer does
        BufferedImage panel = new BufferedImage(242, 560, BufferedImage.TYPE_INT_RGB);
        Graphics2D pg = panel.createGraphics();
        pg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        String[] names = {"base", "charge", "gold", "blue", "flower spell", "barrier", "beam volley"};
        float[] ages = {3f, Chexy.CHARGE_AT + 1f, 25f, 50f, ChexySpells.FLOWER_AT + 1f, ChexySpells.BARRIER_AT + 1.2f,
            ChexySpells.VOLLEYS[0] + 1.9f};
        for (int f = 0; f < names.length; f++)
        {
            int n = 3000;
            final int which = f;
            for (int pass = 0; pass < 2; pass++)
            {
                long start = System.nanoTime();
                for (int i = 0; i < n; i++)
                {
                    float age = ages[which] + (i % 10) * 0.01f;
                    float t = i * 0.033f;
                    Chexy.paint(pg, 120, 200, t, t, Chexy.SIZE, calm, which < 4 ? age : -1f, which < 4 ? -1f : age);
                    if (which == 4) paintFlowers(pg, 120, 200, 2.5f + (i % 10) * 0.01f, t, calm);
                    if (which == 6)
                    {
                        ChexySpells.paintVolley(pg, 120, 200, -1, age - ChexySpells.VOLLEYS[0], t, Chexy.GOLD, calm,
                            new java.awt.Rectangle(0, 0, 242, 560));
                    }
                }
                long took = System.nanoTime() - start;
                if (pass == 1) System.out.printf("Chexy %s: %.3f ms per frame%n", names[f], took / 1e6 / n);
            }
        }
        pg.dispose();
        System.out.println("Wrote previews to " + dir.getAbsolutePath());
    }

    // ------------------------------------------------------------------ the spells

    private static final int SW = 150, SH = 96, SUP = 3;

    /** the flowers' layout round Chexy at (cx, cy), as the panel lays them out: on the card just below, and lower down */
    private static final float[][] FLOWERS = layout(false);
    private static final float[][] FLOWERS_CALM = layout(true);

    private static float[][] layout(boolean calm)
    {
        java.util.List<float[]> out = new java.util.ArrayList<>();
        java.util.Random r = new java.util.Random(7);
        float[] near = calm ? new float[] {-6, 7, 18} : new float[] {-6, 7, -17, 18, -29, 30};
        float[] low = calm ? new float[] {-40, 10, 60} : new float[] {-46, -28, -9, 9, 27, 45, 64, 82};
        int index = 0;
        for (float dx : near) out.add(new float[] {dx, 26, r.nextInt(4), 0.12f + Math.abs(dx) / 110f + 26 / 260f + r.nextFloat() * 0.12f, index++});
        for (float dx : low) out.add(new float[] {dx, 52, r.nextInt(4), 0.12f + Math.abs(dx) / 110f + 52 / 260f + r.nextFloat() * 0.12f, index++});
        return out.toArray(new float[0][]);
    }

    /** the flowers, sinceSpawn seconds after they were placed */
    private static void paintFlowers(Graphics2D g, float cx, float cy, float sinceSpawn, float clock, boolean calm)
    {
        if (sinceSpawn >= 0 && sinceSpawn < 1.5f) ChexySpells.paintWave(g, cx, cy + 22, sinceSpawn, calm);
        for (float[] fl : calm ? FLOWERS_CALM : FLOWERS)
        {
            int x = Math.round(cx + fl[0]);
            int ground = Math.round(cy + fl[1]);
            float since = sinceSpawn - fl[3];
            float life = ChexySpells.FLOWER_LIFE - fl[3] * 0.5f;
            ChexySpells.paintFlower(g, x, ground, (int) fl[2], since, life, clock);
            ChexySpells.paintPetals(g, x, ground, (int) fl[2], since, (int) fl[4], calm);
        }
    }

    /** a dark panel with two cards, as the flowers would stand on them */
    private static Graphics2D scene(BufferedImage img, float cy, boolean cards)
    {
        Graphics2D g = img.createGraphics();
        g.setColor(new Color(PanelTheme.CLASSIC.palette[0]));
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.scale(SUP, SUP);
        if (cards)
        {
            int[] tops = {Math.round(cy + 26), Math.round(cy + 52)};
            int[] rights = {108, 146};
            for (int i = 0; i < 2; i++)
            {
                g.setColor(new Color(PanelTheme.CLASSIC.palette[2]));
                g.fillRect(4, tops[i], rights[i] - 4, i == 0 ? 20 : SH);
                g.setColor(new Color(PanelTheme.CLASSIC.palette[3]));
                g.drawRect(4, tops[i], rights[i] - 4, i == 0 ? 20 : SH);
            }
        }
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        return g;
    }

    /** One frame of a spell at visit age; t is Chexy's clock. which: 0 flowers, 1 barrier, 2 volley. */
    private static BufferedImage spellFrame(int which, float age, float t, boolean calm)
    {
        BufferedImage img = new BufferedImage(SW * SUP, SH * SUP, BufferedImage.TYPE_INT_RGB);
        float cx = which == 0 ? 58 : which == 1 ? 75 : 34;
        float cy = which == 0 ? 30 : which == 1 ? 46 : 50;
        Graphics2D g = scene(img, cy, which == 0);
        float x = cx + Chexy.bobX(t), y = cy + Chexy.bobY(t);
        if (which == 0)
        {
            float spawn = ChexySpells.FLOWER_AT + ChexySpells.FLOWER_SPAWN;
            paintFlowers(g, cx, cy, age - spawn, age, calm);
        }
        float[] kick = new float[2];
        float vp = ChexySpells.volleyPhase(age);
        if (which == 2 && vp >= 0) ChexySpells.recoil(vp, 1, calm, kick);
        Chexy.paint(g, x + kick[0], y + kick[1], t, t, Chexy.SIZE, calm, -1f, age);
        if (which == 2 && vp >= 0)
        {
            ChexySpells.paintVolley(g, x, y, 1, vp, age, Chexy.BASE, calm, new java.awt.Rectangle(0, 0, SW, SH));
        }
        g.dispose();
        return img;
    }

    /** art/chexy-spells.png: key frames, a row per spell (flowers, barrier, beam volley). */
    private static void spellsSheet(File file, boolean calm) throws Exception
    {
        float spawn = ChexySpells.FLOWER_AT + ChexySpells.FLOWER_SPAWN;
        float[][] ages = {
            {spawn + 0.2f, spawn + 0.75f, spawn + 1.3f, spawn + 3.6f},
            {ChexySpells.BARRIER_AT + 0.35f, ChexySpells.BARRIER_AT + 1.15f, ChexySpells.BARRIER_AT + 2.05f, ChexySpells.BARRIER_AT + 3.75f},
            {ChexySpells.VOLLEYS[0] + 0.85f, ChexySpells.VOLLEYS[0] + 1.06f, ChexySpells.VOLLEYS[0] + 1.95f, ChexySpells.VOLLEYS[0] + 2.75f},
        };
        int w = SW * SUP, h = SH * SUP;
        BufferedImage sheet = new BufferedImage(w * 4, h * 3, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = sheet.createGraphics();
        for (int row = 0; row < 3; row++)
        {
            for (int col = 0; col < 4; col++)
            {
                float age = ages[row][col];
                g.drawImage(spellFrame(row, age, 3f + age, calm), col * w, row * h, null);
            }
        }
        g.dispose();
        ImageIO.write(sheet, "png", file);
    }

    /** art/chexy-spells.gif: the three spells playing one after another, looping (long lingers cut short). */
    private static void spellsGif(File file) throws Exception
    {
        float dt = 0.08f;
        float spawn = ChexySpells.FLOWER_AT + ChexySpells.FLOWER_SPAWN;
        float[][] parts = {
            {0, ChexySpells.FLOWER_AT - 0.3f, spawn + 4.4f},
            {0, spawn + ChexySpells.FLOWER_LIFE - 2.1f, spawn + ChexySpells.FLOWER_LIFE + 0.1f},
            {1, ChexySpells.BARRIER_AT - 0.3f, ChexySpells.BARRIER_AT + ChexySpells.BARRIER_TIME + 0.2f},
            {2, ChexySpells.VOLLEYS[0] - 0.3f, ChexySpells.VOLLEYS[0] + ChexySpells.VOLLEY_TIME + 0.2f},
        };
        java.util.List<BufferedImage> frames = new java.util.ArrayList<>();
        for (float[] part : parts)
        {
            float t = 3f + part[1]; // a spell visit never spins up: its clock runs at the usual speed
            for (float age = part[1]; age < part[2]; age += dt)
            {
                frames.add(spellFrame((int) part[0], age, t, false));
                t += dt;
            }
        }
        BufferedImage[] all = frames.toArray(new BufferedImage[0]);
        int w = SW * SUP, h = SH * SUP;
        int cols = 8;
        int shown = (all.length + 3) / 4;
        BufferedImage sheet = new BufferedImage(w * cols / 2, h * ((shown + cols - 1) / cols) / 2, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = sheet.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        for (int i = 0; i < all.length; i += 4)
        {
            int n = i / 4;
            g.drawImage(all[i], n % cols * w / 2, n / cols * h / 2, w / 2, h / 2, null);
        }
        g.dispose();
        new File("build/preview").mkdirs();
        ImageIO.write(sheet, "png", new File("build/preview/chexy-spells-sheet.png"));
        writeGif(file, all, Math.round(dt * 100));
        System.out.println("Spells GIF: " + all.length + " frames");
    }

    private static final int PCELL = 80;

    /** Chexy's own clock at a visit age, run the way the panel runs it (sped up by Chexy.spin). */
    private static float clockAt(float age)
    {
        float t = 3f;
        for (float a = 0; a < age; a += 0.01f) t += 0.01f * Chexy.spin(a);
        return t;
    }

    /** One frame of the power-up at 3x, centred, floating, on the dark panel colour; scale for the pop. */
    private static BufferedImage powerFrame(float t, float age, float pop, boolean calm)
    {
        int up = 3;
        BufferedImage img = new BufferedImage(PCELL * up, PCELL * up, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setColor(new Color(PanelTheme.CLASSIC.palette[0]));
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.scale(up, up);
        g.translate(PCELL / 2f + Chexy.bobX(t), PCELL / 2f + 6 + Chexy.bobY(t));
        if (pop < 1f) g.scale(Math.max(0.02f, pop), Math.max(0.02f, pop));
        Chexy.paint(g, 0, 0, t, t, Chexy.SIZE, calm, age);
        g.dispose();
        return img;
    }

    /** art/chexy-forms.png: frames across the whole power-up (base, charge, flash, gold, charge, flash, blue). */
    private static void forms(File file, boolean calm) throws Exception
    {
        float[] ages = {3f, Chexy.CHARGE_AT + 0.8f, Chexy.GOLD_AT - 0.15f, Chexy.GOLD_AT + 0.05f, Chexy.GOLD_AT + 0.4f, Chexy.GOLD_AT + 9f,
            Chexy.CHARGE2_AT + 1.2f, Chexy.BLUE_AT + 0.05f, Chexy.BLUE_AT + 0.6f, Chexy.BLUE_AT + 10f};
        int w = PCELL * 3;
        BufferedImage strip = new BufferedImage(w * ages.length, w, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = strip.createGraphics();
        for (int i = 0; i < ages.length; i++) g.drawImage(powerFrame(clockAt(ages[i]), ages[i], 1f, calm), i * w, 0, null);
        g.dispose();
        ImageIO.write(strip, "png", file);
    }

    /**
     * art/chexy-powerup.gif: the whole transformation, looping. It pops in, stays itself a moment, charges, flashes
     * gold, holds, charges again, flashes blue, holds, and pops out. The long holds are cut short.
     */
    private static void powerup(File file) throws Exception
    {
        float dt = 0.07f;
        // stretches of visit age to show: (from, to); between them the steady holds are skipped
        float[][] parts = {{Chexy.CHARGE_AT - 1.8f, Chexy.GOLD_AT + 3.2f}, {Chexy.CHARGE2_AT - 0.8f, Chexy.BLUE_AT + 3.4f}};
        java.util.List<BufferedImage> frames = new java.util.ArrayList<>();
        float t = clockAt(parts[0][0]);
        float pop = 0.45f;
        int total = 0;
        for (float[] part : parts) total += (int) ((part[1] - part[0]) / dt);
        int f = 0;
        for (float[] part : parts)
        {
            for (float age = part[0]; age < part[1]; age += dt, f++)
            {
                // the pop in at the start and the pop out at the end, as on the panel
                float sc = 1f;
                float in = f * dt / pop;
                float out = (total - 1 - f) * dt / pop;
                if (in < 1) sc = (float) (1 + 0.25 * Math.sin(in * Math.PI)) * Math.min(1f, in * 1.6f);
                else if (out < 1) sc = 1 - (1 - out) * (1 - out);
                frames.add(powerFrame(t, age, sc, false));
                t += dt * Chexy.spin(age);
            }
        }
        BufferedImage[] all = frames.toArray(new BufferedImage[0]);
        // a contact sheet (every sixth frame) to look at it still
        int w = PCELL * 3;
        int cols = (all.length + 5) / 6;
        BufferedImage sheet = new BufferedImage(w * Math.min(cols, 12), w * ((cols + 11) / 12), BufferedImage.TYPE_INT_RGB);
        Graphics2D g = sheet.createGraphics();
        for (int i = 0; i < all.length; i += 6) g.drawImage(all[i], (i / 6) % 12 * w, (i / 6) / 12 * w, null);
        g.dispose();
        new File("build/preview").mkdirs();
        ImageIO.write(sheet, "png", new File("build/preview/chexy-powerup-sheet.png"));
        writeGif(file, all, Math.round(dt * 100));
        System.out.println("Power-up GIF: " + all.length + " frames");
    }

    private static final int GIF_FRAMES = 36;
    /**
     * A looping GIF of one comet lap at 3x on the dark panel colour: the real pixels blown up on the left, drawn at
     * 3x on the right. The comets, twinkles and float repeat every lap. The rings' slow turn does not, so here its
     * clock sways to and fro around the start (at the same top speed as in the panel) and the loop is seamless.
     */
    private static void gif(File file) throws Exception
    {
        int up = 3;
        int cell = 64;
        Color back = new Color(PanelTheme.CLASSIC.palette[0]);
        float dt = Chexy.LAP / GIF_FRAMES;
        float t0 = 3f;
        BufferedImage[] frames = new BufferedImage[GIF_FRAMES];
        for (int f = 0; f < GIF_FRAMES; f++)
        {
            frames[f] = gifFrame(t0 + f * dt, back, cell, up);
        }
        // a contact sheet of the GIF (every third frame, real pixels on top, drawn big below) to look at it still
        int fw = cell * up;
        BufferedImage sheet = new BufferedImage(fw * GIF_FRAMES / 3, fw * 2, BufferedImage.TYPE_INT_RGB);
        Graphics2D sg = sheet.createGraphics();
        for (int f = 0; f < GIF_FRAMES; f += 3)
        {
            sg.drawImage(frames[f].getSubimage(0, 0, fw, fw), f / 3 * fw, 0, null);
            sg.drawImage(frames[f].getSubimage(fw, 0, fw, fw), f / 3 * fw, fw, null);
        }
        sg.dispose();
        new File("build/preview").mkdirs();
        ImageIO.write(sheet, "png", new File("build/preview/chexy-gif-sheet.png"));

        writeGif(file, frames, Math.round(dt * 100));
    }

    /** Writes a looping GIF, every frame on one shared, dithered palette. */
    private static void writeGif(File file, BufferedImage[] frames, int delayCs) throws Exception
    {
        frames = indexed(frames);
        javax.imageio.ImageWriter writer = ImageIO.getImageWritersByFormatName("gif").next();
        try (javax.imageio.stream.ImageOutputStream out = ImageIO.createImageOutputStream(file))
        {
            writer.setOutput(out);
            writer.prepareWriteSequence(null);
            for (int f = 0; f < frames.length; f++)
            {
                javax.imageio.ImageTypeSpecifier type = javax.imageio.ImageTypeSpecifier.createFromRenderedImage(frames[f]);
                javax.imageio.metadata.IIOMetadata meta = writer.getDefaultImageMetadata(type, null);
                String fmt = meta.getNativeMetadataFormatName();
                javax.imageio.metadata.IIOMetadataNode root = (javax.imageio.metadata.IIOMetadataNode) meta.getAsTree(fmt);
                javax.imageio.metadata.IIOMetadataNode gce = child(root, "GraphicControlExtension");
                gce.setAttribute("disposalMethod", "none");
                gce.setAttribute("userInputFlag", "FALSE");
                gce.setAttribute("transparentColorFlag", "FALSE");
                gce.setAttribute("delayTime", Integer.toString(delayCs));
                gce.setAttribute("transparentColorIndex", "0");
                // the shared palette, written out with every frame (the writer leaves it out otherwise)
                java.awt.image.IndexColorModel cm = (java.awt.image.IndexColorModel) frames[f].getColorModel();
                javax.imageio.metadata.IIOMetadataNode table = child(root, "LocalColorTable");
                table.setAttribute("sizeOfLocalColorTable", "256");
                table.setAttribute("sortFlag", "FALSE");
                while (table.getLength() > 0) table.removeChild(table.getFirstChild());
                for (int i = 0; i < 256; i++)
                {
                    int rgb = i < cm.getMapSize() ? cm.getRGB(i) : 0;
                    javax.imageio.metadata.IIOMetadataNode e = new javax.imageio.metadata.IIOMetadataNode("ColorTableEntry");
                    e.setAttribute("index", Integer.toString(i));
                    e.setAttribute("red", Integer.toString((rgb >> 16) & 255));
                    e.setAttribute("green", Integer.toString((rgb >> 8) & 255));
                    e.setAttribute("blue", Integer.toString(rgb & 255));
                    table.appendChild(e);
                }
                if (f == 0)
                {
                    javax.imageio.metadata.IIOMetadataNode apps = child(root, "ApplicationExtensions");
                    javax.imageio.metadata.IIOMetadataNode app = new javax.imageio.metadata.IIOMetadataNode("ApplicationExtension");
                    app.setAttribute("applicationID", "NETSCAPE");
                    app.setAttribute("authenticationCode", "2.0");
                    app.setUserObject(new byte[] {1, 0, 0});
                    apps.appendChild(app);
                }
                meta.setFromTree(fmt, root);
                writer.writeToSequence(new javax.imageio.IIOImage(frames[f], null, meta), null);
            }
            writer.endWriteSequence();
        }
        writer.dispose();
    }

    /**
     * One shared 256-colour palette for every frame (median cut over all of them), with error-diffusion dithering,
     * so the soft glow and the nebula survive the GIF instead of banding away.
     */
    private static BufferedImage[] indexed(BufferedImage[] frames)
    {
        int[] hist = new int[1 << 15];
        for (BufferedImage f : frames)
        {
            for (int y = 0; y < f.getHeight(); y++)
            {
                for (int x = 0; x < f.getWidth(); x++) hist[key(f.getRGB(x, y))]++;
            }
        }
        java.util.List<int[]> boxes = new java.util.ArrayList<>();
        int n = 0;
        for (int i = 0; i < hist.length; i++) if (hist[i] > 0) n++;
        int[] all = new int[n];
        n = 0;
        for (int i = 0; i < hist.length; i++) if (hist[i] > 0) all[n++] = i;
        boxes.add(all);
        while (boxes.size() < 256)
        {
            // split the box spread widest, at its weighted middle along its widest channel
            int best = -1, bestRange = 0, bestCh = 0;
            for (int b = 0; b < boxes.size(); b++)
            {
                int[] box = boxes.get(b);
                if (box.length < 2) continue;
                for (int ch = 0; ch < 3; ch++)
                {
                    int lo = 31, hi = 0;
                    for (int c : box)
                    {
                        int v = (c >> (10 - ch * 5)) & 31;
                        lo = Math.min(lo, v);
                        hi = Math.max(hi, v);
                    }
                    if (hi - lo > bestRange)
                    {
                        bestRange = hi - lo;
                        best = b;
                        bestCh = ch;
                    }
                }
            }
            if (best < 0) break;
            int shift = 10 - bestCh * 5;
            Integer[] box = java.util.Arrays.stream(boxes.get(best)).boxed().toArray(Integer[]::new);
            java.util.Arrays.sort(box, java.util.Comparator.comparingInt(c -> (c >> shift) & 31));
            long total = 0;
            for (int c : box) total += hist[c];
            long acc = 0;
            int cut = 1;
            for (int i = 0; i < box.length - 1; i++)
            {
                acc += hist[box[i]];
                cut = i + 1;
                if (acc * 2 >= total) break;
            }
            int[] a = new int[cut];
            int[] b = new int[box.length - cut];
            for (int i = 0; i < box.length; i++)
            {
                if (i < cut) a[i] = box[i];
                else b[i - cut] = box[i];
            }
            boxes.set(best, a);
            boxes.add(b);
        }
        int size = boxes.size();
        byte[] rs = new byte[size], gs = new byte[size], bs = new byte[size];
        int[][] pal = new int[size][3];
        for (int b = 0; b < size; b++)
        {
            long r = 0, g = 0, bl = 0, w = 0;
            for (int c : boxes.get(b))
            {
                int k = hist[c];
                r += (long) (((c >> 10) & 31) * 8 + 4) * k;
                g += (long) (((c >> 5) & 31) * 8 + 4) * k;
                bl += (long) ((c & 31) * 8 + 4) * k;
                w += k;
            }
            pal[b][0] = (int) (r / w);
            pal[b][1] = (int) (g / w);
            pal[b][2] = (int) (bl / w);
            rs[b] = (byte) pal[b][0];
            gs[b] = (byte) pal[b][1];
            bs[b] = (byte) pal[b][2];
        }
        java.awt.image.IndexColorModel cm = new java.awt.image.IndexColorModel(8, size, rs, gs, bs);
        int[] near = new int[1 << 15];
        java.util.Arrays.fill(near, -1);
        BufferedImage[] out = new BufferedImage[frames.length];
        for (int fi = 0; fi < frames.length; fi++)
        {
            BufferedImage f = frames[fi];
            int w = f.getWidth(), h = f.getHeight();
            BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_BYTE_INDEXED, cm);
            java.awt.image.WritableRaster ras = img.getRaster();
            float[][] err = new float[2][(w + 2) * 3];
            for (int y = 0; y < h; y++)
            {
                float[] cur = err[y & 1];
                float[] next = err[(y + 1) & 1];
                java.util.Arrays.fill(next, 0f);
                for (int x = 0; x < w; x++)
                {
                    int p = f.getRGB(x, y);
                    int[] want = new int[3];
                    for (int ch = 0; ch < 3; ch++)
                    {
                        int v = (p >> (16 - ch * 8)) & 255;
                        want[ch] = Math.max(0, Math.min(255, Math.round(v + cur[(x + 1) * 3 + ch])));
                    }
                    int key = (want[0] >> 3) << 10 | (want[1] >> 3) << 5 | (want[2] >> 3);
                    if (near[key] < 0)
                    {
                        int bi = 0;
                        long bd = Long.MAX_VALUE;
                        for (int i = 0; i < size; i++)
                        {
                            long dr = pal[i][0] - ((want[0] & 0xf8) + 4);
                            long dg = pal[i][1] - ((want[1] & 0xf8) + 4);
                            long db = pal[i][2] - ((want[2] & 0xf8) + 4);
                            long d = dr * dr * 3 + dg * dg * 4 + db * db * 2;
                            if (d < bd)
                            {
                                bd = d;
                                bi = i;
                            }
                        }
                        near[key] = bi;
                    }
                    int idx = near[key];
                    ras.setSample(x, y, 0, idx);
                    for (int ch = 0; ch < 3; ch++)
                    {
                        float e = want[ch] - pal[idx][ch];
                        cur[(x + 2) * 3 + ch] += e * 7 / 16f;
                        next[x * 3 + ch] += e * 3 / 16f;
                        next[(x + 1) * 3 + ch] += e * 5 / 16f;
                        next[(x + 2) * 3 + ch] += e / 16f;
                    }
                }
            }
            out[fi] = img;
        }
        return out;
    }

    private static int key(int rgb)
    {
        return ((rgb >> 19) & 31) << 10 | ((rgb >> 11) & 31) << 5 | ((rgb >> 3) & 31);
    }

    private static javax.imageio.metadata.IIOMetadataNode child(javax.imageio.metadata.IIOMetadataNode root, String name)
    {
        for (int i = 0; i < root.getLength(); i++)
        {
            if (root.item(i).getNodeName().equals(name)) return (javax.imageio.metadata.IIOMetadataNode) root.item(i);
        }
        javax.imageio.metadata.IIOMetadataNode n = new javax.imageio.metadata.IIOMetadataNode(name);
        root.appendChild(n);
        return n;
    }

    private static BufferedImage gifFrame(float t, Color back, int cell, int up)
    {
        BufferedImage img = new BufferedImage(cell * up * 2, cell * up, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        BufferedImage small = new BufferedImage(cell, cell, BufferedImage.TYPE_INT_RGB);
        Graphics2D sg = small.createGraphics();
        sg.setColor(back);
        sg.fillRect(0, 0, cell, cell);
        // the slow clock sways round the start once per lap (top speed 1, as in the panel), so the loop closes
        double lap = Chexy.LAP;
        float drift = 3f + (float) (lap / (2 * Math.PI) * Math.sin(2 * Math.PI * (t - 3f) / lap));
        Chexy.paint(sg, cell / 2f + Chexy.bobX(t), cell / 2f + Chexy.bobY(t), t, drift, Chexy.SIZE, false, -1f);
        sg.dispose();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(small, 0, 0, cell * up, cell * up, null);
        g.setColor(back);
        g.fillRect(cell * up, 0, cell * up, cell * up);
        g.translate(cell * up, 0);
        g.scale(up, up);
        Chexy.paint(g, cell / 2f + Chexy.bobX(t), cell / 2f + Chexy.bobY(t), t, drift, Chexy.SIZE, false, -1f);
        g.dispose();
        return img;
    }

    private static BufferedImage frame(float t, Color back, int scale, boolean calm)
    {
        BufferedImage img = new BufferedImage(CELL * scale, CELL * scale, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setColor(back);
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.scale(scale, scale);
        Chexy.paint(g, CELL / 2f, CELL / 2f, t, Chexy.SIZE, calm);
        g.dispose();
        return img;
    }
}

package com.forgebingo;

import com.forgebingo.core.Critter;
import com.forgebingo.core.CryptSprites;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/** Writes build/preview/sprites-crypt.png (and a bigger sheet per group) so the crypt sprites can be eyeballed. */
public final class CryptSpritesPreview
{
    private static final int SCALE = 6;
    private static final Color BG = new Color(0x2b2722);

    private CryptSpritesPreview()
    {
    }

    private static final class Entry
    {
        final Critter c;
        final int v;

        Entry(Critter c, int v)
        {
            this.c = c;
            this.v = v;
        }
    }

    private static Entry[] of(Critter... cs)
    {
        Entry[] e = new Entry[cs.length];
        for (int i = 0; i < cs.length; i++) e[i] = new Entry(cs[i], 0);
        return e;
    }

    private static Entry[] join(Entry[]... parts)
    {
        int n = 0;
        for (Entry[] p : parts) n += p.length;
        Entry[] out = new Entry[n];
        int k = 0;
        for (Entry[] p : parts)
        {
            for (Entry e : p) out[k++] = e;
        }
        return out;
    }

    public static void main(String[] args) throws Exception
    {
        File dir = new File("build/preview");
        dir.mkdirs();
        Entry[] barrows = of(Critter.AHRIM, Critter.DHAROK, Critter.GUTHAN, Critter.KARIL, Critter.TORAG, Critter.VERAC);
        Entry[] inferno = of(Critter.ZUK, Critter.JAD, Critter.MELEER, Critter.NIBBLER);
        Entry[] cox = join(of(Critter.MUTTADILE, Critter.TEKTON, Critter.VESPULA),
            new Entry[] {new Entry(Critter.VANGUARD, 0), new Entry(Critter.VANGUARD, 1), new Entry(Critter.VANGUARD, 2)});
        ImageIO.write(sheet(join(barrows, inferno, cox), 3, true), "png", new File(dir, "sprites-crypt.png"));
        ImageIO.write(sheet(barrows, 3, false), "png", new File(dir, "sprites-crypt-barrows.png"));
        ImageIO.write(sheet(inferno, 2, false), "png", new File(dir, "sprites-crypt-inferno.png"));
        ImageIO.write(sheet(cox, 3, false), "png", new File(dir, "sprites-crypt-cox.png"));
        System.out.println("wrote " + dir.getAbsolutePath());
    }

    private static BufferedImage sheet(Entry[] list, int cols, boolean falls)
    {
        int cellW = 2 * 42 * SCALE + 40;
        int cellH = 34 * SCALE + 40;
        int rows = (list.length + cols - 1) / cols;
        int fallH = falls ? 16 * SCALE + 50 : 0;
        BufferedImage out = new BufferedImage(cols * cellW + 20, rows * cellH + fallH + 20, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setColor(BG);
        g.fillRect(0, 0, out.getWidth(), out.getHeight());
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.setFont(new Font("SansSerif", Font.BOLD, 14));
        for (int i = 0; i < list.length; i++)
        {
            int x = 10 + (i % cols) * cellW;
            int y = 10 + (i / cols) * cellH;
            g.setColor(Color.WHITE);
            g.drawString(list[i].c.name() + (list[i].c.variants > 1 ? " v" + list[i].v : ""), x, y + 14);
            for (int f = 0; f < 2; f++)
            {
                BufferedImage img = CryptSprites.image(list[i].c, list[i].v, f);
                g.drawImage(img, x + f * 42 * SCALE, y + 24, 42 * SCALE, 34 * SCALE, null);
            }
        }
        if (falls)
        {
            int y = 10 + rows * cellH;
            g.setColor(Color.WHITE);
            g.drawString("falling: BONE x2, EMBER x2", 10, y + 14);
            int x = 10;
            Critter.Fall[] fs = {Critter.Fall.BONE, Critter.Fall.EMBER};
            for (Critter.Fall fl : fs)
            {
                for (int v = 0; v < 2; v++)
                {
                    BufferedImage img = CryptSprites.fall(fl, v);
                    g.drawImage(img, x, y + 24, 16 * SCALE, 16 * SCALE, null);
                    x += 16 * SCALE + 20;
                }
            }
        }
        g.dispose();
        return out;
    }
}

