package com.forgebingo;

import com.forgebingo.core.Critter;
import com.forgebingo.core.RaidSprites;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.imageio.ImageIO;

/**
 * Writes build/preview/sprites-raid.png: every raid creature, variant and walk frame at 6x, plus the falling things.
 * Set RAID_ONLY=CRAB,NYLO to draw just some critters (handy for zoomed checks). Also prints stray-pixel warnings.
 */
public final class RaidSpritesPreview
{
    private static final int S = 6;

    public static void main(String[] args) throws Exception
    {
        String only = System.getenv("RAID_ONLY");
        Set<String> wanted = new HashSet<>();
        if (only != null && !only.isEmpty()) wanted.addAll(Arrays.asList(only.toUpperCase().split(",")));

        List<Object[]> entries = new ArrayList<>();
        Critter[] order = {Critter.CRAB, Critter.NYLO, Critter.XARPUS, Critter.VERZIK, Critter.AKKHA, Critter.ZEBAK, Critter.KEPHRI, Critter.BABA, Critter.WARDEN};
        for (Critter c : order)
        {
            if (!wanted.isEmpty() && !wanted.contains(c.name())) continue;
            for (int v = 0; v < c.variants; v++) entries.add(new Object[] {c, v});
        }

        int cols = 2;
        int cw = 2 * 42 * S + 16 + 24;
        int ch = 34 * S + 30;
        int rows = (entries.size() + cols - 1) / cols;
        int fallH = 18 * S + 40;
        int stripH = 34 * 2 + 30;
        int width = cols * cw + 24;
        int height = rows * ch + fallH + stripH + 20;
        BufferedImage sheet = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = sheet.createGraphics();
        g.setColor(new Color(0x2b2722));
        g.fillRect(0, 0, width, height);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));

        for (int i = 0; i < entries.size(); i++)
        {
            Critter c = (Critter) entries.get(i)[0];
            int v = (Integer) entries.get(i)[1];
            int x = 24 + (i % cols) * cw;
            int y = 10 + (i / cols) * ch;
            g.setColor(new Color(0xe8dcc0));
            g.drawString(c.name() + " v" + v, x, y + 14);
            for (int f = 0; f < 2; f++)
            {
                BufferedImage img = RaidSprites.image(c, v, f);
                int ix = x + f * (42 * S + 16);
                g.setColor(new Color(0x3a342d));
                g.fillRect(ix, y + 20, 42 * S, 34 * S);
                g.setColor(new Color(0x4a4238));
                g.drawLine(ix, y + 20 + 33 * S + S, ix + 42 * S, y + 20 + 33 * S + S);
                g.drawImage(img, ix, y + 20, 42 * S, 34 * S, null);
                report(c, v, f, img);
            }
        }

        int fy = 10 + rows * ch;
        g.setColor(new Color(0xe8dcc0));
        g.drawString("falling things", 24, fy + 14);
        int fx = 24;
        Object[][] falls = {
            {Critter.Fall.BLOOD_DROP, 0}, {Critter.Fall.BLOOD_DROP, 1}, {Critter.Fall.CRYSTAL, 0}, {Critter.Fall.CRYSTAL, 1},
            {Critter.Fall.KEPHRI_BOMB, 0}, {Critter.Fall.WATER_DROP, 0}};
        for (Object[] fl : falls)
        {
            BufferedImage img = RaidSprites.fall((Critter.Fall) fl[0], (Integer) fl[1]);
            g.setColor(new Color(0x3a342d));
            g.fillRect(fx, fy + 20, img.getWidth() * S, img.getHeight() * S);
            g.drawImage(img, fx, fy + 20, img.getWidth() * S, img.getHeight() * S, null);
            g.setColor(new Color(0xe8dcc0));
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
            g.drawString(fl[0] + " " + fl[1] + " (" + img.getWidth() + "x" + img.getHeight() + ")", fx, fy + 30 + img.getHeight() * S);
            fx += Math.max(img.getWidth() * S, 150) + 14;
        }

        // 2x strip: how they look at roughly real size
        int sy = fy + fallH;
        int sx = 24;
        for (Object[] e : entries)
        {
            BufferedImage img = RaidSprites.image((Critter) e[0], (Integer) e[1], 0);
            g.drawImage(img, sx, sy, 84, 68, null);
            sx += 88;
            if (sx > width - 90) break;
        }
        g.dispose();

        File out = new File("build/preview/sprites-raid" + (wanted.isEmpty() ? "" : "-part") + ".png");
        out.getParentFile().mkdirs();
        ImageIO.write(sheet, "png", out);
        System.out.println("wrote " + out.getAbsolutePath());
    }

    /** Prints connected-component count (stray pixels) and the bounding box of an image. */
    private static void report(Critter c, int v, int f, BufferedImage img)
    {
        int w = img.getWidth();
        int h = img.getHeight();
        boolean[][] seen = new boolean[h][w];
        int comps = 0;
        int x0 = w;
        int x1 = -1;
        int y0 = h;
        int y1 = -1;
        StringBuilder small = new StringBuilder();
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                if ((img.getRGB(x, y) >>> 24) == 0) continue;
                x0 = Math.min(x0, x);
                x1 = Math.max(x1, x);
                y0 = Math.min(y0, y);
                y1 = Math.max(y1, y);
                if (seen[y][x]) continue;
                comps++;
                int n = 0;
                List<int[]> stack = new ArrayList<>();
                stack.add(new int[] {x, y});
                seen[y][x] = true;
                while (!stack.isEmpty())
                {
                    int[] p = stack.remove(stack.size() - 1);
                    n++;
                    for (int dy = -1; dy <= 1; dy++)
                    {
                        for (int dx = -1; dx <= 1; dx++)
                        {
                            int nx = p[0] + dx;
                            int ny = p[1] + dy;
                            if (nx < 0 || ny < 0 || nx >= w || ny >= h || seen[ny][nx]) continue;
                            if ((img.getRGB(nx, ny) >>> 24) == 0) continue;
                            seen[ny][nx] = true;
                            stack.add(new int[] {nx, ny});
                        }
                    }
                }
                if (n < 30) small.append(" [").append(n).append("px at ").append(x).append(',').append(y).append(']');
            }
        }
        System.out.println(c + " v" + v + " f" + f + " comps=" + comps + " bbox x" + x0 + ".." + x1 + " (w" + (x1 - x0 + 1)
            + ") y" + y0 + ".." + y1 + " (h" + (y1 - y0 + 1) + ")" + small);
    }
}

package com.forgebingo;

import static org.junit.Assert.assertEquals;

import com.forgebingo.core.GameEvent;
import org.junit.Test;

/** Owner, 2026-11-14: only reward chests (raids, Barrows, Moons) get two pictures; clues, drops and kills get one. */
public class ShotCountTest
{
    @Test
    public void cluesDropsAndKillsTakeOnePicture()
    {
        assertEquals(1, ForgeBingoPlugin.shotDelays(GameEvent.CLUE, "hard", false).length);
        assertEquals(1, ForgeBingoPlugin.shotDelays(GameEvent.KC, "Clue scroll (elite)", false).length);
        assertEquals(1, ForgeBingoPlugin.shotDelays(GameEvent.NPC, null, false).length);
        assertEquals(1, ForgeBingoPlugin.shotDelays(GameEvent.KC, "Vorkath", false).length);
        assertEquals(1, ForgeBingoPlugin.shotDelays(GameEvent.KC, "Chambers of Xeric", false).length);
    }

    @Test
    public void rewardChestsTakeTwo()
    {
        assertEquals(2, ForgeBingoPlugin.shotDelays(GameEvent.RAID_CHEST, "Chambers of Xeric", true).length);
        assertEquals(2, ForgeBingoPlugin.shotDelays(GameEvent.RAID_CHEST, "Barrows", true).length);
        assertEquals(2, ForgeBingoPlugin.shotDelays(GameEvent.RAID_CHEST, "Lunar Chest", true).length);
    }
}

package com.forgebingo;

import com.forgebingo.core.SkillProp;
import com.forgebingo.core.SkillPropArt;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/** Writes build/preview/skill-props.png (and -a/-b/-c parts): every prop, every stage, both stage-2 frames. */
public final class SkillPropsPreview
{
    private static final int Z = 6;
    private static final int IMG = 24;
    private static final int CELL = IMG * Z + 8;
    private static final int LABEL = 16;
    private static final int ROW = IMG * Z + LABEL + 8;
    private static final int BLOCK = CELL * 4 + 16;
    private static final Color BG = new Color(0x1f281b);
    private static final Color GROUND = new Color(0x4d6342);

    public static void main(String[] args) throws Exception
    {
        SkillProp[] all = SkillProp.values();
        int perCol = 8;
        File dir = new File("build/preview");
        dir.mkdirs();

        // main sheet
        int smallH = 2 * IMG + 40 + IMG;
        BufferedImage sheet = new BufferedImage(BLOCK * 3 + 16, perCol * ROW + smallH + 30, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = setup(sheet);
        for (int i = 0; i < all.length; i++)
        {
            block(g, all[i], 8 + (i / perCol) * BLOCK, 8 + (i % perCol) * ROW);
        }
        int y = perCol * ROW + 20;
        g.setColor(Color.WHITE);
        g.drawString("1x (top) and 2x (bottom), stage 2, frame 0", 8, y - 4);
        for (int i = 0; i < all.length; i++)
        {
            BufferedImage im = SkillPropArt.image(all[i], 2, 0);
            g.drawImage(im, 8 + i * (IMG + 8), y, null);
            g.drawImage(im, 8 + i * (IMG * 2 + 4) / 1 - 0, y + IMG + 12, IMG * 2, IMG * 2, null);
        }
        g.setColor(new Color(0x7f9a70));
        g.fillRect(0, y + IMG, sheet.getWidth(), 1);
        g.fillRect(0, y + IMG + 12 + IMG * 2, sheet.getWidth(), 1);
        g.dispose();
        ImageIO.write(sheet, "png", new File(dir, "skill-props.png"));

        // three part sheets (easier to look at)
        String[] names = {"a", "b", "c"};
        for (int part = 0; part < 3; part++)
        {
            BufferedImage s = new BufferedImage(BLOCK + 16, perCol * ROW + 16, BufferedImage.TYPE_INT_ARGB);
            Graphics2D h = setup(s);
            for (int k = 0; k < perCol; k++)
            {
                block(h, all[part * perCol + k], 8, 8 + k * ROW);
            }
            h.dispose();
            ImageIO.write(s, "png", new File(dir, "skill-props-" + names[part] + ".png"));
        }
        System.out.println("wrote " + new File(dir, "skill-props.png").getAbsolutePath());
    }

    private static Graphics2D setup(BufferedImage img)
    {
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.setColor(BG);
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        return g;
    }

    private static void block(Graphics2D g, SkillProp p, int ox, int oy)
    {
        g.setColor(Color.WHITE);
        g.drawString(p.name(), ox, oy + 12);
        int[][] spec = {{0, 0}, {1, 0}, {2, 0}, {2, 1}};
        for (int k = 0; k < 4; k++)
        {
            BufferedImage im = SkillPropArt.image(p, spec[k][0], spec[k][1]);
            int x = ox + k * CELL;
            int y = oy + LABEL;
            g.setColor(GROUND);
            g.fillRect(x, y + IMG * Z, IMG * Z, 1);
            if (im != null)
            {
                g.drawImage(im, x, y, im.getWidth() * Z, im.getHeight() * Z, null);
            }
        }
    }
}

package com.forgebingo;

import com.forgebingo.core.ApiClient;
import com.forgebingo.core.ScreenshotEncode;
import com.forgebingo.core.ScreenshotStack;
import com.forgebingo.core.ScreenshotStamp;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.nio.file.Files;
import java.time.ZonedDateTime;
import java.util.Arrays;

/** Renders a sample of two proof pictures stacked into one upload. Not a test; writes build/preview/proof-stacked.jpg. */
public final class StackPreview
{
    private StackPreview()
    {
    }

    public static void main(String[] args) throws Exception
    {
        File out = new File(args.length > 0 ? args[0] : "build/preview");
        out.mkdirs();
        ZonedDateTime t = ZonedDateTime.now();
        BufferedImage a = ScreenshotStamp.stamp(frame("Stand-in game picture: 0.3 s after the kill (loot on the ground)", new Color(0x2f3b25)), "ANVIL", t, "Example Player", "Zulrah kills (1 of 2)");
        BufferedImage b = ScreenshotStamp.stamp(frame("Stand-in game picture: 1.5 s after the kill", new Color(0x26323a)), "ANVIL", t.plusNanos(1_200_000_000L), "Example Player", "Zulrah kills (2 of 2)");
        byte[] jpg = ScreenshotEncode.jpeg(ScreenshotStack.vertical(Arrays.asList(a, b)), ApiClient.MAX_SCREENSHOT_BYTES);
        File f = new File(out, "proof-stacked.jpg");
        Files.write(f.toPath(), jpg);
        System.out.println("Wrote " + f.getAbsolutePath() + " (" + jpg.length / 1024 + " KB)");
    }

    private static BufferedImage frame(String text, Color bg)
    {
        BufferedImage img = new BufferedImage(1280, 720, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setColor(bg);
        g.fillRect(0, 0, 1280, 720);
        g.setColor(new Color(255, 255, 255, 200));
        g.setFont(new Font("SansSerif", Font.PLAIN, 26));
        g.drawString(text, 60, 370);
        g.dispose();
        return img;
    }
}

