package com.forgebingo;

import com.forgebingo.core.ApiModels;
import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.RepaintManager;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

/**
 * Writes a run of frames of the side panel per theme (build/preview/frames/<theme>-NN.png, one every tenth of a
 * second), so the creatures, the fliers, the sand and the lava can be watched moving. Not a test.
 */
public final class ThemeMotion
{
    private ThemeMotion()
    {
    }

    private static final int H = 560;
    private static final int FRAMES = 90;

    public static void main(String[] args) throws Exception
    {
        File out = new File(args.length > 0 ? args[0] : "build/preview/frames");
        out.mkdirs();
        try
        {
            net.runelite.client.ui.laf.RuneLiteLAF.setup();
        }
        catch (Throwable t)
        {
            System.out.println("RuneLite look and feel not applied: " + t);
        }
        for (PanelTheme theme : PanelTheme.values())
        {
            if (theme == PanelTheme.CLASSIC) continue;
            SwingUtilities.invokeAndWait(() -> {
                try
                {
                    run(theme, out);
                }
                catch (Exception e)
                {
                    throw new RuntimeException(e);
                }
            });
        }
        System.out.println("Wrote frames to " + out.getAbsolutePath());
        System.exit(0);
    }

    private static void run(PanelTheme theme, File out) throws Exception
    {
        RepaintManager.currentManager(null).setDoubleBufferingEnabled(false);
        PanelUi.animations = false;
        ForgeBingoPanel.usePixelFonts(false);
        ForgeBingoPanel.useTheme(theme);
        ForgeBingoPanel panel = new ForgeBingoPanel(new PanelPreview.Fake(), null);
        panel.setStatus(true, "Connected");
        // the roll lands a few seconds into the clip, so the pop out and pop in can be watched
        panel.imps.setLinked(true);
        panel.imps.rollChance = 1f;
        panel.imps.rollT = 18.5f;
        // -Dchexy=true: the visitor is always Chexy
        if (Boolean.getBoolean("chexy")) panel.imps.chexyChance = 1f;
        ApiModels.BoardResponse board = new Gson().fromJson(ThemePreview.BOARD, ApiModels.BoardResponse.class);
        panel.setBoard(board, null, null);
        JFrame frame = new JFrame();
        frame.setUndecorated(true);
        frame.getContentPane().add(panel);
        frame.pack();
        frame.setSize(PluginPanel.PANEL_WIDTH, H);
        frame.validate();
        PanelUi.animations = true;
        for (int i = 0; i < 500; i++) panel.imps.advance(0.033f);
        for (int f = 0; f < FRAMES; f++)
        {
            for (int i = 0; i < 3; i++) panel.imps.advance(0.033f);
            BufferedImage img = new BufferedImage(PluginPanel.PANEL_WIDTH, H, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = img.createGraphics();
            frame.getContentPane().paint(g);
            g.dispose();
            ImageIO.write(img, "png", new File(out, theme.name().toLowerCase() + "-" + String.format("%02d", f) + ".png"));
        }
        PanelUi.animations = false;
        panel.dispose();
        frame.dispose();
    }
}

package com.forgebingo;

import com.forgebingo.core.ApiModels;
import com.google.gson.Gson;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.RepaintManager;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;

/**
 * Draws the side panel once per theme, with its creatures a few seconds into their walk and a few things falling.
 * Not a test; writes build/preview/theme-<name>.png (and theme-all.png, every theme side by side).
 */
public final class ThemePreview
{
    private ThemePreview()
    {
    }

    static final String BOARD = "{'teamBoardId':'b1','teamId':'team1','teamName':'Team 1',"
        + "'event':{'id':'e1','name':'Wear Protection','status':'live','active':true},'board':{'id':'bd','title':'Board','size':3},'tiles':["
        + "{'id':'t0','row':0,'col':0,'title':'Barrows item','points':1,'completionMode':'all','completed':true,'tasks':[{'id':'k0','description':'Any Barrows item','requiredQty':1,'sourceType':'npc','approvedQty':1,'completed':true}]},"
        + "{'id':'t1','row':0,'col':1,'title':'25 Zulrah kills','points':2,'completionMode':'all','completed':false,'tasks':[{'id':'k1','description':'25 kills at Zulrah (team total)','requiredQty':25,'sourceType':'kc','approvedQty':11}]},"
        + "{'id':'t2','row':0,'col':2,'title':'Magic lamp','points':1,'completionMode':'all','completed':false,'tasks':[{'id':'k2','description':'Rub a lamp','requiredQty':1,'sourceType':'manual','approvedQty':0,'pendingQty':1}]},"
        + "{'id':'t3','row':1,'col':0,'title':'Genie','points':1,'completionMode':'all','completed':false,'tasks':[{'id':'k3','description':'Meet the genie','requiredQty':1,'sourceType':'manual','approvedQty':0}]},"
        + "{'id':'t4','row':1,'col':1,'title':'Free space','points':1,'completionMode':'all','completed':true,'tasks':[]},"
        + "{'id':'t5','row':1,'col':2,'title':'Fighter torso','points':1,'completionMode':'all','completed':false,'tasks':[{'id':'k5','description':'Torso','requiredQty':1,'sourceType':'manual','approvedQty':0}]},"
        + "{'id':'t6','row':2,'col':0,'title':'Any 3 Corp uniques','points':3,'completionMode':'all','completed':false,'tasks':[{'id':'k6','description':'Corp uniques','requiredQty':3,'sourceType':'npc','approvedQty':1}]},"
        + "{'id':'t7','row':2,'col':1,'title':'Mystery','secret':true,'points':1,'completionMode':'all','completed':false,'tasks':[]},"
        + "{'id':'t8','row':2,'col':2,'title':'Vorkath head','points':2,'completionMode':'all','completed':false,'tasks':[{'id':'k8','description':'Vorkath head','requiredQty':1,'sourceType':'npc','approvedQty':0}]}"
        + "]}";

    private static final int H = 860;
    private static final int SCALE = 2;

    public static void main(String[] args) throws Exception
    {
        File out = new File(args.length > 0 ? args[0] : "build/preview");
        out.mkdirs();
        try
        {
            net.runelite.client.ui.laf.RuneLiteLAF.setup();
        }
        catch (Throwable t)
        {
            System.out.println("RuneLite look and feel not applied: " + t);
        }
        PanelTheme[] themes = PanelTheme.values();
        BufferedImage[] shots = new BufferedImage[themes.length];
        for (int i = 0; i < themes.length; i++)
        {
            int n = i;
            SwingUtilities.invokeAndWait(() -> {
                try
                {
                    shots[n] = render(themes[n]);
                    ImageIO.write(shots[n], "png", new File(out, "theme-" + themes[n].name().toLowerCase() + ".png"));
                }
                catch (Exception e)
                {
                    throw new RuntimeException(e);
                }
            });
        }
        // every theme side by side, at half size
        int w = PluginPanel.PANEL_WIDTH;
        BufferedImage all = new BufferedImage((w + 8) * themes.length, H, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = all.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        for (int i = 0; i < themes.length; i++) g.drawImage(shots[i], i * (w + 8), 0, w, H, null);
        g.dispose();
        ImageIO.write(all, "png", new File(out, "theme-all.png"));
        System.out.println("Wrote theme previews to " + out.getAbsolutePath());
        System.exit(0);
    }

    private static BufferedImage render(PanelTheme theme)
    {
        RepaintManager.currentManager(null).setDoubleBufferingEnabled(false);
        PanelUi.animations = false;
        ForgeBingoPanel.usePixelFonts(false);
        ForgeBingoPanel.useTheme(theme);
        ForgeBingoPanel panel = new ForgeBingoPanel(new PanelPreview.Fake(), null);
        panel.setStatus(true, "Connected");
        // the rare bosses are turned up here so the picture shows them; in the plugin they are 1 in 100
        panel.imps.setLinked(true);
        panel.imps.rollChance = 1f;
        panel.imps.rollT = 24f;
        ApiModels.BoardResponse board = new Gson().fromJson(BOARD, ApiModels.BoardResponse.class);
        panel.setBoard(board, null, null);
        panel.setActivity("Counted: 25 Zulrah kills (just now)", java.util.Arrays.asList("25 Zulrah kills - just now, picture sent", "Vorkath head - 4m ago, picture sent"));
        panel.showTile(board.tiles.get(1));
        JFrame frame = new JFrame();
        frame.setUndecorated(true);
        frame.getContentPane().add(panel);
        frame.pack();
        frame.setSize(PluginPanel.PANEL_WIDTH, H);
        frame.validate();
        // let the creatures drop in and wander, and a few things fall
        PanelUi.animations = true; // the sand and the volcanoes only run with animations on
        for (int i = 0; i < 900; i++) panel.imps.advance(0.033f);
        PanelUi.animations = false;
        BufferedImage img = new BufferedImage(PluginPanel.PANEL_WIDTH * SCALE, H * SCALE, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.scale(SCALE, SCALE);
        PanelUi.animations = true;
        frame.getContentPane().paint(g);
        PanelUi.animations = false;
        g.dispose();
        // what a frame costs: one step of the world plus one repaint at real size, averaged
        PanelUi.animations = true;
        BufferedImage one = new BufferedImage(PluginPanel.PANEL_WIDTH, H, BufferedImage.TYPE_INT_RGB);
        long t0 = System.nanoTime();
        int n = 200;
        for (int i = 0; i < n; i++)
        {
            panel.imps.advance(0.033f);
            Graphics2D b = one.createGraphics();
            frame.getContentPane().paint(b);
            b.dispose();
        }
        double ms = (System.nanoTime() - t0) / 1e6 / n;
        PanelUi.animations = false;
        System.out.println(String.format("%-10s %.2f ms per frame (%.1f%% of one core at 30 frames a second)", theme.name(), ms, ms * 30 / 10));
        panel.dispose();
        frame.dispose();
        return img;
    }

    private static BufferedImage unused(ForgeBingoPanel panel, JFrame frame)
    {
        BufferedImage img = new BufferedImage(PluginPanel.PANEL_WIDTH * SCALE, H * SCALE, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.scale(SCALE, SCALE);
        frame.getContentPane().paint(g);
        g.dispose();
        panel.dispose();
        frame.dispose();
        return img;
    }
}

package com.forgebingo;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import org.junit.Test;

/** The "not open yet" card in the side panel: what it says under the bingo and team name. */
public class UpcomingTextTest
{
    private static final long NOW = Instant.parse("2026-11-26T12:00:00Z").toEpochMilli();

    @Test
    public void countsDownToAStartTimeThatIsAhead()
    {
        assertEquals(65, ForgeBingoPanel.secondsUntil("2026-11-26T12:01:05Z", NOW));
        assertEquals("Opens in 1m 05s", ForgeBingoPanel.opensText(65));
        assertEquals("Opens in 2h 13m 05s", ForgeBingoPanel.opensText(2 * 3600 + 13 * 60 + 5));
        assertEquals("Opens in 3d 4h 0m", ForgeBingoPanel.opensText(3 * 86400 + 4 * 3600));
        assertEquals(3600, ForgeBingoPanel.secondsUntil("2026-11-26T14:00:00+01:00", NOW));
    }

    @Test
    public void saysNotOpenYetWhenThereIsNothingToCountDownTo()
    {
        // a start time that has passed while the bingo is still closed (set up, or paused): no endless "opening..."
        assertEquals(0, ForgeBingoPanel.secondsUntil("2026-11-21T08:25:38Z", NOW));
        assertTrue(ForgeBingoPanel.opensText(0).startsWith("Not open yet"));
        // no start time, or one that cannot be read
        assertEquals(-1, ForgeBingoPanel.secondsUntil(null, NOW));
        assertEquals(-1, ForgeBingoPanel.secondsUntil("soon", NOW));
        assertTrue(ForgeBingoPanel.opensText(-1).startsWith("Not open yet"));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.util.Arrays;
import java.util.Map;
import org.junit.Test;

/**
 * Proof that moving the activity-item table into data/activity-items.txt changed nothing: what the plugin loads
 * (ActivityItems) equals the old Java table (ActivityItemsReference) exactly. Also fails when the data file is
 * missing, empty or malformed (the table would then be empty), and checks the parser refuses bad files whole.
 */
public class ActivityItemsDataTest
{
    private static final String FIX = " - data/activity-items.txt and ActivityItemsReference differ; change both together";

    @Test
    public void theLoadedTableIsExactlyTheOldJavaTable()
    {
        Map<Integer, String> ref = ActivityItemsReference.all();
        assertTrue("the reference has rows", ref.size() > 200);
        assertEquals("size()" + FIX, ref.size(), ActivityItems.size());
        // same keys, same values
        assertEquals("parsed file" + FIX, ref, ActivityItems.parse(DataFile.lines("activity-items")));
        // and through the public door, for every id anywhere near the table and well beyond (so no extra ids either)
        int max = 0;
        for (int id : ref.keySet()) max = Math.max(max, id);
        int hits = 0;
        for (int id = -10; id <= max + 10_000; id++)
        {
            String want = ref.get(id);
            assertEquals("item " + id + FIX, want, ActivityItems.activityFor(id));
            if (want != null) hits++;
        }
        assertEquals(ref.size(), hits);
        System.out.println("ActivityItemsDataTest: compared " + ref.size() + " rows, " + (max + 10_011) + " ids probed");
    }

    @Test
    public void aBrokenFileIsRefusedWhole()
    {
        refused("ids before any activity", "123 456");
        refused("not a number", "[Sailing]", "123 abc");
        refused("an id twice", "[Sailing]", "123", "[Pest Control]", "123");
        refused("an id twice in one activity", "[Sailing]", "123 123");
        refused("no activity name", "[]", "123");
        refused("a decimal", "[Sailing]", "12.5");
        assertEquals(2, ActivityItems.parse(Arrays.asList("[Sailing]", "1  2")).size());
        try
        {
            DataFile.lines("no-such-file");
            fail("a missing data file must be an error");
        }
        catch (IllegalStateException expected)
        {
            // good
        }
    }

    private static void refused(String what, String... lines)
    {
        try
        {
            ActivityItems.parse(Arrays.asList(lines));
            fail("a file with " + what + " must be refused");
        }
        catch (RuntimeException expected)
        {
            // good
        }
    }
}

