package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.Random;
import org.junit.Test;

public class BackoffAndErrorTest
{
    @Test
    public void exponentialWithoutJitter()
    {
        assertEquals(5_000, Backoff.delayMillis(1, 0, null));
        assertEquals(10_000, Backoff.delayMillis(2, 0, null));
        assertEquals(20_000, Backoff.delayMillis(3, 0, null));
        assertEquals(Backoff.MAX_MILLIS, Backoff.delayMillis(30, 0, null));
    }

    @Test
    public void jitterStaysWithinTwentyPercent()
    {
        Random r = new Random(1);
        for (int i = 0; i < 200; i++)
        {
            long d = Backoff.delayMillis(3, 0, r);
            assertTrue(d >= 16_000 && d <= 24_000);
        }
    }

    @Test
    public void retryAfterWins()
    {
        assertEquals(60_000, Backoff.delayMillis(1, 60_000, null));
        assertEquals(20_000, Backoff.delayMillis(3, 1_000, null));
        assertEquals(60_000, Backoff.parseRetryAfterMillis(" 60 "));
        assertEquals(0, Backoff.parseRetryAfterMillis("Wed, 21 Oct 2026 07:28:00 GMT"));
        assertEquals(0, Backoff.parseRetryAfterMillis(null));
    }

    @Test
    public void classification()
    {
        assertEquals(ErrorClass.SUCCESS, ErrorClass.of(200));
        assertEquals(ErrorClass.SUCCESS, ErrorClass.of(201));
        // transient: network, 429 (Retry-After), 5xx
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(0));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(429, "rate_limited"));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(500, "internal_error"));
        assertEquals(ErrorClass.TRANSIENT, ErrorClass.of(503));
        // auth: only 401 invalid_api_key pauses the queue
        assertEquals(ErrorClass.AUTH, ErrorClass.of(401, "invalid_api_key"));
        // permanent: every documented 400 code, 403 not_a_member, 404, 413, 415
        for (String code : new String[] {"invalid_payload", "invalid_items", "invalid_rsn", "invalid_account_hash",
            "unsupported_source_type", "occurred_at_out_of_range", "invalid_json"})
        {
            assertEquals(code, ErrorClass.PERMANENT, ErrorClass.of(400, code));
        }
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(403, "not_a_member"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(404, "not_found"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(413, "payload_too_large"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(415, "unsupported_media_type"));
        // 409 event_id_conflict: regenerate the id
        assertEquals(ErrorClass.CONFLICT, ErrorClass.of(409, "event_id_conflict"));
        assertEquals(ErrorClass.PERMANENT, ErrorClass.of(409, "something_else"));
    }

    @Test
    public void iconPathGuard()
    {
        assertTrue(IconRef.isProxyPath("/v1/icons/items/4151.png"));
        assertTrue(IconRef.isProxyPath("/v1/icons/tiles/00000000-0000-4000-b000-000000000001"));
        assertFalse(IconRef.isProxyPath("/v1/icons/items/4151.png?x=1"));
        assertFalse(IconRef.isProxyPath("/v1/icons/items/abc.png"));
        assertFalse(IconRef.isProxyPath("/v1/icons/item/4151.png"));
        assertFalse(IconRef.isProxyPath("https://evil.example/x.png"));
        assertFalse(IconRef.isProxyPath("/v1/icons/../me"));
        assertFalse(IconRef.isProxyPath("//evil.example/v1/icons/x"));
        assertFalse(IconRef.isProxyPath("/v1/me"));
        assertFalse(IconRef.isProxyPath(null));
    }

    @Test
    public void baseUrlValidation()
    {
        assertNotNull(ApiClient.parseBaseUrl("https://api.example.com/plugin-api"));
        assertNotNull(ApiClient.parseBaseUrl("http://localhost:54321/functions/v1/plugin-api"));
        assertNull(ApiClient.parseBaseUrl("http://example.com/"));
        assertNull(ApiClient.parseBaseUrl("ftp://example.com/"));
        assertNull(ApiClient.parseBaseUrl("not a url"));
        assertTrue(ApiClient.isPlaceholder("https://YOUR-PROJECT-REF.supabase.co/functions/v1/plugin-api"));
        assertFalse(ApiClient.isPlaceholder("https://abcdefgh.supabase.co/functions/v1/plugin-api"));
        assertNull(ApiClient.parseBaseUrl(null));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class BoardCelebrationsTest
{
    /** A size x size board; tile ids are "r,c"; the given ids are finished. */
    private static ApiModels.BoardResponse board(int size, String... done)
    {
        Set<String> finished = new HashSet<>(Arrays.asList(done));
        ApiModels.BoardResponse b = new ApiModels.BoardResponse();
        b.board = new ApiModels.BoardInfo();
        b.board.size = size;
        b.tiles = new ArrayList<>();
        for (int r = 0; r < size; r++)
        {
            for (int c = 0; c < size; c++)
            {
                ApiModels.Tile t = new ApiModels.Tile();
                t.id = r + "," + c;
                t.row = r;
                t.col = c;
                t.title = "Tile " + t.id;
                t.completed = finished.contains(t.id);
                b.tiles.add(t);
            }
        }
        return b;
    }

    private static Set<String> set(String... ids)
    {
        return new HashSet<>(Arrays.asList(ids));
    }

    @Test
    public void countsRowsColumnsAndBothDiagonals()
    {
        ApiModels.BoardResponse b = board(3);
        assertEquals(0, BoardCelebrations.countLines(set(), b, 3));
        assertEquals(1, BoardCelebrations.countLines(set("0,0", "0,1", "0,2"), b, 3));           // a row
        assertEquals(1, BoardCelebrations.countLines(set("0,1", "1,1", "2,1"), b, 3));           // a column
        assertEquals(1, BoardCelebrations.countLines(set("0,0", "1,1", "2,2"), b, 3));           // diagonal
        assertEquals(1, BoardCelebrations.countLines(set("0,2", "1,1", "2,0"), b, 3));           // the other diagonal
        assertEquals(2, BoardCelebrations.countLines(set("0,0", "0,1", "0,2", "1,0", "2,0"), b, 3)); // row + column
        Set<String> all = new HashSet<>();
        for (ApiModels.Tile t : b.tiles) all.add(t.id);
        assertEquals(8, BoardCelebrations.countLines(all, b, 3));
        // ids that are not on the board change nothing
        assertEquals(0, BoardCelebrations.countLines(set("9,9", "nope"), b, 3));
    }

    @Test
    public void theFirstLookOnlyRecords()
    {
        BoardCelebrations.Change c = BoardCelebrations.changes(null, board(3, "0,0", "0,1", "0,2"));
        assertTrue(c.firstLook);
        assertEquals(set("0,0", "0,1", "0,2"), c.done);
        assertTrue(c.finishedTitles.isEmpty());
        assertEquals(0, c.newLines);
        assertNull(c.lineText());
        assertFalse(c.all);
    }

    @Test
    public void aFinishedBoardIsABlackoutEvenOnTheFirstLook()
    {
        ApiModels.BoardResponse full = board(2, "0,0", "0,1", "1,0", "1,1");
        assertTrue(BoardCelebrations.changes(null, full).all);
        assertTrue(BoardCelebrations.changes(set("0,0"), full).all);
        // a board with no tiles is never a blackout
        ApiModels.BoardResponse empty = board(1);
        empty.tiles.clear();
        assertFalse(BoardCelebrations.changes(null, empty).all);
    }

    @Test
    public void aTeammatesNewTileIsAnnouncedOnce()
    {
        Set<String> seen = set("0,0");
        ApiModels.BoardResponse b = board(3, "0,0", "1,1");
        BoardCelebrations.Change c = BoardCelebrations.changes(seen, b);
        assertFalse(c.firstLook);
        assertEquals(Collections.singletonList("Tile 1,1"), c.finishedTitles);
        assertEquals(0, c.newLines);
        // the seen set is the caller's to update
        assertEquals(set("0,0"), seen);
        seen.addAll(c.done);
        assertTrue(BoardCelebrations.changes(seen, b).finishedTitles.isEmpty());
    }

    @Test
    public void thePlayersOwnTileMarkedSeenFirstIsNotAnnouncedAgain()
    {
        // the player's own drop finished 0,1 and it was marked seen on this board as the server answered: the
        // refresh that follows must not announce it as a teammate's (the auto-selected board bug)
        Set<String> seen = set("0,0", "0,1");
        BoardCelebrations.Change c = BoardCelebrations.changes(seen, board(3, "0,0", "0,1"));
        assertTrue(c.finishedTitles.isEmpty());
        assertEquals(0, c.newLines);
    }

    @Test
    public void aNewLineAndADoubleLine()
    {
        BoardCelebrations.Change one = BoardCelebrations.changes(set("0,0", "0,1"), board(3, "0,0", "0,1", "0,2"));
        assertEquals(1, one.newLines);
        assertEquals("Line complete!", one.lineText());
        // the corner finishes a row and a column at once
        BoardCelebrations.Change two = BoardCelebrations.changes(set("0,1", "0,2", "1,0", "2,0"), board(3, "0,0", "0,1", "0,2", "1,0", "2,0"));
        assertEquals(2, two.newLines);
        assertEquals("Double line complete!", two.lineText());
    }

    @Test
    public void aSecretTileIsAnnouncedByItsShownName()
    {
        ApiModels.BoardResponse b = board(2, "0,0");
        b.tiles.get(0).title = "?";
        b.tiles.get(0).secret = true;
        b.tiles.get(0).completed = true;
        // a finished secret tile shows the title the server sends for it
        assertEquals(Collections.singletonList("?"), BoardCelebrations.changes(set(), b).finishedTitles);
    }

    @Test
    public void tilesWithoutAnIdAreIgnored()
    {
        ApiModels.BoardResponse b = board(2, "0,0");
        b.tiles.get(1).id = null;
        b.tiles.get(1).completed = true;
        BoardCelebrations.Change c = BoardCelebrations.changes(set(), b);
        assertEquals(set("0,0"), c.done);
        assertEquals(1, c.finishedTitles.size());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Rectangle;
import org.junit.Test;

public class BoardLayoutTest
{
    private static void assertInside(Rectangle outer, Rectangle inner)
    {
        assertTrue(inner + " inside " + outer, outer.contains(inner));
    }

    @Test
    public void tenByTenFitsFixedModeWithMinimumCells()
    {
        BoardLayout l = BoardLayout.compute(765, 503, 10);
        assertTrue(l.cell >= BoardLayout.MIN_CELL);
        Rectangle view = new Rectangle(0, 0, 765, 503);
        assertInside(view, l.board());
        assertInside(l.board(), l.grid());
        assertInside(view, l.card());
        assertTrue(l.board().height <= 503 * BoardLayout.MAX_FRACTION + 1);
    }

    @Test
    public void boardIsCentredAndCapped()
    {
        for (int n = 3; n <= 10; n++)
        {
            BoardLayout l = BoardLayout.compute(1920, 1080, n);
            Rectangle b = l.board();
            assertTrue(b.height <= 1080 * BoardLayout.MAX_FRACTION + 1);
            assertTrue(Math.abs((b.x + b.width / 2) - 960) <= 1);
            assertTrue(Math.abs((b.y + b.height / 2) - 540) <= 1);
            assertEquals(l.grid().width, l.grid().height);
            // last cell sits flush with the grid's bottom-right corner
            Rectangle last = l.cell(n - 1, n - 1);
            Rectangle g = l.grid();
            assertEquals(g.x + g.width, last.x + last.width);
            assertEquals(g.y + g.height, last.y + last.height);
            // gaps grow with the board but stay small next to the cells
            assertTrue(l.gap >= BoardLayout.GAP);
            assertTrue(l.gap * 8 <= l.cell);
        }
    }

    @Test
    public void fixedClientIsScaleOneAndBigWindowsScaleUp()
    {
        BoardLayout fixed = BoardLayout.compute(765, 503, 5);
        assertEquals(1.0, fixed.scale, 1e-9);
        assertEquals(BoardLayout.PAD, fixed.pad);
        assertEquals(BoardLayout.HEADER, fixed.header);
        assertEquals(BoardLayout.CLOSE, fixed.close);
        assertEquals(BoardLayout.GAP, fixed.gap);
        // a small viewport never goes under the fixed-client sizes
        assertEquals(1.0, BoardLayout.compute(320, 240, 5).scale, 1e-9);

        double prev = 1;
        for (int[] view : new int[][] {{1280, 720}, {1920, 1080}, {2560, 1440}, {3840, 2160}, {9000, 9000}})
        {
            BoardLayout l = BoardLayout.compute(view[0], view[1], 5);
            assertTrue(l.scale >= prev);
            assertTrue(l.scale <= BoardLayout.MAX_SCALE);
            prev = l.scale;
            Rectangle b = l.board();
            assertInside(new Rectangle(0, 0, view[0], view[1]), b);
            assertTrue(b.height <= view[1] * BoardLayout.MAX_FRACTION + 1);
            // the header, padding and close button keep their share of the board
            assertEquals(BoardLayout.HEADER * l.scale, l.header, 0.51);
            assertEquals(BoardLayout.PAD * l.scale, l.pad, 0.51);
            Rectangle close = l.closeButton();
            assertEquals(l.close, close.width);
            assertInside(b, close);
            assertTrue(close.y + close.height <= l.grid().y);
            // the grid starts under the header and is padded on every side
            Rectangle g = l.grid();
            assertEquals(b.x + l.pad, g.x);
            assertEquals(b.y + l.pad + l.header, g.y);
            assertEquals(b.x + b.width - l.pad, g.x + g.width);
            assertEquals(b.y + b.height - l.pad, g.y + g.height);
        }
        assertTrue(BoardLayout.compute(1920, 1080, 5).scale > 2);
        // many tiles on a big screen: the cells still reach the minimum
        assertTrue(BoardLayout.compute(1920, 1080, 20).cell >= BoardLayout.MIN_CELL);
    }

    @Test
    public void tinyViewportStillFits()
    {
        BoardLayout l = BoardLayout.compute(200, 160, 10);
        Rectangle view = new Rectangle(0, 0, 200, 160);
        assertInside(view, l.board());
        assertInside(view, l.card());
        assertTrue(l.cell >= 2);
        BoardLayout z = BoardLayout.compute(0, 0, 10);
        assertTrue(z.cell >= 2);
    }

    @Test
    public void smallViewportGrowsCellsToMinimumWhenThereIsRoom()
    {
        // 80% of 420 leaves cells under 28, but the whole viewport fits 28px cells
        BoardLayout l = BoardLayout.compute(640, 420, 10);
        assertEquals(BoardLayout.MIN_CELL, l.cell);
        assertInside(new Rectangle(0, 0, 640, 420), l.board());
    }

    @Test
    public void cellAtHitsCellsAndMissesGaps()
    {
        BoardLayout l = BoardLayout.compute(1280, 900, 5);
        for (int r = 0; r < 5; r++)
        {
            for (int c = 0; c < 5; c++)
            {
                Rectangle cell = l.cell(r, c);
                assertEquals(r * 5 + c, l.cellAt(cell.x, cell.y));
                assertEquals(r * 5 + c, l.cellAt(cell.x + cell.width - 1, cell.y + cell.height - 1));
                assertEquals(r * 5 + c, l.cellAt((int) cell.getCenterX(), (int) cell.getCenterY()));
            }
        }
        Rectangle first = l.cell(0, 0);
        assertEquals(-1, l.cellAt(first.x + first.width, first.y)); // the gap after the first cell
        assertEquals(-1, l.cellAt(first.x - 1, first.y));
        Rectangle g = l.grid();
        assertEquals(-1, l.cellAt(g.x + g.width, g.y));
        assertEquals(-1, l.cellAt(g.x, g.y + g.height));
    }

    @Test
    public void insideBoardCloseButtonAndCard()
    {
        BoardLayout l = BoardLayout.compute(1280, 900, 4);
        Rectangle b = l.board();
        assertTrue(l.insideBoard(b.x, b.y));
        assertTrue(l.insideBoard(b.x + b.width - 1, b.y + b.height - 1));
        assertFalse(l.insideBoard(b.x - 1, b.y));
        assertFalse(l.insideBoard(b.x + b.width, b.y));
        assertFalse(l.insideBoard(5, 5));
        Rectangle close = l.closeButton();
        assertInside(b, close);
        assertTrue(l.onCloseButton((int) close.getCenterX(), (int) close.getCenterY()));
        assertEquals(-1, l.cellAt((int) close.getCenterX(), (int) close.getCenterY()));
        Rectangle card = l.card();
        assertTrue(l.insideCard((int) card.getCenterX(), (int) card.getCenterY()));
        assertFalse(l.insideCard(card.x - 1, card.y));
        // card is about 60% of the board's width and centred on it
        assertTrue(Math.abs(card.width - b.width * 0.6) <= 1);
        assertTrue(Math.abs(card.getCenterX() - b.getCenterX()) <= 1);
    }

    @Test
    public void cardHasAReadableMinimumOnSmallBoards()
    {
        BoardLayout l = BoardLayout.compute(765, 503, 10);
        assertTrue(l.card().width >= 260);
        assertTrue(l.card().height >= 220);
    }

    @Test
    public void messageBoxIsCentred()
    {
        Rectangle m = BoardLayout.message(765, 503);
        assertInside(new Rectangle(0, 0, 765, 503), m);
        assertTrue(Math.abs(m.getCenterX() - 382.5) <= 1);
    }

    @Test
    public void easeOutIsClampedAndMonotonic()
    {
        assertEquals(0.0, BoardLayout.easeOut(-1), 1e-9);
        assertEquals(0.0, BoardLayout.easeOut(0), 1e-9);
        assertEquals(1.0, BoardLayout.easeOut(1), 1e-9);
        assertEquals(1.0, BoardLayout.easeOut(3), 1e-9);
        assertTrue(BoardLayout.easeOut(0.5) > 0.5); // ease-out is ahead of linear
        double prev = 0;
        for (int i = 1; i <= 20; i++)
        {
            double v = BoardLayout.easeOut(i / 20.0);
            assertTrue(v >= prev);
            prev = v;
        }
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import org.junit.Test;

public class BoardSelectionTest
{
    private static ApiModels.BoardSummary board(String id, boolean active)
    {
        ApiModels.BoardSummary b = new ApiModels.BoardSummary();
        b.teamBoardId = id;
        b.active = active;
        b.eventId = "event-" + id;
        return b;
    }

    @Test
    public void thePickedBoardIsShownEvenWhenItIsNotLive()
    {
        List<ApiModels.BoardSummary> boards = Arrays.asList(board("a", true), board("b", false));
        assertEquals("b", BoardSelection.select(boards, "b").teamBoardId);
    }

    @Test
    public void withNoPickTheFirstLiveBoardIsShown()
    {
        // the player never chose a board: the saved choice is empty, and the first live board shows anyway
        List<ApiModels.BoardSummary> boards = Arrays.asList(board("old", false), board("live1", true), board("live2", true));
        assertEquals("live1", BoardSelection.select(boards, "").teamBoardId);
        assertEquals("live1", BoardSelection.select(boards, null).teamBoardId);
        // a saved choice that is gone (team deleted, another key) falls back the same way
        assertEquals("live1", BoardSelection.select(boards, "gone").teamBoardId);
    }

    @Test
    public void withNothingLiveTheFirstBoardIsShown()
    {
        List<ApiModels.BoardSummary> boards = Arrays.asList(board("x", false), board("y", false));
        assertEquals("x", BoardSelection.select(boards, "").teamBoardId);
        assertNull(BoardSelection.select(Collections.emptyList(), "x"));
        assertNull(BoardSelection.select(null, "x"));
    }

    @Test
    public void countsLiveBoardsAndListsIds()
    {
        List<ApiModels.BoardSummary> boards = Arrays.asList(board("a", true), board("b", false), board("c", true));
        assertEquals(2, BoardSelection.liveCount(boards));
        assertEquals(new HashSet<>(Arrays.asList("a", "b", "c")), BoardSelection.ids(boards));
        assertEquals(0, BoardSelection.liveCount(Collections.emptyList()));
        assertTrue(BoardSelection.ids(null).isEmpty());
    }

    @Test
    public void aBoardIsNewlyOpenedOnlyWhenItWasNotKnownBefore()
    {
        ApiModels.BoardSummary a = board("a", true);
        ApiModels.BoardSummary b = board("b", true);
        List<ApiModels.BoardSummary> boards = Arrays.asList(a, b);
        // the first list of a session (or after another key was pasted): nothing is "new"
        assertNull(BoardSelection.newlyOpened(boards, null));
        // both known already
        assertNull(BoardSelection.newlyOpened(boards, new HashSet<>(Arrays.asList("a", "b"))));
        // b appeared while running: its bingo just started
        assertSame(b, BoardSelection.newlyOpened(boards, new HashSet<>(Collections.singletonList("a"))));
        // two appear at once: the first in list order
        assertSame(a, BoardSelection.newlyOpened(boards, new HashSet<>()));
    }

    @Test
    public void aNewBoardThatIsNotLiveIsNotAnOpening()
    {
        List<ApiModels.BoardSummary> boards = Arrays.asList(board("a", true), board("finished", false));
        assertNull(BoardSelection.newlyOpened(boards, new HashSet<>(Collections.singletonList("a"))));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

