    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class ChestOpensTest
{
    private static Map<Integer, Integer> of(int... pairs)
    {
        Map<Integer, Integer> m = new LinkedHashMap<>();
        for (int i = 0; i < pairs.length; i += 2) m.put(pairs[i], pairs[i + 1]);
        return m;
    }

    @Test
    public void bothChestsReportWhenEachShowsItsOwnLoot()
    {
        ChestOpens c = new ChestOpens();
        assertEquals(of(560, 300, 1513, 80), c.opened(of(560, 300, 1513, 80))); // standard chest
        assertEquals(of(34719, 1), c.opened(of(34719, 1)));                     // unique chest
    }

    @Test
    public void secondChestReportsOnlyTheNewItemsWhenLootIsAddedTogether()
    {
        ChestOpens c = new ChestOpens();
        assertEquals(of(560, 300), c.opened(of(560, 300)));
        assertEquals(of(34719, 1), c.opened(of(560, 300, 34719, 1)));
    }

    @Test
    public void openingTheSameChestAgainReportsNothing()
    {
        ChestOpens c = new ChestOpens();
        c.opened(of(34719, 1));
        assertTrue(c.opened(of(34719, 1)).isEmpty());
    }

    @Test
    public void theNextRaidStartsFresh()
    {
        ChestOpens c = new ChestOpens();
        c.opened(of(34719, 1));
        c.reset();
        assertEquals(of(34719, 1), c.opened(of(34719, 1)));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class ChexySpellsTest
{
    @Test
    public void spellsFitTheVisitAndKeepClearOfTheCharges()
    {
        // a spell visit: flowers, the barrier once they have faded, one volley, then a second bloom, all over before
        // the shortest visit ends (60 s)
        float flowersGone = ChexySpells.FLOWER_AT + ChexySpells.FLOWER_SPAWN + ChexySpells.FLOWER_LIFE;
        assertTrue(flowersGone < ChexySpells.BARRIER_AT);
        assertTrue(ChexySpells.BARRIER_AT + ChexySpells.BARRIER_TIME < ChexySpells.VOLLEYS[0]);
        assertEquals(1, ChexySpells.VOLLEYS.length);
        assertTrue(ChexySpells.VOLLEYS[0] + ChexySpells.VOLLEY_TIME < ChexySpells.FLOWER_AGAIN);
        assertTrue(ChexySpells.FLOWER_AGAIN + ChexySpells.FLOWER_SPAWN + ChexySpells.FLOWER_LIFE < 60f);
        // it stands still to fire
        assertEquals(0f, ChexySpells.flySpeed(ChexySpells.VOLLEYS[0] + 1f), 0f);
        assertEquals(1f, ChexySpells.flySpeed(40f), 0f);
    }

    @Test
    public void aVisitIsThePowerUpOrTheSpellsNeverBoth()
    {
        for (boolean spellVisit : new boolean[] {false, true})
        {
            boolean powered = false, cast = false;
            for (float age = 0f; age < 95f; age += 0.05f)
            {
                float power = Chexy.powerAge(spellVisit, age);
                float spell = ChexySpells.spellAge(spellVisit, age);
                boolean powering = Chexy.form(power) != Chexy.BASE || Chexy.charge(power) > 0 || Chexy.spin(power) != 1f;
                boolean casting = ChexySpells.flowerPhase(spell) >= 0 || ChexySpells.barrierPhase(spell) >= 0
                    || ChexySpells.volleyPhase(spell) >= 0;
                assertTrue("both at once at " + age, !(powering && casting));
                powered |= powering;
                cast |= casting;
            }
            // a spell visit casts and never powers up; a power-up visit powers up and never casts
            assertEquals(!spellVisit, powered);
            assertEquals(spellVisit, cast);
        }
        // a power-up visit reaches its blue form well inside the shortest visit
        assertEquals(Chexy.BLUE, Chexy.form(Chexy.powerAge(false, 45f)));
    }

    @Test
    public void everySpellDrawsThroughItsWholeLength()
    {
        Rectangle box = new Rectangle(0, 0, 160, 120);
        float[] kick = new float[2];
        for (boolean calm : new boolean[] {false, true})
        {
            for (float p = 0f; p < ChexySpells.VOLLEY_TIME; p += 0.13f)
            {
                BufferedImage img = new BufferedImage(160, 120, BufferedImage.TYPE_INT_ARGB);
                Graphics2D g = img.createGraphics();
                ChexySpells.paintVolley(g, 40, 60, 1, p, p * 1.3f, Chexy.GOLD, calm, box);
                ChexySpells.paintVolley(g, 120, 60, -1, p, p * 1.3f, Chexy.BLUE, calm, box);
                ChexySpells.recoil(p, 1, calm, kick);
                assertTrue(Math.abs(kick[0]) < 5 && Math.abs(kick[1]) < 5);
                g.dispose();
            }
            for (float p = 0f; p < ChexySpells.BARRIER_TIME; p += 0.13f)
            {
                BufferedImage img = new BufferedImage(120, 120, BufferedImage.TYPE_INT_ARGB);
                Graphics2D g = img.createGraphics();
                ChexySpells.paintBarrier(g, 60, 60, 25, p, p, Chexy.GOLD, calm);
                g.dispose();
            }
            BufferedImage img = new BufferedImage(120, 80, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = img.createGraphics();
            for (float s = -0.5f; s < ChexySpells.FLOWER_LIFE + 0.5f; s += 0.1f)
            {
                for (int kind = 0; kind < ChexySpells.FLOWER_KINDS; kind++)
                {
                    ChexySpells.paintFlower(g, 20 + kind * 20, 60, kind, s, ChexySpells.FLOWER_LIFE, s);
                    ChexySpells.paintPetals(g, 20 + kind * 20, 60, kind, s, kind, calm);
                }
                ChexySpells.paintWave(g, 60, 60, s, calm);
            }
            g.dispose();
        }
    }

    @Test
    public void aFlowerShowsOnceGrownAndIsGoneAfterItsLife()
    {
        BufferedImage img = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        ChexySpells.paintFlower(g, 10, 18, 0, 2f, ChexySpells.FLOWER_LIFE, 0f);
        g.dispose();
        assertTrue(lit(img) > 10);
        BufferedImage gone = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
        g = gone.createGraphics();
        ChexySpells.paintFlower(g, 10, 18, 0, ChexySpells.FLOWER_LIFE + 0.1f, ChexySpells.FLOWER_LIFE, 0f);
        g.dispose();
        assertEquals(0, lit(gone));
    }

    private static int lit(BufferedImage img)
    {
        int n = 0;
        for (int y = 0; y < img.getHeight(); y++)
        {
            for (int x = 0; x < img.getWidth(); x++) if ((img.getRGB(x, y) >>> 24) > 40) n++;
        }
        return n;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class ChexyTest
{
    @Test
    public void drawsAtSeveralSizesAndTimes()
    {
        float[] sizes = {8f, Chexy.SIZE, 60f};
        float[] times = {0f, 0.37f, 5f, 123.4f, 9999f};
        for (float size : sizes)
        {
            for (float t : times)
            {
                for (boolean calm : new boolean[] {false, true})
                {
                    BufferedImage img = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g = img.createGraphics();
                    Chexy.paint(g, 48, 48, t, size, calm);
                    g.dispose();
                    assertTrue("nothing drawn at size " + size + " t " + t, lit(img) > 20);
                }
            }
        }
    }

    @Test
    public void drawsEveryStageOfThePowerUp()
    {
        float[] ages = {-1f, 0f, 3f, Chexy.CHARGE_AT + 0.9f, Chexy.GOLD_AT - 0.05f, Chexy.GOLD_AT + 0.1f, 20f,
            Chexy.CHARGE2_AT + 1f, Chexy.BLUE_AT + 0.2f, 60f, 95f};
        for (float size : new float[] {8f, Chexy.SIZE, 60f})
        {
            for (float age : ages)
            {
                for (boolean calm : new boolean[] {false, true})
                {
                    BufferedImage img = new BufferedImage(128, 128, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g = img.createGraphics();
                    Chexy.paint(g, 64, 70, 7.3f + age, 7.3f + age, size, calm, age);
                    g.dispose();
                    assertTrue("nothing drawn at age " + age, lit(img) > 20);
                }
            }
        }
    }

    @Test
    public void powersUpBaseThenGoldThenBlue()
    {
        assertEquals(Chexy.BASE, Chexy.form(-1f));
        assertEquals(Chexy.BASE, Chexy.form(3f));
        assertEquals(Chexy.GOLD, Chexy.form(Chexy.GOLD_AT + 1f));
        assertEquals(Chexy.BLUE, Chexy.form(Chexy.BLUE_AT + 1f));
        // the blue form arrives well inside the shortest visit (60 s)
        assertTrue(Chexy.BLUE_AT < 45f);
        // it charges before each change, and its rings spin up while it does
        assertTrue(Chexy.charge(Chexy.GOLD_AT - 0.5f) > 0.5f);
        assertTrue(Chexy.charge(Chexy.BLUE_AT - 0.5f) > 0.5f);
        assertEquals(0f, Chexy.charge(20f), 0f);
        assertTrue(Chexy.spin(Chexy.GOLD_AT - 0.1f) > Chexy.spin(3f) * 2);
    }

    @Test
    public void stillFitsTheCreatureGrid()
    {
        BufferedImage img = Chexy.still();
        assertEquals(PixelArt.WIDTH, img.getWidth());
        assertEquals(PixelArt.HEIGHT, img.getHeight());
        assertTrue(lit(img) > 50);
    }

    private static int lit(BufferedImage img)
    {
        int n = 0;
        for (int y = 0; y < img.getHeight(); y++)
        {
            for (int x = 0; x < img.getWidth(); x++) if ((img.getRGB(x, y) >>> 24) > 40) n++;
        }
        return n;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import org.junit.Test;

/**
 * Owner, 2026-11-14: every clue tier counts the moment the casket is opened, and every raid / Barrows / Moons chest
 * counts with its kill-count message. The game's own chat lines go through the parsers and the result must be a name
 * the server knows (its npc_sources aliases, copied here from the live table on 2026-11-14; the server compares
 * lower-cased names against aliases, label and key).
 */
public class ClueAndChestCoverageTest
{
    private static final Map<String, List<String>> SERVER = new HashMap<>();
    static
    {
        for (String t : new String[] {"beginner", "easy", "medium", "hard", "elite", "master"})
        {
            SERVER.put("clue_" + t, Arrays.asList(t, "clue scroll (" + t + ")", "reward casket (" + t + ")"));
        }
        SERVER.put("barrows", Arrays.asList("barrows", "barrows chests"));
        SERVER.put("lunar_chest", Arrays.asList("lunar chest", "moons of peril"));
        SERVER.put("chambers_of_xeric", Arrays.asList("chambers of xeric", "chambers of xeric challenge mode", "cox", "cox cm"));
        SERVER.put("theatre_of_blood", Arrays.asList("theatre of blood", "theatre of blood: entry mode", "theatre of blood: hard mode", "tob"));
        SERVER.put("tombs_of_amascut", Arrays.asList("toa", "tombs of amascut", "tombs of amascut: entry mode", "tombs of amascut: expert mode"));
    }

    private static String resolve(String name)
    {
        String n = name.trim().toLowerCase(Locale.ROOT);
        for (Map.Entry<String, List<String>> e : SERVER.entrySet())
        {
            if (e.getValue().contains(n) || e.getKey().equals(n)) return e.getKey();
        }
        return null;
    }

    @Test
    public void everyClueTierCountsWhenTheCasketIsOpened()
    {
        for (String t : new String[] {"beginner", "easy", "medium", "hard", "elite", "master"})
        {
            // the line the game posts as the reward casket opens (first trail is singular), with and without colour tags
            for (String msg : new String[] {
                "You have completed 1 " + t + " Treasure Trail.",
                "You have completed <col=ef1020>1,234</col> " + t + " Treasure Trails."})
            {
                ChatParsers.Clue c = ChatParsers.clueCompletion(msg).orElseThrow(() -> new AssertionError("not read: " + msg));
                assertEquals(msg, "clue_" + t, resolve(c.sourceName()));
            }
            // the Loot Tracker's casket loot (the items) goes to the same clue tier
            String loot = "Clue Scroll (" + Character.toUpperCase(t.charAt(0)) + t.substring(1) + ")";
            assertEquals(GameEvent.CLUE, SourceClassifier.forEventLoot(loot));
            assertEquals(loot, "clue_" + t, resolve(SourceClassifier.clueTier(loot)));
        }
    }

    @Test
    public void raidBarrowsAndMoonsChestsCount()
    {
        String[][] cases = {
            {"Your Barrows chest count is: <col=ff0000>12</col>.", "barrows"},
            {"Your Lunar Chest count is: <col=ff0000>7</col>.", "lunar_chest"},
            {"Your completed Chambers of Xeric count is: <col=ff0000>5</col>.", "chambers_of_xeric"},
            {"Your completed Chambers of Xeric Challenge Mode count is: 2.", "chambers_of_xeric"},
            {"Your completed Theatre of Blood count is: 9.", "theatre_of_blood"},
            {"Your completed Theatre of Blood: Entry Mode count is: 1.", "theatre_of_blood"},
            {"Your completed Theatre of Blood: Hard Mode count is: 3.", "theatre_of_blood"},
            {"Your completed Tombs of Amascut count is: 4.", "tombs_of_amascut"},
            {"Your completed Tombs of Amascut: Entry Mode count is: 4.", "tombs_of_amascut"},
            {"Your completed Tombs of Amascut: Expert Mode count is: 6.", "tombs_of_amascut"},
        };
        for (String[] c : cases)
        {
            ChatParsers.Kc k = ChatParsers.killCount(c[0]).orElseThrow(() -> new AssertionError("not read: " + c[0]));
            assertEquals(c[0] + " -> " + k.boss, c[1], resolve(k.boss));
        }
        // the chests' loot itself is reported as chest loot (with the two loot-window pictures)
        for (String chest : new String[] {"Barrows", "Lunar Chest", "Chambers of Xeric", "Theatre of Blood", "Tombs of Amascut"})
        {
            assertTrue(chest, !GameEvent.CLUE.equals(SourceClassifier.forEventLoot(chest)));
        }
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/** POST /v1/hello, RSN verification wording, revoked keys (docs/API.md section 8). */
public class ConnectionStatusTest
{
    private final Gson gson = new Gson();
    private MockWebServer server;
    private ApiClient client;

    @Before
    public void start() throws IOException
    {
        server = new MockWebServer();
        server.start();
        String base = server.url("/plugin-api").toString();
        client = new ApiClient(new OkHttpClient(), gson, () -> base, () -> "fb2_test_key", "2.0.0-test");
    }

    @After
    public void stop() throws IOException
    {
        server.shutdown();
    }

    private static ApiModels.Membership m(String status, String joined, String plugin)
    {
        ApiModels.Membership m = new ApiModels.Membership();
        m.eventName = "Forge Bingo";
        m.teamName = "Wolves";
        m.status = status;
        m.verified = "verified".equals(status);
        m.joinedRsn = joined;
        m.pluginRsn = plugin;
