    private static void wing(Grid g, double bx, double by, double len, double thick, double deg, char c, char l, char d)
    {
        double r = Math.toRadians(deg);
        part(g, bevel(ellipseRot(bx + Math.cos(r) * len, by + Math.sin(r) * len, len, thick, deg, c), l, d));
    }

    /** Vespula: big red wasp, two pairs of wings that beat up and down, lime glow, proboscis, dangling legs. */
    private static Grid vespula(int f)
    {
        Grid g = new Grid();
        int dy = f;
        Grid legs = new Grid();
        line(legs, 16, 22 + dy, 13, 28, 'u', 'u');
        line(legs, 19, 23 + dy, 19, 28, 'u', 'u');
        line(legs, 23, 22 + dy, 27, 28, 'u', 'u');
        legs.pxs('u', 12, 28, 18, 28, 28, 28);
        part(g, legs);
        // front pair of wings (towards the head), behind the body
        if (f == 0)
        {
            wing2(g, 17, 12 + dy, 6.5, 2.2, -138);
            wing2(g, 17, 12 + dy, 9, 2.7, -116);
        }
        else
        {
            wing2(g, 17, 15 + dy, 6.5, 2.2, 140);
            wing2(g, 17, 15 + dy, 8.5, 2.7, 114);
        }
        part(g, bevel(ellipseRot(27, 19 + dy, 9, 6, 25, 'M'), 'f', 'P'));
        g.pxs('T', 24, 16 + dy, 25, 16 + dy, 27, 18 + dy, 28, 18 + dy, 30, 20 + dy, 31, 20 + dy, 25, 21 + dy, 26, 21 + dy, 29, 23 + dy);
        g.pxs('t', 24, 17 + dy, 27, 19 + dy, 30, 21 + dy, 25, 22 + dy);
        part(g, bevel(oval(13, 12 + dy, 13, 10, 'M'), 'f', 'P'));
        part(g, bevel(oval(15, 12 + dy, 8, 4, 'T'), (char) 0, 't'));
        part(g, bevel(oval(6, 14 + dy, 9, 8, 'M'), 'f', 'P'));
        part(g, rect(7, 16 + dy, 3, 3, 'T'));
        g.pxs('x', 7, 16 + dy);
        Grid pro = new Grid();
        line(pro, 7, 20 + dy, 2, 22 + dy, 'u', 'u');
        pro.pxs('u', 1, 21 + dy, 0, 20 + dy, 1, 24 + dy, 0, 25 + dy, 1, 22 + dy);
        part(g, pro);
        // rear pair of wings (up and back), over the body
        if (f == 0)
        {
            wing2(g, 22, 12 + dy, 9, 2.7, -62);
            wing2(g, 22, 12 + dy, 6.5, 2.2, -40);
        }
        else
        {
            wing2(g, 22, 15 + dy, 9, 2.7, 62);
            wing2(g, 22, 15 + dy, 6.5, 2.2, 36);
        }
        return shift(g, 2);
    }

    /** A wing: lighter translucent-looking membrane with a darker leading edge. */
    private static void wing2(Grid g, double bx, double by, double len, double thick, double deg)
    {
        double r = Math.toRadians(deg);
        double cx = bx + Math.cos(r) * len;
        double cy = by + Math.sin(r) * len;
        double cs = Math.cos(r);
        double sn = Math.sin(r);
        Grid m = new Grid();
        boolean up = deg < 0;
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                double dx = x + 0.5 - cx;
                double dy = y + 0.5 - cy;
                double u = dx * cs + dy * sn;
                double v = -dx * sn + dy * cs;
                if (u * u / (len * len) + v * v / (thick * thick) > 1) continue;
                boolean lead = up ? v < -thick * 0.45 : v > thick * 0.45;
                boolean inner = up ? v > thick * 0.1 : v < -thick * 0.1;
                m.set(x, y, lead ? 'P' : (inner ? 'a' : 'f'));
            }
        }
        part(g, m);
    }

    /** A smooth 2 px thick cubic curve; thins to 1 px near the end, accent colour on the tip, dark claw at the very end. */
    private static void tentacle(Grid m, double[] p, char body, char tip, char claw)
    {
        int n = 90;
        for (int i = 0; i <= n; i++)
        {
            double t = i / (double) n;
            double u = 1 - t;
            double x = u * u * u * p[0] + 3 * u * u * t * p[2] + 3 * u * t * t * p[4] + t * t * t * p[6];
            double y = u * u * u * p[1] + 3 * u * u * t * p[3] + 3 * u * t * t * p[5] + t * t * t * p[7];
            char c = t > 0.92 ? claw : (t > 0.7 ? tip : body);
            int xi = (int) Math.round(x);
            int yi = (int) Math.round(y);
            m.set(xi, yi, c);
            if (t < 0.85)
            {
                m.set(xi + 1, yi, c);
                m.set(xi, yi + 1, c);
                m.set(xi + 1, yi + 1, c);
            }
        }
    }

    private static void ring(Grid m, double cx, double cy, double rx, double ry, boolean front, char c)
    {
        for (int i = 0; i < 400; i++)
        {
            double a = Math.PI * 2 * i / 400;
            boolean isFront = Math.sin(a) >= 0;
            if (isFront != front) continue;
            int x = (int) Math.round(cx + Math.cos(a) * rx);
            int y = (int) Math.round(cy + Math.sin(a) * ry);
            m.set(x, y, c);
            if (Math.abs(Math.sin(a)) > 0.5) m.set(x, y + 1, c);
            else m.set(x + 1, y, c);
        }
    }

    /** A broad flat pointed tentacle: wide at the root, tapering to a point, accent edge and a darker midrib. */
    private static Grid petal(double rx, double ry, double deg, double len, double wd, char edge)
    {
        Grid m = new Grid();
        double r = Math.toRadians(deg);
        double dx = Math.cos(r);
        double dy = Math.sin(r);
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                double ux = x + 0.5 - rx;
                double uy = y + 0.5 - ry;
                double t = (ux * dx + uy * dy) / len;
                if (t < -0.03 || t > 1) continue;
                double p = Math.abs(-ux * dy + uy * dx);
                double hw = wd / 2 * Math.pow(Math.max(0, 1 - t), 0.65);
                if (p > hw) continue;
                m.set(x, y, (p > hw - 1.0 || t > 0.85) ? edge : (p < 0.6 ? 'd' : 'S'));
            }
        }
        return m;
    }

    /** Vanguard: a tall pointed grey hood with a tail spike, a cute red-orange face with a beak, and tentacles. */
    private static Grid vanguard(int v, int f)
    {
        char tip = v == 1 ? 'T' : (v == 2 ? 'i' : 'a');
        Grid g = new Grid();
        int oy = v == 2 ? 0 : 3;
        double w = f;
        Grid back = new Grid();
        Grid front = new Grid();
        if (v == 0)
        {
            double[][] ts = {
                {16, 25, 3, 30, 1 + w, 10, 12 + w, 4},
                {18, 26, 9, 31, 7 + w, 12, 15 + w, 7},
                {25, 25, 38, 30, 40 - w, 10, 29 - w, 4},
                {23, 26, 31, 31, 34 - w, 14, 27 - w, 9}};
            for (double[] t : ts) tentacle(back, shiftY(t, oy), 'r', tip, 'u');
        }
        else if (v == 1)
        {
            double[][] ts = {
                {17, 24, 2, 19, 15 + 1.5 * w, 9, 7 + w, 0},
                {24, 24, 39, 19, 27 - 1.5 * w, 9, 34 - w, 0}};
            for (double[] t : ts) tentacle(back, shiftY(t, 3), 'r', tip, 'u');
            ring(back, 21, 28 + f, 13, 3, false, 'r');
            ring(front, 21, 28 + f, 13, 3, true, 'r');
        }
        else
        {
            // a fan of broad flat pointed petals along the ground, outer ones first
            double[][] pet = {{9, 20}, {22, 15.5}, {40, 10.5}, {66, 7.5}};
            for (int i = 0; i < pet.length; i++)
            {
                double sw = (i % 2 == 0 ? 3 : -3) * (f == 1 ? 1 : 0);
                part(g, petal(21, 25, 180 - pet[i][0] - sw, pet[i][1], 9, tip));
                part(g, petal(21, 25, pet[i][0] + sw, pet[i][1], 9, tip));
            }
        }
        part(g, back);
        part(g, bevel(ellipseRot(31, 24 + oy + f, 7, 2.3, 14, 'c'), 'C', 'u'));
        Grid hood = new Grid();
        for (int y = 1 + oy; y <= 20 + oy; y++)
        {
            double t = (y - (1 + oy)) / 19.0;
            double hw = 0.7 + 6.9 * Math.pow(t, 0.7);
            for (int x = (int) Math.round(21 - hw); x < (int) Math.round(21 + hw); x++) hood.set(x, y, 'c');
        }
        with(hood, oval(14, 13 + oy, 15, 13, 'c'));
        bevel(hood, 'C', 'u');
        part(g, hood);
        part(g, bevel(oval(15, 13 + oy, 12, 13, 'f'), 'a', 'P'));
        part(g, rect(17, 17 + oy, 3, 3, 'z'));
        part(g, rect(23, 17 + oy, 3, 3, 'z'));
        g.pxs(tip, 18, 18 + oy, 24, 18 + oy).pxs('x', 17, 17 + oy, 23, 17 + oy);
        part(g, rect(19, 21 + oy, 5, 2, 'A'));
        g.pxs('A', 20, 23 + oy, 21, 23 + oy, 22, 23 + oy);
        part(g, front);
        return g;
    }

    private static double[] shiftY(double[] t, int dy)
    {
        double[] o = t.clone();
        for (int i = 1; i < o.length; i += 2) o[i] += dy;
        return o;
    }

    /** A crescent blade arm hugging the lower left of two circles; (mirror) flips it about the sprite's centre. */
    private static Grid crescent(int dy, boolean mirror, double scale)
    {
        Grid m = new Grid();
        for (int y = 0; y < 22; y++)
        {
            for (int x = 0; x < 20; x++)
            {
                double ox = x + 0.5;
                double oy = y + 0.5 - dy;
                double d1 = Math.hypot(ox - 9, oy - 10.5);
                double d2 = Math.hypot(ox - 12.5, oy - 8.5);
                if (d1 > 8.8 * scale || d2 <= 7.2 * scale) continue;
                int xx = mirror ? 41 - x : x;
                m.set(xx, y, d1 > 7.6 * scale ? 's' : 'p');
            }
        }
        return m;
    }

    /** Jal-ImKot: a snake-like obsidian creature: upright torso on a thick slithering coil, big scythe-blade arms. */
    private static Grid meleer(int f)
    {
        Grid g = new Grid();
        int dy = -f;
        int dy2 = f - 1;
        // back arm and blade (mirrored)
        part(g, crescent(dy2 + 1, true, 0.95));
        part(g, bevel(rect(26, 15 + dy2, 8, 4, 'O'), 'p', 'o'));
        part(g, rect(31, 17 + dy2, 3, 3, 'p'));
        // tail and coil
        part(g, bevel(oval(36, 24 + f, 6, 6, 'o'), 'O', 'z'));
        part(g, bevel(oval(29, 25 - f, 10, 8, 'o'), 'O', 'z'));
        part(g, bevel(oval(10, 24, 24, 9, 'o'), 'O', 'z'));
        part(g, bevel(oval(14, 22 + f, 10, 9, 'o'), 'O', 'z'));
        g.pxs('a', 13, 29, 17, 30, 21, 30, 25, 29 - f, 29, 28, 33, 28 - f, 37, 28 + f);
        g.pxs('a', 15, 26 + f, 19, 27, 23, 27, 27, 26, 31, 26 - f);
        // torso and head
        part(g, bevel(oval(14, 11, 14, 15, 'o'), 'O', 'z'));
        g.pxs('a', 17, 17, 18, 18, 19, 19, 24, 17, 23, 18, 22, 19, 21, 21, 21, 22);
        part(g, bevel(oval(14, 2, 14, 11, 'o'), 'O', 'z'));
        part(g, rect(16, 6, 3, 2, 'A'));
        part(g, rect(23, 6, 3, 2, 'A'));
        g.pxs('z', 16, 6, 23, 6).pxs('x', 17, 11, 20, 11, 23, 11);
        g.pxs('a', 18, 9, 19, 9, 20, 9, 21, 9, 22, 9);
        g.pxs('O', 17, 1, 24, 1, 17, 0);
        // front blade arm
        part(g, crescent(dy, false, 1.0));
        part(g, bevel(rect(10, 15 + dy, 6, 4, 'O'), 'p', 'o'));
        part(g, rect(8, 16 + dy, 3, 3, 'p'));
        return g;
    }

    /** Jal-Nib: a little lava grub: segmented dark body low to the ground, glowing seams, two big tusks. */
    private static Grid nibbler(int f)
    {
        Grid g = new Grid();
        part(g, bevel(oval(31, 28 - f, 6, 5 + f, 'o'), 'O', 'z'));
        part(g, bevel(oval(26, 26 - f, 8, 7 + f, 'o'), 'O', 'z'));
        part(g, bevel(oval(20, 25 + f, 8, 8 - f, 'o'), 'O', 'z'));
        part(g, bevel(oval(13, 24, 9, 9, 'o'), 'O', 'z'));
        // glowing seams between the segments
        g.pxs('a', 26, 28 - f, 26, 29 - f, 26, 30, 31, 30, 31, 31, 20, 28, 20, 29 + f, 20, 30);
        g.pxs('a', 23, 26 + f, 29, 27 - f, 34, 29 - f);
        // eyes and tusks
        g.pxs('A', 16, 27, 17, 27, 19, 27, 20, 27);
        g.pxs('f', 16, 28, 19, 28);
        Grid tusks = new Grid();
        tusks.stamp(8, 24, "bb..", "bbb.", ".bbb", "..bb");
        tusks.stamp(8, 29, "..bb", ".bbb", "bbb.", "bb..");
        part(g, tusks);
        g.pxs('z', 13, 30, 14, 30, 15, 30, 16, 30);
        return g;
    }

    // ---------------------------------------------------------------- falling things

    private static Grid buildFall(Critter.Fall fall, int v)
    {
        Grid g = new Grid(16, 16);
        if (fall == Critter.Fall.BONE)
        {
            Grid b = v == 0 ? bone(4, 12, 12, 4) : bone(3.5, 5.5, 12, 10.5);
            bevel(b, (char) 0, 'B');
            PixelArt.part(g, b, 'k');
            return g;
        }
        if (v == 0)
        {
            Grid e = new Grid(16, 16);
            with(e, ovalN(4, 5, 8, 8, 'f'));
            with(e, ovalN(5, 6, 6, 6, 'a'));
            with(e, ovalN(6, 7, 3, 3, 'A'));
            e.set(7, 8, 'x');
            e.stamp(6, 2, "..f.", ".faa");
            e.set(8, 4, 'a');
            e.set(7, 4, 'f');
            PixelArt.part(g, e, 'F');
            return g;
        }
        Grid rock = new Grid(16, 16);
        rock.stamp(3, 4,
            "..HH.Hh...",
            ".HHHHhhhh.",
            "HHhhhahhhh",
            "HhhahhhhhF",
            "hhhhhaahhF",
            ".hhhhhhhFF",
            "..hFFhhFF.");
        PixelArt.part(g, rock, 'k');
        g.pxs('A', 8, 7, 9, 8, 11, 9);
        return g;
    }

    private static Grid ovalN(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid(16, 16);
        double cx = x + w / 2.0;
        double cy = y + h / 2.0;
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++)
            {
                double dx = (x + i + 0.5 - cx) / (w / 2.0);
                double dy = (y + j + 0.5 - cy) / (h / 2.0);
                if (dx * dx + dy * dy <= 1.0) m.set(x + i, y + j, c);
            }
        }
        return m;
    }

    /** A cartoon bone from (ax, ay) to (ex, ey) in pixel coordinates: thin shaft, two round bumps at each end. */
    private static Grid bone(double ax, double ay, double ex, double ey)
    {
        Grid m = new Grid(16, 16);
        double dx = ex - ax;
        double dy = ey - ay;
        double len = Math.hypot(dx, dy);
        dx /= len;
        dy /= len;
        double px = -dy;
        double py = dx;
        for (int j = 0; j < 16; j++)
        {
            for (int i = 0; i < 16; i++)
            {
                double x = i + 0.5;
                double y = j + 0.5;
                double t = Math.max(0, Math.min(len, (x - ax) * dx + (y - ay) * dy));
                double d = Math.hypot(x - (ax + dx * t), y - (ay + dy * t));
                boolean on = d <= 1.1;
                for (int end = 0; end < 2 && !on; end++)
                {
                    double bx = end == 0 ? ax : ex;
                    double by = end == 0 ? ay : ey;
                    for (int s = -1; s <= 1; s += 2)
                    {
                        double cx = bx + px * 1.6 * s;
                        double cy = by + py * 1.6 * s;
                        if (Math.hypot(x - cx, y - cy) <= 1.75) on = true;
                    }
                }
                if (on) m.set(i, j, 'b');
            }
        }
        return m;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import org.junit.Test;

/** The finished tile card's "Finished by": what each teammate's share is called, and how long ago it was. */
public class FinishedCardTest
{
    private static ApiModels.Tile tile(String... sourceTypes)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.tasks = new ArrayList<>();
        for (String st : sourceTypes)
        {
            ApiModels.Task k = new ApiModels.Task();
            k.sourceType = st;
            t.tasks.add(k);
        }
        return t;
    }

    @Test
    public void killTilesCountKillsAndDropTilesCountDrops()
    {
        assertEquals("14 kills", TileInfo.contributed(tile("kc"), 14));
        assertEquals("1 kill", TileInfo.contributed(tile("kc", "kc"), 1));
        assertEquals("3 drops", TileInfo.contributed(tile("npc", "raid_chest"), 3));
        assertEquals("1 drop", TileInfo.contributed(tile("clue"), 1));
    }

    @Test
    public void mixedAndScreenshotTilesShowJustTheNumber()
    {
        assertEquals("x2", TileInfo.contributed(tile("kc", "npc"), 2));
        assertEquals("x1", TileInfo.contributed(tile("manual"), 1));
        assertEquals("x4", TileInfo.contributed(tile(), 4));
        assertEquals("x4", TileInfo.contributed(null, 4));
    }

    @Test
    public void finishedAgoReadsTheServersTime()
    {
        long now = java.time.OffsetDateTime.parse("2026-11-23T12:00:00+00:00").toInstant().toEpochMilli();
        assertEquals("Finished just now", TileInfo.finishedAgo("2026-11-23T11:59:40.5+00:00", now));
        assertEquals("Finished 1 minute ago", TileInfo.finishedAgo("2026-11-23T11:58:30+00:00", now));
        assertEquals("Finished 45 minutes ago", TileInfo.finishedAgo("2026-11-23T11:15:00+00:00", now));
        assertEquals("Finished 1 hour ago", TileInfo.finishedAgo("2026-11-23T10:30:00+00:00", now));
        assertEquals("Finished 2 days ago", TileInfo.finishedAgo("2026-11-21T05:42:20.494322+00:00", now));
        // a clock that is ahead of the server never shows a time in the future
        assertEquals("Finished just now", TileInfo.finishedAgo("2026-11-23T12:05:00+00:00", now));
    }

    @Test
    public void noTimeOrABrokenOneShowsNothing()
    {
        assertNull(TileInfo.finishedAgo(null, 0));
        assertNull(TileInfo.finishedAgo("", 0));
        assertNull(TileInfo.finishedAgo("yesterday", 0));
    }

    @Test
    public void freeSpaceOnlyWhenTheServerSaysSo()
    {
        ApiModels.Tile t = tile("manual");
        assertFalse(TileInfo.isFree(t)); // older servers send nothing
        t.free = true;
        assertTrue(TileInfo.isFree(t));
        assertFalse(TileInfo.isFree(null));
    }

    @Test
    public void namesFromTheServerAreCapped()
    {
        ApiModels.BoardResponse b = new ApiModels.BoardResponse();
        ApiModels.Tile t = tile("kc");
        ApiModels.Contributor ok = new ApiModels.Contributor();
        ok.name = "goonferno";
        ok.qty = 3;
        ApiModels.Contributor none = new ApiModels.Contributor();
        none.name = "nobody";
        none.qty = 0;
        t.contributors = new ArrayList<>(Arrays.asList(ok, none, null));
        b.tiles = new ArrayList<>(Arrays.asList(t));
        Sanitizer.board(b);
        assertEquals(1, b.tiles.get(0).contributors.size());
        assertEquals("goonferno", b.tiles.get(0).contributors.get(0).name);
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class GroundGuardTest
{
    private static final int WHIP = 4151;
    private static final int DRAGON_BONES = 536;
    // a size-1 monster at (3200, 3200) on plane 0
    private static final int X = 3200, Y = 3200, P = 0;

    @Test
    public void aRealDropCounts()
    {
        GroundGuard g = new GroundGuard();
        assertTrue(g.fromMonster(WHIP, 100, X, Y, P, 1));
    }

    /** dropping your own item under the monster as it dies must not count as its drop */
    @Test
    public void anItemIDroppedMyselfNeverCounts()
    {
        GroundGuard g = new GroundGuard();
        g.onDropClicked(WHIP, 100);
        assertFalse(g.fromMonster(WHIP, 100, X, Y, P, 1));
        assertFalse(g.fromMonster(WHIP, 101, X, Y, P, 1));
        assertFalse(g.fromMonster(WHIP, 104, X, Y, P, 1));
        // the rest of that monster's loot still counts
        assertTrue(g.fromMonster(DRAGON_BONES, 101, X, Y, P, 1));
        // and a later, real whip drop counts again
        assertTrue(g.fromMonster(WHIP, 110, X, Y, P, 1));
    }

    /** another player's dropped item turning visible on the monster's tile in that tick must not count */
    @Test
    public void anotherPlayersItemNeverCounts()
    {
        GroundGuard g = new GroundGuard();
        g.onForeignItem(WHIP, 200, X, Y, P);
        assertFalse(g.fromMonster(WHIP, 200, X, Y, P, 1));
        assertFalse(g.fromMonster(WHIP, 201, X, Y, P, 1));
        assertTrue(g.fromMonster(WHIP, 205, X, Y, P, 1));
    }

    /** a busy spot: another player's copy of the item appearing elsewhere on screen does not hide a real drop */
    @Test
    public void anotherPlayersItemFarAwayDoesNotHideARealDrop()
    {
        GroundGuard g = new GroundGuard();
        g.onForeignItem(DRAGON_BONES, 300, X + 6, Y, P);
        g.onForeignItem(DRAGON_BONES, 300, X, Y, P + 1);
        assertTrue(g.fromMonster(DRAGON_BONES, 300, X, Y, P, 1));
    }

    /** a big monster: its loot can land on any of its tiles */
    @Test
    public void bigMonstersCoverTheirWholeArea()
    {
        GroundGuard g = new GroundGuard();
        g.onForeignItem(WHIP, 400, X + 4, Y + 4, P);
        assertFalse(g.fromMonster(WHIP, 400, X, Y, P, 5));
        assertTrue(g.fromMonster(WHIP, 400, X, Y, P, 1));
    }

    @Test
    public void oldRecordsAreForgotten()
    {
        GroundGuard g = new GroundGuard();
        g.onDropClicked(WHIP, 10);
        g.onForeignItem(WHIP, 10, X, Y, P);
        g.prune(100);
        assertTrue(g.fromMonster(WHIP, 10, X, Y, P, 1));
    }

    // a sea creature killed from a distance leaves the loot where it died (owner, 2026-11-27)
    @Test
    public void myOwnLootOnTheGroundIsMineToCollectOnce()
    {
        GroundGuard g = new GroundGuard();
        g.onOwnItem(WHIP, 100, X, Y, P);
        g.prune(400);
        assertTrue(g.takeOwnLoot(WHIP, X, Y, P));
        // answered once: the same tile does not count a second time
        assertFalse(g.takeOwnLoot(WHIP, X, Y, P));
    }

    @Test
    public void anItemIPutDownMyselfIsNotLoot()
    {
        GroundGuard g = new GroundGuard();
        g.onDropClicked(WHIP, 100);
        g.onOwnItem(WHIP, 101, X, Y, P);
        assertFalse(g.takeOwnLoot(WHIP, X, Y, P));
    }

    @Test
    public void lootElsewhereOrOfAnotherKindIsNotMixedUp()
    {
        GroundGuard g = new GroundGuard();
        g.onOwnItem(WHIP, 100, X, Y, P);
        assertFalse(g.takeOwnLoot(WHIP, X + 1, Y, P));
        assertFalse(g.takeOwnLoot(DRAGON_BONES, X, Y, P));
        assertTrue(g.takeOwnLoot(WHIP, X, Y, P));
    }

    @Test
    public void lootLeftLyingForTooLongIsForgotten()
    {
        GroundGuard g = new GroundGuard();
        g.onOwnItem(WHIP, 100, X, Y, P);
        g.prune(100 + GroundGuard.OWN_LOOT_KEEP + 1);
        assertFalse(g.takeOwnLoot(WHIP, X, Y, P));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import org.junit.Test;

public class ImpSpriteTest
{
    private static int filled(BufferedImage img)
    {
        int n = 0;
        for (int y = 0; y < img.getHeight(); y++) for (int x = 0; x < img.getWidth(); x++) if ((img.getRGB(x, y) >>> 24) != 0) n++;
        return n;
    }

    private static boolean same(BufferedImage a, BufferedImage b)
    {
        for (int y = 0; y < a.getHeight(); y++) for (int x = 0; x < a.getWidth(); x++) if (a.getRGB(x, y) != b.getRGB(x, y)) return false;
        return true;
    }

    @Test
    public void plainImpHasTheWebsiteSize()
    {
        BufferedImage img = ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 0);
        assertEquals(42, img.getWidth());
        assertEquals(34, img.getHeight());
        assertTrue("an imp is drawn", filled(img) > 250);
    }

    @Test
    public void feetStandOnTheBottomEdge()
    {
        BufferedImage img = ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 0);
        int bottom = 0;
        for (int x = 0; x < img.getWidth(); x++) if ((img.getRGB(x, img.getHeight() - 1) >>> 24) != 0) bottom++;
        assertTrue(bottom > 0);
    }

    @Test
    public void skinIsTheWebsiteRed()
    {
        BufferedImage img = ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 0);
        int red = 0;
        for (int y = 0; y < img.getHeight(); y++) for (int x = 0; x < img.getWidth(); x++) if (img.getRGB(x, y) == 0xffe0402e) red++;
        assertTrue(red > 60);
    }

    @Test
    public void walkFramesDiffer()
    {
        assertTrue(!same(ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 0), ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 1)));
    }

    @Test
    public void hatsAndItemsAddPixels()
    {
        int plain = filled(ImpSprite.image(ImpSprite.Hat.NONE, ImpSprite.Item.NONE, 0));
        for (ImpSprite.Hat h : ImpSprite.Hat.values())
        {
            if (h != ImpSprite.Hat.NONE) assertNotEquals(h.name(), plain, filled(ImpSprite.image(h, ImpSprite.Item.NONE, 0)));
        }
        for (ImpSprite.Item i : ImpSprite.Item.values())
        {
            if (i != ImpSprite.Item.NONE) assertTrue(i.name(), filled(ImpSprite.image(ImpSprite.Hat.NONE, i, 0)) > plain);
        }
    }

    @Test
    public void framesAreCached()
    {
        assertSame(ImpSprite.image(ImpSprite.Hat.WIZARD, ImpSprite.Item.AYAK, 1), ImpSprite.image(ImpSprite.Hat.WIZARD, ImpSprite.Item.AYAK, 1));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.Map;
import org.junit.Test;

public class InventoryDiffTest
{
    @Test
    public void countsMergeStacksAndSkipEmptySlots()
    {
        Map<Integer, Integer> c = InventoryDiff.counts(new int[]{995, -1, 995, 4151, 4151}, new int[]{10, 0, 5, 1, 1});
        assertEquals(Integer.valueOf(15), c.get(995));
        assertEquals(Integer.valueOf(2), c.get(4151));
        assertFalse(c.containsKey(-1));
        assertTrue(InventoryDiff.counts(null, null).isEmpty());
    }

    @Test
    public void addedReportsNewAndIncreasedItemsOnly()
    {
        Map<Integer, Integer> before = InventoryDiff.counts(new int[]{995, 4151, 385}, new int[]{100, 1, 5});
        Map<Integer, Integer> after = InventoryDiff.counts(new int[]{995, 12646, 385}, new int[]{150, 1, 4});
        Map<Integer, Integer> added = InventoryDiff.added(before, after);
        assertEquals(2, added.size());
        assertEquals(Integer.valueOf(50), added.get(995));
        assertEquals(Integer.valueOf(1), added.get(12646));
        assertFalse(added.containsKey(4151)); // removed
        assertFalse(added.containsKey(385)); // decreased
        assertEquals(1, InventoryDiff.added(null, InventoryDiff.counts(new int[]{1}, new int[]{1})).size());
        assertTrue(InventoryDiff.added(before, null).isEmpty());
        assertTrue(InventoryDiff.added(before, before).isEmpty());
    }
}

