package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import org.junit.Test;

public class ItemSlotsTest
{
    private static ApiModels.SlotProgress p(int approved, int pending)
    {
        ApiModels.SlotProgress s = new ApiModels.SlotProgress();
        s.approved = approved;
        s.pending = pending;
        return s;
    }

    @Test
    public void bonesAndBigBonesAreTwoSubTasks()
    {
        ApiModels.Task k = new ApiModels.Task();
        k.eachItem = true;
        k.itemIds = Arrays.asList(526, 532);
        k.requiredQty = 2;
        k.itemProgress = new HashMap<>();
        k.itemProgress.put("i532", p(1, 0));
        List<ItemSlots.Slot> s = ItemSlots.of(k);
        assertEquals(2, s.size());
        assertEquals("i526", s.get(0).key);
        assertFalse(s.get(0).done());
        assertTrue(s.get(1).done());
        assertEquals(1, s.get(1).need);
    }

    @Test
    public void groupsCountAsOneSubTaskKeyedByIndex()
    {
        ApiModels.Task k = new ApiModels.Task();
        k.eachItem = true;
        k.itemIds = Arrays.asList(1, 2, 3, 4);
        k.itemGroups = Arrays.asList(Arrays.asList(2, 3));
        k.requiredQty = 3;
        k.itemProgress = new HashMap<>();
        k.itemProgress.put("g0", p(0, 5));
        List<ItemSlots.Slot> s = ItemSlots.of(k);
        assertEquals(3, s.size());
        assertEquals(Arrays.asList(2, 3), s.get(1).itemIds);
        assertEquals("g0", s.get(1).key);
        assertEquals(1, s.get(1).pending); // capped at what the sub-task needs
    }

    @Test
    public void eachItemCanNeedItsOwnAmount()
    {
        ApiModels.Task k = new ApiModels.Task();
        k.eachItem = true;
        k.itemIds = Arrays.asList(1, 2, 3, 4);
        k.itemGroups = Arrays.asList(Arrays.asList(2, 3));
        k.requiredQty = 16;
        k.itemQtys = new HashMap<>();
        k.itemQtys.put("1", 5);
        k.itemQtys.put("2", 10);
        k.itemQtys.put("3", 10);
        k.itemQtys.put("4", 1);
        k.itemProgress = new HashMap<>();
        k.itemProgress.put("i1", p(7, 0));
        k.itemProgress.put("g0", p(4, 2));
        List<ItemSlots.Slot> s = ItemSlots.of(k);
        assertEquals(5, s.get(0).need);
        assertEquals(5, s.get(0).approved); // capped at its own amount
        assertTrue(s.get(0).done());
        assertEquals(10, s.get(1).need);
        assertEquals(4, s.get(1).approved);
        assertEquals(2, s.get(1).pending);
        assertEquals(1, s.get(2).need);
    }

    @Test
    public void ordinaryTasksHaveNoSubTasks()
    {
        ApiModels.Task k = new ApiModels.Task();
        k.itemIds = Arrays.asList(526, 532);
        k.requiredQty = 25;
        assertTrue(ItemSlots.of(k).isEmpty());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class MatchNoticesTest
{
    private static final Set<String> NO_HIDDEN = Collections.emptySet();

    private static ApiModels.Task task(String id, String description, boolean completed)
    {
        ApiModels.Task k = new ApiModels.Task();
        k.id = id;
        k.description = description;
        k.completed = completed;
        return k;
    }

    private static ApiModels.Tile tile(String id, String title, boolean completed, ApiModels.Task... tasks)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.id = id;
        t.title = title;
        t.completed = completed;
        t.tasks = new ArrayList<>(Arrays.asList(tasks));
        return t;
    }

    private static ApiModels.BoardResponse board(ApiModels.Tile... tiles)
    {
        ApiModels.BoardResponse b = new ApiModels.BoardResponse();
        b.tiles = new ArrayList<>(Arrays.asList(tiles));
        return b;
    }

    /** tile id -> shown title, as the plugin keeps it for the board on screen */
    private static Map<String, String> titles(ApiModels.BoardResponse b)
    {
        Map<String, String> m = new HashMap<>();
        for (ApiModels.Tile t : b.tiles) m.put(t.id, TileInfo.shownTitle(t));
        return m;
    }

    private static ApiModels.Match match(String team, String tile, String task, String status, int current, int required, boolean completed)
    {
        ApiModels.Match m = new ApiModels.Match();
        m.teamId = team;
        m.tileId = tile;
        m.taskId = task;
        m.submissionId = "sub-" + tile + "-" + task;
        m.status = status;
        m.currentQuantity = current;
        m.requiredQuantity = required;
        m.completed = completed;
        return m;
    }

    private static ApiModels.MatchedTile done(String team, String tile)
    {
        ApiModels.MatchedTile mt = new ApiModels.MatchedTile();
        mt.teamBoardId = team;
        mt.tileId = tile;
        mt.completed = true;
        return mt;
    }

    private static ApiModels.EventResult result(ApiModels.Match... matches)
    {
        ApiModels.EventResult r = new ApiModels.EventResult();
        r.matched = new ArrayList<>(Arrays.asList(matches));
        r.matchedTiles = new ArrayList<>();
        return r;
    }

    private static List<String> texts(MatchNotices.Plan p)
    {
        List<String> out = new ArrayList<>();
        for (MatchNotices.Notice n : p.notices) out.add(n.text);
        return out;
    }

    private static final ApiModels.BoardResponse BOARD = board(
        tile("t1", "Dragon bones", false, task("k1", "Bury 5 bones", false), task("k2", "Kill Vorkath", true)),
        tile("t2", "Done already", true, task("k3", "Old task", true)));

    @Test
    public void countedWithProgressAndTheSidePanelLine()
    {
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t1", "k1", "approved", 2, 5, false)), BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Counted: Dragon bones (2/5)"), texts(p));
        assertNull(p.notices.get(0).taskEffect);
        assertEquals("Bury 5 bones", p.counted);
        assertTrue(p.celebrations.isEmpty());
    }

    @Test
    public void progressNeverShowsMoreThanIsNeeded()
    {
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t1", "k2", "approved", 7, 5, true)), BOARD, titles(BOARD), NO_HIDDEN);
        // k2 was finished before this drop: counted, not "Task complete" again
        assertEquals(Collections.singletonList("Counted: Dragon bones (5/5)"), texts(p));
    }

    @Test
    public void waitingForReviewAndUnverifiedNames()
    {
        ApiModels.Match pending = match("A", "t1", "k1", "pending", 1, 5, false);
        ApiModels.Match unverified = match("A", "t1", "k1", "pending", 1, 5, false);
        unverified.verified = false;
        MatchNotices.Plan p = MatchNotices.plan(result(pending, unverified), BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Arrays.asList(
            "Counted: Dragon bones (1/5) - waiting for review",
            "Counted: Dragon bones (1/5) - waiting for review (your name isn't verified yet)"), texts(p));
    }

    @Test
    public void taskCompleteNamesTheTaskAndItsTile()
    {
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t1", "k1", "approved", 5, 5, true)), BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Task complete: Bury 5 bones (Dragon bones)"), texts(p));
        assertEquals("Bury 5 bones", p.notices.get(0).taskEffect);
        assertTrue(p.celebrations.isEmpty());
    }

    @Test
    public void aTaskTheBoardDoesNotNameGoesByItsTile()
    {
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t1", "unknown", "pending", 1, 1, true)), BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Task complete: Dragon bones - waiting for review"), texts(p));
        assertEquals("Dragon bones", p.notices.get(0).taskEffect);
        // the side panel line falls back to the tile's title
        assertEquals("Dragon bones", p.counted);
    }

    @Test
    public void tileCompleteIsSaidOnceAndCelebrated()
    {
        ApiModels.EventResult r = result(match("A", "t1", "k1", "approved", 5, 5, true), match("A", "t1", "k2", "approved", 1, 1, true));
        r.matchedTiles.add(done("A", "t1"));
        MatchNotices.Plan p = MatchNotices.plan(r, BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Tile complete: Dragon bones"), texts(p));
        assertEquals(1, p.celebrations.size());
        assertEquals("A", p.celebrations.get(0).teamBoardId);
        assertEquals("t1", p.celebrations.get(0).tileId);
        assertEquals("Dragon bones", p.celebrations.get(0).title);
        assertEquals("Bury 5 bones, Kill Vorkath", p.counted);
    }

    @Test
    public void anAlreadyFinishedTileIsAnExtraDropWithNoSecondCelebration()
    {
        ApiModels.EventResult r = result(match("A", "t2", "k3", "pending", 3, 1, true));
        r.matchedTiles.add(done("A", "t2"));
        MatchNotices.Plan p = MatchNotices.plan(r, BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Extra drop logged for Done already (already done) - waiting for review"), texts(p));
        assertTrue(p.celebrations.isEmpty());
    }

    @Test
    public void aHiddenSecretTileNeverShowsItsAmount()
    {
        ApiModels.Tile secret = tile("s1", "?", false);
        secret.secret = true;
        ApiModels.BoardResponse b = board(secret);
        Set<String> hidden = new HashSet<>(Collections.singletonList("s1"));
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "s1", null, "approved", 3, 10, false)), b, titles(b), hidden);
        assertEquals(Collections.singletonList("Counted: Secret tile"), texts(p));
        // the server leaves out which secret tile it was: still no amounts, even if it were to send them
        MatchNotices.Plan q = MatchNotices.plan(result(match("A", null, null, "pending", 3, 10, false)), b, titles(b), hidden);
        assertEquals(Collections.singletonList("Counted: a secret tile - waiting for review"), texts(q));
        assertNull(q.counted);
    }

    @Test
    public void aSecretTileBeingFinishedShowsOnlyItsName()
    {
        ApiModels.Tile secret = tile("s1", "?", false);
        secret.secret = true;
        ApiModels.BoardResponse b = board(secret);
        ApiModels.EventResult r = result(match("A", "s1", "hiddenTask", "approved", 10, 10, true));
        r.matchedTiles.add(done("A", "s1"));
        MatchNotices.Plan p = MatchNotices.plan(r, b, titles(b), new HashSet<>(Collections.singletonList("s1")));
        assertEquals(Collections.singletonList("Tile complete: Secret tile"), texts(p));
        assertEquals("Secret tile", p.celebrations.get(0).title);
    }

    @Test
    public void twoBingosAtOnceOnlyTheBoardOnScreenHasNames()
    {
        // team A's board is on screen; the same drop also counted for team B in another bingo
        ApiModels.EventResult r = result(
            match("A", "t1", "k1", "approved", 1, 5, false),
            match("B", "other-tile", "other-task", "approved", 1, 1, true));
        r.matchedTiles.add(done("B", "other-tile"));
        MatchNotices.Plan p = MatchNotices.plan(r, BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Arrays.asList("Counted: Dragon bones (1/5)", "Tile complete: a tile"), texts(p));
        // the other board's tile is celebrated on its own team board, not the one on screen
        assertEquals(1, p.celebrations.size());
        assertEquals("B", p.celebrations.get(0).teamBoardId);
        assertEquals("other-tile", p.celebrations.get(0).tileId);
        assertNull(p.celebrations.get(0).title);
        assertEquals("Bury 5 bones", p.counted);
    }

    @Test
    public void theCelebratedTeamComesFromTheMatchWhenTheTileEntryHasNone()
    {
        ApiModels.EventResult r = result(match("A", "t1", "k1", "approved", 5, 5, true));
        r.matchedTiles.add(done(null, "t1"));
        assertEquals("A", MatchNotices.plan(r, BOARD, titles(BOARD), NO_HIDDEN).celebrations.get(0).teamBoardId);
        // neither says: null, and the plugin uses the board on screen
        ApiModels.EventResult s = result(match(null, "t1", "k1", "approved", 5, 5, true));
        s.matchedTiles.add(done(null, "t1"));
        assertNull(MatchNotices.plan(s, BOARD, titles(BOARD), NO_HIDDEN).celebrations.get(0).teamBoardId);
    }

    @Test
    public void orOptionsTheFinishedOptionIsTheTaskThatCompletes()
    {
        ApiModels.Task a = task("o1", "Abyssal whip", false);
        ApiModels.Task b = task("o2", "Kraken tentacle", false);
        a.group = 1;
        b.group = 1;
        ApiModels.BoardResponse board = board(tile("t", "Slayer uniques", false, a, b, task("k", "Something else", false)));
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t", "o2", "approved", 1, 1, true)), board, titles(board), NO_HIDDEN);
        assertEquals(Collections.singletonList("Task complete: Kraken tentacle (Slayer uniques)"), texts(p));
    }

    @Test
    public void theSameTaskTwiceInOneAnswerIsAnnouncedOnce()
    {
        ApiModels.EventResult r = result(match("A", "t1", "k1", "approved", 5, 5, true), match("A", "t1", "k1", "approved", 5, 5, true));
        MatchNotices.Plan p = MatchNotices.plan(r, BOARD, titles(BOARD), NO_HIDDEN);
        assertEquals(Collections.singletonList("Task complete: Bury 5 bones (Dragon bones)"), texts(p));
        assertEquals("Bury 5 bones", p.counted);
    }

    @Test
    public void withNoBoardLoadedNothingIsNamed()
    {
        MatchNotices.Plan p = MatchNotices.plan(result(match("A", "t1", "k1", "approved", 1, 5, false)), null, new HashMap<>(), NO_HIDDEN);
        assertEquals(Collections.singletonList("Counted: a tile (1/5)"), texts(p));
        assertNull(p.counted);
        assertTrue(MatchNotices.plan(null, BOARD, titles(BOARD), NO_HIDDEN).notices.isEmpty());
        assertTrue(MatchNotices.plan(new ApiModels.EventResult(), BOARD, titles(BOARD), NO_HIDDEN).notices.isEmpty());
    }

    @Test
    public void namesAreJoinedTwoAtMostThenACount()
    {
        assertNull(MatchNotices.joinNames(Collections.emptyList()));
        assertNull(MatchNotices.joinNames(null));
        assertEquals("a", MatchNotices.joinNames(Collections.singletonList("a")));
        assertEquals("a, b", MatchNotices.joinNames(Arrays.asList("a", "b")));
        assertEquals("a, b +1", MatchNotices.joinNames(Arrays.asList("a", "b", "c")));
        assertEquals("a, b +3", MatchNotices.joinNames(Arrays.asList("a", "b", "c", "d", "e")));
    }

    @Test
    public void taskNamesIndexTheWholeBoard()
    {
        Map<String, String> names = MatchNotices.taskNames(BOARD);
        assertEquals(3, names.size());
        assertEquals("Kill Vorkath", names.get("k2"));
        assertTrue(MatchNotices.taskNames(null).isEmpty());
        assertTrue(MatchNotices.taskNames(new ApiModels.BoardResponse()).isEmpty());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class OfflineQueueTest
{
    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    private final Gson gson = new Gson();

    private static GameEvent event(String id)
    {
        GameEvent e = new GameEvent();
        e.id = id;
        e.sourceType = GameEvent.NPC;
        e.npcId = 8061;
        e.npcName = "Vorkath";
        e.rsn = "Test Player";
        e.accountHash = "123";
        e.occurredAt = "2026-10-07T00:00:00Z";
        e.addItem(11286, 1);
        return e;
    }

    @Test
    public void survivesRestart() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("forgebingo").resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson);
        q.add(new QueuedEvent(event("a"), 1000));
        q.add(new QueuedEvent(event("b"), 1000));
        q.scheduleRetry("b", 3, 99_000, "HTTP 503");

        OfflineQueue reloaded = new OfflineQueue(TestFiles.fp(f), gson);
        reloaded.load();
        assertEquals(2, reloaded.size());
        assertEquals(1, reloaded.due(1000).size());
        assertEquals("a", reloaded.due(1000).get(0).event.id);
        QueuedEvent b = reloaded.due(99_000).get(1);
        assertEquals(3, b.attempts);
        assertEquals("HTTP 503", b.lastError);
        assertEquals(11286, b.event.items.get(0).itemId);
    }

    @Test
    public void idsListsSurvivorsAfterLoad() throws IOException
    {
        // the ids queued when the client last closed: their in-memory proof screenshots are gone on the next start
        Path f = tmp.getRoot().toPath().resolve("forgebingo").resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson);
        q.add(new QueuedEvent(event("a"), 1000));
        q.add(new QueuedEvent(event("b"), 1000));

        OfflineQueue reloaded = new OfflineQueue(TestFiles.fp(f), gson);
        assertTrue("nothing survived until the file is loaded", reloaded.ids().isEmpty());
        reloaded.load();
        assertEquals(new java.util.HashSet<>(java.util.Arrays.asList("a", "b")), reloaded.ids());
        reloaded.remove("a");
        assertEquals(java.util.Collections.singleton("b"), reloaded.ids());
        // the snapshot is a copy: changing it does not touch the queue
        reloaded.ids().clear();
        assertEquals(1, reloaded.size());
    }

    @Test
    public void corruptFileIsSetAsideNotCrash() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("queue.json");
        Files.write(f, "{{{ not json".getBytes());
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson);
        q.load();
        assertEquals(0, q.size());
        assertTrue(Files.exists(tmp.getRoot().toPath().resolve("queue.json.corrupt")));
    }

    @Test
    public void boundedAndExpiring() throws IOException
    {
        OfflineQueue q = new OfflineQueue(TestFiles.fp(tmp.getRoot().toPath().resolve("q.json")), gson);
        List<QueuedEvent> evicted = new ArrayList<>();
        for (int i = 0; i < OfflineQueue.MAX_ENTRIES + 3; i++)
        {
            evicted.addAll(q.add(new QueuedEvent(event("e" + i), 0)));
        }
        assertEquals(OfflineQueue.MAX_ENTRIES, q.size());
        assertEquals(3, evicted.size());
        assertEquals("e0", evicted.get(0).event.id);

        assertEquals(OfflineQueue.MAX_ENTRIES, q.expire(OfflineQueue.MAX_AGE_MILLIS + 1).size());
        assertEquals(0, q.size());
    }

    // --- deferred saves (the plugin's mode: events are added on the game thread, the worker writes the file) ---

    @Test
    public void deferredAddWritesNothingUntilFlushed() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("forgebingo").resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson, true);
        q.add(new QueuedEvent(event("a"), 1000));
        q.add(new QueuedEvent(event("b"), 1000));
        // in memory at once, so the send that follows sees them
        assertEquals(2, q.size());
        assertEquals(2, q.due(1000).size());
        assertTrue(q.unsaved());
        assertFalse(Files.exists(f));

        assertTrue(q.flush());
        assertFalse(q.unsaved());
        OfflineQueue reloaded = new OfflineQueue(TestFiles.fp(f), gson);
        reloaded.load();
        assertEquals(2, reloaded.size());
        assertEquals("a", reloaded.due(1000).get(0).event.id);
    }

    @Test
    public void deferredFlushWritesOnceForManyChangesAndNotAtAllForNone() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson, true);
        for (int i = 0; i < 5; i++) q.add(new QueuedEvent(event("e" + i), 1000));
        assertTrue(q.flush());
        // nothing changed since: the file is left alone (deleted here to see that it is not written again)
        Files.delete(f);
        assertFalse(q.flush());
        assertFalse(Files.exists(f));

        // a drain's worth of changes (two sent, one to retry) is one write
        q.remove("e0");
        q.remove("e1");
        q.scheduleRetry("e2", 1, 99_000, "HTTP 503");
        assertFalse(Files.exists(f));
        assertTrue(q.flush());
        OfflineQueue reloaded = new OfflineQueue(TestFiles.fp(f), gson);
        reloaded.load();
        assertEquals(3, reloaded.size());
        assertEquals("HTTP 503", reloaded.due(99_000).get(0).lastError);
    }

    @Test
    public void deferredRemoveOfAnUnknownEventIsNotAChange() throws IOException
    {
        OfflineQueue q = new OfflineQueue(TestFiles.fp(tmp.getRoot().toPath().resolve("queue.json")), gson, true);
        q.remove("nope");
        q.scheduleRetry("nope", 1, 5, "x");
        assertTrue(q.expire(5).isEmpty());
        assertFalse(q.unsaved());
        assertFalse(q.flush());
    }

    @Test
    public void anEventSentBeforeItsRemovalWasSavedIsStillOnDiskAfterACrash() throws IOException
    {
        // deferred mode's order of risk: the file may still hold an event the server already took (it is sent again
        // after a restart and the server answers "duplicate"), never the other way round
        Path f = tmp.getRoot().toPath().resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson, true);
        q.add(new QueuedEvent(event("a"), 1000));
        q.flush();
        q.remove("a"); // accepted by the server; the "crash" comes before the next flush
        OfflineQueue afterCrash = new OfflineQueue(TestFiles.fp(f), gson);
        afterCrash.load();
        assertEquals(1, afterCrash.size());
    }

    @Test
    public void theWriteOnEveryChangeModeIgnoresFlush() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson);
        q.add(new QueuedEvent(event("a"), 1000));
        assertTrue(Files.exists(f));
        assertFalse(q.unsaved());
        assertFalse(q.flush());
    }

    @Test
    public void processorDrainOnADeferredQueueLeavesOneFlushToDo() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("queue.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson, true);
        q.add(new QueuedEvent(event("ok1"), 1000));
        q.add(new QueuedEvent(event("ok2"), 1000));
        q.flush();
        Recorder rec = new Recorder();
        QueueProcessor p = new QueueProcessor(q, e -> result(200), rec, () -> 2000, new Random(0));
        assertEquals(-1, p.drain());
        assertEquals(2, rec.accepted.size());
        assertTrue(q.unsaved());
        assertTrue(q.flush());
        OfflineQueue reloaded = new OfflineQueue(TestFiles.fp(f), gson);
        reloaded.load();
        assertEquals(0, reloaded.size());
    }

    // --- processor ---

    private static final class Recorder implements QueueProcessor.Listener
    {
        final List<String> accepted = new ArrayList<>();
        final List<String> dropped = new ArrayList<>();
        final List<String> auth = new ArrayList<>();

        public void onAccepted(GameEvent e, ApiModels.EventResult r)
        {
            accepted.add(e.id);
        }

        public void onDropped(GameEvent e, String reason)
        {
            dropped.add(e.id + ":" + reason);
        }

        public void onAuthProblem(String m)
        {
            auth.add(m);
        }

        public void onQueueChanged(int size, String lastError)
        {
        }
    }

    private static ApiResult<ApiModels.EventResult> result(int status)
    {
        return new ApiResult<>(status, null, null, null, null, 0);
    }

    @Test
    public void processorRetriesTransientDropsPermanentPausesOnAuth() throws IOException
    {
        Path f = tmp.getRoot().toPath().resolve("q.json");
        OfflineQueue q = new OfflineQueue(TestFiles.fp(f), gson);
        AtomicLong now = new AtomicLong(1_000_000);
        q.add(new QueuedEvent(event("ok"), now.get()));
        q.add(new QueuedEvent(event("bad"), now.get()));
        q.add(new QueuedEvent(event("flaky"), now.get()));
        Recorder rec = new Recorder();
        java.util.Map<String, Integer> statuses = new java.util.HashMap<>();
        statuses.put("ok", 200);
        statuses.put("bad", 422);
        statuses.put("flaky", 503);
        QueueProcessor p = new QueueProcessor(q, e -> result(statuses.get(e.id)), rec, now::get, new Random(0));

        long next = p.drain();
        assertEquals(java.util.Collections.singletonList("ok"), rec.accepted);
        assertEquals(1, rec.dropped.size());
        assertTrue(rec.dropped.get(0).startsWith("bad:"));
        assertEquals(1, q.size());
        assertTrue(next >= 4_000 && next <= 6_000);
        assertEquals(1, q.due(Long.MAX_VALUE).get(0).attempts);

        // not due yet
        assertEquals(0, q.due(now.get()).size());

        // later: still failing, backoff grows
        now.addAndGet(10_000);
        p.drain();
        assertEquals(2, q.due(Long.MAX_VALUE).get(0).attempts);

        // key rejected: event kept, paused
        statuses.put("flaky", 401);
        now.addAndGet(600_000);
        p.drain();
        assertEquals(1, q.size());
        assertTrue(p.isAuthPaused());
        assertEquals(1, rec.auth.size());

        // fixed key: resumes immediately
        statuses.put("flaky", 200);
        p.resumeAfterAuthChange();
        p.drain();
        assertEquals(0, q.size());
        assertEquals(2, rec.accepted.size());
    }

    @Test
    public void processorRegeneratesIdOnEventIdConflict() throws IOException
    {
        OfflineQueue q = new OfflineQueue(TestFiles.fp(tmp.getRoot().toPath().resolve("q.json")), gson);
        q.add(new QueuedEvent(event("dup"), 1000));
        Recorder rec = new Recorder();
        java.util.Set<String> seen = new java.util.HashSet<>();
        QueueProcessor p = new QueueProcessor(q, e -> {
            seen.add(e.id);
            return seen.size() == 1 ? new ApiResult<>(409, null, "taken", "event_id_conflict", null, 0) : result(200);
        }, rec, () -> 2000, new Random(0));
        p.drain();
        assertEquals(1, q.size());
        assertNotEquals("dup", q.due(Long.MAX_VALUE).get(0).event.id);
        p.drain();
        assertEquals(0, q.size());
        assertEquals(2, seen.size());
        assertEquals(1, rec.accepted.size());
    }

    @Test
    public void processorDropsExpired() throws IOException
    {
        OfflineQueue q = new OfflineQueue(TestFiles.fp(tmp.getRoot().toPath().resolve("q.json")), gson);
        q.add(new QueuedEvent(event("old"), 0));
        Recorder rec = new Recorder();
        QueueProcessor p = new QueueProcessor(q, e -> result(200), rec,
            () -> OfflineQueue.MAX_AGE_MILLIS + 5, new Random(0));
        assertEquals(-1, p.drain());
        assertEquals(1, rec.dropped.size());
        assertTrue(rec.accepted.isEmpty());
    }

    @Test
    public void deduplicatorWindow()
    {
        EventDeduplicator d = new EventDeduplicator(2_000, 10);
        GameEvent e = event("x");
        String sig = EventDeduplicator.signature(e, 100);
        assertTrue(d.firstSeen(sig, 0));
        assertFalse(d.firstSeen(sig, 1_000));
        assertTrue(d.firstSeen(sig, 5_000));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import org.junit.Test;

public class OpeningAnimTest
{
    @Test
    public void thereAre100UniqueAnimationsSplitByRarity()
    {
        assertEquals(100, OpeningAnim.ALL.size());
        assertEquals(OpeningAnim.COUNT, OpeningAnim.ALL.size());
        Set<String> names = new HashSet<>();
        Set<String> moves = new HashSet<>();
        Map<OpeningAnim.Rarity, Integer> per = new EnumMap<>(OpeningAnim.Rarity.class);
        for (OpeningAnim.Spec s : OpeningAnim.ALL)
        {
            assertTrue("blank name", s.name != null && !s.name.trim().isEmpty() && s.name.length() <= 24);
            assertTrue("duplicate name " + s.name, names.add(s.name.toLowerCase()));
            // no two share the same order and entrance, so each looks different
            assertTrue("same order and entrance as another: " + s.name, moves.add(s.order + "/" + s.entrance));
            per.merge(s.rarity, 1, Integer::sum);
        }
        assertEquals(45, (int) per.get(OpeningAnim.Rarity.COMMON));
        assertEquals(30, (int) per.get(OpeningAnim.Rarity.UNCOMMON));
        assertEquals(17, (int) per.get(OpeningAnim.Rarity.EPIC));
        assertEquals(8, (int) per.get(OpeningAnim.Rarity.LEGENDARY));
    }

    @Test
    public void theTiersAreNamedAndColoured()
    {
        assertEquals("Common", OpeningAnim.Rarity.COMMON.label);
        assertEquals("Uncommon", OpeningAnim.Rarity.UNCOMMON.label);
        assertEquals("Epic", OpeningAnim.Rarity.EPIC.label);
        assertEquals("Legendary", OpeningAnim.Rarity.LEGENDARY.label);
        assertEquals(0x3ec46d, OpeningAnim.Rarity.UNCOMMON.colour.getRGB() & 0xffffff);
        double total = 0;
        for (OpeningAnim.Rarity r : OpeningAnim.Rarity.values()) total += r.chance;
        assertEquals(1, total, 1e-9);
    }

    @Test
    public void everyAnimationHasItsTiersEffectAndEachLegendaryHasItsOwnScene()
    {
        Set<OpeningAnim.Fx> scenes = new HashSet<>();
        for (OpeningAnim.Spec s : OpeningAnim.ALL)
        {
            assertEquals(s.name, s.rarity, s.fx.tier);
            if (s.rarity == OpeningAnim.Rarity.LEGENDARY) assertTrue("shared scene " + s.fx, scenes.add(s.fx));
            assertNotNull(s.accent(3));
            assertTrue(OpeningAnim.byName(s.name) == s);
        }
    }

    @Test
    public void everyAnimationFinishesInsideTheTimingLimits()
    {
        assertTrue(OpeningAnim.LAND_MS + OpeningAnim.LANDING_FX_MS <= OpeningAnim.DEAL_MS);
        for (OpeningAnim.Spec s : OpeningAnim.ALL)
        {
            assertTrue(s.name, s.pace.flightMs > 0 && s.pace.flightMs < OpeningAnim.LAND_MS);
            for (int size = 1; size <= 10; size++)
            {
                int[] ranks = OpeningAnim.ranks(s.order, size, 99);
                int max = 0;
                for (int r : ranks) max = Math.max(max, r);
                double lastLand = 0;
                for (int r : ranks)
                {
                    double start = OpeningAnim.startMs(s.pace, r, max);
                    assertTrue(s.name + " starts early", start >= 0);
                    double land = start + s.pace.flightMs;
                    assertTrue(s.name + " size " + size + " lands at " + land, land <= OpeningAnim.LAND_MS + 1e-6);
                    lastLand = Math.max(lastLand, land);
                }
                // the whole board is used: the last tile lands right at LAND_MS (one tile simply flies in)
                if (max > 0) assertEquals(s.name, OpeningAnim.LAND_MS, lastLand, 1e-6);
            }
        }
    }

    @Test
    public void laterPlacesNeverLeaveEarlier()
    {
        for (OpeningAnim.Pace p : OpeningAnim.Pace.values())
        {
            double last = -1;
            for (int r = 0; r <= 48; r++)
            {
                double at = OpeningAnim.startMs(p, r, 48);
                assertTrue(p + " " + r, at >= last);
                last = at;
            }
        }
    }

    @Test
    public void rollsFollowTheRarityChancesOverManySeeds()
    {
        Map<OpeningAnim.Rarity, Integer> got = new EnumMap<>(OpeningAnim.Rarity.class);
        int n = 40000;
        for (int seed = 0; seed < n; seed++) got.merge(OpeningAnim.roll(new Random(1_760_000_000_000L + seed * 7919L)).rarity, 1, Integer::sum);
        for (OpeningAnim.Rarity r : OpeningAnim.Rarity.values())
        {
            double share = got.getOrDefault(r, 0) / (double) n;
            assertEquals(r.label, r.chance, share, 0.012);
        }
    }

    @Test
    public void everyAnimationCanBeRolled()
    {
        Random rng = new Random(5);
        Map<String, Integer> seen = new HashMap<>();
        for (int i = 0; i < 200_000; i++) seen.merge(OpeningAnim.roll(rng).name, 1, Integer::sum);
        assertEquals(100, seen.size());
        // the bingo-start reveal is always Legendary
        for (int i = 0; i < 200; i++) assertEquals(OpeningAnim.Rarity.LEGENDARY, OpeningAnim.rollOf(OpeningAnim.Rarity.LEGENDARY, rng).rarity);
    }

    @Test
    public void everyOrderPlacesEveryTileWithNoGaps()
    {
        for (int size = 1; size <= 10; size++)
        {
            for (OpeningAnim.Order o : OpeningAnim.Order.values())
            {
                int[] ranks = OpeningAnim.ranks(o, size, 7);
                assertEquals(size * size, ranks.length);
                int max = 0;
                for (int r : ranks)
                {
                    assertTrue(o + " size " + size, r >= 0 && r < size * size);
                    max = Math.max(max, r);
                }
                Set<Integer> seen = new HashSet<>();
                for (int r : ranks) seen.add(r);
                assertEquals(o + " size " + size, max + 1, seen.size());
                // a real order: on a board of 3 or more, at least three separate moments
                if (size >= 3) assertTrue(o + " size " + size, max >= 2);
            }
        }
    }

    @Test
    public void everyEntranceLandsExactlyOnItsTile()
    {
        for (OpeningAnim.Entrance e : OpeningAnim.Entrance.values())
        {
            double[] p = OpeningAnim.pose(e, 1, 3, 100, 80, 30, 0, 0, 300, 300, 150, 280);
            assertEquals(e + " x", 100, p[0], 0.01);
            assertEquals(e + " y", 80, p[1], 0.01);
            assertEquals(e + " scale x", 1, p[2], 0.01);
            assertEquals(e + " scale y", 1, p[3], 0.01);
            assertEquals(e + " rotation", 0, p[4], 0.01);
            assertEquals(e + " alpha", 1, p[5], 0.01);
        }
    }

    @Test
    public void everyEntranceStaysFiniteAllTheWay()
    {
        double[] out = new double[6];
        for (OpeningAnim.Entrance e : OpeningAnim.Entrance.values())
        {
            for (int idx = 0; idx < 49; idx += 6)
            {
                for (double fp = -0.1; fp <= 1.1; fp += 0.01)
                {
                    OpeningAnim.pose(out, e, fp, idx, 100, 80, 30, 0, 0, 300, 300, 150, 280);
                    for (double v : out) assertTrue(e + " at " + fp, Double.isFinite(v));
                    assertTrue(e + " alpha", out[5] >= 0 && out[5] <= 1);
                }
            }
        }
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class PayloadAndClientTest
{
    private final Gson gson = new Gson();
    private MockWebServer server;
    private ApiClient client;

    @Before
    public void start() throws IOException
    {
        server = new MockWebServer();
        server.start();
        String base = server.url("/plugin-api").toString();
        client = new ApiClient(new OkHttpClient(), gson, () -> base, () -> "fb2_test_key", "2.0.0-test");
    }

    @After
    public void stop() throws IOException
    {
        server.shutdown();
    }

    private static GameEvent kcEvent()
    {
        GameEvent e = new GameEvent();
        e.id = "11111111-1111-4111-8111-111111111111";
        e.sourceType = GameEvent.KC;
        e.sourceName = "Zulrah";
        e.rsn = "Test Player";
        e.accountHash = "-9007199254740993";
        e.world = 301;
        e.occurredAt = "2026-10-07T12:00:00Z";
        return e;
    }

    @Test
    public void payloadSerializationMatchesContract()
    {
        GameEvent e = new GameEvent();
        e.id = "11111111-1111-4111-8111-111111111111";
        e.sourceType = GameEvent.NPC;
        e.npcId = 2215;
        e.npcName = "General Graardor";
        e.rsn = "Zezima";
        e.accountHash = "-9007199254740993";
        e.addItem(11832, 1);
        JsonObject o = gson.toJsonTree(e).getAsJsonObject();
        assertEquals("11111111-1111-4111-8111-111111111111", o.get("eventId").getAsString());
        assertFalse("internal field name must not leak", o.has("id"));
        assertEquals("npc", o.get("sourceType").getAsString());
        assertEquals(2215, o.get("npcId").getAsInt());
        assertEquals("General Graardor", o.get("npcName").getAsString());
        // 64-bit account hash must stay a string
        assertTrue(o.get("accountHash").getAsJsonPrimitive().isString());
        assertEquals("-9007199254740993", o.get("accountHash").getAsString());
        JsonObject item = o.getAsJsonArray("items").get(0).getAsJsonObject();
        assertEquals(11832, item.get("itemId").getAsInt());
        assertEquals(1, item.get("quantity").getAsInt());
        assertEquals("only itemId and quantity per item", 2, item.size());
        // null fields are omitted
        assertFalse(o.has("skill"));
        assertFalse(o.has("sourceName"));
    }

    @Test
    public void levelAndKcPayloads()
    {
        GameEvent lvl = new GameEvent();
        lvl.id = "x";
        lvl.sourceType = GameEvent.LEVEL;
        lvl.skill = "attack";
        lvl.level = 99;
        JsonObject o = gson.toJsonTree(lvl).getAsJsonObject();
        assertEquals("attack", o.get("skill").getAsString());
        assertEquals(99, o.get("level").getAsInt());
        assertFalse(o.has("items"));
    }

    @Test
    public void sendEventHitsGameEventsWithDocumentedHeaders() throws Exception
    {
        server.enqueue(new MockResponse().setResponseCode(200).setBody("{\"eventId\":\"x\",\"duplicate\":false,\"automationDisabled\":false,"
            + "\"sourceType\":\"kc\",\"unknownSource\":false,\"matched\":[{\"eventId\":\"e1\",\"teamId\":\"t1\",\"tileId\":\"ti\","
            + "\"taskId\":\"ta\",\"submissionId\":\"s1\",\"status\":\"pending\",\"contributedQuantity\":1,\"approvedQuantity\":0,"
            + "\"currentQuantity\":1,\"requiredQuantity\":3,\"completed\":false}],\"matchedTiles\":[],"
            + "\"skipped\":[{\"teamId\":\"t2\",\"eventId\":\"e2\",\"reason\":\"account_mismatch\"}]}"));
        ApiResult<ApiModels.EventResult> r = client.sendEvent(kcEvent());
        assertTrue(r.ok());
        assertTrue(r.body.isMatched());
        assertEquals("s1", r.body.matched.get(0).submissionId);
        assertEquals(3, r.body.matched.get(0).requiredQuantity);
        assertEquals("account_mismatch", r.body.skipped.get(0).reason);
        RecordedRequest req = server.takeRequest();
        assertEquals("POST", req.getMethod());
        assertEquals("/plugin-api/v1/game-events", req.getPath());
        assertEquals("fb2_test_key", req.getHeader("X-API-Key"));
        assertEquals("application/json", req.getHeader("Accept"));
        assertTrue(req.getHeader("Content-Type").startsWith("application/json"));
        assertEquals("2.0.0-test", req.getHeader("X-Plugin-Version"));
        assertNull("idempotency is the eventId in the body", req.getHeader("Idempotency-Key"));
        JsonObject sent = gson.fromJson(req.getBody().readUtf8(), JsonObject.class);
        assertEquals("11111111-1111-4111-8111-111111111111", sent.get("eventId").getAsString());
        assertEquals("2.0.0-test", sent.get("pluginVersion").getAsString());
    }

    @Test
    public void errorBodiesAndRetryAfter()
    {
        server.enqueue(new MockResponse().setResponseCode(429).setHeader("Retry-After", "30")
            .setBody("{\"error\":\"rate_limited\",\"message\":\"Too many requests\"}"));
        ApiResult<ApiModels.EventResult> r = client.sendEvent(kcEvent());
        assertEquals(ErrorClass.TRANSIENT, r.errorClass());
        assertEquals(30_000, r.retryAfterMillis);
        assertEquals("rate_limited", r.errorCode);
        assertEquals("Too many requests", r.error);

        server.enqueue(new MockResponse().setResponseCode(400).setBody("{\"error\":\"invalid_rsn\",\"message\":\"bad\"}"));
        r = client.sendEvent(kcEvent());
        assertEquals(ErrorClass.PERMANENT, r.errorClass());
        assertEquals("invalid_rsn", r.errorCode);

        server.enqueue(new MockResponse().setResponseCode(401).setBody("{\"error\":\"invalid_api_key\",\"message\":\"x\"}"));
        assertEquals(ErrorClass.AUTH, client.sendEvent(kcEvent()).errorClass());

        server.enqueue(new MockResponse().setResponseCode(409).setBody("{\"error\":\"event_id_conflict\",\"message\":\"x\"}"));
        assertEquals(ErrorClass.CONFLICT, client.sendEvent(kcEvent()).errorClass());

        server.enqueue(new MockResponse().setResponseCode(502).setBody("<html>bad gateway</html>"));
        assertEquals(ErrorClass.TRANSIENT, client.sendEvent(kcEvent()).errorClass());
    }

    @Test
    public void networkFailureIsTransient() throws IOException
    {
        server.shutdown();
        ApiResult<ApiModels.Me> r = client.me();
        assertEquals(0, r.status);
        assertEquals(ErrorClass.TRANSIENT, r.errorClass());
    }

    @Test
    public void meAndBoardsRoutes() throws Exception
