package com.forgebingo.core;

import java.awt.image.BufferedImage;

/**
 * The pets as DRAWN by code: one door to PetSpritesA..F (this was the body of PetSprites before the art was baked
 * into sprites/pets.png). Source of truth for PetSheetBaker and PetSpritesBakedTest. Null when a pet has no picture.
 */
public final class PetArt
{
    private PetArt()
    {
    }

    public static BufferedImage image(Pet pet, int frame)
    {
        if (pet == null) return null;
        BufferedImage img = PetSpritesA.image(pet, frame);
        if (img == null) img = PetSpritesB.image(pet, frame);
        if (img == null) img = PetSpritesC.image(pet, frame);
        if (img == null) img = PetSpritesD.image(pet, frame);
        if (img == null) img = PetSpritesE.image(pet, frame);
        if (img == null) img = PetSpritesF.image(pet, frame);
        return img;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.Arrays;
import java.util.Collections;
import java.util.Optional;
import org.junit.Test;

public class PetDetectorTest
{
    private final PetDetector d = new PetDetector();

    @Test
    public void followerIdentifiesNewPet()
    {
        assertFalse(d.onPetMessage(ChatParsers.Pet.FOLLOWING, 100).isPresent());
        assertTrue(d.wantsFollower());
        assertFalse(d.wantsInventory());
        assertFalse(d.onFollower(2215, 100).isPresent()); // not a pet follower
        PetDetector.Drop drop = d.onFollower(6635, 101).get();
        assertEquals("Baby mole", drop.pet.name);
        assertFalse(drop.duplicate);
        assertEquals("follower", drop.via);
        assertFalse(d.pending());
        assertFalse(d.onFollower(6635, 102).isPresent()); // reported once
    }

    @Test
    public void followerIgnoredForBackpackCase()
    {
        // a pet that was already following must not be mistaken for the one that went into the backpack
        d.onPetMessage(ChatParsers.Pet.BACKPACK, 50);
        assertFalse(d.onFollower(8029, 50).isPresent());
        assertFalse(d.onInventoryAdded(Collections.singletonList(995), 51).isPresent());
        PetDetector.Drop drop = d.onInventoryAdded(Arrays.asList(995, 13320), 51).get();
        assertEquals("Heron", drop.pet.name);
        assertEquals("inventory", drop.via);
    }

    @Test
    public void inventoryIgnoredWithoutBackpackLine()
    {
        assertFalse(d.onInventoryAdded(Collections.singletonList(12646), 5).isPresent());
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 6);
        assertFalse(d.onInventoryAdded(Collections.singletonList(12646), 6).isPresent());
    }

    @Test
    public void collectionLogAfterOrBeforeTheLine()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 10);
        assertEquals("Olmlet", d.onCollectionLog("Olmlet", 10).get().pet.name);
        assertFalse(d.onFollower(7520, 11).isPresent()); // already reported

        PetDetector d2 = new PetDetector();
        assertFalse(d2.onCollectionLog("Tiny tempor", 20).isPresent());
        PetDetector.Drop drop = d2.onPetMessage(ChatParsers.Pet.BACKPACK, 21).get();
        assertEquals("Tiny tempor", drop.pet.name);
        assertEquals("collection_log", drop.via);
    }

    @Test
    public void collectionLogOfOrdinaryItemsIsIgnored()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 10);
        assertFalse(d.onCollectionLog("Abyssal whip", 10).isPresent());
        assertTrue(d.pending());
    }

    @Test
    public void staleEarlySignalIsNotPaired()
    {
        d.onCollectionLog("Vorki", 0);
        d.onTick(PetDetector.WINDOW_TICKS + 1);
        assertFalse(d.onPetMessage(ChatParsers.Pet.FOLLOWING, 500).isPresent());
    }

    @Test
    public void duplicateNamedByBroadcast()
    {
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 30);
        assertFalse(d.wantsFollower());
        PetDetector.Drop drop = d.onBroadcast("Vorki", true, 31).get();
        assertEquals("Vorki", drop.pet.name);
        assertTrue(drop.duplicate);
        assertEquals("broadcast", drop.via);
    }

    @Test
    public void duplicateAttributedToTheBossJustKilled()
    {
        d.onSource("Vorkath", 39);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 40);
        assertFalse(d.onTick(40 + PetDetector.WINDOW_TICKS).isPresent());
        PetDetector.Drop drop = d.onTick(41 + PetDetector.WINDOW_TICKS).get();
        assertEquals("Vorki", drop.pet.name);
        assertTrue(drop.duplicate);
        assertEquals("source", drop.via);
    }

    @Test
    public void unidentifiedWhenNothingNamesThePet()
    {
        d.onSource("Goblin", 40);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 40);
        Optional<PetDetector.Drop> drop = d.onTick(100);
        assertTrue(drop.isPresent());
        assertFalse(drop.get().identified());
        assertFalse(d.pending());
        assertFalse(d.onTick(101).isPresent());
    }

    @Test
    public void staleSourceIsNotUsed()
    {
        d.onSource("Vorkath", 0);
        d.onPetMessage(ChatParsers.Pet.DUPLICATE, 1000);
        assertFalse(d.onTick(1100).get().identified());
    }

    @Test
    public void newPetWithoutAnySignalIsReportedUnidentified()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 5);
        PetDetector.Drop drop = d.onTick(50).get();
        assertFalse(drop.identified());
        assertFalse(drop.duplicate);
    }

    @Test
    public void resetClearsState()
    {
        d.onPetMessage(ChatParsers.Pet.FOLLOWING, 1);
        d.reset();
        assertFalse(d.pending());
        assertFalse(d.onFollower(6635, 2).isPresent());
    }
}

package com.forgebingo.core;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Bakes every pet's two walk frames (drawn by PetSpritesA..F through PetArt) into
 * src/main/resources/com/forgebingo/sprites/pets.png + pets.txt, which PetSprites loads in the plugin.
 * One row per drawn pet, frame 0 then frame 1; keys are "PET_NAME|frame".
 *
 * Re-bake after ANY change to the pet art, from the plugin directory, either by running this main() (IDE, or a
 * JavaExec on the test classpath) or with:
 *   bash:        FORGE_BAKE=1 ./gradlew cleanTest test --tests "*PetSpritesBakedTest"
 *   PowerShell:  $env:FORGE_BAKE='1'; ./gradlew cleanTest test --tests "*PetSpritesBakedTest"; $env:FORGE_BAKE=$null
 * then run ./gradlew test again (without FORGE_BAKE) to prove the sheet matches.
 */
public final class PetSheetBaker
{
    public static final String REBAKE = "from plugin/: FORGE_BAKE=1 ./gradlew cleanTest test --tests \"*PetSpritesBakedTest\""
        + " (PowerShell: $env:FORGE_BAKE='1' first), or run com.forgebingo.core.PetSheetBaker.main; then ./gradlew test";

    private PetSheetBaker()
    {
    }

    /** Every pet x frame as the art code draws it (null for a pet with no picture), in sheet order. */
    public static Map<String, BufferedImage> drawn()
    {
        Map<String, BufferedImage> out = new LinkedHashMap<>();
        for (Pet p : Pet.values())
        {
            for (int f = 0; f < 2; f++) out.put(p.name() + "|" + f, PetArt.image(p, f));
        }
        return out;
    }

    public static void bake() throws IOException
    {
        SheetBaker.bake("pets", drawn(), 2);
    }

    public static void main(String[] args) throws IOException
    {
        bake();
    }
}

package com.forgebingo.core;

import com.forgebingo.core.PixelArt.Grid;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Pixel art for the skilling pets (baby chinchompa, beaver, giant squirrel, heron, rift guardian, rock golem, Rocky,
 * Soup and Tangleroot). Original chunky chibi art in the style of CryptSprites: big head, 1px dark outline, 2-3 shades
 * per colour, two walk frames, drawn facing LEFT on the shared grid with the feet on the bottom rows.
 */
public final class PetSpritesA
{
    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private PetSpritesA()
    {
    }

    /** One walk frame (0 or 1) on the PixelArt.WIDTH x PixelArt.HEIGHT grid, facing left, feet on the bottom rows. */
    public static BufferedImage image(Pet pet, int frame)
    {
        if (pet == null) return null;
        switch (pet)
        {
            case BABY_CHINCHOMPA: case BEAVER: case GIANT_SQUIRREL: case HERON: case RIFT_GUARDIAN:
            case ROCK_GOLEM: case ROCKY: case SOUP: case TANGLEROOT:
                break;
            default:
                return null;
        }
        int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(pet + "|" + f, k -> PixelArt.render(build(pet, f), PetSpritesA::colour));
    }

    private static int colour(int c)
    {
        switch ((char) c)
        {
            case 'k': return 0x16140f; // outline
            case 'z': return 0x1d1a22; // darkest (eyes, noses)
            case 'x': return 0xfff7e0; // white
            case 'c': return 0xb9ab8c; // chinchompa fur
            case 'C': return 0xddd2b4;
            case 'd': return 0x85785f;
            case 'p': return 0xe08c84; // pink
            case 'n': return 0x7a5232; // beaver
            case 'N': return 0xa47450;
            case 'm': return 0x49301c;
            case 'l': return 0x3b2a20;
            case 'L': return 0x5e4636;
            case 'q': return 0x45404a; // squirrel
            case 'Q': return 0x6e6874;
            case 'u': return 0x26222c;
            case 'r': return 0xb0603a;
            case 'R': return 0xdc8c58;
            case 'v': return 0x6e3420;
            case 'h': return 0xc5cbd2; // heron
            case 'H': return 0xf0f2f4;
            case 'i': return 0x8b939e;
            case 'y': return 0xe8a828;
            case 'Y': return 0xf8d060;
            case 'o': return 0xb08828;
            case 'g': return 0x8d9098; // rift guardian stone
            case 'G': return 0xb9bcc4;
            case 'D': return 0x555962;
            case 'a': return 0xff8a1e; // rune glow
            case 'A': return 0xffd04a;
            case 'f': return 0xe03a12;
            case 'b': return 0xa98a58; // rock golem
            case 'B': return 0xd2b27c;
            case 'e': return 0x6c5634;
            case 'E': return 0x8a7040;
            case 'j': return 0x8c8c96; // raccoon
            case 'J': return 0xc2c2cc;
            case 'K': return 0x585860;
            case 'S': return 0x7e7038; // turtle
            case 'T': return 0xa89a52;
            case 'U': return 0x534a26;
            case 'P': return 0x8fa044;
            case 'M': return 0xb7c860;
            case 'O': return 0x5d6e2c;
            case 'W': return 0x7c5c3a; // tangleroot
            case 'V': return 0xa67e50;
            case 'X': return 0x4d3925;
            case '1': return 0x58a840;
            case '2': return 0x94d868;
            case '3': return 0x2e6a2e;
            default: return 0xff00ff;
        }
    }

    // ---------------------------------------------------------------- helpers

    private static Grid rect(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++) m.set(x + i, y + j, c);
        }
        return m;
    }

    private static Grid oval(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        double cx = x + w / 2.0;
        double cy = y + h / 2.0;
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++)
            {
                double dx = (x + i + 0.5 - cx) / (w / 2.0);
                double dy = (y + j + 0.5 - cy) / (h / 2.0);
                if (dx * dx + dy * dy <= 1.0) m.set(x + i, y + j, c);
            }
        }
        return m;
    }

    private static Grid trap(int cx, int y0, int y1, double hw0, double hw1, char c)
    {
        Grid m = new Grid();
        for (int y = y0; y <= y1; y++)
        {
            double t = y1 == y0 ? 0 : (double) (y - y0) / (y1 - y0);
            int hw = (int) Math.round(hw0 + (hw1 - hw0) * t);
            for (int x = cx - hw; x < cx + hw; x++) m.set(x, y, c);
        }
        return m;
    }

    /** Light on the top-left edge, dark on the bottom-right edge (0 to skip one). */
    private static Grid bevel(Grid m, char light, char dark)
    {
        char[][] src = new char[m.h][];
        for (int j = 0; j < m.h; j++) src[j] = m.px[j].clone();
        for (int j = 0; j < m.h; j++)
        {
            for (int i = 0; i < m.w; i++)
            {
                if (src[j][i] == 0) continue;
                boolean top = j == 0 || src[j - 1][i] == 0;
                boolean left = i == 0 || src[j][i - 1] == 0;
                boolean bottom = j == m.h - 1 || src[j + 1][i] == 0;
                boolean right = i == m.w - 1 || src[j][i + 1] == 0;
                if (dark != 0 && (bottom || right)) m.px[j][i] = dark;
                else if (light != 0 && (top || left)) m.px[j][i] = light;
            }
        }
        return m;
    }

    /** b painted over a. */
    private static Grid with(Grid a, Grid b)
    {
        for (int j = 0; j < b.h; j++)
        {
            for (int i = 0; i < b.w; i++)
            {
                if (b.px[j][i] != 0) a.set(i, j, b.px[j][i]);
            }
        }
        return a;
    }

    private static void part(Grid g, Grid fill)
    {
        PixelArt.part(g, fill, 'k');
    }

    /** Stubby legs ending on row 32; in the walk frame every other one lifts a pixel. */
    private static void feet(Grid g, int[] xs, int w, int top, char c, char light, char dark, int f)
    {
        for (int i = 0; i < xs.length; i++)
        {
            boolean lifted = (i % 2 == 0) == (f == 1);
            int lift = lifted ? 1 : 0;
            part(g, bevel(rect(xs[i] + (lifted ? 1 : 0), top, w, 33 - top - lift, c), light, dark));
        }
    }

    private static Grid build(Pet pet, int f)
    {
        switch (pet)
        {
            case BABY_CHINCHOMPA: return chinchompa(f);
            case BEAVER: return beaver(f);
            case GIANT_SQUIRREL: return squirrel(f);
            case HERON: return heron(f);
            case RIFT_GUARDIAN: return riftGuardian(f);
            case ROCK_GOLEM: return rockGolem(f);
            case ROCKY: return rocky(f);
            case SOUP: return soup(f);
            default: return tangleroot(f);
        }
    }

    // ---------------------------------------------------------------- pets

    /** A thick curving shape: {x, y, radius} control points joined by round blobs (bushy tails). */
    private static Grid blob(double[][] pts, char c, boolean scallop)
    {
        Grid m = new Grid();
        int n = 0;
        for (int s = 0; s + 1 < pts.length; s++)
        {
            for (int i = 0; i < 24; i++)
            {
                double t = i / 24.0;
                double cx = pts[s][0] + (pts[s + 1][0] - pts[s][0]) * t;
                double cy = pts[s][1] + (pts[s + 1][1] - pts[s][1]) * t;
                double r = pts[s][2] + (pts[s + 1][2] - pts[s][2]) * t;
                if (scallop && (n++ / 6) % 2 == 1) r += 1.4;
                for (int y = 0; y < m.h; y++)
                {
                    for (int x = 0; x < m.w; x++)
                    {
                        if (Math.hypot(x + 0.5 - cx, y + 0.5 - cy) <= r) m.set(x, y, c);
                    }
                }
            }
        }
        return m;
    }

    /** Baby chinchompa: a round, fluffy tan rodent with huge round ears, a big shiny eye, whiskers and a curly tufted tail. */
    private static Grid chinchompa(int f)
    {
        Grid g = new Grid();
        double w = f * 1.5;
        Grid tail = bevel(blob(new double[][] {{27, 25, 2.2}, {31, 21, 2.8}, {34 + w * 0.3, 15, 3.2}, {34 + w, 9, 3.4}, {31 + w, 5, 2.6}}, 'c', true), 'C', 'd');
        tail.pxs('d', 33, 9, 34, 10, 31, 6, 32, 6, 33, 15);
        part(g, tail);
        feet(g, new int[] {13, 24}, 4, 29, 'd', (char) 0, 'z', f);
        Grid body = bevel(oval(10, 16, 20, 15, 'c'), 'C', 'd');
        with(body, oval(12, 24, 11, 7, 'C'));
        body.pxs('d', 20, 17, 22, 17, 24, 18, 26, 19, 27, 21, 18, 17);
        part(g, body);
        part(g, bevel(oval(7, 6, 7, 9, 'c'), 'C', 'd'));
        part(g, bevel(oval(14, 6, 7, 9, 'c'), 'C', 'd'));
        g.pxs('p', 9, 9, 9, 10, 9, 11, 16, 9, 16, 10, 16, 11);
        g.pxs('d', 8, 6, 9, 6, 15, 6, 16, 6);
        part(g, bevel(oval(4, 11, 17, 15, 'c'), 'C', 'd'));
        // big shiny eye, nose, whiskers, rosy cheek
        g.pxs('z', 8, 16, 9, 16, 8, 17, 9, 17, 8, 18, 9, 18).pxs('x', 8, 16);
        g.pxs('z', 4, 20, 4, 21).pxs('p', 5, 20);
        g.pxs('p', 10, 21, 11, 21);
        g.pxs('C', 12, 12, 13, 12, 14, 12);
        return g;
    }

    /** Beaver: round brown rodent, big shiny eye, whiskers, two big buck teeth and a wide cross-hatched paddle tail that slaps. */
    private static Grid beaver(int f)
    {
        Grid g = new Grid();
        Grid tail = bevel(oval(24, 21 + f, 14, 8, 'l'), 'L', 'z');
        for (int x = 26; x <= 36; x += 2)
        {
            for (int y = 22 + f; y <= 27 + f; y += 2) tail.set(x + (y % 4 == 0 ? 0 : 1), y, 'L');
        }
        part(g, tail);
        feet(g, new int[] {11, 14, 23}, 4, 28, 'm', (char) 0, 'z', f);
        Grid body = bevel(oval(10, 14, 20, 16, 'n'), 'N', 'm');
        with(body, oval(12, 23, 10, 6, 'N'));
        body.pxs('m', 24, 16, 26, 18, 27, 21);
        part(g, body);
        part(g, bevel(oval(14, 8, 5, 5, 'm'), 'n', 'z'));
        g.pxs('p', 15, 10);
        part(g, bevel(oval(4, 11, 16, 14, 'n'), 'N', 'm'));
        part(g, bevel(oval(2, 17, 9, 8, 'N'), 'x', 'n'));
        g.pxs('z', 2, 19, 2, 20, 3, 19);
        g.pxs('x', 5, 23, 6, 23, 5, 24, 6, 24).pxs('B', 5, 25);
        g.pxs('m', 7, 24, 8, 24);
        g.pxs('z', 9, 14, 10, 14, 9, 15, 10, 15, 9, 16, 10, 16).pxs('x', 9, 14);
        g.pxs('m', 7, 12, 8, 12, 11, 12, 12, 12);
        return g;
    }

    /** Giant squirrel: a dark little body with a huge bushy S-curved red-brown tail full of fur tufts. */
    private static Grid squirrel(int f)
    {
        Grid g = new Grid();
        double w = f * 1.2;
        Grid tail = blob(new double[][] {{26, 26, 2.6}, {31, 22, 3.6}, {34, 16, 4.4}, {33 + w * 0.5, 10, 4.4},
            {29 + w, 5, 4.0}, {24 + w, 4, 3.4}, {20 + w, 6, 2.4}}, 'r', true);
        bevel(tail, 'R', 'v');
        tail.pxs('v', 31, 19, 32, 20, 33, 14, 34, 15, 33, 9, 34, 10, 29, 6, 30, 7, 25, 6);
        tail.pxs('R', 31, 12, 32, 12, 30, 8, 29, 7, 26, 4, 27, 4, 35, 18);
        tail.pxs('x', 21 + (int) w, 5);
        part(g, tail);
        feet(g, new int[] {12, 22}, 4, 28, 'u', (char) 0, 'z', f);
        Grid body = bevel(oval(10, 19, 18, 12, 'q'), 'Q', 'u');
        with(body, oval(11, 25, 10, 5, 'Q'));
        part(g, body);
        part(g, bevel(oval(6, 14, 13, 12, 'q'), 'Q', 'u'));
        part(g, bevel(oval(10, 10, 4, 6, 'q'), 'Q', 'u'));
        part(g, bevel(oval(15, 11, 4, 5, 'q'), 'Q', 'u'));
        g.pxs('r', 11, 11, 16, 12);
        g.pxs('z', 8, 17, 9, 17, 8, 18, 9, 18, 8, 19, 9, 19).pxs('x', 8, 17);
        g.pxs('z', 6, 21, 6, 22);
        g.pxs('Q', 11, 16, 12, 16, 13, 16);
        return g;
    }

    /** Heron: a tall slim grey-white wader on long thin legs, an S-curved neck, a dagger beak and a small crest. */
    private static Grid heron(int f)
    {
        Grid g = new Grid();
        int dy = f;
        // long thin legs: one planted, one lifted and bent forward
        int ax = 18 + f;
        int bx = 22 - f;
        for (int y = 22; y <= 31; y++) g.set(ax, y, 'o');
        g.pxs('o', ax - 2, 32, ax - 1, 32, ax, 32);
        for (int y = 22; y <= 28; y++) g.set(bx, y, 'o');
        g.pxs('o', bx - 1, 29, bx - 2, 30, bx - 3, 30, bx - 4, 30);
        g.set(ax, 22, 'i');
        g.set(bx, 22, 'i');
        // tail feathers
        Grid tail = new Grid();
        tail.stamp(28, 16 + dy, "iiii", ".iiiii", "..iiii");
        part(g, tail);
        // slim body with a folded wing
        Grid body = bevel(oval(14, 13 + dy, 16, 9, 'h'), 'H', 'i');
        body.stamp(17, 15 + dy, "hiiiiiiii", "iiiiiiiiii", ".iiiiiiii");
        body.pxs('h', 20, 17 + dy, 23, 17 + dy, 26, 16 + dy);
        part(g, body);
        // S-curved neck
        Grid neck = new Grid();
        int[] nx = {14, 14, 13, 13, 12, 12, 12, 13, 13, 12, 12};
        for (int i = 0; i < nx.length; i++) neck.stamp(nx[i], 15 + dy - i, "HH");
        part(g, bevel(neck, 'H', 'h'));
        // small head, dagger beak, crest
        part(g, bevel(oval(8, 2 + dy, 7, 6, 'H'), (char) 0, 'h'));
        Grid beak = new Grid();
        beak.stamp(0, 4 + dy, "yyyyyyyy", ".yyyyyyy", "...yyyyy");
        part(g, beak);
        g.pxs('Y', 1, 4 + dy, 2, 4 + dy, 3, 4 + dy);
        g.pxs('z', 9, 4 + dy, 10, 4 + dy, 9, 5 + dy).pxs('x', 10, 3 + dy);
        g.pxs('z', 13, 2 + dy, 14, 2 + dy, 15, 3 + dy, 16, 4 + dy, 14, 3 + dy);
        g.pxs('z', 12, 8 + dy, 12, 9 + dy);
        return g;
    }

    /** Rift guardian: a small rough grey stone golem of loose lumpy rocks, a glowing rune core floating in a hollow chest. */
    private static Grid riftGuardian(int f)
    {
        Grid g = new Grid();
        int dy = f;
        // lumpy legs
        for (int i = 0; i < 2; i++)
        {
            boolean lifted = (i == 0) == (f == 1);
            int x = i == 0 ? 13 : 23;
            part(g, bevel(oval(x + (lifted ? 1 : 0), 26 - (lifted ? 1 : 0), 8, 7, 'g'), 'G', 'D'));
        }
        // floating rock arms
        part(g, bevel(oval(5, 14 + dy, 8, 8, 'g'), 'G', 'D'));
        part(g, bevel(oval(5, 23 + dy, 7, 7, 'g'), 'G', 'D'));
        part(g, bevel(oval(30, 15 + 1 - dy, 8, 8, 'g'), 'G', 'D'));
        part(g, bevel(oval(31, 24 + 1 - dy, 7, 7, 'g'), 'G', 'D'));
        // rocky body
        Grid t = oval(11, 13, 20, 15, 'g');
        with(t, oval(10, 17, 7, 7, 'g'));
        with(t, oval(25, 14, 7, 8, 'g'));
        with(t, oval(14, 22, 14, 7, 'g'));
        bevel(t, 'G', 'D');
        t.pxs('D', 13, 20, 14, 21, 28, 18, 29, 19, 15, 26, 16, 27, 27, 25, 26, 26);
        t.pxs('G', 14, 15, 15, 14, 26, 15);
        part(g, t);
        // hollow chest with the floating rune core
        part(g, oval(16, 17, 11, 9, 'z'));
        part(g, oval(18, 19, 7, 6, 'f'));
        with(g, oval(19, 20, 5, 4, 'a'));
        g.pxs('A', 21, 21, 22, 21, 21, 22).pxs('x', 21, 21);
        g.pxs('a', 17, 19, 25, 24, 18, 24);
        // lumpy head with glowing eyes
        Grid head = oval(14, 4, 14, 10, 'g');
        with(head, oval(13, 6, 5, 5, 'g'));
        with(head, oval(25, 3, 5, 5, 'g'));
        bevel(head, 'G', 'D');
        part(g, head);
        g.pxs('D', 17, 8, 18, 8, 23, 8, 24, 8);
        g.pxs('a', 17, 9, 18, 9, 23, 9, 24, 9).pxs('A', 17, 9, 23, 9);
        g.pxs('D', 20, 11, 21, 11, 22, 11, 21, 12);
        g.pxs('G', 18, 5, 19, 5, 27, 4);
        return g;
    }

    /** Rock golem: a small tan-brown boulder golem, hunched, with lumpy shoulders, big fists and a stubborn little face. */
    private static Grid rockGolem(int f)
    {
        Grid g = new Grid();
        int dy = f;
        feet(g, new int[] {13, 24}, 6, 28, 'e', 'b', 'z', f);
        part(g, bevel(oval(6, 15 + dy, 9, 9, 'b'), 'B', 'e'));
        part(g, bevel(oval(6, 22 + dy, 9, 8, 'b'), 'B', 'e'));
        part(g, bevel(oval(28, 16 + 1 - dy, 9, 9, 'b'), 'B', 'e'));
        part(g, bevel(oval(28, 23 + 1 - dy, 9, 7, 'b'), 'B', 'e'));
        Grid body = bevel(oval(11, 12, 21, 18, 'b'), 'B', 'e');
        body.pxs('B', 15, 15, 16, 14, 24, 15, 26, 17, 17, 22, 18, 22, 14, 19);
        body.pxs('e', 17, 24, 18, 25, 19, 26, 26, 21, 27, 22, 22, 28, 23, 27, 20, 18, 21, 19, 22, 20);
        part(g, body);
        Grid head = bevel(oval(13, 3, 15, 12, 'E'), 'B', 'e');
        part(g, head);
        g.pxs('e', 14, 8, 15, 8, 16, 8, 20, 8, 21, 8, 22, 8);
        g.pxs('z', 15, 9, 16, 9, 15, 10, 16, 10, 20, 9, 21, 9, 20, 10, 21, 10).pxs('x', 15, 9, 20, 9);
        g.pxs('B', 18, 5, 19, 5, 24, 6, 17, 4).pxs('e', 23, 13, 22, 13, 21, 13, 18, 12);
        g.pxs('b', 14, 4, 26, 5);
        return g;
    }

    /** Rocky: a raccoon, grey fur, black bandit mask, pointed muzzle, ringed bushy tail. */
    private static Grid rocky(int f)
    {
        Grid g = new Grid();
        // ringed tail
        Grid tail = new Grid();
        for (int i = 0; i <= 60; i++)
        {
            double t = i / 60.0;
            double cx = 28.5 + 6.5 * t + f * t * t * 1.5;
            double cy = 23 - 12 * t;
            double r = 3.4 - 0.9 * t;
            char c = Math.min(5, (int) (t * 6)) % 2 == 0 ? 'j' : 'u';
            for (int y = 0; y < 34; y++)
            {
                for (int x = 0; x < 42; x++)
                {
                    if (Math.hypot(x + 0.5 - cx, y + 0.5 - cy) <= r) tail.set(x, y, c);
                }
            }
        }
        part(g, tail);
        feet(g, new int[] {12, 24}, 4, 29, 'K', (char) 0, 'z', f);
        Grid body = bevel(oval(10, 17, 20, 14, 'j'), 'J', 'K');
        with(body, oval(12, 25, 10, 6, 'J'));
        part(g, body);
        part(g, bevel(oval(10, 8, 5, 6, 'j'), 'J', 'K'));
        part(g, bevel(oval(16, 8, 5, 6, 'j'), 'J', 'K'));
        g.pxs('z', 12, 10, 12, 11, 18, 10, 18, 11);
        part(g, bevel(oval(5, 11, 17, 13, 'j'), 'J', 'K'));
        // muzzle, bandit mask, eye
        part(g, bevel(oval(2, 17, 9, 7, 'J'), 'x', 'j'));
        Grid mask = rect(7, 15, 12, 4, 'z');
        mask.pxs('z', 6, 16, 6, 17, 7, 19, 8, 19);
        with(g, mask);
        g.pxs('x', 9, 16, 10, 16, 9, 17).pxs('z', 10, 17);
        g.pxs('z', 2, 18, 2, 19, 3, 18);
        g.pxs('J', 14, 14, 15, 14, 16, 14);
        g.pxs('z', 4, 22, 5, 22);
        return g;
    }

    /** Soup: a turtle, brown-green plated shell, olive skin, round head and paddle flippers. */
    private static Grid soup(int f)
    {
        Grid g = new Grid();
        // tail
        part(g, bevel(trap(35, 25, 28, 1, 3, 'P'), (char) 0, 'O'));
        // back flipper
        part(g, bevel(oval(26 - f * 2, 27 + f, 8, 5, 'P'), 'M', 'O'));
        // underside rim and shell
        part(g, bevel(oval(10, 23, 24, 7, 'T'), (char) 0, 'S'));
        Grid shell = bevel(oval(9, 13, 25, 16, 'S'), 'T', 'U');
        shell.pxs('U', 21, 15, 21, 16, 21, 17, 21, 24, 21, 25, 21, 26, 22, 26);
        shell.pxs('U', 14, 18, 15, 19, 16, 20, 17, 21, 18, 22, 28, 18, 27, 19, 26, 20, 25, 21, 24, 22);
        shell.pxs('U', 16, 25, 17, 25, 18, 25, 25, 25, 26, 25, 27, 25);
        shell.pxs('T', 18, 15, 19, 15, 24, 15, 25, 16, 12, 22, 13, 21, 30, 22, 31, 23);
        part(g, shell);
        // head on a short neck
        part(g, bevel(rect(8, 21, 6, 5, 'P'), 'M', 'O'));
        part(g, bevel(oval(2, 15 + f, 10, 9, 'P'), 'M', 'O'));
        g.pxs('z', 5, 18 + f, 6, 18 + f, 5, 19 + f, 6, 19 + f).pxs('x', 5, 18 + f);
        g.pxs('O', 2, 21 + f, 3, 22 + f, 4, 22 + f);
        // front flipper
        part(g, bevel(oval(9 + f * 2, 27 + f, 8, 5, 'P'), 'M', 'O'));
        return g;
    }

    /** Tangleroot: a little walking stump with twiggy arms, root feet, mossy bark and a leafy sprout on its head. */
    private static Grid tangleroot(int f)
    {
        Grid g = new Grid();
        int dy = f;
        // root feet
        feet(g, new int[] {14, 23}, 5, 28, 'X', 'W', 'z', f);
        // twig arms
        Grid armL = new Grid();
        armL.stamp(8, 17 + dy, "WW.", ".WW", ".WW", "..W", "..W");
        armL.stamp(6, 15 + dy, "W");
        armL.stamp(6, 21 + dy, "W.W");
        part(g, armL);
        Grid armR = new Grid();
        armR.stamp(31, 18 - dy + 1, ".WW", "WW.", "WW.", "W..", "W..");
        armR.stamp(35, 16 - dy + 1, "W");
        part(g, armR);
        // trunk and head bulge
        Grid trunk = bevel(trap(21, 19, 29, 8, 9, 'W'), 'V', 'X');
        trunk.pxs('X', 16, 24, 16, 25, 16, 26, 22, 25, 22, 26, 22, 27, 27, 23, 27, 24, 20, 22);
        trunk.pxs('1', 25, 28, 26, 28, 15, 22);
        part(g, trunk);
        Grid head = bevel(oval(11, 11, 20, 14, 'W'), 'V', 'X');
        head.pxs('X', 14, 13, 15, 14, 27, 13, 26, 14, 21, 12, 22, 12);
        part(g, head);
        // face
        g.pxs('X', 14, 16, 15, 16, 16, 16, 21, 16, 22, 16, 23, 16);
        g.pxs('A', 15, 17, 16, 17, 22, 17, 23, 17).pxs('z', 15, 18, 16, 18, 22, 18, 23, 18);
        g.pxs('z', 18, 21, 19, 21, 20, 21, 17, 20, 21, 20);
        // leafy sprout
        Grid stem = new Grid();
        stem.stamp(20, 6, "W", "W", "W", "W");
        part(g, stem);
        g.pxs('W', 21, 10);
        Grid leafL = bevel(oval(10, 1 + f, 11, 6, '1'), '2', '3');
        leafL.pxs('3', 14, 4 + f, 15, 4 + f, 16, 4 + f, 17, 4 + f);
        part(g, leafL);
        Grid leafR = bevel(oval(21, 3 - f, 9, 5, '1'), '2', '3');
        leafR.pxs('3', 23, 5 - f, 24, 5 - f, 25, 5 - f);
        part(g, leafR);
        return g;
    }
}

package com.forgebingo.core;

import com.forgebingo.core.PixelArt.Grid;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Pixel art for some of the pets (see Pet): the Abyssal protector, Bloodhound, Chompy chick, Herbi, Lil' Creator,
 * Mr McGroot, Pet Penance Queen and Quetzin. Original chunky chibi art in the style of CryptSprites: big head, 1px dark
 * outline, 2-3 shades per colour, two walk frames. Facing LEFT, feet on the bottom rows, body centred on column 21.
 * Returns null for a pet this file does not draw.
 */
public final class PetSpritesB
{
    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private PetSpritesB()
    {
    }

    /** One walk frame (0 or 1) on the PixelArt.WIDTH x PixelArt.HEIGHT grid, facing left, feet on the bottom rows. */
    public static BufferedImage image(Pet pet, int frame)
    {
        if (pet == null) return null;
        switch (pet)
        {
            case ABYSSAL_PROTECTOR: case BLOODHOUND: case CHOMPY_CHICK: case HERBI:
            case LIL_CREATOR: case MR_MCGROOT: case PENANCE_QUEEN: case QUETZIN:
                break;
            default:
                return null;
        }
        int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(pet + "|" + f, k -> PixelArt.render(build(pet, f), PetSpritesB::colour));
    }

    private static int colour(int c)
    {
        switch ((char) c)
        {
            case 'k': return 0x16140f; // outline
            case 'z': return 0x1d1a22; // darkest
            case 'x': return 0xfff6dc; // highlight white
            case 'c': return 0x55555e; // stone grey
            case 'C': return 0x82828e;
            case 'u': return 0x33333b;
            case 'i': return 0x2fd0c0; // teal glow
            case 'I': return 0xa6f6ea;
            case 'J': return 0x1a8088;
            case 'p': return 0x7a4aa0; // purple
            case 'P': return 0x4a2868;
            case 'q': return 0xa87ccc;
            case 'r': return 0x8a5a36; // brown
            case 'R': return 0x4e301c;
            case 'j': return 0xb88252;
            case 't': return 0xdcbc84; // tan
            case 'T': return 0xf2e0b0;
            case 's': return 0xa88650;
            case 'g': return 0x4f9a3c; // green
            case 'G': return 0x86d05e;
            case 'H': return 0x2c6030;
            case 'm': return 0xa6c890; // pale green
            case 'M': return 0xd4ecba;
            case 'n': return 0x6f9670;
            case 'a': return 0xd8342a; // red
            case 'A': return 0xff7c50;
            case 'o': return 0xf0a020; // orange
            case 'O': return 0xffd460;
            case 'Q': return 0xb86418;
            case 'b': return 0x2aa890; // blue-green
            case 'B': return 0x70e4cc;
            case 'd': return 0x186a74;
            case 'y': return 0xf8d838; // yellow
            case 'Y': return 0xfff48a;
            case 'e': return 0xe6dcc4; // bone/cream
            case 'E': return 0xb0a488;
            case 'K': return 0x1f4a24; // far wing: dark green
            case 'L': return 0x14525c; // far wing: dark teal
            case 'N': return 0x2e7a56; // far wing tips
            case 'w': return 0x6a4a28; // wood/hoof
            case 'W': return 0x3e2a14;
            default: return 0xff00ff;
        }
    }

    // ---------------------------------------------------------------- helpers

    private static Grid rect(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++) m.set(x + i, y + j, c);
        }
        return m;
    }

    private static Grid oval(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        double cx = x + w / 2.0;
        double cy = y + h / 2.0;
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++)
            {
                double dx = (x + i + 0.5 - cx) / (w / 2.0);
                double dy = (y + j + 0.5 - cy) / (h / 2.0);
                if (dx * dx + dy * dy <= 1.0) m.set(x + i, y + j, c);
            }
        }
        return m;
    }

    private static Grid trap(int cx, int y0, int y1, double hw0, double hw1, char c)
    {
        Grid m = new Grid();
        for (int y = y0; y <= y1; y++)
        {
            double t = y1 == y0 ? 0 : (double) (y - y0) / (y1 - y0);
            int hw = (int) Math.round(hw0 + (hw1 - hw0) * t);
            for (int x = cx - hw; x < cx + hw; x++) m.set(x, y, c);
        }
        return m;
    }

    private static Grid ellipseRot(double cx, double cy, double a, double b, double deg, char c)
    {
        Grid m = new Grid();
        double r = Math.toRadians(deg);
        double cs = Math.cos(r);
        double sn = Math.sin(r);
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                double dx = x + 0.5 - cx;
                double dy = y + 0.5 - cy;
                double u = dx * cs + dy * sn;
                double v = -dx * sn + dy * cs;
                if (u * u / (a * a) + v * v / (b * b) <= 1) m.set(x, y, c);
            }
        }
        return m;
    }

    /** Light on the top-left edge, dark on the bottom-right edge (0 to skip one). */
    private static Grid bevel(Grid m, char light, char dark)
    {
        char[][] src = new char[m.h][];
        for (int j = 0; j < m.h; j++) src[j] = m.px[j].clone();
        for (int j = 0; j < m.h; j++)
        {
            for (int i = 0; i < m.w; i++)
            {
                if (src[j][i] == 0) continue;
                boolean top = j == 0 || src[j - 1][i] == 0;
                boolean left = i == 0 || src[j][i - 1] == 0;
                boolean bottom = j == m.h - 1 || src[j + 1][i] == 0;
                boolean right = i == m.w - 1 || src[j][i + 1] == 0;
                if (dark != 0 && (bottom || right)) m.px[j][i] = dark;
                else if (light != 0 && (top || left)) m.px[j][i] = light;
            }
        }
        return m;
    }

    private static Grid with(Grid a, Grid b)
    {
        for (int j = 0; j < b.h; j++)
        {
            for (int i = 0; i < b.w; i++)
            {
                if (b.px[j][i] != 0) a.set(i, j, b.px[j][i]);
            }
        }
        return a;
    }

    private static void part(Grid g, Grid fill)
    {
        PixelArt.part(g, fill, 'k');
    }

    private static void line(Grid m, int x0, int y0, int x1, int y1, char c)
    {
        int n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
        for (int i = 0; i <= n; i++)
        {
            m.set((int) Math.round(x0 + (x1 - x0) * (double) i / n), (int) Math.round(y0 + (y1 - y0) * (double) i / n), c);
        }
    }

    /**
     * Four legs; diagonal pairs alternate. A lifted leg swings forward (left) and is 2px shorter, a planted leg
     * is pushed back (right). Legs end on row 32.
     */
    private static void legs4(Grid g, int[] xs, int top, int w, char c, char foot, int f)
    {
        for (int i = 0; i < xs.length; i++)
        {
            boolean fwd = (i % 2 == 0) == (f == 1);
            int lift = fwd ? 2 : 0;
            int x = xs[i] + (fwd ? -1 : 1);
            Grid l = bevel(rect(x, top, w, 33 - top - lift, c), (char) 0, 'R');
            if (foot != 0) with(l, rect(x, 32 - lift, w, 1, foot));
            part(g, l);
        }
    }

    /** A tapering round-brush stroke along the polyline through the given x, y points. */
    private static Grid stroke(char c, double w0, double w1, int... p)
    {
        Grid m = new Grid();
        int segs = p.length / 2 - 1;
        int n = segs * 24;
        for (int s = 0; s <= n; s++)
        {
            double t = s / (double) n;
            double ft = t * segs;
            int k = Math.min(segs - 1, (int) ft);
            double u = ft - k;
            double x = p[2 * k] + (p[2 * k + 2] - p[2 * k]) * u + 0.5;
            double y = p[2 * k + 1] + (p[2 * k + 3] - p[2 * k + 1]) * u + 0.5;
            double r = Math.max(0.7, (w0 + (w1 - w0) * t) / 2);
            for (int j = (int) (y - r - 1); j <= y + r + 1; j++)
            {
                for (int i = (int) (x - r - 1); i <= x + r + 1; i++)
                {
                    if (Math.hypot(i + 0.5 - x, j + 0.5 - y) <= r) m.set(i, j, c);
                }
            }
        }
        return m;
    }

    private static Grid build(Pet pet, int f)
    {
        switch (pet)
        {
            case ABYSSAL_PROTECTOR: return protector(f);
            case BLOODHOUND: return bloodhound(f);
            case CHOMPY_CHICK: return chompy(f);
            case HERBI: return herbi(f);
            case LIL_CREATOR: return creator(f);
            case MR_MCGROOT: return goat(f);
            case PENANCE_QUEEN: return queen(f);
            default: return quetzin(f);
        }
    }

    // ---------------------------------------------------------------- pets

    /** Abyssal protector: faceted dark stone cone with a glowing teal band and stubby arms, hovering on a purple base. */
    private static Grid protector(int f)
    {
        Grid g = new Grid();
        int dy = -f;
        // purple base: a wobbling disc with a glossy rim
        part(g, bevel(oval(9 - f, 27, 24 + 2 * f, 7, 'p'), 'q', 'P'));
        part(g, bevel(oval(13, 25, 16, 5, 'P'), 'p', 'z'));
        g.pxs('q', 12, 29, 13, 29, 28, 30, 29, 30);
        // stubby arms that swing up and down
        part(g, bevel(oval(7, 18 + (f == 0 ? 1 : -1) + dy, 7, 5, 'c'), 'C', 'u'));
        part(g, bevel(oval(28, 18 + (f == 0 ? -1 : 1) + dy, 7, 5, 'c'), 'C', 'u'));
        // stone cone with a lit left face and a shaded right face
        Grid cone = trap(21, 2 + dy, 24 + dy, 1, 8, 'c');
        for (int y = 2 + dy; y <= 24 + dy; y++)
        {
            for (int x = 0; x < 21; x++)
            {
                if (cone.has(x, y)) cone.set(x, y, 'C');
            }
            if (cone.has(21, y)) cone.set(21, y, 'u');
        }
        part(g, cone);
        g.pxs('x', 20, 4 + dy, 20, 5 + dy, 19, 8 + dy, 18, 11 + dy);
        // glowing teal band with a bright core
        Grid band = bevel(trap(21, 20 + dy, 25 + dy, 7, 9, 'i'), 'I', 'J');
        part(g, band);
        g.pxs('I', 16, 22 + dy, 17, 22 + dy, 21, 22 + dy, 22, 22 + dy, 26, 23 + dy);
        // face: two glowing eyes and a small mouth
        g.pxs('z', 16, 13 + dy, 17, 13 + dy, 18, 13 + dy, 24, 13 + dy, 25, 13 + dy, 26, 13 + dy);
        g.pxs('i', 17, 14 + dy, 18, 14 + dy, 25, 14 + dy, 26, 14 + dy);
        g.pxs('I', 17, 14 + dy, 25, 14 + dy);
        g.pxs('u', 20, 17 + dy, 21, 17 + dy, 22, 17 + dy);
        return g;
    }

    /** Bloodhound: brown and tan dog, long droopy ear, little green hat; head bobs, legs alternate, tail wags. */
    private static Grid bloodhound(int f)
    {
        Grid g = new Grid();
        int hd = f;
        // tail wags up and down
        Grid tail = stroke('r', 3, 2, 32, 18, 35, 15 - 2 * f, 36, 12 - 3 * f);
        part(g, bevel(tail, 'j', 'R'));
        legs4(g, new int[] {8, 12, 26, 30}, 24, 3, 'r', 't', f);
        part(g, bevel(oval(11, 14, 24, 13, 'r'), 'j', 'R'));
        part(g, bevel(oval(14, 21, 16, 6, 't'), 'T', 's'));
        g.pxs('R', 18, 17, 24, 16, 29, 18, 21, 18);
        // head, tan muzzle, black nose
        part(g, bevel(oval(3, 9 + hd, 15, 14, 'r'), 'j', 'R'));
        part(g, bevel(oval(0, 16 + hd, 10, 8, 't'), 'T', 's'));
        part(g, rect(0, 16 + hd, 3, 2, 'z'));
        g.pxs('x', 1, 16 + hd);
        g.pxs('R', 3, 22 + hd, 4, 22 + hd, 5, 22 + hd, 6, 21 + hd);
        // eye with a bright spot and a worried brow
        g.pxs('z', 8, 14 + hd, 9, 14 + hd, 8, 15 + hd, 9, 15 + hd).pxs('x', 8, 14 + hd);
        g.pxs('R', 7, 12 + hd, 8, 12 + hd, 9, 13 + hd);
        // long droopy ear that swings
        part(g, bevel(oval(12, 11 + hd, 6, 15 + f, 'R'), 'r', 'W'));
        g.pxs('r', 13, 13 + hd, 13, 14 + hd);
        // little green hat with a band and feather
        Grid hat = bevel(trap(10, 3 + hd, 9 + hd, 3, 5, 'g'), 'G', 'H');
        with(hat, rect(5, 9 + hd, 11, 2, 'H'));
        part(g, hat);
        g.pxs('y', 8, 8 + hd, 9, 8 + hd, 10, 8 + hd, 11, 8 + hd);
        g.pxs('a', 13, 2 + hd, 13, 3 + hd);
        return g;
    }

    /** Chompy chick: plump tan baby bird, long neck, folded feathered wing, blue-green tail, big orange feet. */
    private static Grid chompy(int f)
    {
        Grid g = new Grid();
        int dy = -f;
        // tail feathers that flick
        Grid tail = new Grid();
        tail.stamp(29, 12 + dy - f, "..bB", "..bB", ".bBb", ".bBd", "bBbd", "bBd.");
        tail.stamp(30, 19 + dy, "bBbb", "bBb.");
        part(g, tail);
        // big webbed feet that clearly swap
        for (int i = 0; i < 2; i++)
        {
            boolean fwd = (i == 0) == (f == 1);
            int x = (i == 0 ? 11 : 20) + (fwd ? -1 : 1);
            int lift = fwd ? 2 : 0;
            Grid foot = bevel(rect(x + 2, 27, 2, 5 - lift, 'o'), (char) 0, 'Q');
            with(foot, rect(x - 1, 32 - lift, 8, 1, 'o'));
            foot.set(x - 1, 32 - lift, 'Q');
            foot.set(x + 2, 32 - lift, 'O');
            foot.set(x + 6, 32 - lift, 'Q');
            part(g, foot);
        }
        part(g, bevel(oval(10, 15 + dy, 21, 15, 't'), 'T', 's'));
        g.pxs('T', 14, 21 + dy, 15, 20 + dy);
        // folded wing: pointed back, rows of feather tips
        Grid wing = new Grid();
        wing.stamp(16, 19 + dy,
            ".TTTTTtt...",
            "TtttttttT..",
            "ttsttsttstt",
            "ssssssssss.",
            ".ssTssTss..");
        part(g, wing);
        g.pxs('R', 18, 21 + dy, 21, 21 + dy, 24, 21 + dy, 20, 22 + dy, 23, 22 + dy);
        // neck and head bob
        part(g, bevel(rect(9, 7 + dy, 5, 14, 't'), 'T', 's'));
        part(g, bevel(oval(5, 2 + dy, 12, 9, 't'), 'T', 's'));
        part(g, bevel(trap(3, 5 + dy, 8 + dy, 1, 3, 'o'), 'O', 'Q'));
        g.pxs('Q', 2, 7 + dy, 3, 7 + dy);
        g.pxs('z', 9, 5 + dy, 10, 5 + dy, 9, 6 + dy, 10, 6 + dy).pxs('x', 9, 5 + dy);
        g.pxs('A', 7, 8 + dy, 8, 8 + dy);
        g.pxs('s', 11, 2 + dy, 12, 1 + dy, 13, 2 + dy);
        return g;
    }

    /** Herbi: little boar with a back full of herbs and leaves, small tusks; head bobs, legs alternate. */
    private static Grid herbi(int f)
    {
        Grid g = new Grid();
        int hd = f;
        Grid tail = stroke('r', 2, 2, 33, 18, 35, 16 - f, 36, 14 - f);
        part(g, tail);
        legs4(g, new int[] {8, 12, 27, 31}, 25, 4, 'w', 'W', f);
        part(g, bevel(oval(11, 15, 23, 12, 'r'), 'j', 'R'));
        // herbs and leaves sprouting up the back and swaying a little
        Grid leaves = new Grid();
        with(leaves, ellipseRot(15, 12, 4.5, 2.2, -50 + 8 * f, 'g'));
        with(leaves, ellipseRot(21, 9, 4.8, 2.2, -100, 'G'));
        with(leaves, ellipseRot(27, 12, 4.5, 2.2, -135 - 8 * f, 'g'));
        with(leaves, ellipseRot(21, 14, 7, 2.6, 0, 'H'));
        part(g, leaves);
        g.pxs('G', 15, 11, 21, 7, 26, 11, 21, 8).pxs('a', 18, 13).pxs('y', 24, 13).pxs('A', 19, 12);
        g.pxs('j', 14, 17, 15, 16, 20, 16);
        part(g, bevel(oval(3, 14 + hd, 13, 12, 'r'), 'j', 'R'));
        part(g, bevel(oval(0, 19 + hd, 8, 6, 't'), 'T', 's'));
        g.pxs('z', 0, 20 + hd, 1, 20 + hd, 1, 21 + hd);
        g.pxs('x', 3, 25 + hd, 3, 24 + hd, 3, 23 + hd, 7, 25 + hd, 7, 24 + hd, 7, 23 + hd);
        g.pxs('z', 8, 18 + hd, 9, 18 + hd, 8, 19 + hd, 9, 19 + hd).pxs('x', 8, 18 + hd);
        g.pxs('R', 7, 16 + hd, 8, 16 + hd, 9, 17 + hd);
        part(g, bevel(oval(10, 11 + hd, 5, 5, 'r'), 'j', 'R'));
        g.pxs('a', 12, 13 + hd);
        return g;
    }

    /** Lil' Creator: pale green horned creature with a fierce-cute face, on little legs. */
    private static Grid creator(int f)
    {
        Grid g = new Grid();
        int hd = f;
        for (int i = 0; i < 2; i++)
        {
            boolean fwd = (i == 0) == (f == 1);
            int x = (i == 0 ? 15 : 23) + (fwd ? -1 : 1);
            int lift = fwd ? 2 : 0;
            part(g, bevel(rect(x, 28, 4, 5 - lift, 'n'), (char) 0, 'H'));
        }
        // body with a belly highlight; arms swing
        part(g, bevel(oval(14, 21, 14, 10, 'm'), 'M', 'n'));
        g.pxs('M', 18, 25, 19, 25, 20, 26);
        part(g, bevel(oval(10, 22 + f, 5, 5, 'm'), 'M', 'n'));
        part(g, bevel(oval(27, 22 + (1 - f), 5, 5, 'm'), 'M', 'n'));
        // long swept-back horns
        Grid horns = stroke('e', 4, 1, 12, 10 + hd, 8, 7 + hd, 5, 2 + hd);
        with(horns, stroke('e', 4, 1, 30, 10 + hd, 34, 7 + hd, 37, 2 + hd));
        bevel(horns, 'x', 'E');
        part(g, horns);
        // wide head
        part(g, bevel(oval(9, 6 + hd, 24, 16, 'm'), 'M', 'n'));
        g.pxs('x', 14, 8 + hd, 15, 8 + hd, 16, 7 + hd);
        // fierce eyes: bright, slanted brows
        part(g, bevel(oval(13, 12 + hd, 6, 5, 'x'), (char) 0, 'Y'));
        part(g, bevel(oval(23, 12 + hd, 6, 5, 'x'), (char) 0, 'Y'));
        g.pxs('z', 16, 13 + hd, 17, 13 + hd, 16, 14 + hd, 17, 14 + hd, 24, 13 + hd, 25, 13 + hd, 24, 14 + hd, 25, 14 + hd);
        g.pxs('H', 12, 10 + hd, 13, 10 + hd, 14, 11 + hd, 15, 11 + hd, 16, 12 + hd, 17, 12 + hd);
        g.pxs('H', 30, 10 + hd, 29, 10 + hd, 28, 11 + hd, 27, 11 + hd, 26, 12 + hd, 25, 12 + hd);
        g.pxs('n', 20, 15 + hd, 22, 15 + hd);
        // wide fanged grin and a glowing chin gem
        g.pxs('z', 16, 18 + hd, 17, 19 + hd, 18, 19 + hd, 19, 19 + hd, 20, 19 + hd, 21, 19 + hd, 22, 19 + hd, 23, 19 + hd,
            24, 19 + hd, 25, 18 + hd);
        g.pxs('x', 18, 18 + hd, 24, 18 + hd);
        g.pxs('i', 20, 21 + hd, 21, 21 + hd).pxs('I', 20, 21 + hd);
        return g;
    }

    /** Mr McGroot: brown mountain goat, big curved shaded horns, a goatee; head bobs, legs alternate. */
    private static Grid goat(int f)
    {
        Grid g = new Grid();
        int hd = f;
        Grid tail = stroke('r', 3, 2, 33, 16, 35, 14 - f, 36, 12 - f);
        part(g, tail);
        legs4(g, new int[] {11, 15, 27, 31}, 25, 2, 'r', 'W', f);
        part(g, bevel(oval(11, 14, 25, 13, 'r'), 'j', 'R'));
        part(g, bevel(oval(15, 21, 15, 5, 't'), 'T', 's'));
        g.pxs('R', 18, 17, 25, 16, 30, 18, 22, 18);
        // neck
        part(g, bevel(oval(8, 11, 10, 13, 'r'), 'j', 'R'));
        // two ram horns, thick at the base, sweeping back and curling down in a tight C; ridged, with a highlight
        Grid horn = stroke('e', 4, 2, 11, 11 + hd, 12, 6 + hd, 17, 3 + hd, 22, 6 + hd, 22, 10 + hd, 19, 12 + hd);
        bevel(horn, 'x', 'E');
        for (int[] r : new int[][] {{12, 7}, {15, 4}, {20, 4}, {22, 8}}) horn.pxs('E', r[0], r[1] + hd, r[0] + 1, r[1] + 1 + hd);
        part(g, horn);
        // goat head: round skull, long narrow muzzle sloping down to a small pale nose
        part(g, bevel(stroke('r', 9, 4, 11, 12 + hd, 8, 16 + hd, 4, 21 + hd), 'j', 'R'));
        part(g, bevel(stroke('t', 3, 3, 6, 19 + hd, 3, 21 + hd), 'T', 's'));
        part(g, bevel(oval(1, 20 + hd, 4, 3, 'T'), 'x', 's'));
        g.pxs('z', 1, 21 + hd, 2, 21 + hd);
        g.pxs('R', 5, 22 + hd, 6, 22 + hd);
        // eye set high with a horizontal slit pupil, and a sideways leaf-shaped ear
        g.pxs('R', 8, 11 + hd, 9, 11 + hd, 10, 11 + hd);
        g.pxs('y', 8, 12 + hd, 11, 12 + hd).pxs('z', 9, 12 + hd, 10, 12 + hd);
        Grid ear = ellipseRot(16.5, 13.5 + hd, 4.2, 1.7, -12, 'r');
        bevel(ear, 'j', 'R');
        part(g, ear);
        g.pxs('R', 14, 13 + hd, 15, 13 + hd, 16, 13 + hd);
        // pointed goatee
        Grid beard = new Grid();
        beard.stamp(4, 22 + hd, "ee", "xe", ".e", ".E");
        part(g, beard);
        return g;
    }

    /** Pet Penance Queen: pale slug queen: ringed tall neck, red crest, segmented bulbous base that wobbles. */
    private static Grid queen(int f)
    {
        Grid g = new Grid();
        int w = f;
        // three stacked body segments, each a little wider on alternate frames
        part(g, bevel(oval(8 - w, 26, 26 + 2 * w, 8 - w, 'm'), 'M', 'n'));
        part(g, bevel(oval(11 + w, 22, 20 - 2 * w, 7, 'm'), 'M', 'n'));
        part(g, bevel(oval(14 - w, 18, 14 + 2 * w, 7, 'm'), 'M', 'n'));
        g.pxs('M', 11, 28, 12, 28, 14, 24, 15, 24, 17, 20, 18, 20);
        g.pxs('n', 27, 30, 29, 29, 25, 26, 22, 24, 24, 21);
        // neck: stacked rows that lean with the wobble, with ring lines
        Grid neck = new Grid();
        for (int y = 10; y <= 19; y++)
        {
            int ox = (int) Math.round(f * (19 - y) / 8.0);
            for (int x = 19; x < 23; x++) neck.set(x + ox, y, y % 3 == 0 ? 'n' : (x == 19 ? 'M' : (x >= 22 ? 'n' : 'm')));
        }
        part(g, neck);
        int nx = 19 + f;
        // head with snout, eye, red three-spike crest
        part(g, bevel(oval(nx - 4, 3, 10, 8, 'm'), 'M', 'n'));
        Grid crest = new Grid();
        crest.stamp(nx - 1, 0, "a.a.a", "aAaAa", "yyyyy");
        part(g, crest);
        g.pxs('z', nx - 2, 6, nx + 1, 6);
        g.pxs('A', nx - 3, 8, nx + 2, 8);
        g.pxs('M', nx - 2, 4, nx - 1, 4);
        return g;
    }

    /** Quetzin: bright green bird, two feathered wings with teal bands and yellow tips, hopping with flapping wings. */
    private static Grid quetzin(int f)
    {
        Grid g = new Grid();
        int dy = -f;
        // far wing (behind): same fan, darker, rotated slightly
        wing(g, 19, 17 + dy, f == 0 ? -92 : -62, f == 0 ? -48 : -22, 4, 10, 13, true);
        // legs alternate while hopping
        for (int i = 0; i < 2; i++)
        {
            boolean fwd = (i == 0) == (f == 1);
            int x = (i == 0 ? 15 : 22) + (fwd ? -1 : 1);
            int lift = fwd ? 2 : 0;
            part(g, bevel(rect(x, 27 + dy, 2, 6 - dy - lift, 'o'), (char) 0, 'Q'));
            part(g, rect(x - 2, 32 - lift, 4, 1, 'o'));
        }
        // long tail feathers with teal bands
        Grid tail = new Grid();
        tail.stamp(29, 22 + dy, "..bd", ".bBd", "bBBd", "bBd.", "bd..");
        tail.stamp(28, 19 + dy, "ggg", "gG.");
        tail.stamp(31, 28 + dy, "yy", ".y");
        part(g, tail);
        part(g, bevel(oval(12, 15 + dy, 19, 14, 'g'), 'G', 'H'));
        part(g, bevel(oval(13, 22 + dy, 11, 6, 'y'), 'Y', 'o'));
        part(g, bevel(oval(6, 8 + dy, 13, 12, 'g'), 'G', 'H'));
        g.pxs('b', 10, 8 + dy, 11, 8 + dy, 12, 8 + dy).pxs('B', 11, 7 + dy, 12, 7 + dy);
        part(g, bevel(trap(4, 13 + dy, 16 + dy, 1, 3, 'o'), 'O', 'Q'));
        g.pxs('z', 9, 12 + dy, 10, 12 + dy, 9, 13 + dy, 10, 13 + dy).pxs('x', 9, 12 + dy);
        // near wing: fan of feathers, half open, flapping
        wing(g, 22, 18 + dy, f == 0 ? -70 : -38, f == 0 ? -20 : 14, 4, 12, 16, false);
        return g;
    }

    /** A fan of n feathers from a root at angles a0..a1 (degrees, 0 = straight back, negative = up). */
    private static void wing(Grid g, double bx, double by, double a0, double a1, int n, double len0, double len1, boolean far)
    {
        Grid all = new Grid();
        for (int i = n - 1; i >= 0; i--)
        {
            double t = n == 1 ? 0 : i / (double) (n - 1);
            double deg = a1 + (a0 - a1) * t;
            double len = len0 + (len1 - len0) * t;
            with(all, feather(bx, by, len, deg, far));
        }
        part(g, all);
    }

    /** One feather: green quill end, teal band, yellow tip (dark versions for the far wing). */
    private static Grid feather(double bx, double by, double len, double deg, boolean far)
    {
        Grid m = new Grid();
        double r = Math.toRadians(deg);
        double dx = Math.cos(r);
        double dy = Math.sin(r);
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                double ux = x + 0.5 - bx;
                double uy = y + 0.5 - by;
                double u = ux * dx + uy * dy;
                double v = -ux * dy + uy * dx;
                if (u < 0 || u > len) continue;
                double hw = u > len * 0.7 ? 2.4 * (1 - 0.8 * (u - len * 0.7) / (len * 0.3)) : 2.4;
                if (Math.abs(v) > hw) continue;
                double t = u / len;
                boolean low = v > hw - 1.0;
                char c;
                if (far) c = t < 0.4 ? 'K' : (t < 0.7 ? 'L' : (low ? 'K' : 'N'));
                else if (t < 0.4) c = low ? 'H' : (v < -0.8 ? 'G' : 'g');
                else if (t < 0.7) c = low ? 'd' : (v < -0.8 ? 'B' : 'b');
                else c = low ? 'o' : (v < 0 ? 'Y' : 'y');
                m.set(x, y, c);
            }
        }
        return m;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.util.Map;
import org.junit.Test;

/**
 * Proof that baking the pets changed no pixel: what the plugin loads from sprites/pets.png (PetSprites) is exactly
 * what the art code (PetSpritesA..F via PetArt) draws, for every pet and both frames. Fails when the art is edited
 * without re-baking. With the FORGE_BAKE environment variable set it re-bakes instead (see PetSheetBaker).
 */
public class PetSpritesBakedTest
{
    @Test
    public void everyPetFrameLoadedFromTheSheetIsPixelForPixelTheDrawnOne() throws Exception
    {
        if (SheetBaker.bakeRequested())
        {
            PetSheetBaker.bake();
            return;
        }
        int compared = 0;
        int pictures = 0;
        for (Pet p : Pet.values())
        {
            for (int f = 0; f < 2; f++)
            {
                BufferedImage drawn = PetArt.image(p, f);
                SheetBaker.assertSame(p + " frame " + f, drawn, PetSprites.image(p, f), PetSheetBaker.REBAKE);
                compared++;
                if (drawn != null) pictures++;
            }
            assertEquals(p + " drawn()", PetArt.image(p, 0) != null, PetSprites.drawn(p));
        }
        assertEquals(Pet.values().length * 2, compared);
        assertTrue("some pets are drawn", pictures > 0);
        System.out.println("PetSpritesBakedTest: compared " + compared + " pet x frame images, " + pictures + " with a picture");
    }

    @Test
    public void theLoaderKeepsTheOldContract()
    {
        Pet drawn = null;
        for (Pet p : Pet.values()) if (PetArt.image(p, 0) != null) { drawn = p; break; }
        if (drawn == null || SheetBaker.bakeRequested()) return;
        // null pet -> null; any frame other than 0 is the second frame; the same cached instance every call
        assertEquals(null, PetSprites.image(null, 0));
        assertSame(PetSprites.image(drawn, 0), PetSprites.image(drawn, 0));
        assertSame(PetSprites.image(drawn, 1), PetSprites.image(drawn, 7));
        assertSame(PetSprites.image(drawn, 1), PetSprites.image(drawn, -1));
        for (Map.Entry<String, BufferedImage> e : PetSheetBaker.drawn().entrySet())
        {
            if (e.getValue() != null) assertEquals(e.getKey(), BufferedImage.TYPE_INT_ARGB, e.getValue().getType());
        }
    }

    @Test
    public void aMissingSheetMeansNoArtNotAnException()
    {
        assertEquals(null, new SpriteSheet("no-such-sheet").get("ANY|0"));
    }
}

package com.forgebingo.core;

import com.forgebingo.core.PixelArt.Grid;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Pixel art for the boss pets (Abyssal orphan, Aggy, Baby Mole, Baron, Beef, Bran, Butch, Callisto cub, Dom, Gull,
 * Hellpuppy, Huberte, Ikkle Hydra and Jal-Nib-Rek). Original chunky chibi art in the style of PetSpritesA: 1px dark
 * outline, 2-3 shades per colour, two walk frames, drawn facing LEFT with the feet on the bottom rows.
 * Palette letters are per pet: a/b/c = main body colour (mid, light, dark), d/e/f = second material.
 */
public final class PetSpritesC
{
    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private PetSpritesC()
    {
    }

    /** One walk frame (0 or 1) on the PixelArt.WIDTH x PixelArt.HEIGHT grid, facing left, feet on the bottom rows. */
    public static BufferedImage image(Pet pet, int frame)
    {
        if (pet == null) return null;
        switch (pet)
        {
            case ABYSSAL_ORPHAN: case AGGY: case BABY_MOLE: case BARON: case BEEF: case BRAN: case BUTCH:
            case CALLISTO_CUB: case DOM: case GULL: case HELLPUPPY: case HUBERTE: case IKKLE_HYDRA: case JAL_NIB_REK:
                break;
            default:
                return null;
        }
        int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(pet + "|" + f, k -> PixelArt.render(shift(build(pet, f), centreShift(pet)), c -> colour(pet, c)));
    }

    /** Columns to move a pet so frame 0 sits centred on column 21 (same shift for both frames, so no jitter). */
    private static int centreShift(Pet pet)
    {
        Grid g = build(pet, 0);
        int lo = g.w;
        int hi = -1;
        for (int j = 0; j < g.h; j++)
        {
            for (int i = 0; i < g.w; i++)
            {
                if (g.px[j][i] == 0) continue;
                lo = Math.min(lo, i);
                hi = Math.max(hi, i);
            }
        }
        return hi < 0 ? 0 : PixelArt.WIDTH / 2 - (lo + hi + 1) / 2;
    }

    private static Grid shift(Grid g, int dx)
    {
        if (dx == 0) return g;
        Grid m = new Grid();
        for (int j = 0; j < g.h; j++)
        {
            for (int i = 0; i < g.w; i++)
            {
                if (g.px[j][i] != 0) m.set(i + dx, j, g.px[j][i]);
            }
        }
        return m;
    }

    private static int colour(Pet pet, int c)
    {
        switch ((char) c)
        {
            case 'k': return 0x16140f; // outline
            case 'z': return 0x1d1a22; // darkest (eyes, noses)
            case 'x': return 0xfff7e0; // white
            case 'X': return 0xd6cdb8; // off-white
            case 'y': return 0xf0c030; // gold / yellow glow
            case 'Y': return 0xfff088;
            case 'r': return 0xe02a1a; // red glow
            case 'R': return 0xff7a40;
            case 'p': return 0xe88c9c; // pink
            case 's': return 0xc4ccd4; // steel
            case 'S': return 0x7c8696;
            default: break;
        }
        switch (pet)
        {
            case ABYSSAL_ORPHAN:
                switch ((char) c)
                {
                    case 'a': return 0x4e4c58;
                    case 'b': return 0x7a7886;
                    case 'c': return 0x2c2a34;
                    case 'd': return 0x8c1c18;
                    default: break;
                }
                break;
            case AGGY:
                switch ((char) c)
                {
                    case 'a': return 0xa8c098; // pale grey-green skin
                    case 'b': return 0xd0e2c0;
                    case 'c': return 0x6a8060;
                    case 'd': return 0x30343c; // charcoal wing membrane
                    case 'e': return 0xb4bcb4; // bone / rim
                    case 'f': return 0x1c1f26;
                    case 'g': return 0x6a4a2a; // hilt
                    case 'h': return 0x5e6a34; // olive robe
                    case 'i': return 0x84924a;
                    case 'j': return 0x38401e;
                    default: break;
                }
                break;
            case BABY_MOLE:
                switch ((char) c)
                {
                    case 'a': return 0x80583a;
                    case 'b': return 0xa87c58;
                    case 'c': return 0x4e3322;
                    case 'd': return 0xe8dcb8; // claws
                    case 'e': return 0xb8a880;
                    default: break;
                }
                break;
            case BARON:
                switch ((char) c)
                {
                    case 'a': return 0x7a6a92;
                    case 'b': return 0xa696bc;
                    case 'c': return 0x4c3e62;
                    case 'd': return 0x3a1430; // mouth
                    case 'e': return 0xd8607c; // tongue
                    default: break;
                }
                break;
            case BEEF:
                switch ((char) c)
                {
                    case 'a': return 0x40302a;
                    case 'b': return 0x66503e;
                    case 'c': return 0x241a18;
                    case 'd': return 0xe0d0a0; // horn
                    case 'e': return 0xfff0c8;
                    case 'f': return 0x8c6c58; // snout
                    default: break;
                }
                break;
            case BRAN:
                switch ((char) c)
                {
                    case 'a': return 0x4a3830; // dark rock
                    case 'b': return 0x70584a;
                    case 'c': return 0x2a1e1c;
                    case 'd': return 0xe0501a; // fire
                    case 'e': return 0xff9a30;
                    case 'f': return 0x8a5a30; // club wood
                    default: break;
                }
                break;
            case BUTCH:
                switch ((char) c)
                {
                    case 'a': return 0xcabab0; // pale skin
                    case 'b': return 0xeee2d8;
                    case 'c': return 0x8e7e7a;
                    case 'd': return 0xb02030; // tendrils
                    case 'e': return 0xe04858;
                    case 'f': return 0x6a1424;
                    case 'g': return 0x6a4a2a; // handle
                    default: break;
                }
                break;
            case CALLISTO_CUB:
                switch ((char) c)
                {
                    case 'a': return 0x4e4e58;
                    case 'b': return 0x78788a;
                    case 'c': return 0x2c2c34;
                    case 'd': return 0xd8d0c0; // muzzle
                    case 'e': return 0xf0eadc;
                    case 'f': return 0xaaa294;
                    default: break;
                }
                break;
            case DOM:
                switch ((char) c)
                {
                    case 'a': return 0x8a3a22;
                    case 'b': return 0xb85c38;
                    case 'c': return 0x54200f;
                    case 'd': return 0x5c3a2c; // head
                    case 'e': return 0x886454;
                    case 'f': return 0x38201a;
                    case 'h': return 0xe8dcb8; // horn tips
                    default: break;
                }
                break;
            case GULL:
                switch ((char) c)
                {
                    case 'a': return 0xf2efe4;
                    case 'b': return 0xffffff;
                    case 'c': return 0xc2bfb8;
                    case 'd': return 0xf09a1c; // beak / claws
                    case 'e': return 0xffc860;
                    case 'f': return 0xb06c10;
                    case 'g': return 0x9a98a0; // wing tips
                    case 'h': return 0xd8a860; // lion hind body
                    case 'i': return 0xf0c888;
                    case 'j': return 0x9a6a30;
                    default: break;
                }
                break;
            case HELLPUPPY:
                switch ((char) c)
                {
                    case 'a': return 0x74221e;
                    case 'b': return 0xa4402c;
                    case 'c': return 0x44100e;
                    case 'd': return 0xb8745a; // pale muzzle
                    case 'e': return 0xe0a888;
                    default: break;
                }
                break;
            case HUBERTE:
                switch ((char) c)
                {
                    case 'a': return 0x3a9c9c; // teal
                    case 'b': return 0x78cec4;
                    case 'c': return 0x1e6264;
                    case 'd': return 0xe0788c; // pink feathers
                    case 'e': return 0xf8b0bc;
                    case 'f': return 0xa84862;
                    default: break;
                }
                break;
            case IKKLE_HYDRA:
                switch ((char) c)
                {
                    case 'a': return 0x2c4a30;
                    case 'b': return 0x4c7248;
                    case 'c': return 0x16261c;
                    case 'd': return 0xa8c030; // belly
                    case 'e': return 0xd2e060;
                    case 'f': return 0x6e8a1c;
                    default: break;
                }
                break;
            default: // JAL_NIB_REK
                switch ((char) c)
                {
                    case 'a': return 0x40363c;
                    case 'b': return 0x6a5c62;
                    case 'c': return 0x241c20;
                    default: break;
                }
                break;
        }
        return 0xff00ff;
    }

    // ---------------------------------------------------------------- helpers

    private static Grid rect(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++) m.set(x + i, y + j, c);
        }
        return m;
    }

    private static Grid oval(int x, int y, int w, int h, char c)
    {
        Grid m = new Grid();
        double cx = x + w / 2.0;
        double cy = y + h / 2.0;
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++)
            {
                double dx = (x + i + 0.5 - cx) / (w / 2.0);
                double dy = (y + j + 0.5 - cy) / (h / 2.0);
                if (dx * dx + dy * dy <= 1.0) m.set(x + i, y + j, c);
            }
        }
        return m;
    }

    private static Grid trap(int cx, int y0, int y1, double hw0, double hw1, char c)
    {
        Grid m = new Grid();
        for (int y = y0; y <= y1; y++)
        {
            double t = y1 == y0 ? 0 : (double) (y - y0) / (y1 - y0);
            int hw = (int) Math.round(hw0 + (hw1 - hw0) * t);
            for (int x = cx - hw; x < cx + hw; x++) m.set(x, y, c);
        }
        return m;
    }

    /** A straight stroke th pixels thick. */
    private static Grid line(int x0, int y0, int x1, int y1, int th, char c)
    {
        Grid m = new Grid();
        int n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
        for (int i = 0; i <= n; i++)
        {
            double t = n == 0 ? 0 : (double) i / n;
            int x = (int) Math.round(x0 + (x1 - x0) * t);
            int y = (int) Math.round(y0 + (y1 - y0) * t);
            for (int a = 0; a < th; a++)
            {
                for (int b = 0; b < th; b++) m.set(x + a, y + b, c);
            }
        }
        return m;
    }

    /** Light on the top-left edge, dark on the bottom-right edge (0 to skip one). */
    private static Grid bevel(Grid m, char light, char dark)
    {
        char[][] src = new char[m.h][];
        for (int j = 0; j < m.h; j++) src[j] = m.px[j].clone();
        for (int j = 0; j < m.h; j++)
        {
            for (int i = 0; i < m.w; i++)
            {
                if (src[j][i] == 0) continue;
                boolean top = j == 0 || src[j - 1][i] == 0;
                boolean left = i == 0 || src[j][i - 1] == 0;
                boolean bottom = j == m.h - 1 || src[j + 1][i] == 0;
                boolean right = i == m.w - 1 || src[j][i + 1] == 0;
                if (dark != 0 && (bottom || right)) m.px[j][i] = dark;
                else if (light != 0 && (top || left)) m.px[j][i] = light;
            }
        }
        return m;
    }

    /** b painted over a. */
    private static Grid with(Grid a, Grid b)
    {
        for (int j = 0; j < b.h; j++)
        {
            for (int i = 0; i < b.w; i++)
            {
                if (b.px[j][i] != 0) a.set(i, j, b.px[j][i]);
            }
        }
        return a;
    }

    private static void part(Grid g, Grid fill)
    {
        PixelArt.part(g, fill, 'k');
    }

    /** Stubby legs ending on row 32; in the walk frame every other one lifts a pixel. */
    private static void feet(Grid g, int[] xs, int w, int top, char c, char light, char dark, int f)
    {
        for (int i = 0; i < xs.length; i++)
        {
            boolean lifted = (i % 2 == 0) == (f == 1);
            int lift = lifted ? 1 : 0;
            part(g, bevel(rect(xs[i] + (lifted ? 1 : 0), top, w, 33 - top - lift, c), light, dark));
        }
    }

    /** A 2x2 eye with a white glint on its top left. */
    private static void eye(Grid g, int x, int y)
    {
        g.pxs('z', x, y, x + 1, y, x, y + 1, x + 1, y + 1).pxs('x', x, y);
    }

    private static Grid build(Pet pet, int f)
    {
        switch (pet)
        {
            case ABYSSAL_ORPHAN: return abyssal(f);
            case AGGY: return aggy(f);
            case BABY_MOLE: return mole(f);
            case BARON: return baron(f);
            case BEEF: return beef(f);
            case BRAN: return bran(f);
            case BUTCH: return butch(f);
            case CALLISTO_CUB: return callisto(f);
            case DOM: return dom(f);
            case GULL: return gull(f);
            case HELLPUPPY: return hellpuppy(f);
            case HUBERTE: return huberte(f);
            case IKKLE_HYDRA: return hydra(f);
            default: return nibRek(f);
        }
    }

    // ---------------------------------------------------------------- pets

    /** Filled polygon (even-odd) through the given corner points. */
    private static Grid poly(int[] xs, int[] ys, char c)
    {
        Grid m = new Grid();
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                boolean in = false;
                for (int i = 0, j = xs.length - 1; i < xs.length; j = i++)
                {
                    if ((ys[i] > y + 0.5) != (ys[j] > y + 0.5)
                        && x + 0.5 < (xs[j] - xs[i]) * (y + 0.5 - ys[i]) / (double) (ys[j] - ys[i]) + xs[i]) in = !in;
                }
                if (in) m.set(x, y, c);
            }
        }
        return m;
    }

    /** Abyssal orphan: a dark grey demon-spider, four spread legs with red glowing tips, red eyes and chest. */
    private static Grid abyssal(int f)
    {
        Grid g = new Grid();
        int dy = f;
        int[][] legs = {{26, 20, 31, 30}, {16, 22, 12, 30}, {24, 22, 28, 30}, {14, 20, 8, 30}};
        for (int i = 0; i < legs.length; i++)
        {
            boolean up = (i % 2 == 0) == (f == 1);
            int fx = legs[i][2] + (up ? (legs[i][2] > 20 ? -1 : 1) : 0);
            int fy = legs[i][3] - (up ? 2 : 0);
            part(g, bevel(line(legs[i][0], legs[i][1], fx, fy, 2, 'a'), 'b', 'c'));
            g.pxs('d', fx, fy + 1, fx + 1, fy + 1).pxs('r', fx, fy + 1);
            g.pxs('r', fx, fy + 2, fx + 1, fy + 2);
        }
        Grid body = bevel(oval(13, 11 + dy, 16, 13, 'a'), 'b', 'c');
        body.pxs('c', 17, 14 + dy, 18, 13 + dy, 25, 14 + dy, 24, 13 + dy, 20, 12 + dy, 21, 12 + dy);
        part(g, body);
        g.pxs('d', 21, 15 + dy, 21, 16 + dy, 20, 17 + dy, 22, 17 + dy, 21, 18 + dy, 21, 19 + dy);
        g.pxs('r', 21, 16 + dy, 21, 18 + dy).pxs('R', 21, 17 + dy);
        part(g, bevel(oval(6, 9 + dy, 11, 9, 'a'), 'b', 'c'));
        part(g, line(7, 6 + dy, 8, 9 + dy, 1, 'c'));
        part(g, line(14, 6 + dy, 14, 9 + dy, 1, 'c'));
        g.pxs('r', 9, 12 + dy, 10, 12 + dy, 13, 12 + dy, 14, 12 + dy).pxs('R', 9, 12 + dy, 13, 12 + dy);
        g.pxs('z', 8, 15 + dy, 9, 15 + dy, 10, 15 + dy);
        return g;
    }

    /** Aggy: a hunched pale grey-green figure in an olive robe, with big dark ragged bony wings and a bright sword. */
    private static Grid aggy(int f)
    {
        Grid g = new Grid();
        int dy = f;
        // dark charcoal wing with a scalloped lower edge, light rim and bone line along the top
        int[] px = {15, 23, 23, 27, 25, 27, 23, 21, 18, 17};
        int[] py = {12 + dy, 5 + dy + f, 12 + dy, 14 + dy, 19 + dy, 25 + dy, 23 + dy, 28 + dy, 23 + dy, 20 + dy};
        part(g, bevel(poly(px, py, 'd'), 'e', 'f'));
        part(g, line(16, 12 + dy, 23, 6 + dy + f, 1, 'e'));
        g.pxs('e', 24, 6 + dy + f);
        int[][] tips = {{27, 14 + dy}, {27, 25 + dy}, {21, 28 + dy}};
        for (int[] t : tips)
        {
            for (int i = 0; i <= 10; i++)
            {
                int x = 17 + (t[0] - 17) * i / 10;
                int y = 13 + dy + (t[1] - 13 - dy) * i / 10;
                g.set(x, y, 'e');
            }
        }
        feet(g, new int[] {7, 12}, 4, 28, 'h', 'i', 'z', f);
        // olive robe body with a belt, pale skin showing at the neck and hands
        Grid robe = bevel(oval(6, 14 + dy, 12, 16, 'h'), 'i', 'j');
        robe.pxs('j', 8, 24 + dy, 9, 24 + dy, 10, 24 + dy, 11, 24 + dy, 12, 24 + dy, 13, 24 + dy);
        robe.pxs('y', 10, 24 + dy);
        part(g, robe);
        // hunched head, pale skin, pointed ears, dark brow and yellow eyes
        part(g, bevel(oval(3, 8 + dy, 11, 9, 'a'), 'b', 'c'));
        part(g, line(4, 5 + dy, 5, 9 + dy, 1, 'c'));
        part(g, line(11, 5 + dy, 11, 9 + dy, 1, 'c'));
        g.pxs('z', 4, 11 + dy, 5, 11 + dy, 6, 12 + dy, 9, 12 + dy, 10, 11 + dy, 11, 11 + dy);
        g.pxs('y', 5, 12 + dy, 6, 13 + dy, 10, 12 + dy, 9, 13 + dy).pxs('Y', 5, 12 + dy, 10, 12 + dy);
        g.pxs('z', 5, 13 + dy, 10, 13 + dy);
        g.pxs('c', 6, 15 + dy, 7, 15 + dy, 8, 15 + dy);
        // arm and sword
        part(g, line(8, 20 + dy, 5, 24, 2, 'a'));
