        g.pxs('a', 10, 15 + dy, 11, 15 + dy, 10, 16 + dy, 11, 16 + dy, 14, 14 + dy, 15, 14 + dy, 14, 15 + dy, 15, 15 + dy);
        g.pxs('A', 10, 15 + dy, 14, 14 + dy);
        g.pxs('a', 12, 18 + dy, 13, 18 + dy, 9, 18 + dy, 16, 17 + dy);
        part(g, new Grid().stamp(10, 23 + dy, "G..G", "G..G"));
