    /** Wisp: tall thin dark blue-grey shadow with pale glowing eyes, swaying pale tendrils and a faint glow. */
    private static Grid wisp(int f)
    {
        Grid g = new Grid();
        int dy = 1 - f;
        double ph = f * Math.PI;
        // faint glow (a dithered halo behind the figure)
        Grid halo = new Grid();
        for (int y = 0; y < 22; y++)
        {
            for (int x = 10; x < 32; x++)
            {
                double dx = (x - 21) / 11.0;
                double dyy = (y - 9 - dy) / 11.0;
                if (dx * dx + dyy * dyy <= 1 && (x + y) % 2 == 0) halo.set(x, y + 1, 'm');
            }
        }
        with(g, halo);
        // trailing pale tendrils
        Grid t = new Grid();
        tendril(t, 17, 26 + dy, 5, ph, -0.2, 'N');
        tendril(t, 21, 27 + dy, 4, ph + 1.5, 0.0, 'N');
        tendril(t, 25, 26 + dy, 5, ph + 3, 0.2, 'N');
        // two pixel wide wavy side tendrils
        for (int side = 0; side < 2; side++)
        {
            int dir = side == 0 ? -1 : 1;
            int x0 = side == 0 ? 17 : 25;
            for (int k = 0; k <= 10; k++)
            {
                int x = x0 + (int) Math.round(dir * k * 0.55 + Math.sin(k * 0.8 + ph + side * 2) * 1.6);
                t.set(x, 13 + dy + k, k > 8 ? 'L' : 'N');
                t.set(x + 1, 13 + dy + k, k > 8 ? 'L' : 'N');
            }
        }
        part(g, t);
        // tall cloak with a tattered hem
        Grid cloak = bevel(trap(21, 8 + dy, 24 + dy, 2, 6, 'm'), 'M', 'z');
        for (int x = 15; x < 27; x++)
        {
            int len = x % 3 == 0 ? 3 : x % 3 == 1 ? 1 : 2;
            for (int j = 0; j < len; j++) cloak.set(x, 25 + dy + j, j == len - 1 ? 'z' : 'm');
        }
        part(g, cloak);
        g.pxs('M', 20, 13 + dy, 20, 15 + dy, 19, 18 + dy, 18, 21 + dy);
        g.pxs('z', 23, 14 + dy, 23, 17 + dy, 24, 20 + dy);
        part(g, bevel(oval(16, 1 + dy, 10, 11, 'm'), 'M', 'z'));
        part(g, bevel(trap(23, -2 + dy, 2 + dy, 1, 3, 'm'), 'M', 'z'));
        // pale glowing eyes
        g.pxs('z', 16, 5 + dy, 17, 5 + dy, 18, 5 + dy, 19, 5 + dy, 16, 6 + dy, 17, 6 + dy, 18, 6 + dy, 19, 6 + dy, 17, 7 + dy, 18, 7 + dy);
        g.pxs('x', 17, 6 + dy, 18, 6 + dy);
        g.pxs('N', 17, 7 + dy);
        g.pxs('z', 21, 5 + dy, 22, 5 + dy, 21, 6 + dy, 22, 6 + dy);
        g.pxs('x', 21, 6 + dy);
        return g;
    }

    /** Yami: small red demon hugged by two huge curled, ridged, tan ram horns. */
    private static Grid yami(int f)
    {
        Grid g = new Grid();
        int dy = -f;
        legs2(g, 15, 22, 27, 4, 'D', 'h', 'z', f);
        Grid tail = new Grid();
        thick(tail, 'D', 27, 25 + dy, 30, 25 + dy, 31, 22 - f);
        part(g, tail);
        part(g, bevel(oval(12, 19 + dy, 17, 11, 'a'), 'A', 'h'));
        // far horn, curling over the top of the head
        java.util.List<int[]> fp = new java.util.ArrayList<>();
        for (int k = 0; k <= 24; k++)
        {
            double t = k / 24.0;
            double a = Math.toRadians(-150 + t * 400);
            double r = 7.5 - 4.5 * t;
            fp.add(new int[] {(int) Math.round(14 + r * Math.cos(a)), (int) Math.round(11 + dy + r * Math.sin(a))});
        }
        Grid far = bevel(taper(fp, 4, 'r'), 't', 'w');
        part(g, far);
        // head
        part(g, bevel(oval(7, 9 + dy, 17, 15, 'a'), 'A', 'h'));
        // near horn: out from the brow, round the side of the head and curling forward underneath
        java.util.List<int[]> hp = new java.util.ArrayList<>();
        for (int k = 0; k <= 44; k++)
        {
            double t = k / 44.0;
            double a = Math.toRadians(-120 + t * 470);
            double r = 6.5 - 4.0 * t;
            hp.add(new int[] {(int) Math.round(19 + r * Math.cos(a)), (int) Math.round(14 + dy + r * Math.sin(a))});
        }
        Grid horn = bevel(taper(hp, 3, 't'), 'T', 'r');
        for (int k = 2; k < hp.size() - 2; k += 3)
        {
            int[] p = hp.get(k);
            horn.set(p[0] + 1, p[1] + 1, 'r');
            horn.set(p[0] + 2, p[1], 'r');
        }
        part(g, horn);
        // face
        g.pxs('h', 9, 14 + dy, 10, 15 + dy, 11, 15 + dy, 12, 14 + dy);
        g.pxs('z', 9, 16 + dy, 10, 16 + dy, 11, 16 + dy, 9, 17 + dy, 10, 17 + dy, 11, 17 + dy);
        g.pxs('Y', 10, 17 + dy);
        g.pxs('z', 16, 16 + dy, 17, 16 + dy, 16, 17 + dy, 17, 17 + dy);
        g.pxs('Y', 16, 17 + dy);
        g.pxs('z', 8, 20 + dy, 9, 20 + dy, 10, 20 + dy, 11, 20 + dy, 12, 20 + dy, 13, 20 + dy);
        g.pxs('x', 9, 21 + dy, 12, 21 + dy);
        return g;
    }

