package com.forgebingo.core;

import static org.junit.Assert.*;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class PetTableTest
{
    @Test
    public void wellKnownPets()
    {
        PetTable.Pet mole = PetTable.byName("Baby mole");
        assertNotNull(mole);
        assertEquals(12646, mole.primaryItemId());
        assertSame(mole, PetTable.byItemId(12646));
        assertSame(mole, PetTable.byFollowerNpcId(6635));
        assertSame(mole, PetTable.bySource("Giant Mole").get(0));

        assertEquals(21992, PetTable.byName("vorki").primaryItemId());
        assertSame(PetTable.byName("Vorki"), PetTable.byFollowerNpcId(8029));
        assertEquals(20851, PetTable.byName("Olmlet").primaryItemId());
        assertEquals(20693, PetTable.byName("Phoenix").primaryItemId());
        assertEquals(12921, PetTable.byName("Pet snakeling").primaryItemId());
        assertEquals(12650, PetTable.byName("Pet general graardor").primaryItemId());
        assertSame(PetTable.byName("Pet general graardor"), PetTable.byFollowerNpcId(6632));
        // typographic apostrophe and odd casing from chat
        assertEquals(22473, PetTable.byName("Lil’ Zik").primaryItemId());
        assertEquals(13179, PetTable.byName("VET'ION JR.").primaryItemId());
    }

    @Test
    public void variantsMapToTheirPet()
    {
        PetTable.Pet hydra = PetTable.byName("Ikkle hydra");
        for (int id : new int[]{22746, 22748, 22750, 22752})
        {
            assertSame(hydra, PetTable.byItemId(id));
        }
        assertSame(PetTable.byName("Noon"), PetTable.byItemId(21750)); // Midnight
        assertSame(PetTable.byName("Youngllef"), PetTable.byItemId(23759)); // Corrupted youngllef
    }

    @Test
    public void tableIsConsistent()
    {
        assertTrue(PetTable.all().size() >= 60);
        Set<String> names = new HashSet<>();
        for (PetTable.Pet p : PetTable.all())
        {
            assertTrue(p.name, names.add(ItemNames.normalize(p.name)));
            assertTrue(p.name, p.itemIds.length > 0);
            assertTrue(p.name, p.followerNpcIds.length > 0);
            for (int id : p.itemIds) assertSame(p.name, p, PetTable.byItemId(id));
            for (int id : p.followerNpcIds) assertSame(p.name, p, PetTable.byFollowerNpcId(id));
        }
    }

    @Test
    public void unknowns()
    {
        assertNull(PetTable.byName("Abyssal whip"));
        assertNull(PetTable.byName(null));
        assertNull(PetTable.byItemId(4151));
        assertNull(PetTable.byFollowerNpcId(2215)); // General Graardor himself, not his pet
        assertNull(PetTable.byFollowerNpcId(494)); // the Kraken boss
        assertTrue(PetTable.bySource("Goblin").isEmpty());
        assertTrue(PetTable.bySource(null).isEmpty());
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;
import org.junit.Test;

public class PetTest
{
    @Test
    public void thereAreSeventyTwoPets()
    {
        assertEquals(72, Pet.values().length);
    }

    @Test
    public void rarePetsTurnUpFarLessOftenThanCommonOnes()
    {
        Map<Pet.Rarity, Integer> seen = new EnumMap<>(Pet.Rarity.class);
        Random r = new Random(7);
        int draws = 200_000;
        for (int i = 0; i < draws; i++)
        {
            Pet p = Pet.pick(r.nextDouble(), x -> true);
            assertNotNull(p);
            seen.merge(p.rarity, 1, Integer::sum);
        }
        int common = seen.getOrDefault(Pet.Rarity.COMMON, 0);
        int rare = seen.getOrDefault(Pet.Rarity.RARE, 0);
        int legendary = seen.getOrDefault(Pet.Rarity.LEGENDARY, 0);
        assertTrue("common pets are most of what you see", common > draws / 2);
        assertTrue(rare < common / 4);
        // the two legendary pets together: about 1 in 2,800
        assertTrue("legendary pets are almost never seen: " + legendary, legendary > 0 && legendary < draws / 1000);
    }

    @Test
    public void onlyDrawnPetsArePicked()
    {
        assertNull(Pet.pick(0.5, x -> false));
        for (double roll = 0; roll < 1; roll += 0.01)
        {
            assertEquals(Pet.HERON, Pet.pick(roll, x -> x == Pet.HERON));
        }
    }

    @Test
    public void everyDrawnPetHasBothFramesInTheSharedBox()
    {
        for (Pet p : Pet.values())
        {
            if (!PetSprites.drawn(p)) continue;
            for (int f = 0; f < 2; f++)
            {
                BufferedImage img = PetSprites.image(p, f);
                assertNotNull(p + " frame " + f, img);
                assertEquals(PixelArt.WIDTH, img.getWidth());
                assertEquals(PixelArt.HEIGHT, img.getHeight());
            }
        }
    }
}

package com.forgebingo.core;

import java.awt.image.BufferedImage;
import java.util.function.IntUnaryOperator;

/**
 * Shared tools for the side panel's themed pixel-art creatures (the imp has its own older copy in ImpSprite).
 * A creature is drawn on a WIDTH x HEIGHT grid of palette letters, facing LEFT, feet on the bottom row, body centred
 * on column WIDTH / 2, so every creature fits the same walking code.
 *
 * Lives in src/test/java since the art was baked into sprite sheets: only the drawing code (PetSpritesA..F,
 * RaidSprites, CryptSprites, SkillPropArt) uses it now. The plugin itself takes the grid size from ImpSprite.
 */
public final class PixelArt
{
    public static final int WIDTH = ImpSprite.WIDTH;
    public static final int HEIGHT = ImpSprite.HEIGHT;

    private PixelArt()
    {
    }

    /** A pixel grid of palette letters ((0,0) is the top left); anything outside it is dropped. */
    public static final class Grid
    {
        public final int w;
        public final int h;
        public final char[][] px;

        public Grid()
        {
            this(WIDTH, HEIGHT);
        }

        public Grid(int w, int h)
        {
            this.w = w;
            this.h = h;
            this.px = new char[h][w];
        }

        public void set(int x, int y, char c)
        {
            if (x >= 0 && x < w && y >= 0 && y < h) px[y][x] = c;
        }

        public boolean has(int x, int y)
        {
            return x >= 0 && x < w && y >= 0 && y < h && px[y][x] != 0;
        }

        /** Rows of palette letters with their top left at (x0, y0); '.' and ' ' are see-through. */
        public Grid stamp(int x0, int y0, String... rows)
        {
            for (int j = 0; j < rows.length; j++)
            {
                String row = rows[j];
                for (int i = 0; i < row.length(); i++)
                {
                    char c = row.charAt(i);
                    if (c != '.' && c != ' ') set(x0 + i, y0 + j, c);
                }
            }
            return this;
        }

        /** Single pixels: x, y pairs. */
        public Grid pxs(char c, int... xy)
        {
            for (int i = 0; i + 1 < xy.length; i += 2) set(xy[i], xy[i + 1], c);
            return this;
        }
    }

    public static Grid shape(int w, int h, int x, int y, String... rows)
    {
        return new Grid(w, h).stamp(x, y, rows);
    }

    public static Grid shape(int x, int y, String... rows)
    {
        return new Grid().stamp(x, y, rows);
    }

    private static final int[][] SIDES = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Paints a part onto the sprite with an automatic 1px outline (palette letter {@code outline}) around it. */
    public static void part(Grid g, Grid fill, char outline)
    {
        for (int j = 0; j < fill.h; j++)
        {
            for (int i = 0; i < fill.w; i++)
            {
                if (fill.px[j][i] == 0) continue;
                for (int[] s : SIDES)
                {
                    if (!fill.has(i + s[0], j + s[1])) g.set(i + s[0], j + s[1], outline);
                }
            }
        }
        for (int j = 0; j < fill.h; j++)
        {
            for (int i = 0; i < fill.w; i++)
            {
                if (fill.px[j][i] != 0) g.set(i, j, fill.px[j][i]);
            }
        }
    }

    /** The grid as a transparent image; {@code colour} gives each palette letter its 0xRRGGBB. */
    public static BufferedImage render(Grid g, IntUnaryOperator colour)
    {
        BufferedImage img = new BufferedImage(g.w, g.h, BufferedImage.TYPE_INT_ARGB);
        for (int j = 0; j < g.h; j++)
        {
            for (int i = 0; i < g.w; i++)
            {
                char c = g.px[j][i];
                if (c != 0) img.setRGB(i, j, 0xff000000 | colour.applyAsInt(c));
            }
        }
        return img;
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class ProofPlanTest
{
    private static ApiModels.Match match(String team, String tile, String task, String submission)
    {
        ApiModels.Match m = new ApiModels.Match();
        m.teamId = team;
        m.tileId = tile;
        m.taskId = task;
        m.submissionId = submission;
        return m;
    }

    private static Map<String, String> map(String... pairs)
    {
        Map<String, String> m = new HashMap<>();
        for (int i = 0; i < pairs.length; i += 2) m.put(pairs[i], pairs[i + 1]);
        return m;
    }

    private static ApiModels.Tile tile(String id, String title)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.id = id;
        t.title = title;
        return t;
    }

    private static ApiModels.BoardResponse board(ApiModels.Tile... tiles)
    {
        ApiModels.BoardResponse b = new ApiModels.BoardResponse();
        b.tiles = new ArrayList<>(Arrays.asList(tiles));
        return b;
    }

    @Test
    public void oneUploadPerTeamWithItsOwnEntries()
    {
        List<ProofPlan.Team> teams = ProofPlan.teams(Arrays.asList(
            match("A", "t1", "k1", "s1"),
            match("A", "t2", "k2", "s2"),
            match("A", "t1", "k1", "s1")), // the same entry twice: attached once
            map("k1", "Bury bones", "k2", "Kill Vorkath"), map("t1", "Bones", "t2", "Dragons"));
        assertEquals(1, teams.size());
        ProofPlan.Team a = teams.get(0);
        assertEquals("A", a.teamId);
        assertEquals(Arrays.asList("s1", "s2"), a.submissionIds);
        // the file is named after the first task the drop counted for
        assertEquals("Bury bones", a.label);
        assertEquals(Arrays.asList("t1", "t2", "t1"), a.tileIds);
    }

    @Test
    public void twoBingosAtOnceEachTeamGetsItsOwnPicture()
    {
        List<ProofPlan.Team> teams = ProofPlan.teams(Arrays.asList(
            match("A", "t1", "k1", "s1"),
            match("B", "x9", "other", "s7"),
            match("A", "t2", "k2", "s2")),
            map("k1", "Bury bones"), map("t1", "Bones", "t2", "Dragons"));
        assertEquals(2, teams.size());
        assertEquals("A", teams.get(0).teamId);
        assertEquals(Arrays.asList("s1", "s2"), teams.get(0).submissionIds);
        assertEquals("Bury bones", teams.get(0).label);
        // team B's board is not the one on screen: nothing to name its file after
        assertEquals("B", teams.get(1).teamId);
        assertEquals(Collections.singletonList("s7"), teams.get(1).submissionIds);
        assertNull(teams.get(1).label);
        assertEquals(Collections.singletonList("x9"), teams.get(1).tileIds);
    }

    @Test
    public void theLabelFallsBackToTheTileTitle()
    {
        List<ProofPlan.Team> teams = ProofPlan.teams(Collections.singletonList(match("A", "t1", "unknown", "s1")),
            new HashMap<>(), map("t1", "Bones"));
        assertEquals("Bones", teams.get(0).label);
    }

    @Test
    public void matchesWithoutAnEntryOrTeamMakeNoUpload()
    {
        assertTrue(ProofPlan.teams(Arrays.asList(match("A", "t1", "k1", null), match(null, "t1", "k1", "s1"), null),
            new HashMap<>(), new HashMap<>()).isEmpty());
        assertTrue(ProofPlan.teams(null, new HashMap<>(), new HashMap<>()).isEmpty());
        // but with an entry on the team, such a match's tile is still named on the stamp
        List<ProofPlan.Team> teams = ProofPlan.teams(Arrays.asList(match("A", "t1", "k1", "s1"), match("A", "t2", "k2", null)),
            new HashMap<>(), new HashMap<>());
        assertEquals(Collections.singletonList("s1"), teams.get(0).submissionIds);
        assertEquals(Arrays.asList("t1", "t2"), teams.get(0).tileIds);
    }

    @Test
    public void atMostTwentyFiveEntriesPerPicture()
    {
        List<ApiModels.Match> many = new ArrayList<>();
        for (int i = 0; i < 40; i++) many.add(match("A", "t" + i, "k" + i, "s" + i));
        List<ProofPlan.Team> teams = ProofPlan.teams(many, new HashMap<>(), new HashMap<>());
        assertEquals(25, teams.get(0).submissionIds.size());
        assertEquals("s0", teams.get(0).submissionIds.get(0));
        assertEquals("s24", teams.get(0).submissionIds.get(24));
    }

    @Test
    public void aRaidChestAlsoProvesTheRaidItself()
    {
        ApiModels.EventResult chest = new ApiModels.EventResult();
        chest.eventId = "chest-event";
        chest.matched = new ArrayList<>(Collections.singletonList(match("A", "purple", "k-item", "s-chest")));
        ApiModels.EventResult kill = new ApiModels.EventResult();
        kill.matched = new ArrayList<>(Arrays.asList(match("A", "kc-tile", "k-kc", "s-kc"), match("B", "kc-b", "k-kc-b", "s-kc-b")));

        ApiModels.EventResult both = ProofPlan.withRaidKill(chest, kill);
        assertEquals("chest-event", both.eventId);
        assertEquals(3, both.matched.size());
        // the answers themselves are left as they were
        assertEquals(1, chest.matched.size());
        assertEquals(2, kill.matched.size());

        List<ProofPlan.Team> teams = ProofPlan.teams(both.matched, map("k-item", "Twisted bow", "k-kc", "50 raids"), new HashMap<>());
        assertEquals(2, teams.size());
        assertEquals(Arrays.asList("s-chest", "s-kc"), teams.get(0).submissionIds);
        assertEquals("Twisted bow", teams.get(0).label);
        assertEquals(Arrays.asList("purple", "kc-tile"), teams.get(0).tileIds);
        assertEquals(Collections.singletonList("s-kc-b"), teams.get(1).submissionIds);
    }

    @Test
    public void aChestThatCountedForNothingStillProvesTheRaid()
    {
        ApiModels.EventResult chest = new ApiModels.EventResult();
        ApiModels.EventResult kill = new ApiModels.EventResult();
        kill.matched = new ArrayList<>(Collections.singletonList(match("A", "kc-tile", "k-kc", "s-kc")));
        ApiModels.EventResult both = ProofPlan.withRaidKill(chest, kill);
        assertTrue(both.isMatched());
        assertEquals("s-kc", both.matched.get(0).submissionId);
    }

    @Test
    public void withNoRaidKillTheChestAnswerIsUsedAsItIs()
    {
        ApiModels.EventResult chest = new ApiModels.EventResult();
        assertSame(chest, ProofPlan.withRaidKill(chest, null));
        assertSame(chest, ProofPlan.withRaidKill(chest, new ApiModels.EventResult()));
        assertNull(ProofPlan.withRaidKill(null, new ApiModels.EventResult()));
    }

    @Test
    public void theStampNamesTheTilesFromTheTeamsOwnBoard()
    {
        ApiModels.BoardResponse teamBoard = board(tile("t1", "Team name for t1"), tile("t2", "Second"), tile("t3", "Third"));
        Map<String, String> onScreen = map("t1", "On-screen name", "t9", "Only on screen");
        assertEquals("Team name for t1", ProofPlan.tiles(Collections.singletonList("t1"), teamBoard, onScreen));
        assertEquals("Team name for t1, Second", ProofPlan.tiles(Arrays.asList("t1", "t2", "t1"), teamBoard, onScreen));
        assertEquals("Team name for t1, Second +2", ProofPlan.tiles(Arrays.asList("t1", "t2", "t3", "t9"), teamBoard, onScreen));
        // the team's board could not be fetched: the board on screen names what it can
        assertEquals("On-screen name", ProofPlan.tiles(Arrays.asList("t1", "t2"), null, onScreen));
        assertNull(ProofPlan.tiles(Collections.singletonList("t2"), null, onScreen));
        assertNull(ProofPlan.tiles(Collections.emptyList(), teamBoard, onScreen));
    }

    @Test
    public void aHiddenSecretTileIsStampedByItsShownName()
    {
        ApiModels.Tile secret = tile("s1", "?");
        secret.secret = true;
        assertEquals("Secret tile", ProofPlan.tiles(Collections.singletonList("s1"), board(secret), new HashMap<>()));
    }

    private static final long TTL = 10 * 60_000L;

    @Test
    public void aBusyOrUnreachableServerGetsTheSamePictureAgain()
    {
        // never completed (timeout, no network), rate limited, server error: worth another try
        assertEquals(5_000, ProofPlan.retryDelay(0, null, 0, 1, 1_000, TTL));
        assertEquals(10_000, ProofPlan.retryDelay(503, null, 0, 2, 1_000, TTL));
        // the server's own wait is honoured (it answers 429 with 60 s)...
        assertEquals(60_000, ProofPlan.retryDelay(429, "rate_limited", 60_000, 1, 1_000, TTL));
        // ...up to a limit
        assertEquals(ProofPlan.RETRY_MAX_MILLIS, ProofPlan.retryDelay(429, null, 15 * 60_000L, 1, 1_000, TTL));
    }

    @Test
    public void threeSendsAtMost()
    {
        assertTrue(ProofPlan.retryDelay(503, null, 0, 1, 0, TTL) >= 0);
        assertTrue(ProofPlan.retryDelay(503, null, 0, 2, 0, TTL) >= 0);
        assertEquals(-1, ProofPlan.retryDelay(503, null, 0, 3, 0, TTL));
    }

    @Test
    public void anAnswerThatWillNotChangeIsNotRetried()
    {
        assertEquals(-1, ProofPlan.retryDelay(404, null, 0, 1, 0, TTL));
        assertEquals(-1, ProofPlan.retryDelay(409, "event_not_open", 0, 1, 0, TTL));
        assertEquals(-1, ProofPlan.retryDelay(409, "submission_reviewed", 0, 1, 0, TTL));
        assertEquals(-1, ProofPlan.retryDelay(400, "invalid_targets", 0, 1, 0, TTL));
        assertEquals(-1, ProofPlan.retryDelay(413, "payload_too_large", 0, 1, 0, TTL));
        assertEquals(-1, ProofPlan.retryDelay(401, "invalid_api_key", 0, 1, 0, TTL));
    }

    @Test
    public void noRetryPastTheScreenshotTimeLimit()
    {
        assertEquals(60_000, ProofPlan.retryDelay(429, null, 60_000, 1, TTL - 61_000, TTL));
        assertEquals(-1, ProofPlan.retryDelay(429, null, 60_000, 1, TTL - 60_000, TTL));
        assertEquals(-1, ProofPlan.retryDelay(0, null, 0, 1, TTL + 1, TTL));
    }

    @Test
    public void severalFramesSayWhichTheyAre()
    {
        assertEquals("Bones", ProofPlan.stampText("Bones", 1, 1));
        assertNull(ProofPlan.stampText(null, 1, 1));
        assertEquals("Bones (1 of 2)", ProofPlan.stampText("Bones", 1, 2));
        assertEquals("Bones (2 of 2)", ProofPlan.stampText("Bones", 2, 2));
        assertEquals("3 of 3", ProofPlan.stampText(null, 3, 3));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import org.junit.Test;

public class ProofPolicyTest
{
    private static GameEvent event(String type, int... itemIds)
    {
        GameEvent e = new GameEvent();
        e.sourceType = type;
        for (int id : itemIds) e.addItem(id, 1);
        return e;
    }

    private static ApiModels.Task itemTask(Integer... itemIds)
    {
        ApiModels.Task k = new ApiModels.Task();
        k.sourceType = GameEvent.NPC;
        k.itemIds = new ArrayList<>(Arrays.asList(itemIds));
        return k;
    }

    private static ApiModels.Task sourceTask(String sourceType)
    {
        ApiModels.Task k = new ApiModels.Task();
        k.sourceType = sourceType;
        return k;
    }

    private static ApiModels.Tile tile(ApiModels.Task... tasks)
    {
        ApiModels.Tile t = new ApiModels.Tile();
        t.title = "Tile";
        t.tasks = new ArrayList<>(Arrays.asList(tasks));
        return t;
    }

    private static ApiModels.BoardResponse board(ApiModels.Tile... tiles)
    {
        ApiModels.BoardResponse b = new ApiModels.BoardResponse();
        b.tiles = new ArrayList<>(Arrays.asList(tiles));
        return b;
    }

    @Test
    public void withNoBoardLoadedEverythingGetsAPicture()
    {
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 1), null, 1));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 1), new ApiModels.BoardResponse(), 0));
    }

    @Test
    public void onlyItemsTheBoardAsksFor()
    {
        ApiModels.BoardResponse b = board(tile(itemTask(11286, 22006)));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 526, 11286), b, 1));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC, 526), b, 1));
        // an item task never matches an event without items, whatever its source type
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC), b, 1));
    }

    @Test
    public void tasksWithoutItemsGoBySourceType()
    {
        ApiModels.BoardResponse b = board(tile(sourceTask(GameEvent.KC)));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.KC), b, 1));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.LEVEL), b, 1));
    }

    @Test
    public void finishedTilesStillCount()
    {
        // drops keep counting (with proof) until the bingo is over
        ApiModels.Tile done = tile(itemTask(11286));
        done.completed = true;
        done.tasks.get(0).completed = true;
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 11286), board(done), 1));
    }

    @Test
    public void orOptionsEachCount()
    {
        ApiModels.Task a = itemTask(100);
        ApiModels.Task b = itemTask(200);
        a.group = 1;
        b.group = 1;
        ApiModels.BoardResponse board = board(tile(a, b));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 100), board, 1));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 200), board, 1));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC, 300), board, 1));
    }

    @Test
    public void twoLiveBingosAtOnceEverythingGetsAPicture()
    {
        // only the selected board is known: the drop may count for the other one
        ApiModels.BoardResponse b = board(tile(itemTask(11286)));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC, 526), b, 1));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 526), b, 2));
        // a finished bingo next to a live one does not count as a second board
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC, 526), b, 0));
    }

    @Test
    public void secretTilesGoByHiddenItemIds()
    {
        ApiModels.Tile secret = new ApiModels.Tile();
        secret.title = "?";
        secret.secret = true;
        ApiModels.BoardResponse b = board(secret);
        b.hiddenItemIds = new ArrayList<>(Arrays.asList(4151));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.NPC, 4151), b, 1));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.NPC, 526), b, 1));
    }

    @Test
    public void withASecretTileKillsPetsAndCluesAlwaysGetAPicture()
    {
        ApiModels.Tile secret = new ApiModels.Tile();
        secret.title = "?";
        secret.secret = true;
        ApiModels.BoardResponse b = board(secret, tile(itemTask(11286)));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.KC), b, 1));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.PET, 12921), b, 1));
        assertTrue(ProofPolicy.couldCount(event(GameEvent.CLUE, 995), b, 1));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.LEVEL), b, 1));
        // without a secret tile on the board they go by the tasks like anything else
        ApiModels.BoardResponse open = board(tile(itemTask(11286)));
        assertFalse(ProofPolicy.couldCount(event(GameEvent.KC), open, 1));
    }

    @Test
    public void onePictureForDropsKillsAndCluesTwoForRewardChests()
    {
        assertArrayEquals(new long[] {600}, ProofPolicy.shotDelays(GameEvent.NPC, "Vorkath", false));
        assertArrayEquals(new long[] {600}, ProofPolicy.shotDelays(GameEvent.KC, "Chambers of Xeric", false));
        assertArrayEquals(new long[] {600}, ProofPolicy.shotDelays(GameEvent.CLUE, "hard", false));
        // a clue's reward window is never treated as a chest, even when asked that way
        assertEquals(1, ProofPolicy.shotDelays(GameEvent.CLUE, "hard", true).length);
        assertEquals(1, ProofPolicy.shotDelays(GameEvent.KC, "Clue scroll (elite)", true).length);
        assertArrayEquals(new long[] {300, 1800}, ProofPolicy.shotDelays(GameEvent.RAID_CHEST, "Barrows", true));
    }

    @Test
    public void cluesAreTheCasketAndItsCompletionCount()
    {
        assertTrue(ProofPolicy.isClue(GameEvent.CLUE, null));
        assertTrue(ProofPolicy.isClue(GameEvent.KC, "Clue Scroll (hard)"));
        assertFalse(ProofPolicy.isClue(GameEvent.KC, "Vorkath"));
        assertFalse(ProofPolicy.isClue(GameEvent.KC, null));
        assertFalse(ProofPolicy.isClue(GameEvent.NPC, "clue scroll (easy)"));
    }

    @Test
    public void raidsWhoseChestComesAfterTheKillLine()
    {
        assertTrue(ProofPolicy.raidWithChest("Chambers of Xeric: Challenge Mode"));
        assertTrue(ProofPolicy.raidWithChest("Theatre of Blood"));
        assertTrue(ProofPolicy.raidWithChest("Tombs of Amascut: Expert Mode"));
        assertTrue(ProofPolicy.raidWithChest("Fractured Archive"));
        assertFalse(ProofPolicy.raidWithChest("Barrows"));
        assertFalse(ProofPolicy.raidWithChest(null));
    }
}

package com.forgebingo.core;

import com.forgebingo.core.PixelArt.Grid;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.IntUnaryOperator;

/**
 * Raid-themed pixel-art creatures for the side panel (Chambers of Xeric crab, Theatre of Blood nylocas, Tombs of
 * Amascut chibi bosses) plus the little things that fall. All of it is our own original art, drawn on the shared
 * PixelArt grid facing LEFT with its feet on the bottom rows. Two walk frames each.
 */
public final class RaidSprites
{
    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private RaidSprites()
    {
    }

    /** One walk frame (0 or 1) of a raid creature, or null for critters this file does not draw. */
    public static BufferedImage image(Critter c, int variant, int frame)
    {
        if (c == null) return null;
        switch (c)
        {
            case CRAB:
            case NYLO:
            case XARPUS:
            case VERZIK:
            case AKKHA:
            case ZEBAK:
            case KEPHRI:
            case BABA:
            case WARDEN:
                break;
            default:
                return null;
        }
        final int v = Math.max(0, Math.min(c.variants - 1, variant));
        final int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(c + "|" + v + "|" + f, k -> make(c, v, f));
    }

    /** A small falling thing (14 to 18 px), or null for ones this file does not draw. */
    public static BufferedImage fall(Critter.Fall f, int variant)
    {
        if (f == null) return null;
        final int v = variant <= 0 ? 0 : 1;
        switch (f)
        {
            case BLOOD_DROP:
            case CRYSTAL:
                return CACHE.computeIfAbsent("fall|" + f + "|" + v, k -> makeFall(f, v));
            case KEPHRI_BOMB:
            case WATER_DROP:
                return CACHE.computeIfAbsent("fall|" + f + "|0", k -> makeFall(f, 0));
            default:
                return null;
        }
    }

    private static BufferedImage make(Critter c, int v, int f)
    {
        switch (c)
        {
            case CRAB: return PixelArt.render(crab(v, f), pal(CRAB_PAL + CRAB_GEM[v]));
            case NYLO: return PixelArt.render(nylo(f), pal(NYLO_PAL[v] + (f == 1 ? NYLO_PULSE[v] : "")));
            case XARPUS: return PixelArt.render(xarpus(f), pal(XARPUS_PAL));
            case VERZIK: return PixelArt.render(verzik(f), pal(VERZIK_PAL));
            case AKKHA: return PixelArt.render(akkha(f), pal(AKKHA_PAL));
            case ZEBAK: return PixelArt.render(zebak(f), pal(ZEBAK_PAL));
            case KEPHRI: return PixelArt.render(kephri(f), pal(KEPHRI_PAL));
            case BABA: return PixelArt.render(baba(f), pal(BABA_PAL));
            default: return PixelArt.render(warden(f), pal(WARDEN_PAL + (f == 1 ? " Wffffff Tb0fff0" : " Wd0fff8 T50f0e0")));
        }
    }

    // ---------------------------------------------------------------- palette and drawing helpers

    /** "kRRGGBB gRRGGBB ..." : a palette letter followed by its six hex digits, separated by spaces. */
    private static IntUnaryOperator pal(String spec)
    {
        Map<Character, Integer> m = new HashMap<>();
        for (String t : spec.trim().split("\\s+"))
        {
            if (t.length() == 7) m.put(t.charAt(0), Integer.parseInt(t.substring(1), 16));
        }
        return ch -> m.getOrDefault((char) ch, 0xff00ff);
    }

    private static void part(Grid g, Grid fill)
    {
        PixelArt.part(g, fill, 'k');
    }

    /** Fills an ellipse into {@code m}, lit from the top left: highlight letter, base letter, shade letter. */
    private static Grid ell(Grid m, double cx, double cy, double rx, double ry, char base, char hi, char sh)
    {
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                double nx = (x - cx) / rx;
                double ny = (y - cy) / ry;
                if (nx * nx + ny * ny > 1.0) continue;
                double t = nx * 0.6 + ny * 0.8;
                m.set(x, y, t < -0.5 ? hi : t > 0.5 ? sh : base);
            }
        }
        return m;
    }

    private static Grid ell(double cx, double cy, double rx, double ry, char base, char hi, char sh)
    {
        return ell(new Grid(), cx, cy, rx, ry, base, hi, sh);
    }

    /** A line of {@code thick} x {@code thick} pixel brush. */
    private static void line(Grid m, int x0, int y0, int x1, int y1, char c, int thick)
    {
        int dx = Math.abs(x1 - x0);
        int dy = Math.abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int x = x0;
        int y = y0;
        while (true)
        {
            for (int a = 0; a < thick; a++)
            {
                for (int b = 0; b < thick; b++) m.set(x + a, y + b, c);
            }
            if (x == x1 && y == y1) break;
            int e2 = 2 * err;
            if (e2 > -dy)
            {
                err -= dy;
                x += sx;
            }
            if (e2 < dx)
            {
                err += dx;
                y += sy;
            }
        }
    }

    /** Paints {@code o} onto {@code m} only where {@code m} already has pixels. */
    private static void overlay(Grid m, Grid o)
    {
        for (int y = 0; y < o.h; y++)
        {
            for (int x = 0; x < o.w; x++)
            {
                if (o.px[y][x] != 0 && m.has(x, y)) m.px[y][x] = o.px[y][x];
            }
        }
    }

    /** Pixels with nothing directly below them become {@code sh} (a cheap under-shade). */
    private static void underShade(Grid m, char sh)
    {
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                if (m.px[y][x] != 0 && !m.has(x, y + 1)) m.px[y][x] = sh;
            }
        }
