    /** Even-odd polygon fill. */
    private static Grid poly(int[][] pts, char c)
    {
        Grid m = new Grid();
        for (int y = 0; y < m.h; y++)
        {
            for (int x = 0; x < m.w; x++)
            {
                boolean in = false;
                for (int i = 0, j = pts.length - 1; i < pts.length; j = i++)
                {
                    if ((pts[i][1] > y) != (pts[j][1] > y)
                        && x < (double) (pts[j][0] - pts[i][0]) * (y - pts[i][1]) / (pts[j][1] - pts[i][1]) + pts[i][0])
                    {
                        in = !in;
                    }
                }
                if (in) m.set(x, y, c);
            }
        }
        return m;
    }

