package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import org.junit.Test;

public class ScreenshotStampTest
{
    private static final ZonedDateTime T = ZonedDateTime.of(2026, 11, 6, 14, 5, 0, 0, ZoneOffset.ofHours(2));

    private static BufferedImage white(int w, int h)
    {
        BufferedImage b = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) b.setRGB(x, y, Color.WHITE.getRGB());
        return b;
    }

    @Test
    public void stampsTopLeftAndKeepsSize()
    {
        BufferedImage src = white(765, 503);
        BufferedImage out = ScreenshotStamp.stamp(src, "Zulrah42", T);
        assertEquals(765, out.getWidth());
        assertEquals(503, out.getHeight());
        assertNotEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(2, 2) & 0xffffff);
        assertEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(700, 450) & 0xffffff);
        assertEquals(Color.WHITE.getRGB(), src.getRGB(2, 2));
    }

    /** Tile, player, code and time make a taller box than the time alone (four lines instead of one). */
    @Test
    public void proofStampHasTilePlayerCodeAndTime()
    {
        BufferedImage full = ScreenshotStamp.stamp(white(765, 503), "Zulrah42", T, "Goonferno", "Big bones x10");
        BufferedImage bare = ScreenshotStamp.stamp(white(765, 503), null, T, null, null);
        int fullBox = boxHeight(full), bareBox = boxHeight(bare);
        assertTrue("4-line box " + fullBox + " vs 1-line " + bareBox, fullBox > bareBox * 3);
    }

    private static int boxHeight(BufferedImage img)
    {
        int y = 0;
        while (y < img.getHeight() && (img.getRGB(1, y) & 0xffffff) != (Color.WHITE.getRGB() & 0xffffff)) y++;
        return y;
    }

    @Test
    public void stampsTimeWithoutKeyword()
    {
        BufferedImage out = ScreenshotStamp.stamp(white(400, 300), null, T);
        assertNotEquals(Color.WHITE.getRGB() & 0xffffff, out.getRGB(2, 2) & 0xffffff);
        assertTrue(ScreenshotStamp.timeText(T).startsWith("2026-11-06 14:05 UTC+02:00"));
    }
}

package com.forgebingo.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Map;
import javax.imageio.ImageIO;

/**
 * Bakes pictures drawn by code into a sprite sheet that the plugin's SpriteSheet reads back (NAME.png + NAME.txt in
 * src/main/resources/com/forgebingo/sprites), and checks a baked sheet against the drawing code. Shared by every
 * *SheetBaker / *BakedTest pair. Run from the plugin directory.
 */
public final class SheetBaker
{
    /** Where the sheets live, relative to the plugin directory (Gradle's working directory for tests and mains). */
    public static final File DIR = new File("src/main/resources/com/forgebingo/sprites");

    /** Set this environment variable (to anything) to make the *BakedTest tests re-bake instead of compare. */
    public static final String BAKE_ENV = "FORGE_BAKE";

    private SheetBaker()
    {
    }

    public static boolean bakeRequested()
    {
        String v = System.getenv(BAKE_ENV);
        return v != null && !v.isEmpty();
    }

    /**
     * Writes NAME.png and NAME.txt. Pictures are packed left to right, {@code cols} per row, in the map's order, in
     * cells the size of the biggest picture; null pictures are left out (so the loader returns null for them too).
     * Keys must not contain spaces.
     */
    public static void bake(String name, Map<String, BufferedImage> images, int cols) throws IOException
    {
        int cw = 1;
        int ch = 1;
        int n = 0;
        for (BufferedImage img : images.values())
        {
            if (img == null) continue;
            cw = Math.max(cw, img.getWidth());
            ch = Math.max(ch, img.getHeight());
            n++;
        }
        int rows = Math.max(1, (n + cols - 1) / cols);
        BufferedImage sheet = new BufferedImage(cw * cols, ch * rows, BufferedImage.TYPE_INT_ARGB);
        StringBuilder index = new StringBuilder();
        index.append("# ").append(name).append(": ").append(n).append(" pictures, cell ").append(cw).append('x').append(ch)
            .append(", ").append(cols).append(" per row. Written by SheetBaker - do not edit by hand.\n");
        index.append("# KEY x y w h\n");
        int i = 0;
        for (Map.Entry<String, BufferedImage> e : images.entrySet())
        {
            BufferedImage img = e.getValue();
            if (img == null) continue;
            if (e.getKey().indexOf(' ') >= 0) throw new IllegalArgumentException("key with a space: " + e.getKey());
            int x = (i % cols) * cw;
            int y = (i / cols) * ch;
            int w = img.getWidth();
            int h = img.getHeight();
            sheet.setRGB(x, y, w, h, img.getRGB(0, 0, w, h, null, 0, w), 0, w);
            index.append(e.getKey()).append(' ').append(x).append(' ').append(y).append(' ').append(w).append(' ').append(h).append('\n');
            i++;
        }
        Files.createDirectories(DIR.toPath());
        File png = new File(DIR, name + ".png");
        if (!ImageIO.write(sheet, "png", png)) throw new IOException("no PNG writer");
        Files.write(new File(DIR, name + ".txt").toPath(), index.toString().getBytes(StandardCharsets.UTF_8));
        System.out.println("baked " + n + " pictures into " + png.getPath() + " (" + sheet.getWidth() + "x" + sheet.getHeight()
            + ", " + png.length() + " bytes)");
    }

    /**
     * Asserts the baked picture is exactly the drawn one: both null, or the same type, size and every ARGB pixel.
     * {@code rebake} is the command to print when they differ.
     */
    public static void assertSame(String key, BufferedImage drawn, BufferedImage baked, String rebake)
    {
        String hint = " - the art code and the baked sheet differ. If the art was changed on purpose, re-bake: " + rebake;
        if (drawn == null)
        {
            assertNull(key + " is not drawn by the art code but is in the baked sheet" + hint, baked);
            return;
        }
        assertNotNull(key + " is drawn by the art code but missing from the baked sheet" + hint, baked);
        assertEquals(key + " image type" + hint, drawn.getType(), baked.getType());
        assertEquals(key + " width" + hint, drawn.getWidth(), baked.getWidth());
        assertEquals(key + " height" + hint, drawn.getHeight(), baked.getHeight());
        for (int y = 0; y < drawn.getHeight(); y++)
        {
            for (int x = 0; x < drawn.getWidth(); x++)
            {
                int a = drawn.getRGB(x, y);
                int b = baked.getRGB(x, y);
                if (a != b)
                {
                    fail(key + " pixel (" + x + "," + y + ") drawn " + Integer.toHexString(a) + " baked " + Integer.toHexString(b) + hint);
                }
            }
        }
    }
}

package com.forgebingo.core;

import com.forgebingo.core.PixelArt.Grid;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Pixel art for the skill props (see SkillProp): one little original prop per Old School skill that grows in three
 * stages (0 hint, 1 half, 2 complete) and has a gentle 2-frame animation. Chunky 1px dark outline, 2-3 shades per
 * colour, drawn on a 24 x 24 grid with the ground on the bottom row, centred on the middle.
 *
 * This is the DRAWING code (it was core/SkillProps in main before the art was baked into sprites/skillprops.png).
 * Source of truth for SkillPropSheetBaker and SkillPropsBakedTest; the plugin's SkillProps loads the baked sheet.
 */
public final class SkillPropArt
{
    private static final int S = 24;
    private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();

    private SkillPropArt()
    {
    }

    /**
     * One prop at a growth stage (0, 1 or 2) and animation frame (0 or 1), as a small transparent image whose
     * BOTTOM edge is the ground it stands on. At most 26 x 26.
     */
    public static BufferedImage image(SkillProp prop, int stage, int frame)
    {
        if (prop == null) return null;
        int st = Math.max(0, Math.min(2, stage));
        int f = frame == 0 ? 0 : 1;
        return CACHE.computeIfAbsent(prop + "|" + st + "|" + f, k -> PixelArt.render(build(prop, st, f), SkillPropArt::colour));
    }

    private static int colour(int c)
    {
        switch ((char) c)
        {
            case 'k': return 0x16140f; // outline
            case 'z': return 0x1d1a22; // darkest
            case 'w': return 0xfff7e0; // white
            case 'x': return 0xe6dcc0; // cream
            case 'X': return 0xb9ab8c;
            case 'n': return 0x7a5232; // wood
            case 'N': return 0xa47450;
            case 'F': return 0xc89a68;
            case 'm': return 0x49301c;
            case '1': return 0x58a840; // leaf green
            case '2': return 0x94d868;
            case '3': return 0x2e6a2e;
            case 'g': return 0x8d9098; // stone
            case 'G': return 0xb9bcc4;
            case 'D': return 0x555962;
            case 't': return 0x9aa6b4; // steel
            case 'T': return 0xdbe5ee;
            case 'u': return 0x5a6676;
            case 'i': return 0x5c616c; // iron
            case 'I': return 0x8b92a0;
            case 'j': return 0x363a44;
            case 'r': return 0xd2402e; // red
            case 'R': return 0xf27a62;
            case 'v': return 0x7a2018;
            case 'y': return 0xe8a828; // gold
            case 'Y': return 0xf8d060;
            case 'o': return 0xb08828;
            case 'b': return 0x4a78d0; // blue
            case 'B': return 0x8ab4f0;
            case 'd': return 0x2a4890;
            case 'p': return 0x8a52c8; // purple
            case 'P': return 0xb88ae8;
            case 'q': return 0x523088;
            case 'f': return 0xe03a12; // fire
            case 'a': return 0xff8a1e;
            case 'A': return 0xffd04a;
            case 'e': return 0x6c5634; // dirt
            case 'E': return 0x8a7040;
            case 'l': return 0x3ce870; // mark of grace green
            case 'L': return 0xc0ffd0;
            case 'h': return 0x1f9a4c;
            case 's': return 0xf08cb0; // pink
            case 'c': return 0x5ff0ff; // rune cyan
            case 'C': return 0xd8ffff;
            case 'Z': return 0x2aa0b4;
            case 'H': return 0xc8e6f4; // glass
            case 'O': return 0x6a9cc0;
            default: return 0xff00ff;
        }
    }

    // ---------------------------------------------------------------- helpers

    private static Grid L()
    {
        return new Grid(S, S);
    }

    private static Grid rc(Grid l, int x, int y, int w, int h, char c)
    {
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++) l.set(x + i, y + j, c);
        }
        return l;
    }

    private static Grid ov(Grid l, int x, int y, int w, int h, char c)
    {
        double cx = x + w / 2.0;
        double cy = y + h / 2.0;
        for (int j = 0; j < h; j++)
        {
            for (int i = 0; i < w; i++)
            {
                double dx = (x + i + 0.5 - cx) / (w / 2.0);
                double dy = (y + j + 0.5 - cy) / (h / 2.0);
                if (dx * dx + dy * dy <= 1.0) l.set(x + i, y + j, c);
            }
        }
        return l;
    }

    private static Grid ln(Grid l, int x0, int y0, int x1, int y1, char c)
    {
        int n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
        for (int i = 0; i <= n; i++)
        {
            double t = n == 0 ? 0 : i / (double) n;
            l.set((int) Math.round(x0 + (x1 - x0) * t), (int) Math.round(y0 + (y1 - y0) * t), c);
        }
        return l;
    }

    private static boolean occ(boolean[][] o, int x, int y)
    {
        return y >= 0 && y < o.length && x >= 0 && x < o[0].length && o[y][x];
    }

    /** Light from the top left: rim pixels of {@code base} facing down or right turn dark, facing up or left light. */
    private static Grid shade(Grid l, char base, char hi, char lo)
    {
        boolean[][] o = new boolean[l.h][l.w];
        for (int j = 0; j < l.h; j++)
        {
            for (int i = 0; i < l.w; i++) o[j][i] = l.px[j][i] != 0;
        }
        for (int j = 0; j < l.h; j++)
        {
            for (int i = 0; i < l.w; i++)
            {
                if (l.px[j][i] != base) continue;
                boolean up = !occ(o, i, j - 1);
                boolean left = !occ(o, i - 1, j);
                boolean right = !occ(o, i + 1, j);
                boolean down = !occ(o, i, j + 1);
                if (down || right) l.px[j][i] = lo;
                else if (up || left) l.px[j][i] = hi;
            }
        }
        return l;
    }

    private static void P(Grid g, Grid l)
    {
        PixelArt.part(g, l, 'k');
    }

    private static void P(Grid g, Grid l, char outline)
    {
        PixelArt.part(g, l, outline);
    }

    /** Paints a layer without an outline. */
    private static void put(Grid g, Grid l)
    {
        for (int j = 0; j < l.h; j++)
        {
            for (int i = 0; i < l.w; i++)
            {
                if (l.px[j][i] != 0) g.set(i, j, l.px[j][i]);
            }
        }
    }

    private static void sp(Grid g, int x, int y, boolean big, char core, char arm)
    {
        g.set(x, y, core);
        if (big)
        {
            g.set(x - 1, y, arm);
            g.set(x + 1, y, arm);
            g.set(x, y - 1, arm);
            g.set(x, y + 1, arm);
        }
    }

    private static String[] mir(String[] rows)
    {
        String[] out = new String[rows.length];
        for (int i = 0; i < rows.length; i++) out[i] = new StringBuilder(rows[i]).reverse().toString();
        return out;
    }

    private static final String[] BIG = {
        ".......f...",
        ".......ff..",
        "......fff..",
        "......ffaf.",
        ".....fffaf.",
        "....fffaaf.",
        "...fffaaaff",
        "...ffaaaaff",
        "..fffaaAaaf",
        "..ffaaAAaaf",
        ".fffaaAAAaf",
        ".ffaaAAAAaf",
        ".ffaaAAAAaf",
        ".fffaAAAAff",
        "..ffaaAAaf.",
        "...fffffff."};

    private static final String[] SMALL = {
        "...f...",
        "...ff..",
        "..fff..",
        "..faaf.",
        ".faaaaf",
        ".faAAaf",
        ".faAAaf",
        "..ffff."};

    private static void flame(Grid g, int x, int y, String[] rows, boolean mirror)
    {
        Grid l = L();
        l.stamp(x, y, mirror ? mir(rows) : rows);
        P(g, l, 'v');
    }

    private static Grid build(SkillProp p, int st, int f)
    {
        Grid g = new Grid(S, S);
        switch (p)
        {
            case WOODCUTTING: woodcutting(g, st, f); break;
            case FARMING: farming(g, st, f); break;
            case MINING: mining(g, st, f); break;
            case SMITHING: smithing(g, st, f); break;
            case FIREMAKING: firemaking(g, st, f); break;
            case COOKING: cooking(g, st, f); break;
            case FISHING: fishing(g, st, f); break;
            case RUNECRAFT: runecraft(g, st, f); break;
            case MAGIC: magic(g, st, f); break;
            case PRAYER: prayer(g, st, f); break;
            case HERBLORE: herblore(g, st, f); break;
            case CRAFTING: crafting(g, st, f); break;
            case FLETCHING: fletching2(g, st, f); break;
            case CONSTRUCTION: construction(g, st, f); break;
            case AGILITY: agility(g, st, f); break;
            case THIEVING: thieving2(g, st, f); break;
            case HUNTER: hunter2(g, st, f); break;
            case SLAYER: slayer(g, st, f); break;
            case ATTACK: attack(g, st, f); break;
            case STRENGTH: strength(g, st, f); break;
            case DEFENCE: defence(g, st, f); break;
            case RANGED: ranged(g, st, f); break;
            case HITPOINTS: hitpoints(g, st, f); break;
            case SAILING: sailing(g, st, f); break;
            default: break;
        }
        return g;
    }

    // ---------------------------------------------------------------- props

    private static void hunter2(Grid g, int st, int f)
    {
        Grid c = L();
        rc(c, 4, 16, 18, 8, 'N');
        rc(c, 4, 16, 18, 1, 'F');
        rc(c, 6, 18, 14, 5, 'z');
        rc(c, 7, 20, 12, 1, 'm');
        rc(c, 4, 18, 2, 6, 'n');
        rc(c, 20, 18, 2, 6, 'n');
        rc(c, 4, 23, 18, 1, 'n');
        c.pxs('n', 9, 17, 13, 17, 17, 17);
        Grid l = L();
        if (st == 0)
        {
            ov(l, 10, 20, 4, 4, 'r');
            shade(l, 'r', 'R', 'v');
            P(g, l);
            l = L();
            ln(l, 5, 23, 6, 14, 'N');
            ln(l, 6, 23, 7, 14, 'N');
            P(g, l);
            ln(g, 6 - f, 15, 1, 21, 'w');
            return;
        }
        if (st == 1)
        {
            P(g, c);
            l = L();
            ln(l, 1, 23, 2, 17, 'N');
            ln(l, 2, 23, 3, 17, 'N');
            P(g, l);
            return;
        }
        ov(l, 8, 21, 3, 3, 'r');
        shade(l, 'r', 'R', 'v');
        P(g, l);
        g.pxs('w', 9, 21);
        Grid t = L();
        for (int x = 4; x <= 21; x++)
        {
            int lift = (int) Math.round((21 - x) * 4 / 17.0);
            for (int y = 0; y < S; y++)
            {
                if (c.px[y][x] != 0 && y - lift >= 0) t.px[y - lift][x] = c.px[y][x];
            }
        }
        P(g, t);
        l = L();
        ln(l, 1, 23, 3 - f, 20, 'N');
        ln(l, 2, 23, 4 - f, 20, 'N');
        P(g, l);
        ln(g, 0, 18, 0, 22, 'w');
        g.pxs('w', 1, 17 + f);
    }

    private static void thieving2(Grid g, int st, int f)
    {
        Grid l = L();
        if (st == 0)
        {
            ov(l, 8, 16, 9, 8, 'n');
            rc(l, 10, 13, 5, 4, 'n');
            rc(l, 9, 11, 7, 3, 'n');
            shade(l, 'n', 'N', 'm');
            P(g, l);
            g.pxs('y', 11, 14, 12, 14, 13, 14);
            return;
        }
        if (st == 2)
        {
            ov(l, 10, 1, 5, 6, 'y');
            shade(l, 'y', 'Y', 'o');
            P(g, l);
            l = L();
        }
        ov(l, 4, 11, 16, 13, 'n');
        rc(l, 5, 19, 14, 5, 'n');
        rc(l, 9, 8, 6, 4, 'n');
        rc(l, 7, 5, 10, 4, 'n');
        shade(l, 'n', 'N', 'm');
        P(g, l);
        g.pxs('m', 8, 7, 11, 7, 14, 7);
        g.pxs('y', 9, 10, 10, 10, 11, 10, 12, 10, 13, 10, 14, 10);
        g.pxs('Y', 15, 10, 16, 11, 15, 12, 16, 13);
        g.pxs('N', 7, 15, 7, 16, 8, 14);
        if (st == 1)
