    private static void shp(Grid l, int top, int bot, int hw, char c)
    {
        for (int y = top; y <= bot; y++)
        {
            double t = (y - top) / (double) (bot - top);
            int w = t < 0.45 ? 2 * hw : (int) Math.round(2 * hw * (1 - (t - 0.45) / 0.55 * 0.95));
            if (w < 2) w = 2;
            if (y == top) w -= 2;
            rc(l, 12 - w / 2, y, w, 1, c);
        }
    }

